				local emoteNames, emoteByName, emoteGroups = {}, {}, {}
				for _, emote in ipairs(emotes) do
					table.insert(emoteNames, emote.name)
					emoteByName[emote.name] = emote
					local group = emoteGroups[#emoteGroups]
					if not group or group.name ~= emote.group then
						group = { name = emote.group, names = {} }
						table.insert(emoteGroups, group)
					end
					table.insert(group.names, emote.name)
				end
				trolling.emoteNames = emoteNames
				if not emoteByName[featureSettings.trollEmote] then featureSettings.trollEmote = "Dance 1" end
				local emoteState = { track = nil }
				local function stopEmoteTrack()
					if emoteState.track then
						pcall(function() emoteState.track:Stop(0.2) end)
						emoteState.track = nil
					end
				end
				-- Plays the chosen emote on a loop. Says why not when it can't.
				local function playChosenEmote()
					stopEmoteTrack()
					local _, humanoid = myCharacter()
					if not humanoid then return false, "Your character isn't ready yet." end
					local emote = emoteByName[featureSettings.trollEmote] or emotes[1]
					local id = isR15(humanoid) and emote.r15 or emote.r6
					if not id then return false, emote.name .. " needs an R15 avatar, and this game has you as R6." end
					local track = playOnMe("rbxassetid://" .. tostring(id))
					if not track then return false, "Your character isn't ready yet." end
					track.Looped = true
					emoteState.track = track
					return true
				end
				-- Makes name the Emote switch's emote (playing it if Emote is on). Spaces and punctuation
				-- don't matter, so "floss dance" finds "Floss Dance". fromDropdown: the dropdown already
				-- shows it.
				function trolling.chooseEmote(name, fromDropdown)
					local wanted = tostring(name or ""):lower():gsub("[%s%p]", "")
					for _, emote in ipairs(emotes) do
						if emote.name:lower():gsub("[%s%p]", "") == wanted then
							featureSettings.trollEmote = emote.name
							saveFeatureSettings()
							if not fromDropdown then pcall(function() trolling.emoteDropdown:Set(emote.name, true) end) end
							local entry = quickToggleByName["Emote"]
							if entry and entry.state then
								local played, why = playChosenEmote()
								if not played then notify("Emote", why) end
							end
							return true
						end
					end
					return false
				end
				-- Plays the emote called name once, over everything, without the Emote switch (the Troll
				-- Panel's emotes). Returns its track, or nil and why not.
				function trolling.playEmoteOnce(name)
					local _, humanoid = myCharacter()
					if not humanoid then return nil, "Your character isn't ready yet." end
					local emote = emoteByName[name]
					if not emote then return nil, "There's no emote called " .. tostring(name) .. "." end
					local id = isR15(humanoid) and emote.r15 or emote.r6
					if not id then return nil, emote.name .. " needs an R15 avatar, and this game has you as R6." end
					if emoteState.once then pcall(function() emoteState.once:Stop(0.2) end) end
					local track = playOnMe("rbxassetid://" .. tostring(id))
					emoteState.once = track
					if track then track.Looped = false end
					return track
				end
				withIcon(trollTabs.emotes, "CreateSection", { name = "Emotes" }, "smile", "music")
				addQuickToggle(trollTabs.emotes, "Emote", "Loops the emote picked below (or right-click to pick by category). Everyone sees it", function(enabled)
					if not enabled then return stopEmoteTrack() end
					local played, why = playChosenEmote()
					if not played then
						notify("Emote", why)
						return false
					end
				end, "music", "smile")
