					local entry = quickToggleByName["Emote"]
					if entry and entry.state then playChosenEmote() end
				end)
				-- Every preset in one list: picking one plays it straight away, through the Emote switch.
				trolling.emoteDropdown = withIcon(trollTabs.emotes, "CreateDropdown", {
					name = "Pick an Emote",
					description = tostring(#emotes) .. " emotes and dances. Picking one plays it on a loop; switch Emote off to stop",
					options = emoteNames,
					value = featureSettings.trollEmote,
					callback = function(value)
						-- Rayfield may call this as the dropdown is made; only a real pick counts.
						if not trolling.emoteDropdownReady then return end
						if type(value) == "table" then value = value[1] end
						value = tostring(value)
						if not emoteByName[value] then return end
						local entry = quickToggleByName["Emote"]
						if value == featureSettings.trollEmote and entry and entry.state then return end
						trolling.chooseEmote(value, true)
						if entry and not entry.state then setQuickToggle(entry, true) end
					end,
				}, "smile", "music")
				task.defer(function() trolling.emoteDropdownReady = true end)

				-- Emote Wheel: hold its key (B to start with) and a wheel of eight emotes opens round the
				-- cursor (the middle of the screen in first person). Point at one and let go, or click it,
				-- to play it through the Emote switch; let go in the middle to stop the emote that's
				-- playing. The key and the eight emotes are in its settings card.
				local wheelDefaults = { "Wave", "Dance 1", "Floss Dance", "Laugh", "Cheer", "Shrek Roar", "Hot To Go!", "Confused" }
				-- Saved slots that aren't emotes here any more go back to how they started.
				for slot = 1, 8 do
					if not emoteByName[featureSettings.emoteWheelEmotes[slot]] then
						featureSettings.emoteWheelEmotes[slot] = wheelDefaults[slot]
					end
				end
				for slot = #featureSettings.emoteWheelEmotes, 9, -1 do
					table.remove(featureSettings.emoteWheelEmotes, slot)
				end
				addQuickToggle(trollTabs.emotes, "Emote Wheel", "Hold a key (B to start with) for a wheel of emotes and point at one. Right-click to change them and the key", function(enabled)
					if featureSettings.emoteWheel ~= enabled then
						featureSettings.emoteWheel = enabled
						saveFeatureSettings()
					end
				end, "pie-chart", "smile")
				do
					local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:WaitForChild("PlayerGui")
					local previousGui = playerGui:FindFirstChild("SpreadCheeksEmoteWheel")
					if previousGui then previousGui:Destroy() end
					local gui = Instance.new("ScreenGui")
					gui.Name = "SpreadCheeksEmoteWheel"
					gui.ResetOnSpawn = false
					gui.IgnoreGuiInset = true
					-- Over the game's own buttons and the ; bar, under the notifications.
					gui.DisplayOrder = 1002
					gui.Enabled = false
					gui.Parent = playerGui
					-- Covers the screen while the wheel is open. Being Modal frees the mouse in first person
					-- and shift lock, and it takes the click that picks an emote, so the game doesn't get it.
					local cover = Instance.new("TextButton")
					cover.Size = UDim2.fromScale(1, 1)
					cover.AutoButtonColor = false
					cover.BackgroundColor3 = Color3.new(0, 0, 0)
					cover.BackgroundTransparency = 0.7
					cover.BorderSizePixel = 0
					cover.Text = ""
					cover.Modal = true
					cover.Parent = gui
					local wheelFrame = Instance.new("Frame")
					wheelFrame.Size = UDim2.fromOffset(0, 0)
					wheelFrame.BackgroundTransparency = 1
					wheelFrame.Parent = gui
					local hub = Instance.new("TextLabel")
					hub.AnchorPoint = Vector2.new(0.5, 0.5)
					hub.Size = UDim2.fromOffset(84, 84)
					hub.BorderSizePixel = 0
					hub.Font = Enum.Font.GothamBold
					hub.TextSize = 12
					hub.Parent = wheelFrame
					local hubCorner = Instance.new("UICorner")
					hubCorner.CornerRadius = UDim.new(1, 0)
					hubCorner.Parent = hub
					local hubStroke = Instance.new("UIStroke")
					hubStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
					hubStroke.Thickness = 1.5
					hubStroke.Parent = hub
					local slots = {}
					for slot = 1, 8 do
						-- Slot 1 at the top, then round clockwise.
						local angle = math.rad((slot - 1) * 45)
						local label = Instance.new("TextLabel")
						label.AnchorPoint = Vector2.new(0.5, 0.5)
						label.Position = UDim2.fromOffset(math.sin(angle) * 140, -math.cos(angle) * 140)
						label.Size = UDim2.fromOffset(112, 38)
						label.BorderSizePixel = 0
						label.Font = Enum.Font.GothamMedium
						label.TextSize = 12
						label.TextWrapped = true
						label.Parent = wheelFrame
						local labelCorner = Instance.new("UICorner")
						labelCorner.CornerRadius = UDim.new(0, 10)
						labelCorner.Parent = label
						local labelStroke = Instance.new("UIStroke")
						labelStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
						labelStroke.Thickness = 1.5
						labelStroke.Parent = label
						slots[slot] = { label = label, stroke = labelStroke }
					end

					local open, hovered, wheelCenter, savedMouseIcon = false, 0, Vector2.zero, nil
					local function emotePlaying()
						local entry = quickToggleByName["Emote"]
						return entry ~= nil and entry.state
					end
					local function paint()
						local theme = auxiliaryUiTheme
						for slot, parts in ipairs(slots) do
							local selected = hovered == slot
							parts.label.Text = tostring(featureSettings.emoteWheelEmotes[slot] or "")
							parts.label.BackgroundColor3 = selected and theme.Accent or theme.Background
							parts.label.TextColor3 = selected and theme.OnAccent or theme.Text
							parts.stroke.Color = selected and theme.Accent or theme.Stroke
						end
						hub.Text = emotePlaying() and "Stop" or "Close"
						hub.BackgroundColor3 = hovered == 0 and theme.Accent or theme.Card
						hub.TextColor3 = hovered == 0 and theme.OnAccent or theme.SubText
						hubStroke.Color = hovered == 0 and theme.Accent or theme.Stroke
					end
					-- The slot the mouse points at from the middle of the wheel, or 0 in the middle.
					local function pointedSlot()
						local offset = UserInputService:GetMouseLocation() - wheelCenter
						if offset.Magnitude < 50 then return 0 end
						local angle = math.deg(math.atan2(offset.X, -offset.Y)) % 360
						return math.floor((angle + 22.5) / 45) % 8 + 1
					end
					local function setOpen(on)
						if open == on then return end
						open = on
						if not on then
							gui.Enabled = false
							if savedMouseIcon ~= nil then UserInputService.MouseIconEnabled = savedMouseIcon end
							savedMouseIcon = nil
							return
						end
						-- Round the cursor, kept clear of the screen's edges.
						local camera = workspace.CurrentCamera
						local screen = camera and camera.ViewportSize or Vector2.new(1280, 720)
						local mouse = UserInputService:GetMouseLocation()
						wheelCenter = Vector2.new(math.clamp(mouse.X, 200, math.max(200, screen.X - 200)), math.clamp(mouse.Y, 170, math.max(170, screen.Y - 170)))
						wheelFrame.Position = UDim2.fromOffset(wheelCenter.X, wheelCenter.Y)
						hovered = pointedSlot()
						paint()
						-- Some games hide the cursor; it's needed to point.
						savedMouseIcon = UserInputService.MouseIconEnabled
						UserInputService.MouseIconEnabled = true
						gui.Enabled = true
					end
					-- Plays the emote in a slot, or with 0 stops the one playing.
					local function choose(slot)
						if slot == 0 then
							if emotePlaying() then trolling.stopAnimations() end
							return
						end
						local name = featureSettings.emoteWheelEmotes[slot]
						if not name or not trolling.chooseEmote(name) then return end
						local entry = quickToggleByName["Emote"]
						if entry and not entry.state then setQuickToggle(entry, true) end
					end
					-- The key is read straight from the keyboard each frame, so it still works when the game
					-- uses that key for something too.
					local wasDown, keyName, keyCode = false, nil, nil
					pcall(function() RunService:UnbindFromRenderStep("SpreadCheeksEmoteWheel") end)
					RunService:BindToRenderStep("SpreadCheeksEmoteWheel", Enum.RenderPriority.Input.Value, function()
						local entry = quickToggleByName["Emote Wheel"]
						if not entry or not entry.state then
							wasDown = false
							return setOpen(false)
						end
						if featureSettings.emoteWheelKey ~= keyName then
							keyName = featureSettings.emoteWheelKey
							local keyOk, code = pcall(function() return Enum.KeyCode[keyName] end)
							keyCode = keyOk and code or nil
						end
						local down = keyCode ~= nil and UserInputService:IsKeyDown(keyCode)
						if down and not wasDown then
							-- Not while typing in the chat or a text box.
							if not UserInputService:GetFocusedTextBox() then setOpen(true) end
						elseif not down and wasDown and open then
							choose(hovered)
							setOpen(false)
						end
						wasDown = down
						if open then
							local pointed = pointedSlot()
							if pointed ~= hovered then
								hovered = pointed
								paint()
							end
						end
					end)
					cover.MouseButton1Click:Connect(function()
						if not open then return end
						choose(pointedSlot())
						setOpen(false)
					end)
				end
				if featureSettings.emoteWheel then setQuickToggle(quickToggleByName["Emote Wheel"], true) end

				withIcon(trollTabs.emotes, "CreateSection", { name = "Animation tricks" }, "wand-sparkles", "sparkles")
				addQuickToggle(trollTabs.emotes, "Reverse Animations", "Everything you do plays backwards", function(enabled)
					trolling.reverse = enabled
					updateSpeedLoop()
				end, "rewind", "undo-2")
				addQuickToggle(trollTabs.emotes, "Mannequin", "Your arms and legs stop moving, so you glide about stiff as a board", function(enabled)
					holdAnimate("Mannequin", enabled)
				end, "accessibility", "person-standing")
				-- Statue: frozen mid-pose and rooted to the spot (anchored) until it's switched off.
				local statueState = { root = nil }
				local function setStatue(enabled)
					if statueState.root then
						pcall(function() statueState.root.Anchored = false end)
						statueState.root = nil
					end
					trolling.statue = false
					if enabled then
						local _, _, root = myCharacter()
						if not root then
							notify("Statue", "Your character isn't ready yet.")
							updateSpeedLoop()
							return false
						end
						claimMovement("Statue")
						root.Anchored = true
						statueState.root = root
						trolling.statue = true
					end
					updateSpeedLoop()
				end
				addQuickToggle(trollTabs.emotes, "Statue", "Freeze mid-pose and stay rooted to the spot", setStatue, "pause", "snowflake")
				table.insert(respawnHandlers, function() switchOff("Statue") end)

				-- Play Animation ID: any animation Roblox lets this game load, played over everything else.
				local customState = { track = nil, serial = 0 }
				local function stopCustomTrack()
					customState.serial += 1
					if customState.track then
						pcall(function() customState.track:Stop(0.2) end)
						customState.track = nil
					end
				end
				function trolling.playAnimationId(text)
					local id = tostring(text or ""):match("%d+")
					if not id then
						return notify("Play Animation", "Type an animation's ID number, like 507771019.")
					end
					stopCustomTrack()
					local serial = customState.serial
					task.spawn(function()
						local animationId = "rbxassetid://" .. id
						-- A catalog emote wraps its animation; this finds the animation inside, the way
						-- Infinite Yield's animation command does.
						local unwrapped, inner = pcall(anim2track, animationId)
						if unwrapped and type(inner) == "string" and inner ~= "" then animationId = inner end
						if customState.serial ~= serial then return end
						local track = playOnMe(animationId)
						if not track then
							return notify("Play Animation", "Your character isn't ready yet.")
						end
						customState.track = track
						-- An animation Roblox won't let this game use never gets a length.
						local started = os.clock()
						while track.Length == 0 and os.clock() - started < 4 and customState.serial == serial do
							task.wait(0.1)
						end
						if track.Length == 0 and customState.serial == serial then
							stopCustomTrack()
							notify("Play Animation", "That one didn't load. Roblox only lets a game play animations made by Roblox or by the game's creator.", 6)
						end
					end)
				end

				function trolling.stopAnimations()
					stopCustomTrack()
					switchOff("Emote")
					stopEmoteTrack()
				end
				trolling.animationInput = withIcon(trollTabs.emotes, "CreateInput", {
					name = "Play Animation ID",
					description = "Plays an animation or emote by its ID. Roblox only allows ones made by Roblox or by this game's creator",
					placeholder = "Animation ID",
					numeric = true,
					callback = function(value)
						if tostring(value or "") == "" then return end
						trolling.playAnimationId(value)
						-- Emptied again, so the same ID can be played twice in a row.
						task.defer(function()
							pcall(function() trolling.animationInput:Set("", true) end)
						end)
					end,
				}, "clapperboard", "film", "play")
				-- Kept so its row gets a key box, like the moves (see trolling.moves).
				trolling.stopAnimationsButton = withIcon(trollTabs.emotes, "CreateButton", {
					name = "Stop Animations",
					description = "Stops the emote and anything played by ID",
					callback = function() trolling.stopAnimations() end,
				}, "circle-stop", "square")

				-- Silly walks.
				withIcon(trollTabs.walks, "CreateSection", { name = "Silly walks" }, "footprints")
				-- Moonwalk and Crab Walk turn you away from where you're walking: right round, so you glide
				-- the wrong way, or sideways like a crab.
				local facingState = { loop = nil, humanoid = nil, autoRotate = true }
				local function setWalkFacing(angle)
					if facingState.loop then
						facingState.loop:Disconnect()
						facingState.loop = nil
					end
					if facingState.humanoid and facingState.humanoid.Parent then
						facingState.humanoid.AutoRotate = facingState.autoRotate
					end
					facingState.humanoid = nil
					if not angle then return end
					local turn = CFrame.Angles(0, angle, 0)
					facingState.loop = RunService.Heartbeat:Connect(function()
						local _, humanoid, root = myCharacter()
						if not humanoid then return end
						if facingState.humanoid ~= humanoid then
							facingState.humanoid = humanoid
							facingState.autoRotate = humanoid.AutoRotate
						end
						humanoid.AutoRotate = false
						local direction = flat(humanoid.MoveDirection)
						if direction.Magnitude > 0.1 then
							root.CFrame = CFrame.lookAt(root.Position, root.Position + turn:VectorToWorldSpace(direction.Unit))
						end
					end)
				end
				local function walkFacingSwitch(name, angle)
					return function(enabled)
						if enabled then claimMovement(name) end
						setWalkFacing(enabled and angle or nil)
					end
				end
				addQuickToggle(trollTabs.walks, "Moonwalk", "You face backwards as you walk, so you glide the wrong way", walkFacingSwitch("Moonwalk", math.pi), "footprints")
				addQuickToggle(trollTabs.walks, "Crab Walk", "You walk sideways, like a crab", walkFacingSwitch("Crab Walk", math.pi / 2), "shell", "bug")

				-- Drunk Walk: your steering wobbles from side to side, and every so often you trip over.
				local drunkWalkState = { nextTrip = 0 }
				addQuickToggle(trollTabs.walks, "Drunk Walk", "You stagger about and trip over now and then", function(enabled)
					if not enabled then return afterControls("SpreadCheeksDrunkWalk", nil) end
					claimMovement("Drunk Walk")
					drunkWalkState.nextTrip = os.clock() + 5
					afterControls("SpreadCheeksDrunkWalk", function()
						local _, humanoid = myCharacter()
						if not humanoid then return end
						local move = flat(humanoid.MoveDirection)
						if move.Magnitude < 0.1 then return end
						local now = os.clock()
						local wobble = math.sin(now * 2.2) * math.rad(45) + math.sin(now * 5.3) * math.rad(15)
						humanoid:Move(CFrame.Angles(0, wobble, 0):VectorToWorldSpace(move), false)
						if now > drunkWalkState.nextTrip then
							drunkWalkState.nextTrip = now + 6 + math.random() * 8
							humanoid:ChangeState(Enum.HumanoidStateType.FallingDown)
						end
					end)
				end, "beer", "wine")

				-- Zoomies: you run round and round in circles by yourself, whatever keys you press.
				local zoomiesState = { angle = 0 }
				addQuickToggle(trollTabs.walks, "Zoomies", "You run round and round in circles all by yourself", function(enabled)
					if not enabled then return afterControls("SpreadCheeksZoomies", nil) end
					claimMovement("Zoomies")
					afterControls("SpreadCheeksZoomies", function(deltaTime)
						local _, humanoid = myCharacter()
						if not humanoid then return end
						zoomiesState.angle = (zoomiesState.angle + deltaTime * 2.5) % (math.pi * 2)
						humanoid:Move(Vector3.new(math.cos(zoomiesState.angle), 0, math.sin(zoomiesState.angle)), false)
					end)
				end, "dog", "paw-print")

				-- Ice Skates: your keys push you along instead of walking you, and you keep gliding and slow
				-- down gradually, like on ice. You glide standing up, facing where you're going.
				local skateState = { velocity = Vector3.zero }
				addQuickToggle(trollTabs.walks, "Ice Skates", "Glide around like you're on ice", function(enabled)
					if not enabled then return afterControls("SpreadCheeksIceSkates", nil) end
					claimMovement("Ice Skates")
					skateState.velocity = Vector3.zero
					afterControls("SpreadCheeksIceSkates", function(deltaTime)
						local _, humanoid, root = myCharacter()
						if not humanoid then return end
						local push = flat(humanoid.MoveDirection)
						local velocity = skateState.velocity * math.max(0, 1 - 0.5 * deltaTime) + push * humanoid.WalkSpeed * 2 * deltaTime
						local topSpeed = humanoid.WalkSpeed * 1.6
						if velocity.Magnitude > topSpeed then velocity = velocity.Unit * topSpeed end
						skateState.velocity = velocity
						-- As far as the humanoid knows you're standing still; the glide moves you instead.
						humanoid:Move(Vector3.zero, false)
						if velocity.Magnitude > 0.05 then
							local position = root.Position + velocity * deltaTime
							root.CFrame = CFrame.lookAt(position, position + velocity)
						end
					end)
				end, "snowflake", "wind")

				-- Bunny Hop: holds jump down for you whenever you're on the ground. The control script sets
				-- jumping from your keys every frame, so this goes straight after it.
				addQuickToggle(trollTabs.walks, "Bunny Hop", "Keeps you hopping nonstop", function(enabled)
					if not enabled then return afterControls("SpreadCheeksBunnyHop", nil) end
					claimMovement("Bunny Hop")
					afterControls("SpreadCheeksBunnyHop", function()
						local _, humanoid = myCharacter()
						if humanoid and not humanoid.Sit and humanoid.FloorMaterial ~= Enum.Material.Air then
							humanoid.Jump = true
						end
					end)
				end, "rabbit", "chevrons-up")

				-- Bouncy Ball: every landing bounces you back up, nearly as high as you came down from.
				local bouncyState = { loop = nil, fallSpeed = 0 }
				addQuickToggle(trollTabs.walks, "Bouncy Ball", "Every time you land, you bounce back up", function(enabled)
					if bouncyState.loop then
						bouncyState.loop:Disconnect()
						bouncyState.loop = nil
					end
					if not enabled then return end
					claimMovement("Bouncy Ball")
					bouncyState.fallSpeed = 0
					bouncyState.loop = RunService.Heartbeat:Connect(function()
						local _, humanoid, root = myCharacter()
						if not humanoid then return end
						local velocity = root.AssemblyLinearVelocity
						if humanoid.FloorMaterial == Enum.Material.Air then
							bouncyState.fallSpeed = math.max(bouncyState.fallSpeed, -velocity.Y)
						else
							if bouncyState.fallSpeed > 15 then
								root.AssemblyLinearVelocity = Vector3.new(velocity.X, bouncyState.fallSpeed * 0.85 + 8, velocity.Z)
								humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
							end
							bouncyState.fallSpeed = 0
						end
					end)
				end, "circle-dot", "disc")

				-- Flip Every Jump: each jump comes with a random flip. Hooked to the humanoid, so it's hooked
				-- again on each new character.
				local flipJumpState = { enabled = false, connection = nil }
				local function hookFlipJumps()
					if flipJumpState.connection then
						flipJumpState.connection:Disconnect()
						flipJumpState.connection = nil
					end
					if not flipJumpState.enabled then return end
					local _, humanoid = myCharacter()
					if not humanoid then return end
					local kinds = { "front", "back", "side", "spin" }
					flipJumpState.connection = humanoid.StateChanged:Connect(function(_, newState)
						if newState == Enum.HumanoidStateType.Jumping then
							trolling.flip(kinds[math.random(#kinds)], true)
						end
					end)
				end
				table.insert(respawnHandlers, hookFlipJumps)
				addQuickToggle(trollTabs.walks, "Flip Every Jump", "Every jump comes with a random flip. Try it with Bunny Hop", function(enabled)
					flipJumpState.enabled = enabled
					hookFlipJumps()
				end, "rotate-3d", "refresh-cw")

				-- Body tricks.
				withIcon(trollTabs.tricks, "CreateSection", { name = "On the spot" }, "smile", "user-round")
				-- Fake Dead: you drop flat (on your back, or face down) and lie still, seated so you don't
				-- stand back up, until it's switched off or you jump.
				local fakeDeadState = { loop = nil, upright = nil, serial = 0 }
				local function setFakeDead(enabled)
					fakeDeadState.serial += 1
					local serial = fakeDeadState.serial
					if fakeDeadState.loop then
						fakeDeadState.loop:Disconnect()
						fakeDeadState.loop = nil
					end
					local _, humanoid, root = myCharacter()
					if not enabled then
						holdAnimate("Fake Dead", false)
						if humanoid and fakeDeadState.upright then
							humanoid.Sit = false
							root.CFrame = fakeDeadState.upright.Rotation + (root.Position + Vector3.new(0, 2, 0))
							humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
						end
						fakeDeadState.upright = nil
						return
					end
					if not humanoid then
						notify("Fake Dead", "Your character isn't ready yet.")
						return false
					end
					claimMovement("Fake Dead")
					switchOff("Emote")
					local flatLook = flat(root.CFrame.LookVector)
					if flatLook.Magnitude < 0.1 then flatLook = Vector3.new(0, 0, -1) end
					fakeDeadState.upright = CFrame.lookAt(root.Position, root.Position + flatLook.Unit)
					holdAnimate("Fake Dead", true)
					humanoid.Sit = true
					-- A moment to sit down, then over you go.
					task.delay(0.1, function()
						if fakeDeadState.serial ~= serial or not root.Parent then return end
						if not humanoid.Sit then
							notify("Fake Dead", "This game doesn't let you lie down.")
							return switchOff("Fake Dead")
						end
						local faceDown = featureSettings.trollDeadPose == "Face down"
						root.CFrame = fakeDeadState.upright * CFrame.Angles(faceDown and -math.pi / 2 or math.pi / 2, 0, 0)
						stopAllTracks(humanoid, 0)
						fakeDeadState.loop = RunService.Heartbeat:Connect(function()
							-- Jumping gets you up, and so does dying for real.
							if not humanoid.Parent or humanoid.Health <= 0 or not humanoid.Sit then
								switchOff("Fake Dead")
							end
						end)
					end)
				end
				addQuickToggle(trollTabs.tricks, "Fake Dead", "Drop down and lie still as if you died. Jump to get back up. Right-click for the pose", setFakeDead, "skull")

				-- Fake Lag: makes you look laggy to everyone. Stutter freezes you for moments at a time,
				-- Rubber-band snaps you back to where you just were, Glitch twitches you about, Spikes runs
				-- smoothly and then hits you with one big freeze and a snap back, and Mixed changes between
				-- those every few seconds. Strength (5 is how it always was) makes it longer and wilder, and
				-- "Only while moving" leaves you alone while you stand still. All in its settings card.
				local fakeLagState = { serial = 0, anchoredRoot = nil }
				local function releaseLagAnchor()
					if fakeLagState.anchoredRoot then
						pcall(function() fakeLagState.anchoredRoot.Anchored = false end)
						fakeLagState.anchoredRoot = nil
					end
				end
				local function setFakeLag(enabled)
					fakeLagState.serial += 1
					local serial = fakeLagState.serial
					releaseLagAnchor()
					if not enabled then return end
					claimMovement("Fake Lag")
					task.spawn(function()
						local mixedStyles = { "Stutter", "Rubber-band", "Glitch", "Spikes" }
						local mixedStyle, mixedUntil = "Stutter", 0
						while fakeLagState.serial == serial do
							local _, humanoid, root = myCharacter()
							-- 1 at the usual strength of 5, from 0.2 up to 2.
							local strength = featureSettings.trollLagStrength / 5
							local style = featureSettings.trollLagStyle
							if style == "Mixed" then
								if os.clock() > mixedUntil then
									mixedStyle = mixedStyles[math.random(#mixedStyles)]
									mixedUntil = os.clock() + 3 + math.random() * 3
								end
								style = mixedStyle
							end
							if not root or (featureSettings.trollLagMoving and humanoid.MoveDirection.Magnitude < 0.1) then
								task.wait(0.2)
							elseif style == "Rubber-band" then
								local from = root.Position
								task.wait((0.25 + math.random() * 0.2) * math.sqrt(strength))
								if fakeLagState.serial ~= serial then break end
								if root.Parent and (root.Position - from).Magnitude > 1.5 then
									root.CFrame = root.CFrame.Rotation + from
								end
								task.wait((0.2 + math.random() * 0.45) / math.sqrt(strength))
							elseif style == "Glitch" then
								if math.random() < math.min(0.35 * strength, 0.9) then
									local reach = 1.2 * strength
									root.CFrame = root.CFrame * CFrame.new((math.random() - 0.5) * reach, 0, (math.random() - 0.5) * reach)
										* CFrame.Angles(0, math.rad(math.random(-30, 30) * math.min(strength, 2)), 0)
								end
								RunService.Heartbeat:Wait()
							elseif style == "Spikes" then
								-- Smooth for a few seconds, then frozen, then snapped back to where it hit.
								task.wait(1.5 + math.random() * 3)
								local _, _, spikeRoot = myCharacter()
								if fakeLagState.serial ~= serial or not spikeRoot then continue end
								local from = spikeRoot.Position
								spikeRoot.Anchored = true
								fakeLagState.anchoredRoot = spikeRoot
								task.wait((0.4 + math.random() * 0.4) * strength)
								releaseLagAnchor()
								task.wait(0.35)
								if fakeLagState.serial == serial and spikeRoot.Parent and (spikeRoot.Position - from).Magnitude > 1.5 then
									spikeRoot.CFrame = spikeRoot.CFrame.Rotation + from
								end
							else
								root.Anchored = true
								fakeLagState.anchoredRoot = root
								task.wait((0.08 + math.random() * 0.17) * strength)
								releaseLagAnchor()
								task.wait((0.1 + math.random() * 0.3) / math.sqrt(strength))
							end
						end
					end)
				end
				addQuickToggle(trollTabs.tricks, "Fake Lag", "Makes you look like you're lagging. Right-click for the style, strength and more", setFakeLag, "wifi-off", "wifi")

				-- Ragdoll: you go limp and flop over, arms and legs loose, until you jump or switch it off.
				-- Your joints are swapped for loose ball joints while it's on, so your body really falls and
				-- tumbles; everyone sees you collapse.
				do
					local ragdoll = { joints = {}, collisions = {}, humanoid = nil, loop = nil, spaceDown = true }
					local function standUp()
						if ragdoll.loop then
							ragdoll.loop:Disconnect()
							ragdoll.loop = nil
						end
						for _, joint in ipairs(ragdoll.joints) do
							if joint.motor.Parent then joint.motor.Enabled = true end
							joint.socket:Destroy()
							joint.attachment0:Destroy()
							joint.attachment1:Destroy()
						end
						table.clear(ragdoll.joints)
						for part, canCollide in pairs(ragdoll.collisions) do
							if part.Parent then part.CanCollide = canCollide end
						end
						table.clear(ragdoll.collisions)
						local humanoid = ragdoll.humanoid
						ragdoll.humanoid = nil
						holdAnimate("Ragdoll", false)
						if not humanoid or not humanoid.Parent or humanoid.Health <= 0 then return end
						humanoid.PlatformStand = false
						local root = getRoot(humanoid.Parent)
						if root then
							-- Upright again, just above where you lay.
							local look = flat(root.CFrame.LookVector)
							look = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
							local position = root.Position + Vector3.new(0, 2, 0)
							root.CFrame = CFrame.lookAt(position, position + look)
							root.AssemblyLinearVelocity = Vector3.zero
							root.AssemblyAngularVelocity = Vector3.zero
						end
						humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
					end
					local function setRagdoll(enabled)
						standUp()
						if not enabled then return end
						local character, humanoid, root = myCharacter()
						if not humanoid then
							notify("Ragdoll", "Your character isn't ready yet.")
							return false
						end
						claimMovement("Ragdoll")
						ragdoll.humanoid = humanoid
						holdAnimate("Ragdoll", true)
						humanoid.PlatformStand = true
						for _, motor in ipairs(character:GetDescendants()) do
							-- Every joint but the one holding your root part to your body.
							if motor:IsA("Motor6D") and motor.Part0 and motor.Part1 and motor.Part0 ~= root and motor.Part1 ~= root then
								local attachment0 = Instance.new("Attachment")
								attachment0.Name = "SpreadCheeksRagdoll"
								attachment0.CFrame = motor.C0
								attachment0.Parent = motor.Part0
								local attachment1 = Instance.new("Attachment")
								attachment1.Name = "SpreadCheeksRagdoll"
								attachment1.CFrame = motor.C1
								attachment1.Parent = motor.Part1
								local socket = Instance.new("BallSocketConstraint")
								socket.Name = "SpreadCheeksRagdoll"
								socket.Attachment0 = attachment0
								socket.Attachment1 = attachment1
								-- Loose, but not so loose that limbs bend the wrong way round.
								socket.LimitsEnabled = true
								socket.UpperAngle = motor.Name:find("Neck") and 30 or 70
								socket.TwistLimitsEnabled = true
								socket.TwistLowerAngle = -40
								socket.TwistUpperAngle = 40
								socket.Parent = motor.Part0
								motor.Enabled = false
								table.insert(ragdoll.joints, { motor = motor, socket = socket, attachment0 = attachment0, attachment1 = attachment1 })
							end
						end
						-- Loose limbs have to hit the floor to flop about on it.
						for _, part in ipairs(character:GetChildren()) do
							if part:IsA("BasePart") and part ~= root then
								ragdoll.collisions[part] = part.CanCollide
								part.CanCollide = true
							end
						end
						-- A shove to topple you over.
						root.AssemblyLinearVelocity += flat(root.CFrame.LookVector) * 6 + Vector3.new(0, 4, 0)
						root.AssemblyAngularVelocity = root.CFrame.RightVector * -4
						-- Space gets you back up; one already held when it starts doesn't count.
						ragdoll.spaceDown = true
						ragdoll.loop = RunService.Heartbeat:Connect(function()
							if not humanoid.Parent or humanoid.Health <= 0 then return switchOff("Ragdoll") end
							humanoid.PlatformStand = true
							local down = UserInputService:IsKeyDown(Enum.KeyCode.Space) and not UserInputService:GetFocusedTextBox()
							if down and not ragdoll.spaceDown then return switchOff("Ragdoll") end
							ragdoll.spaceDown = down
						end)
					end
					addQuickToggle(trollTabs.tricks, "Ragdoll", "Go limp and flop over like a ragdoll. Jump to get back up", setRagdoll, "person-standing", "bone")
				end

				-- Spin: turns you round and round like a top. The speed is in its settings card. During
				-- Handstand it's a headspin.
				local spinState = { enabled = false, mover = nil }
				local function attachSpin()
					if spinState.mover then
						spinState.mover:Destroy()
						spinState.mover = nil
					end
					if not spinState.enabled then return end
					local _, _, root = myCharacter()
					if not root then return end
					local mover = Instance.new("BodyAngularVelocity")
					mover.Name = "SpreadCheeksSpin"
					mover.MaxTorque = Vector3.new(0, math.huge, 0)
					mover.AngularVelocity = Vector3.new(0, featureSettings.trollSpinSpeed, 0)
					mover.Parent = root
					spinState.mover = mover
				end
				table.insert(respawnHandlers, attachSpin)
				function trolling.setSpinSpeed(value)
					featureSettings.trollSpinSpeed = math.clamp(tonumber(value) or 20, 1, 100)
					if spinState.mover then
						spinState.mover.AngularVelocity = Vector3.new(0, featureSettings.trollSpinSpeed, 0)
					end
				end
				addQuickToggle(trollTabs.tricks, "Spin", "Spin like a top. Right-click for the speed", function(enabled)
					spinState.enabled = enabled
					attachSpin()
				end, "refresh-cw", "rotate-cw")

				-- Vibrate: you shake on the spot like a phone going off. Each frame takes back the last nudge,
				-- so you don't drift.
				local vibrateState = { loop = nil, offset = nil }
				addQuickToggle(trollTabs.tricks, "Vibrate", "Shake on the spot like a phone going off", function(enabled)
					if vibrateState.loop then
						vibrateState.loop:Disconnect()
						vibrateState.loop = nil
					end
					vibrateState.offset = nil
					if not enabled then return end
					vibrateState.loop = RunService.Heartbeat:Connect(function()
						local _, _, root = myCharacter()
						if not root then return end
						local offset = Vector3.new((math.random() - 0.5) * 0.35, (math.random() - 0.5) * 0.2, (math.random() - 0.5) * 0.35)
						root.CFrame = root.CFrame + offset - (vibrateState.offset or Vector3.zero)
						vibrateState.offset = offset
					end)
				end, "vibrate", "activity")

				-- Fake Leave: you freeze mid-step as if your game's frozen or your internet's gone, and a couple
				-- of seconds later you vanish, as if you've left. You're tucked away under the map, held still,
				-- and your camera stays where it was as a free camera (Infinite Yield's Freecam), so you can
				-- watch what everyone does. Switching it off puts you back on the exact spot, moving again.
				do
					local leave = { serial = 0, root = nil, home = nil, freecam = false }
					local function setFakeLeave(enabled)
						leave.serial += 1
						local serial = leave.serial
						-- Back: on the spot you left from, moving again, with your own camera.
						local root = leave.root
						leave.root = nil
						if root then
							if root.Parent and leave.home then
								root.CFrame = leave.home
								root.AssemblyLinearVelocity = Vector3.zero
							end
							pcall(function() root.Anchored = false end)
						end
						if leave.freecam then
							leave.freecam = false
							execCmd("unfreecam", localPlayer, true)
						end
						if trolling.statue and not (quickToggleByName["Statue"] and quickToggleByName["Statue"].state) then
							trolling.statue = false
							updateSpeedLoop()
						end
						leave.home = nil
						if not enabled then return end
						local _, _, myRoot = myCharacter()
						if not myRoot then
							notify("Fake Leave", "Your character isn't ready yet.")
							return false
						end
						claimMovement("Fake Leave")
						-- Frozen, like a lag-out: rooted to the spot and stopped mid-pose.
						leave.root, leave.home = myRoot, myRoot.CFrame
						myRoot.AssemblyLinearVelocity = Vector3.zero
						myRoot.Anchored = true
						trolling.statue = true
						updateSpeedLoop()
						task.delay(2.5, function()
							if leave.serial ~= serial or not myRoot.Parent then return end
							-- Gone: the camera stays as a free camera, and you go under the map (never so
							-- far down that the void, or Anti-Void, takes you).
							if not fcRunning then
								leave.freecam = true
								execCmd("freecam", localPlayer, true)
							end
							local home = leave.home.Position
							myRoot.CFrame = CFrame.new(home.X, math.max(home.Y - 300, workspace.FallenPartsDestroyHeight + 60), home.Z)
							notify("Fake Leave", "You've \"left\". Look round with the free camera, and switch Fake Leave off to come back.", 4)
						end)
					end
					addQuickToggle(trollTabs.tricks, "Fake Leave", "Freeze like you've lagged out, then vanish as if you left, and watch from where you were. Switch it off to come back", setFakeLeave, "log-out", "wifi-off")
					table.insert(respawnHandlers, function() switchOff("Fake Leave") end)
				end

				withIcon(trollTabs.tricks, "CreateSection", { name = "Ways to get around" }, "plane", "rocket")
				-- Infinite Yield's swim, which turns gravity off and keeps you swimming. It ends when you die.
				addQuickToggle(trollTabs.tricks, "Swim in Air", "Swim through the air like it's water. Hold Space to rise", function(enabled)
					if enabled then claimMovement("Swim in Air") end
					execCmd(enabled and "swim" or "unswim", localPlayer, true)
				end, "waves")
				table.insert(respawnHandlers, function() switchOff("Swim in Air") end)

				-- The takeovers (Handstand, Crawl, Superman, Helicopter, Bow Down and Cartwheel Walk) hold your character
				-- themselves: PlatformStand stops the humanoid fighting them, Animate is held so your limbs
				-- keep still (a mode can loop an animation of its own), and every frame the mode's step says
				-- where your root goes. takeoverState.yaw is the way you face, for standing back up after.
				local function endTakeover(name)
					if takeoverState.name ~= name then return end
					takeoverState.name = nil
					if takeoverState.loop then
						takeoverState.loop:Disconnect()
						takeoverState.loop = nil
					end
					if takeoverState.track then
						pcall(function() takeoverState.track:Stop(0.2) end)
						takeoverState.track = nil
					end
					local _, humanoid, root = myCharacter()
					if humanoid then
						humanoid.PlatformStand = false
						root.CFrame = CFrame.new(root.Position + Vector3.new(0, 2.5, 0)) * CFrame.Angles(0, takeoverState.yaw, 0)
						humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
					end
					holdAnimate(name, false)
				end
				-- mode has start(humanoid, root), step(deltaTime, humanoid, root) returning the root's CFrame
				-- (or nil to leave it), and optionally animation = { r15 = id, r6 = id }.
				local function beginTakeover(name, mode)
					if takeoverState.name == name and takeoverState.loop then
						-- Starting again, on a new target: only the loop changes.
						takeoverState.loop:Disconnect()
						takeoverState.loop = nil
					else
						claimMovement(name)
					end
					local _, humanoid, root = myCharacter()
					if not humanoid then
						notify(name, "Your character isn't ready yet.")
						return false
					end
					local look = flat(root.CFrame.LookVector)
					takeoverState.name = name
					takeoverState.yaw = yawOf(look.Magnitude > 0.1 and look or Vector3.new(0, 0, -1))
					holdAnimate(name, true)
					mode.start(humanoid, root)
					if mode.animation and not takeoverState.track then
						local id = isR15(humanoid) and mode.animation.r15 or mode.animation.r6
						takeoverState.track = id and playOnMe("rbxassetid://" .. tostring(id)) or nil
						if takeoverState.track then takeoverState.track.Looped = true end
					end
					takeoverState.loop = RunService.Heartbeat:Connect(function(deltaTime)
						local _, myHumanoid, myRoot = myCharacter()
						if not myHumanoid then return end
						-- A new character ends it.
						if myHumanoid ~= humanoid then return switchOff(name) end
						myHumanoid.PlatformStand = true
						local cframe = mode.step(deltaTime, myHumanoid, myRoot)
						if cframe then
							myRoot.CFrame = cframe
							myRoot.AssemblyLinearVelocity = Vector3.zero
							myRoot.AssemblyAngularVelocity = Vector3.zero
						end
					end)
					return true
				end
				local function takeoverSwitch(name, mode)
					return function(enabled)
						if not enabled then return endTakeover(name) end
						return beginTakeover(name, mode)
					end
				end

				-- Handstand: upside down on your head and hands, legs walking in the air as you go.
				local handstandMode = { animation = { r15 = 507777826, r6 = 180426354 }, position = nil, headHeight = 2.5, moving = nil }
				function handstandMode.start(humanoid, root)
					local head = humanoid.Parent:FindFirstChild("Head")
					local height = head and head:IsA("BasePart") and (head.Position.Y + head.Size.Y / 2 - root.Position.Y) or 2.5
					handstandMode.headHeight = math.clamp(height, 1.5, 4)
					handstandMode.position = root.Position
					handstandMode.moving = nil
				end
				function handstandMode.step(deltaTime, humanoid, root)
					local move = flat(humanoid.MoveDirection)
					local moving = move.Magnitude > 0.05
					if moving then
						handstandMode.position += move * humanoid.WalkSpeed * 0.5 * deltaTime
						takeoverState.yaw = yawOf(move)
					end
					-- Spin on too makes it a headspin.
					if spinState.enabled then takeoverState.yaw += featureSettings.trollSpinSpeed * deltaTime end
					-- The legs only walk while you're moving.
					if takeoverState.track and moving ~= handstandMode.moving then
						takeoverState.track:AdjustSpeed(moving and 1 or 0)
					end
					handstandMode.moving = moving
					local ground = groundBelow(handstandMode.position, { humanoid.Parent })
					local position = handstandMode.position
					handstandMode.position = Vector3.new(position.X, ground and ground + handstandMode.headHeight or position.Y, position.Z)
					return CFrame.new(handstandMode.position) * CFrame.Angles(0, takeoverState.yaw, 0) * CFrame.Angles(0, 0, math.pi)
				end
				addQuickToggle(trollTabs.tricks, "Handstand", "Walk on your head and hands, legs kicking in the air. With Spin on too, it's a headspin", takeoverSwitch("Handstand", handstandMode), "hand", "hand-metal")

				-- Crawl: down on the ground, wriggling along like a worm, sliding on your belly or rolling
				-- along like a log (the style is in its settings card).
				local crawlMode = { position = nil, roll = 0, phase = 0 }
				function crawlMode.start(humanoid, root)
					crawlMode.position = root.Position
					crawlMode.roll, crawlMode.phase = 0, 0
				end
				function crawlMode.step(deltaTime, humanoid, root)
					local style = featureSettings.trollCrawlStyle
					local move = flat(humanoid.MoveDirection)
					if move.Magnitude > 0.05 then
						local speed = humanoid.WalkSpeed * (style == "Belly Slide" and 1.4 or style == "Log Roll" and 0.6 or 0.35)
						local step = move * speed * deltaTime
						crawlMode.position += step
						takeoverState.yaw = yawOf(move)
						crawlMode.roll += step.Magnitude / 0.9
						crawlMode.phase += deltaTime * 9
					end
					local height = style == "Log Roll" and 1 or 0.75
					if style == "Worm" then height += math.max(0, math.sin(crawlMode.phase)) * 0.45 end
					local ground = groundBelow(crawlMode.position, { humanoid.Parent })
					local position = crawlMode.position
					crawlMode.position = Vector3.new(position.X, ground and ground + height or position.Y, position.Z)
					local facing = CFrame.new(crawlMode.position) * CFrame.Angles(0, takeoverState.yaw, 0)
					if style == "Log Roll" then
						-- On your side across the way you're going, rolling over and over.
						return facing * CFrame.Angles(0, 0, math.pi / 2) * CFrame.Angles(0, crawlMode.roll, 0)
					end
					-- Face down and head first; the worm arches as it goes.
					local wiggle = style == "Worm" and math.sin(crawlMode.phase) * math.rad(14) or 0
					return facing * CFrame.Angles(-math.pi / 2 + wiggle, 0, 0)
				end
				addQuickToggle(trollTabs.tricks, "Crawl", "Get down and wriggle along like a worm. Right-click for belly slide or log roll", takeoverSwitch("Crawl", crawlMode), "worm", "bug")

				-- Superman: flying flat out, face down and head first. Your movement keys steer, Space goes
				-- up and Ctrl or Q go down.
				local supermanMode = { animation = { r15 = 616108001, r6 = 180436148 }, position = nil }
				function supermanMode.start(humanoid, root)
					supermanMode.position = root.Position + Vector3.new(0, 3, 0)
				end
				function supermanMode.step(deltaTime, humanoid, root)
					local move = flat(humanoid.MoveDirection)
					local rising = 0
					if not UserInputService:GetFocusedTextBox() then
						if UserInputService:IsKeyDown(Enum.KeyCode.Space) then rising += 1 end
						if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.Q) then rising -= 1 end
					end
					supermanMode.position += (move * 45 + Vector3.new(0, rising * 30, 0)) * deltaTime
					local moving = move.Magnitude > 0.05
					if moving then takeoverState.yaw = yawOf(move) end
					-- A gentle bob while you hover.
					local bob = moving and 0 or math.sin(os.clock() * 2) * 0.3
					return CFrame.new(supermanMode.position + Vector3.new(0, bob, 0)) * CFrame.Angles(0, takeoverState.yaw, 0) * CFrame.Angles(-math.pi / 2, 0, 0)
				end
				addQuickToggle(trollTabs.tricks, "Superman", "Fly flat out like a superhero. Space goes up, Ctrl or Q down", takeoverSwitch("Superman", supermanMode), "plane", "rocket")

				-- Helicopter: hovering above the ground and spinning, arms up like rotor blades. The height is
				-- in its settings card.
				local helicopterMode = { animation = { r15 = 507767968, r6 = 180436148 }, position = nil }
				function helicopterMode.start(humanoid, root)
					helicopterMode.position = root.Position
				end
				function helicopterMode.step(deltaTime, humanoid, root)
					local move = flat(humanoid.MoveDirection)
					local position = helicopterMode.position + move * humanoid.WalkSpeed * deltaTime
					local height = featureSettings.trollHeliHeight
					local ground = groundBelow(position, { humanoid.Parent })
					local targetY = (ground and ground + height or position.Y) + math.sin(os.clock() * 2) * 0.6
					helicopterMode.position = Vector3.new(position.X, position.Y + (targetY - position.Y) * math.min(1, deltaTime * 2.5), position.Z)
					takeoverState.yaw += 16 * deltaTime
					return CFrame.new(helicopterMode.position) * CFrame.Angles(0, takeoverState.yaw, 0)
				end
				addQuickToggle(trollTabs.tricks, "Helicopter", "Hover and spin with your arms up like rotor blades. Right-click for the height", takeoverSwitch("Helicopter", helicopterMode), "fan", "tornado")

				-- Marble Ball (from your marble ball script): your root part turns into a big invisible ball
				-- and you roll about on it, your body tumbling round with it for everyone to see. The
				-- movement keys roll it the way the camera faces, and jump bounces it when it's on the
				-- ground. Speed, jump and ball size are in its settings card.
				local marbleState = { enabled = false, character = nil, root = nil, saved = nil, connections = {}, lastJump = 0 }
				-- Which way to roll: your movement direction, or the WASD keys against the camera, for
				-- games that don't pass your movement on while you're rolling.
				local function marbleDirection(humanoid)
					local direction = flat(humanoid.MoveDirection)
					if direction.Magnitude > 0.05 then return direction.Unit end
					local camera = workspace.CurrentCamera
					if not camera or UserInputService:GetFocusedTextBox() then return Vector3.zero end
					local look, right = flat(camera.CFrame.LookVector), flat(camera.CFrame.RightVector)
					local keys = Vector3.zero
					if UserInputService:IsKeyDown(Enum.KeyCode.W) then keys += look end
					if UserInputService:IsKeyDown(Enum.KeyCode.S) then keys -= look end
					if UserInputService:IsKeyDown(Enum.KeyCode.D) then keys += right end
					if UserInputService:IsKeyDown(Enum.KeyCode.A) then keys -= right end
					return keys.Magnitude > 0.05 and keys.Unit or Vector3.zero
				end
				-- Puts your character back as it was: the root's shape, size and collisions, standing up,
				-- and the camera on you again.
				local function stopMarble()
					for _, connection in ipairs(marbleState.connections) do
						connection:Disconnect()
					end
					table.clear(marbleState.connections)
					local saved, root, character = marbleState.saved, marbleState.root, marbleState.character
					marbleState.saved, marbleState.root, marbleState.character = nil, nil, nil
					if saved and root and root.Parent then
						pcall(function()
							root.Shape = saved.shape
							root.Size = saved.size
							root.CanCollide = saved.rootCollides
							root.AssemblyAngularVelocity = Vector3.zero
						end)
						for part, canCollide in pairs(saved.collisions) do
							if part.Parent then part.CanCollide = canCollide end
						end
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						if humanoid and humanoid.Health > 0 then
							humanoid.PlatformStand = false
							root.CFrame = CFrame.new(root.Position + Vector3.new(0, 1.5, 0)) * CFrame.Angles(0, saved.yaw, 0)
							humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
						end
						local camera = workspace.CurrentCamera
						if camera and humanoid and camera.CameraSubject == root then camera.CameraSubject = humanoid end
					end
					holdAnimate("Marble Ball", false)
				end
				local function startMarble()
					stopMarble()
					local character, humanoid = myCharacter()
					local root = character and character:FindFirstChild("HumanoidRootPart")
					if not humanoid or not root then return false end
					local look = flat(root.CFrame.LookVector)
					local saved = {
						shape = root.Shape, size = root.Size, rootCollides = root.CanCollide, collisions = {},
						yaw = yawOf(look.Magnitude > 0.1 and look or Vector3.new(0, 0, -1)),
					}
					for _, part in ipairs(character:GetDescendants()) do
						if part:IsA("BasePart") and part ~= root then saved.collisions[part] = part.CanCollide end
					end
					marbleState.saved, marbleState.root, marbleState.character = saved, root, character
					holdAnimate("Marble Ball", true)
					local size = featureSettings.trollMarbleSize
					root.Shape = Enum.PartType.Ball
					root.Size = Vector3.new(size, size, size)
					root.CanCollide = true
					-- The bigger ball sits on the ground rather than inside it.
					local ground = groundBelow(root.Position, { character })
					if ground then
						root.CFrame = root.CFrame.Rotation + Vector3.new(root.Position.X, ground + size / 2 + 0.1, root.Position.Z)
					end
					local camera = workspace.CurrentCamera
					if camera then camera.CameraSubject = root end
					local rayParams = RaycastParams.new()
					rayParams.FilterType = Enum.RaycastFilterType.Exclude
					rayParams.FilterDescendantsInstances = { character }
					-- Only the ball touches anything; your body rides along with it. The humanoid keeps
					-- turning collisions back on, so they're switched off again every frame.
					table.insert(marbleState.connections, RunService.Stepped:Connect(function()
						for part in pairs(saved.collisions) do
							if part.Parent then part.CanCollide = false end
						end
						root.CanCollide = true
						humanoid.PlatformStand = true
					end))
					table.insert(marbleState.connections, RunService.RenderStepped:Connect(function(deltaTime)
						if not root.Parent then return end
						local direction = marbleDirection(humanoid)
						if direction.Magnitude == 0 then return end
						-- Spinning about the line across your direction rolls the ball along it. The speed
						-- setting is how fast it speeds up, and half of it is the fastest it spins.
						local speed = featureSettings.trollMarbleSpeed
						local spin = root.AssemblyAngularVelocity + Vector3.new(direction.Z, 0, -direction.X) * speed * deltaTime
						if spin.Magnitude > speed * 0.5 then spin = spin.Unit * speed * 0.5 end
						root.AssemblyAngularVelocity = spin
					end))
					table.insert(marbleState.connections, UserInputService.JumpRequest:Connect(function()
						if UserInputService:GetFocusedTextBox() or not root.Parent or os.clock() - marbleState.lastJump < 0.25 then return end
						-- Only off the ground, like in your script.
						local reach = root.Size.Y / 2 + 0.3
						if workspace:Raycast(root.Position, Vector3.new(0, -reach, 0), rayParams) then
							marbleState.lastJump = os.clock()
							root.AssemblyLinearVelocity += Vector3.new(0, featureSettings.trollMarbleJump, 0)
						end
					end))
					table.insert(marbleState.connections, humanoid.Died:Connect(stopMarble))
					return true
				end
				function trolling.setMarbleSize(size)
					featureSettings.trollMarbleSize = math.clamp(tonumber(size) or 5, 3, 10)
					local root = marbleState.root
					if root and root.Parent then
						local diameter = featureSettings.trollMarbleSize
						root.Size = Vector3.new(diameter, diameter, diameter)
					end
				end
				-- While the switch is on, each new character rolls too.
				table.insert(respawnHandlers, function()
					if marbleState.enabled then startMarble() end
				end)
				addQuickToggle(trollTabs.tricks, "Marble Ball", "Roll around on a big ball, tumbling along for everyone to see. Right-click for speed, jump and size", function(enabled)
					marbleState.enabled = enabled
					if not enabled then return stopMarble() end
					claimMovement("Marble Ball")
					if not startMarble() then
						marbleState.enabled = false
						notify("Marble Ball", "Your character isn't ready yet.")
						return false
					end
				end, "globe", "circle-dot")

				-- Roomba: you lie face down and slide about the floor by yourself like a robot vacuum, going
				-- straight until you bump into something, then turning on the spot and heading off a new way.
				-- Like a real one, it won't drive off a ledge. It moves you by velocity, the way Orbit does,
				-- so everyone sees a smooth slide. Its speed is in its settings card.
				local roombaState = { loop = nil, humanoid = nil, heading = nil, turnFrom = nil, turnAngle = nil, turnStart = 0 }
				local roombaParams = RaycastParams.new()
				roombaParams.FilterType = Enum.RaycastFilterType.Exclude
				local function stopRoomba()
					if roombaState.loop then
						roombaState.loop:Disconnect()
						roombaState.loop = nil
					end
					holdAnimate("Roomba", false)
					local humanoid = roombaState.humanoid
					roombaState.humanoid = nil
					if not humanoid or not humanoid.Parent or humanoid.Health <= 0 then return end
					local root = getRoot(humanoid.Parent)
					humanoid.PlatformStand = false
					if root then
						root.AssemblyLinearVelocity = Vector3.zero
						root.AssemblyAngularVelocity = Vector3.zero
						-- Back on your feet, facing the way you were going.
						local heading = roombaState.heading or Vector3.new(0, 0, -1)
						local standing = root.Position + Vector3.new(0, 2.5, 0)
						root.CFrame = CFrame.lookAt(standing, standing + heading)
					end
					humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
				end
				-- Something in the way, or the floor running out, this far ahead.
				local function roombaBlocked(character, position, heading, ground)
					roombaParams.FilterDescendantsInstances = { character }
					for _, height in ipairs({ 0.9, 2 }) do
						local wall = workspace:Raycast(Vector3.new(position.X, ground + height, position.Z), heading * 3.2, roombaParams)
						-- Ramps and gentle slopes don't count; walls and steps too high to slide up do.
						if wall and wall.Normal.Y < 0.7 then return true end
					end
					local ahead = position + heading * 3
					local floor = groundBelow(Vector3.new(ahead.X, ground + 1, ahead.Z), { character })
					return not floor or floor < ground - 2.5
				end
				local function setRoomba(enabled)
					stopRoomba()
					if not enabled then return end
					local _, humanoid, root = myCharacter()
					if not humanoid then
						notify("Roomba", "Your character isn't ready yet.")
						return false
					end
					claimMovement("Roomba")
					local look = flat(root.CFrame.LookVector)
					roombaState.humanoid = humanoid
					roombaState.heading = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
					roombaState.turnAngle = nil
					holdAnimate("Roomba", true)
					roombaState.loop = RunService.Heartbeat:Connect(function(deltaTime)
						local character, myHumanoid, myRoot = myCharacter()
						if not myHumanoid then return end
						-- A new character ends it.
						if myHumanoid ~= roombaState.humanoid then return switchOff("Roomba") end
						myHumanoid.PlatformStand = true
						myRoot.AssemblyAngularVelocity = Vector3.zero
						local now = os.clock()
						local position = myRoot.Position
						local ground = groundBelow(position, { character })
						local speed = 0
						if roombaState.turnAngle then
							-- Turning on the spot after a bump, then off again once it's round.
							local progress = math.clamp((now - roombaState.turnStart) / 0.6, 0, 1)
							roombaState.heading = CFrame.Angles(0, roombaState.turnAngle * progress, 0):VectorToWorldSpace(roombaState.turnFrom)
							if progress >= 1 then roombaState.turnAngle = nil end
						elseif ground and roombaBlocked(character, position, roombaState.heading, ground) then
							-- Bump: a new way to go, a bit over a quarter turn up to right round, either way.
							roombaState.turnFrom = roombaState.heading
							roombaState.turnAngle = math.rad(math.random(100, 180)) * (math.random() < 0.5 and -1 or 1)
							roombaState.turnStart = now
						else
							speed = featureSettings.trollRoombaSpeed
						end
						-- Lying flat just off the floor, or dropping when there's no floor under you.
						local wantedY = ground and ground + 0.75 or position.Y - 30 * deltaTime
						local rise = math.clamp((wantedY - position.Y) / math.max(deltaTime, 1 / 120), -60, 60)
						myRoot.AssemblyLinearVelocity = roombaState.heading * speed + Vector3.new(0, rise, 0)
						-- Face down and head first; only the facing changes here, physics does the moving.
						myRoot.CFrame = CFrame.lookAt(position, position + roombaState.heading) * CFrame.Angles(-math.pi / 2, 0, 0)
					end)
				end
				addQuickToggle(trollTabs.tricks, "Roomba", "Slide about the floor by yourself like a robot vacuum, bouncing off walls. Right-click for the speed", setRoomba, "disc", "circle-dot")

				-- Two more silly walks, made here (after the takeovers they use) so they come at the end of
				-- Silly walks in Walks & Moves.
				-- Penguin Waddle: you rock from side to side as you walk, leaning forwards a touch, like a
				-- penguin. Only while you're walking on the ground; standing still, you stand up straight.
				do
					local waddle = { loop = nil, phase = 0 }
					addQuickToggle(trollTabs.walks, "Penguin Waddle", "Rock from side to side as you walk, like a penguin", function(enabled)
						if waddle.loop then
							waddle.loop:Disconnect()
							waddle.loop = nil
						end
						if not enabled then return end
						claimMovement("Penguin Waddle")
						waddle.phase = 0
						waddle.loop = RunService.Heartbeat:Connect(function(deltaTime)
							local _, humanoid, root = myCharacter()
							if not humanoid or humanoid.Sit or humanoid.PlatformStand or humanoid.FloorMaterial == Enum.Material.Air then return end
							local look = flat(root.CFrame.LookVector)
							if flat(humanoid.MoveDirection).Magnitude < 0.1 or look.Magnitude < 0.1 then
								waddle.phase = 0
								return
							end
							-- Two and a half waddles a second, tipping 14 degrees each way.
							waddle.phase = (waddle.phase + deltaTime * math.pi * 5) % (math.pi * 2)
							root.CFrame = CFrame.lookAt(root.Position, root.Position + look) * CFrame.Angles(-math.rad(5), 0, math.sin(waddle.phase) * math.rad(14))
							root.AssemblyAngularVelocity = Vector3.zero
						end)
					end, "bird", "footprints")
				end

				-- Cartwheel Walk: you cartwheel along instead of walking, side-on to the way you're going and
				-- turning over towards it, a full turn every five studs. When you stop, you finish the turn
				-- you're in and stand up. It holds your character itself, like the takeovers.
				do
					local cartwheelMode = { position = nil, turned = 0, forward = Vector3.new(1, 0, 0), standing = 3 }
					function cartwheelMode.start(humanoid, root)
						cartwheelMode.position = root.Position
						cartwheelMode.turned = 0
						-- Until you move, the way you'd go is to your right.
						local look = flat(root.CFrame.LookVector)
						cartwheelMode.forward = look.Magnitude > 0.1 and Vector3.new(-look.Z, 0, look.X).Unit or Vector3.new(1, 0, 0)
						cartwheelMode.standing = isR15(humanoid) and (humanoid.HipHeight + root.Size.Y / 2) or 3
					end
					function cartwheelMode.step(deltaTime, humanoid, root)
						local move = flat(humanoid.MoveDirection)
						local full = math.pi * 2
						if move.Magnitude > 0.05 then
							local step = move * humanoid.WalkSpeed * 0.9 * deltaTime
							cartwheelMode.position += step
							cartwheelMode.forward = move.Unit
							cartwheelMode.turned = (cartwheelMode.turned + step.Magnitude / 5 * full) % full
						elseif cartwheelMode.turned > 0 then
							-- Finishing the turn, back onto your feet.
							cartwheelMode.turned += math.min(full - cartwheelMode.turned, full * deltaTime / 0.6)
							if cartwheelMode.turned >= full - 0.001 then cartwheelMode.turned = 0 end
						end
						local ground = groundBelow(cartwheelMode.position, { humanoid.Parent })
						local position = cartwheelMode.position
						cartwheelMode.position = Vector3.new(position.X, ground and ground + cartwheelMode.standing or position.Y, position.Z)
						-- Side-on, with the way you're going on your right, tipping over towards it.
						local forward = cartwheelMode.forward
						local facing = Vector3.new(forward.Z, 0, -forward.X)
						takeoverState.yaw = yawOf(facing)
						return CFrame.lookAt(cartwheelMode.position, cartwheelMode.position + facing) * CFrame.Angles(0, 0, -cartwheelMode.turned)
					end
					addQuickToggle(trollTabs.walks, "Cartwheel Walk", "Cartwheel along instead of walking, sideways the way you go", takeoverSwitch("Cartwheel Walk", cartwheelMode), "rotate-3d", "refresh-ccw")
				end

				-- Moves: one-off tricks. They're kept in trolling.moves for the Favourites bar too, along
				-- with Stop Animations from further up.
				withIcon(trollTabs.walks, "CreateSection", { name = "Moves" }, "zap", "sparkles")
				trollTabs.walks:CreateText({
					text = "Click the key box on a move to put it on a key. They're commands too (frontflip, backflip, cartwheel, triplespin, trip, tumble, diveroll, groundpound, windmill, yeet, launch, fakeout).",
				})
				trolling.moves = {
					{ name = "Front Flip", description = "A jump with a full turn forwards", icons = { "rotate-cw", "refresh-cw" }, run = function() trolling.flip("front") end },
					{ name = "Back Flip", description = "A jump with a full turn backwards", icons = { "rotate-ccw", "refresh-ccw" }, run = function() trolling.flip("back") end },
					{ name = "Cartwheel", description = "A jump with a full turn sideways", icons = { "rotate-3d", "refresh-ccw" }, run = function() trolling.flip("side") end },
					{ name = "Triple Spin", description = "A jump with three spins, like a figure skater", icons = { "refresh-cw", "tornado" }, run = function() trolling.flip("spin") end },
					{ name = "Trip", description = "Fall flat over", icons = { "footprints" }, run = function() execCmd("trip", localPlayer, true) end },
					{ name = "Tumble", description = "Go head over heels in a heap, then get back up", icons = { "dices", "shuffle" }, run = function() trolling.tumble() end },
					{ name = "Dive Roll", description = "Dive forwards, flat out, and roll back up onto your feet", icons = { "arrow-down-right", "rotate-cw" }, run = function() trolling.diveRoll() end },
					{ name = "Ground Pound", description = "Jump, spin in mid-air and slam straight down", icons = { "arrow-down-to-line", "chevrons-down" }, run = function() trolling.groundPound() end },
					{ name = "Windmill", description = "A breakdance spin on your back, legs in the air, then back up", icons = { "fan", "rotate-cw" }, run = function() trolling.windmill() end },
					{ name = "Yeet", description = "Throw yourself forwards, tumbling through the air", icons = { "wind", "rocket" }, run = function() trolling.yeet() end },
					{ name = "Launch", description = "Shoots you high into the air. Some games give fall damage", icons = { "rocket" }, run = function() trolling.launch() end },
					{ name = "Fakeout", description = "Vanish into the void for a second, then pop back where you were", icons = { "ghost" }, run = function() execCmd("fakeout", localPlayer, true) end },
				}
				-- Each move's row is kept (move.object) so it gets a key box like the switches.
				for _, move in ipairs(trolling.moves) do
					move.object = withIcon(trollTabs.walks, "CreateButton", {
						name = move.name,
						description = move.description,
						callback = move.run,
					}, table.unpack(move.icons))
				end
				table.insert(trolling.moves, { name = "Stop Animations", icons = { "circle-stop", "square" }, run = function() trolling.stopAnimations() end, object = trolling.stopAnimationsButton })

				-- Parkour: jump again in mid-air (up to three times, in its settings card), kick off a wall
				-- you're next to, and dash the way you're going with the dash key (Q to start with), once
				-- per jump. It all moves your own character, so everyone sees it. Keys are read straight
				-- from the keyboard each frame, so a game that takes Space for itself doesn't stop it.
				withIcon(trollTabs.walks, "CreateSection", { name = "Parkour" }, "wind", "footprints")
				do
					local parkour = {
						airJumps = 0, lastWallJump = 0, lastDash = 0, dashUntil = 0, dashVelocity = Vector3.zero,
						dashedInAir = false, spaceDown = false, dashDown = false, keyName = nil, keyCode = nil,
					}
					local wallParams = RaycastParams.new()
					wallParams.FilterType = Enum.RaycastFilterType.Exclude
					-- How fast a jump sends you up, going by the humanoid's own jump settings.
					local function jumpSpeed(humanoid)
						if humanoid.UseJumpPower then return math.max(humanoid.JumpPower, 40) end
						return math.max(math.sqrt(2 * workspace.Gravity * humanoid.JumpHeight), 40)
					end
					-- Which way a wall right beside you faces (the way off it), or nil with no wall there.
					local function wallBeside(character, root)
						wallParams.FilterDescendantsInstances = { character }
						local look = flat(root.CFrame.LookVector)
						look = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
						local nearest, nearestDistance = nil, math.huge
						for turn = 0, 7 do
							local direction = CFrame.Angles(0, turn * math.pi / 4, 0):VectorToWorldSpace(look)
							local hit = workspace:Raycast(root.Position, direction * 2.6, wallParams)
							if hit and math.abs(hit.Normal.Y) < 0.3 then
								local distance = (hit.Position - root.Position).Magnitude
								if distance < nearestDistance then nearest, nearestDistance = hit.Normal, distance end
							end
						end
						return nearest
					end
					-- Whether a key has just gone down: down now, and not on the frame before.
					local function pressed(field, down)
						local wasDown = parkour[field]
						parkour[field] = down
						return down and not wasDown
					end
					local function step()
						local character, humanoid, root = myCharacter()
						if not humanoid then return end
						local now = os.clock()
						local grounded = humanoid.FloorMaterial ~= Enum.Material.Air
						if grounded then parkour.airJumps, parkour.dashedInAir = 0, false end
						if featureSettings.parkourDashKey ~= parkour.keyName then
							parkour.keyName = featureSettings.parkourDashKey
							local keyOk, keyCode = pcall(function() return Enum.KeyCode[parkour.keyName] end)
							parkour.keyCode = keyOk and keyCode or nil
						end
						local typing = UserInputService:GetFocusedTextBox() ~= nil
						local jumpPressed = pressed("spaceDown", not typing and UserInputService:IsKeyDown(Enum.KeyCode.Space))
						local dashPressed = pressed("dashDown", not typing and parkour.keyCode ~= nil and UserInputService:IsKeyDown(parkour.keyCode))
						-- Not while sitting, flying, or in one of the tricks that hold you themselves.
						if humanoid.Sit or humanoid.PlatformStand then return end
						-- Space in the air: off a wall if you're next to one, or else another jump.
						if jumpPressed and not grounded then
							local wall = featureSettings.parkourWallJump and now - parkour.lastWallJump > 0.2 and wallBeside(character, root)
							if wall then
								parkour.lastWallJump = now
								-- Kicking off a wall gives your air jumps back.
								parkour.airJumps = 0
								local away = flat(wall)
								away = away.Magnitude > 0.1 and away.Unit or -flat(root.CFrame.LookVector)
								humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
								root.AssemblyLinearVelocity = away * 38 + Vector3.new(0, jumpSpeed(humanoid), 0)
								root.CFrame = CFrame.lookAt(root.Position, root.Position + away)
							elseif featureSettings.parkourDoubleJump and parkour.airJumps < featureSettings.parkourAirJumps then
								parkour.airJumps += 1
								humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
								local velocity = root.AssemblyLinearVelocity
								root.AssemblyLinearVelocity = Vector3.new(velocity.X, jumpSpeed(humanoid), velocity.Z)
							end
						end
						-- The dash key: a quick burst the way you're moving (or facing), once per jump.
						if dashPressed and featureSettings.parkourDash and now - parkour.lastDash > 0.6 and (grounded or not parkour.dashedInAir) then
							local direction = flat(humanoid.MoveDirection)
							if direction.Magnitude < 0.1 then
								local camera = workspace.CurrentCamera
								direction = flat(camera and camera.CFrame.LookVector or root.CFrame.LookVector)
							end
							if direction.Magnitude > 0.1 then
								parkour.lastDash = now
								parkour.dashUntil = now + 0.18
								parkour.dashVelocity = direction.Unit * 75
								if not grounded then parkour.dashedInAir = true end
							end
						end
						if now < parkour.dashUntil then
							-- Level along the ground; in the air, rising a touch so a dash carries you over a gap.
							local rise = root.AssemblyLinearVelocity.Y
							if not grounded then rise = math.max(rise, 4) end
							root.AssemblyLinearVelocity = parkour.dashVelocity + Vector3.new(0, rise, 0)
						end
					end
					addQuickToggle(trollTabs.walks, "Parkour Mode", "Double jump, kick off walls and dash. Right-click for the moves and the dash key", function(enabled)
						if not enabled then return afterControls("SpreadCheeksParkour", nil) end
						claimMovement("Parkour Mode")
						-- A key already held when it's switched on doesn't count as a press.
						parkour.spaceDown = UserInputService:IsKeyDown(Enum.KeyCode.Space)
						parkour.dashDown = true
						afterControls("SpreadCheeksParkour", step)
					end, "wind", "chevrons-up")
				end

				-- Grapple Hook: hold the grapple key (G to start with) to fire a hook at whatever your mouse
				-- points at, and hang on for as long as it's held. Swing (to start with) swings you on the
				-- rope like a pendulum while reeling you in; Pull flies you straight there. The style, the
				-- key, the range and the pull speed are in its settings card. The rope is only drawn on your
				-- screen, but everyone sees you fly. The hook moves with what it caught, so it holds on to
				-- moving platforms, vehicles and players.
				do
					local grapple = {
						part = nil, offset = nil, length = 0, keyDown = false, keyName = nil, keyCode = nil,
						beam = nil, rootAttachment = nil, hookAttachment = nil,
					}
					local grappleParams = RaycastParams.new()
					grappleParams.FilterType = Enum.RaycastFilterType.Exclude
					local function letGo()
						grapple.part = nil
						for _, field in ipairs({ "beam", "rootAttachment", "hookAttachment" }) do
							if grapple[field] then
								grapple[field]:Destroy()
								grapple[field] = nil
							end
						end
					end
					-- Where the hook is now, following the part it caught; nil once that part is gone.
					local function hookPosition()
						local part = grapple.part
						if not part or not part.Parent then return nil end
						return part.CFrame:PointToWorldSpace(grapple.offset)
					end
					-- Fires at whatever's under the mouse, within range. Nothing happens on a miss.
					local function fire(character, humanoid, root)
						local camera = workspace.CurrentCamera
						if not camera then return end
						local mouse = UserInputService:GetMouseLocation()
						local ray = camera:ViewportPointToRay(mouse.X, mouse.Y)
						grappleParams.FilterDescendantsInstances = { character }
						-- Far enough to reach the full range from you, wherever the camera is.
						local reach = featureSettings.grappleRange + (camera.CFrame.Position - root.Position).Magnitude
						local hit = workspace:Raycast(ray.Origin, ray.Direction * reach, grappleParams)
						if not hit or (hit.Position - root.Position).Magnitude > featureSettings.grappleRange then return end
						letGo()
						grapple.part = hit.Instance
						grapple.offset = hit.Instance.CFrame:PointToObjectSpace(hit.Position)
						-- A bit shorter than the gap, so the rope lifts you as it catches.
						grapple.length = (hit.Position - root.Position).Magnitude * 0.85
						-- The rope, drawn on your screen only.
						local rootAttachment = Instance.new("Attachment")
						rootAttachment.Parent = root
						local hookAttachment = Instance.new("Attachment")
						hookAttachment.WorldPosition = hit.Position
						hookAttachment.Parent = workspace.Terrain
						local beam = Instance.new("Beam")
						beam.Attachment0 = rootAttachment
						beam.Attachment1 = hookAttachment
						beam.Width0, beam.Width1 = 0.12, 0.12
						beam.FaceCamera = true
						beam.Segments = 1
						beam.LightEmission = 0.4
						beam.Color = ColorSequence.new(auxiliaryUiTheme.AccentText)
						-- Named so FPS Boost leaves it alone.
						beam.Name = "SpreadCheeksRope"
						beam.Parent = rootAttachment
						grapple.rootAttachment, grapple.hookAttachment, grapple.beam = rootAttachment, hookAttachment, beam
						-- Off the ground, so the rope can carry you.
						if humanoid.FloorMaterial ~= Enum.Material.Air then humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end
					end
					local function step(deltaTime)
						local character, humanoid, root = myCharacter()
						if not humanoid then return letGo() end
						if featureSettings.grappleKey ~= grapple.keyName then
							grapple.keyName = featureSettings.grappleKey
							local keyOk, keyCode = pcall(function() return Enum.KeyCode[grapple.keyName] end)
							grapple.keyCode = keyOk and keyCode or nil
						end
						local down = UserInputService:GetFocusedTextBox() == nil and grapple.keyCode ~= nil and UserInputService:IsKeyDown(grapple.keyCode)
						local blocked = humanoid.Sit or humanoid.PlatformStand
						if down and not grapple.keyDown and not blocked then
							fire(character, humanoid, root)
						elseif (not down and grapple.keyDown) or blocked then
							letGo()
						end
						grapple.keyDown = down
						local hook = hookPosition()
						if not hook then return letGo() end
						-- A new character leaves the old rope behind.
						if grapple.rootAttachment.Parent ~= root then return letGo() end
						grapple.hookAttachment.WorldPosition = hook
						local offset = hook - root.Position
						local distance = offset.Magnitude
						local frame = math.max(deltaTime, 1 / 120)
						if featureSettings.grappleStyle == "Pull" then
							-- Straight there, then hanging on at the hook.
							root.AssemblyLinearVelocity = distance > 3 and offset.Unit * math.min(featureSettings.grapplePullSpeed, distance / frame) or Vector3.zero
							return
						end
						-- Swing: reeling in as you go, and the rope only ever pulls, it never pushes.
						grapple.length = math.max(4, grapple.length - 10 * deltaTime)
						if distance > grapple.length and distance > 0.1 then
							local outward = -offset.Unit
							local velocity = root.AssemblyLinearVelocity
							local away = velocity:Dot(outward)
							if away > 0 then velocity -= outward * away end
							-- And back to the rope's length if you've stretched past it.
							velocity -= outward * math.min((distance - grapple.length) / frame * 0.5, 60)
							root.AssemblyLinearVelocity = velocity
						end
					end
					addQuickToggle(trollTabs.walks, "Grapple Hook", "Hold G and point to swing on a rope to anything. Right-click for swing or pull, the key and the range", function(enabled)
						letGo()
						if not enabled then return afterControls("SpreadCheeksGrapple", nil) end
						claimMovement("Grapple Hook")
						-- A key already held when it's switched on doesn't fire.
						grapple.keyDown = true
						afterControls("SpreadCheeksGrapple", step)
					end, "anchor", "link")
				end

				-- Wall Walk: walk into a wall and you climb straight up it like Spider-Man, sideways too as
				-- you steer along it, and pull yourself over the top. Climb up into a ceiling and you hang
				-- under it upside down and crawl along it until it ends or you jump. Letting go of the keys
				-- on a wall lets go of it, and jumping kicks you off. It's your own character, so everyone
				-- sees you climb. On a wall, as under a ceiling, you go limp (PlatformStand): standing, the
				-- humanoid holds itself at its height over the floor, which would pull you straight back down.
				do
					local wallParams = RaycastParams.new()
					wallParams.FilterType = Enum.RaycastFilterType.Exclude
					local climbIds = { r15 = 507765644, r6 = 180436334 }
					local wall = { track = nil, ceiling = false, climbing = false, ledgeUntil = 0, spaceDown = true, yaw = 0 }
					local function stopClimbAnimation()
						if wall.track then
							wall.track:Stop(0.2)
							wall.track = nil
						end
					end
					local function climbAnimation(humanoid, speed)
						if not wall.track then
							wall.track = playOnMe("rbxassetid://" .. (isR15(humanoid) and climbIds.r15 or climbIds.r6))
						end
						if wall.track then wall.track:AdjustSpeed(speed) end
					end
					local function leaveCeiling(humanoid, root)
						if not wall.ceiling then return end
						wall.ceiling = false
						humanoid.PlatformStand = false
						-- The right way up as you drop.
						root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, wall.yaw, 0)
						humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
					end
					local function leaveWall(humanoid)
						if not wall.climbing then return end
						wall.climbing = false
						humanoid.PlatformStand = false
						humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
					end
					-- The ceiling just over you (a surface facing down), or nil.
					local function ceilingAbove(root)
						local hit = workspace:Raycast(root.Position, Vector3.new(0, 4.5, 0), wallParams)
						return hit and hit.Normal.Y < -0.7 and hit or nil
					end
					local function step(deltaTime)
						local character, humanoid, root = myCharacter()
						if not humanoid then
							stopClimbAnimation()
							wall.ceiling, wall.climbing = false, false
							return
						end
						wallParams.FilterDescendantsInstances = { character }
						local move = flat(humanoid.MoveDirection)
						local speed = math.max(humanoid.WalkSpeed, 8)
						local frame = math.max(deltaTime, 1 / 120)
						local spaceDown = UserInputService:IsKeyDown(Enum.KeyCode.Space) and not UserInputService:GetFocusedTextBox()
						local jumped = spaceDown and not wall.spaceDown
						wall.spaceDown = spaceDown
						if humanoid.Sit then
							leaveWall(humanoid)
							return stopClimbAnimation()
						end
						-- Under a ceiling: crawling along it upside down, feet to the ceiling.
						if wall.ceiling then
							local above = ceilingAbove(root)
							if not above or jumped then
								stopClimbAnimation()
								return leaveCeiling(humanoid, root)
							end
							humanoid.PlatformStand = true
							if move.Magnitude > 0.1 then wall.yaw = yawOf(move) end
							local reach = isR15(humanoid) and (humanoid.HipHeight + root.Size.Y / 2) or 3
							local hangY = above.Position.Y - reach
							root.AssemblyLinearVelocity = move * speed + Vector3.new(0, math.clamp((hangY - root.Position.Y) / frame, -40, 40), 0)
							root.AssemblyAngularVelocity = Vector3.zero
							root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, wall.yaw, 0) * CFrame.Angles(0, 0, math.pi)
							climbAnimation(humanoid, move.Magnitude > 0.1 and 1 or 0)
							return
						end
						-- Something else has you limp (Ragdoll, say): that's left alone.
						if humanoid.PlatformStand and not wall.climbing then return stopClimbAnimation() end
						-- A wall the way you're walking, that you're pushing into.
						local hit = move.Magnitude > 0.1 and workspace:Raycast(root.Position, move.Unit * 2.4, wallParams)
						local into = hit and math.abs(hit.Normal.Y) < 0.4 and -flat(hit.Normal)
						if into and into.Magnitude > 0.1 then into = into.Unit else into = nil end
						local push = into and move:Dot(into) or 0
						if not into or push < 0.3 or os.clock() < wall.ledgeUntil then
							leaveWall(humanoid)
							return stopClimbAnimation()
						end
						-- Climbed up into a ceiling: hang under it (still limp, so the ceiling takes over).
						if ceilingAbove(root) then
							wall.climbing = false
							wall.ceiling = true
							wall.yaw = yawOf(into)
							return
						end
						-- Nothing in front of your head any more: pull yourself up and over the top.
						if not workspace:Raycast(root.Position + Vector3.new(0, 2.5, 0), into * 3, wallParams) then
							wall.ledgeUntil = os.clock() + 0.35
							stopClimbAnimation()
							leaveWall(humanoid)
							root.AssemblyLinearVelocity = into * 14 + Vector3.new(0, speed + 14, 0)
							return
						end
						if jumped then
							-- Kick off the wall, backwards.
							wall.ledgeUntil = os.clock() + 0.4
							stopClimbAnimation()
							leaveWall(humanoid)
							root.AssemblyLinearVelocity = -into * 30 + Vector3.new(0, 40, 0)
							return
						end
						-- Climbing: up as you push into it, sideways as you steer along it, held against it.
						-- Gravity's pull for this frame is added back, so you climb at the full speed.
						wall.climbing = true
						humanoid.PlatformStand = true
						local along = move - into * move:Dot(into)
						root.AssemblyLinearVelocity = Vector3.new(0, push * speed + workspace.Gravity * frame, 0) + along * speed * 0.7 + into * 4
						root.AssemblyAngularVelocity = Vector3.zero
						root.CFrame = CFrame.lookAt(root.Position, root.Position + into)
						climbAnimation(humanoid, math.max(push, 0.4))
					end
					addQuickToggle(trollTabs.walks, "Wall Walk", "Walk into a wall to climb straight up it like Spider-Man, and crawl along ceilings upside down. Jump to let go", function(enabled)
						stopClimbAnimation()
						local _, humanoid, root = myCharacter()
						if humanoid then
							leaveCeiling(humanoid, root)
							leaveWall(humanoid)
						end
						wall.ceiling, wall.climbing = false, false
						if not enabled then return afterControls("SpreadCheeksWallWalk", nil) end
						claimMovement("Wall Walk")
						-- A key already held when it's switched on doesn't count as a jump.
						wall.spaceDown = true
						afterControls("SpreadCheeksWallWalk", step)
					end, "footprints", "arrow-up-to-line")
				end

				-- Player Pranks: the tricks played on someone else use the player picked here, which is the
				-- one selected on the Players tab too.
				withIcon(trollTabs.players, "CreateSection", { name = "Your target" }, "crosshair", "user-round")
				local function findPlayer(name)
					name = tostring(name or ""):lower()
					if name == "" then return nil end
					for _, player in ipairs(Players:GetPlayers()) do
						if player.Name:lower() == name then return player end
					end
					for _, player in ipairs(Players:GetPlayers()) do
						if player.Name:lower():sub(1, #name) == name or player.DisplayName:lower():sub(1, #name) == name then
							return player
						end
					end
					return nil
				end
				local function currentTarget()
					local player = findPlayer(menuModules.selectedPlayerName and menuModules.selectedPlayerName())
					if player == localPlayer then return nil end
					return player
				end
				local function targetFor(feature)
					local player = currentTarget()
					if not player then
						notify(feature, "Pick someone first: Choose Player or Nearest Player on the Player Pranks tab, or Ctrl+click them.")
					end
					return player
				end
				local targetText = withIcon(trollTabs.players, "CreateText", {
					name = "Target",
					text = "Nobody picked yet",
				}, "user-round")
				local function refreshTargetText()
					local name = menuModules.selectedPlayerName and menuModules.selectedPlayerName()
					local player = findPlayer(name)
					local text = "Nobody picked yet"
					if player and player ~= localPlayer then
						text = menuModules.labelOf(player, "  ")
					elseif not player and name and name ~= "" then
						text = "@" .. name .. " isn't in this server"
					end
					pcall(function() targetText:Set(text) end)
				end
				table.insert(menuModules.nameListeners, refreshTargetText)
				withIcon(trollTabs.players, "CreateButton", {
					name = "Choose Player",
					description = "Pick who the tricks below use, by their face and name",
					callback = function()
						if menuModules.openPlayerPicker then menuModules.openPlayerPicker() end
					end,
				}, "layout-grid", "users-round")
				withIcon(trollTabs.players, "CreateButton", {
					name = "Nearest Player",
					description = "Picks the player closest to you",
					callback = function()
						local _, _, root = myCharacter()
						local nearest, nearestDistance = nil, math.huge
						for _, player in ipairs(Players:GetPlayers()) do
							local theirRoot = player ~= localPlayer and player.Character and getRoot(player.Character)
							if root and theirRoot then
								local distance = (theirRoot.Position - root.Position).Magnitude
								if distance < nearestDistance then nearest, nearestDistance = player, distance end
							end
						end
						if not nearest then return notify("Nearest Player", "There's nobody else around right now.") end
						if menuModules.selectPlayer then
							menuModules.selectPlayer(nearest.Name, menuModules.labelOf(nearest, "  "))
						end
						notify("Target", menuModules.nameOf(nearest) .. ", " .. math.floor(nearestDistance + 0.5) .. " studs away", 2.5)
					end,
				}, "locate-fixed", "crosshair")
				-- Ctrl+Click Select (menuModules.ctrlClickSelect) and the Troll Panel (menuModules.trollPanel)
				-- are built further down; both are remembered between sessions. Spectate Target watches your
				-- target, which brings the Troll Panel up for them.
				addRememberedToggle(trollTabs.players, "Ctrl+Click Select", "ctrlClickSelect", "ctrlClickSelect", "Hold Ctrl and click a player to make them your target", "mouse-pointer-click", "crosshair")
				do
					local function spectateTarget()
						local target = currentTarget()
						if not target then return notify("Spectate", "Pick someone first: Choose Player, Nearest Player, or Ctrl+click them.") end
						if menuModules.spectateBar and menuModules.spectateBar.watch then menuModules.spectateBar.watch(target) end
					end
					addQuickAction("Spectate Target", spectateTarget, withIcon(trollTabs.players, "CreateButton", {
						name = "Spectate Target",
						description = "Watch your target, with the Troll Panel of pranks just for them",
						callback = spectateTarget,
					}, "eye", "video"))
				end
				addRememberedToggle(trollTabs.players, "Troll Panel", "trollPanel", "trollPanel", "While you spectate someone, a panel of pranks, emotes, moves and tools just for them. Shift+click a player to spectate them and open it", "drama", "layout-grid")

				-- Picking someone else moves whichever of these are on over to them.
				local targetedSwitches = {}
				local function retarget()
					for name, setter in pairs(targetedSwitches) do
						local entry = quickToggleByName[name]
						if entry and entry.state and setter(true) == false then switchOff(name) end
					end
				end
				table.insert(menuModules.selectionListeners, function()
					refreshTargetText()
					retarget()
				end)
				Players.PlayerAdded:Connect(function() task.defer(refreshTargetText) end)
				Players.PlayerRemoving:Connect(function() task.defer(refreshTargetText) end)

				withIcon(trollTabs.players, "CreateSection", { name = "Stick to them" }, "magnet", "users-round")
				-- Headsit: you sit on the target's head, or on their back for a piggyback (in its settings
				-- card), and ride along. Jump to get off.
				local headsitState = { loop = nil, sitting = false }
				local function setHeadsit(enabled)
					if headsitState.loop then
						headsitState.loop:Disconnect()
						headsitState.loop = nil
					end
					local _, humanoid = myCharacter()
					if not enabled then
						if humanoid and headsitState.sitting then humanoid.Sit = false end
						headsitState.sitting = false
						return
					end
					local target = targetFor("Headsit")
					if not target then return false end
					if not humanoid then
						notify("Headsit", "Your character isn't ready yet.")
						return false
					end
					claimMovement("Headsit")
					humanoid.Sit = true
					headsitState.sitting = true
					headsitState.loop = RunService.Heartbeat:Connect(function()
						if not target.Parent then
							notify("Headsit", menuModules.nameOf(target) .. " left the server")
							return switchOff("Headsit")
						end
						local _, myHumanoid, myRoot = myCharacter()
						local character = target.Character
						local head = character and character:FindFirstChild("Head")
						local theirRoot = character and getRoot(character)
						if not myHumanoid or not head or not theirRoot then return end
						if not myHumanoid.Sit then return switchOff("Headsit") end
						if featureSettings.trollSitSpot == "Back" then
							myRoot.CFrame = theirRoot.CFrame * CFrame.new(0, 0.9, 1.1)
						else
							myRoot.CFrame = theirRoot.CFrame.Rotation + (head.Position + Vector3.new(0, head.Size.Y / 2 + 1, 0))
						end
						myRoot.AssemblyLinearVelocity = Vector3.zero
					end)
				end
				targetedSwitches["Headsit"] = setHeadsit
				addQuickToggle(trollTabs.players, "Headsit", "Sit on your target's head and ride along. Jump to get off. Right-click for a piggyback", setHeadsit, "armchair")

				-- Orbit: you circle round the target. Speed, distance and height are in its settings card.
				-- You're moved by your velocity rather than teleported each frame, so the movement Roblox
				-- sends to the server and everyone else (position and velocity) matches what you see, and
				-- they see a smooth circle instead of a lagging, jumping one. The circle is centred where
				-- the target will be by the time they see you, allowing for lag both ways. You go limp
				-- (PlatformStand, so the humanoid doesn't fight it) and stop colliding, so walls and the
				-- target can't knock you off course.
				local orbitState = { loop = nil, noclip = nil, angle = 0, collisions = nil, humanoid = nil, ping = 0, pingAt = 0 }
				-- keepPose: starting again on a new target, so you stay in the air rather than standing up
				-- (the humanoid is kept, so you're still stood up if the new start fails).
				local function stopOrbitMotion(keepPose)
					if orbitState.loop then
						orbitState.loop:Disconnect()
						orbitState.loop = nil
					end
					if orbitState.noclip then
						orbitState.noclip:Disconnect()
						orbitState.noclip = nil
					end
					for part, canCollide in pairs(orbitState.collisions or {}) do
						if part.Parent then part.CanCollide = canCollide end
					end
					orbitState.collisions = nil
					if keepPose then return end
					local humanoid = orbitState.humanoid
					orbitState.humanoid = nil
					if not humanoid or not humanoid.Parent or humanoid.Health <= 0 then return end
					local root = getRoot(humanoid.Parent)
					humanoid.PlatformStand = false
					if root then
						root.AssemblyLinearVelocity = Vector3.zero
						root.AssemblyAngularVelocity = Vector3.zero
					end
					humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
				end
				-- Your round trip to the server in seconds, checked once a second.
				local function networkPing()
					local now = os.clock()
					if now - orbitState.pingAt > 1 then
						orbitState.pingAt = now
						local measured, ping = pcall(function() return localPlayer:GetNetworkPing() end)
						orbitState.ping = measured and tonumber(ping) or 0.1
					end
					return orbitState.ping
				end
				local function setOrbit(enabled)
					stopOrbitMotion(enabled)
					if not enabled then return end
					local target = targetFor("Orbit")
					if not target then return false end
					local character, humanoid, root = myCharacter()
					if not humanoid then
						notify("Orbit", "Your character isn't ready yet.")
						return false
					end
					claimMovement("Orbit")
					orbitState.humanoid = humanoid
					orbitState.collisions = {}
					for _, part in ipairs(character:GetDescendants()) do
						if part:IsA("BasePart") then orbitState.collisions[part] = part.CanCollide end
					end
					-- The circle starts from where you already are round them, so there's no jump.
					local startRoot = target.Character and getRoot(target.Character)
					local fromThem = startRoot and flat(root.Position - startRoot.Position)
					if fromThem and fromThem.Magnitude > 0.1 then orbitState.angle = math.atan2(fromThem.Z, fromThem.X) end
					-- The humanoid keeps turning collisions back on, so they're switched off every frame.
					orbitState.noclip = RunService.Stepped:Connect(function()
						for part in pairs(orbitState.collisions) do
							if part.Parent then part.CanCollide = false end
						end
					end)
					orbitState.loop = RunService.Heartbeat:Connect(function(deltaTime)
						if not target.Parent then
							notify("Orbit", menuModules.nameOf(target) .. " left the server")
							return switchOff("Orbit")
						end
						local _, myHumanoid, myRoot = myCharacter()
						if not myHumanoid then return end
						-- A new character ends it.
						if myHumanoid ~= orbitState.humanoid then return switchOff("Orbit") end
						myHumanoid.PlatformStand = true
						myRoot.AssemblyAngularVelocity = Vector3.zero
						local theirRoot = target.Character and getRoot(target.Character)
						if not theirRoot then
							-- Hold still while they respawn.
							myRoot.AssemblyLinearVelocity = Vector3.zero
							return
						end
						orbitState.angle = (orbitState.angle + deltaTime * featureSettings.trollOrbitSpeed * 1.2) % (math.pi * 2)
						-- What you see of them is a moment old, and they see you a moment late, so the centre
						-- is moved on by their velocity over about two round trips.
						local lead = math.clamp(networkPing() * 2 + 0.05, 0, 0.5)
						local center = theirRoot.Position + flat(theirRoot.AssemblyLinearVelocity) * lead
						local distance = featureSettings.trollOrbitDistance
						local spot = center + Vector3.new(math.cos(orbitState.angle) * distance, featureSettings.trollOrbitHeight, math.sin(orbitState.angle) * distance)
						local offset = spot - myRoot.Position
						if offset.Magnitude > 40 then
							-- Too far to fly in one frame (starting from across the map, say): one jump onto
							-- the circle, and smooth from there.
							myRoot.CFrame = CFrame.lookAt(spot, Vector3.new(center.X, spot.Y, center.Z))
							myRoot.AssemblyLinearVelocity = Vector3.zero
							return
						end
						-- The velocity that carries you to the spot by the next frame. Physics does the moving,
						-- so your velocity always matches how you're really moving.
						local velocity = offset / math.max(deltaTime, 1 / 120)
						if velocity.Magnitude > 350 then velocity = velocity.Unit * 350 end
						myRoot.AssemblyLinearVelocity = velocity
						-- Only the facing changes here; the position stays where physics put it.
						local position = myRoot.Position
						local facing = Vector3.new(center.X, position.Y, center.Z)
						if (facing - position).Magnitude > 0.1 then
							myRoot.CFrame = CFrame.lookAt(position, facing)
						end
					end)
				end
				targetedSwitches["Orbit"] = setOrbit
				addQuickToggle(trollTabs.players, "Orbit", "Circle round your target. Right-click for speed, distance and height", setOrbit, "orbit")

				-- Copycat: plays whatever animations the target is playing, in step with them, and can follow
				-- them about too (in its settings card). Your own Animate script is off meanwhile, so only
				-- their animations show on you.
				local copycatState = { loop = nil, tracks = {}, animator = nil }
				local function stopCopiedTracks()
					for _, track in pairs(copycatState.tracks) do
						pcall(function() track:Stop(0.2) end)
					end
					table.clear(copycatState.tracks)
				end
				local function setCopycat(enabled)
					if copycatState.loop then
						copycatState.loop:Disconnect()
						copycatState.loop = nil
					end
					stopCopiedTracks()
					copycatState.animator = nil
					if not enabled then
						holdAnimate("Copycat", false)
						return
					end
					local target = targetFor("Copycat")
					if not target then return false end
					local _, humanoid = myCharacter()
					local theirHumanoid = target.Character and target.Character:FindFirstChildOfClass("Humanoid")
					if humanoid and theirHumanoid and humanoid.RigType ~= theirHumanoid.RigType then
						notify("Copycat", "You and " .. menuModules.nameOf(target) .. " have different body types (R6 and R15), so some moves won't copy.", 5)
					end
					switchOff("Emote")
					holdAnimate("Copycat", true)
					local lastSync = 0
					copycatState.loop = RunService.Heartbeat:Connect(function()
						if not target.Parent then
							notify("Copycat", menuModules.nameOf(target) .. " left the server")
							return switchOff("Copycat")
						end
						local _, myHumanoid, myRoot = myCharacter()
						local theirCharacter = target.Character
						local theirRoot = theirCharacter and getRoot(theirCharacter)
						local follow = featureSettings.trollCopyFollow
						if follow ~= "Off" and myRoot and theirRoot then
							myRoot.CFrame = theirRoot.CFrame * (follow == "Beside" and CFrame.new(3.5, 0, 0) or CFrame.new(0, 0, 3.5))
							myRoot.AssemblyLinearVelocity = Vector3.zero
						end
						local now = os.clock()
						if now - lastSync < 0.1 then return end
						lastSync = now
						local animator = animatorOf(myHumanoid)
						local theirAnimator = animatorOf(theirCharacter and theirCharacter:FindFirstChildOfClass("Humanoid"))
						if not animator or not theirAnimator then return end
						if animator ~= copycatState.animator then
							-- A new character of yours: copy onto it from scratch.
							copycatState.animator = animator
							table.clear(copycatState.tracks)
						end
						local playing = {}
						for _, theirTrack in ipairs(theirAnimator:GetPlayingAnimationTracks()) do
							local animation = theirTrack.Animation
							local id = animation and animation.AnimationId
							if id and id ~= "" then
								playing[id] = true
								local mine = copycatState.tracks[id]
								if not mine then
									local copy = Instance.new("Animation")
									copy.AnimationId = id
									local loaded, track = pcall(animator.LoadAnimation, animator, copy)
									if loaded and track then
										mine = track
										mine.Priority = theirTrack.Priority
										mine.Looped = theirTrack.Looped
										copycatState.tracks[id] = mine
									end
								end
								if mine then
									if not mine.IsPlaying then mine:Play(0.15, theirTrack.WeightTarget, theirTrack.Speed) end
									if math.abs(mine.Speed - theirTrack.Speed) > 0.01 then mine:AdjustSpeed(theirTrack.Speed) end
									if math.abs(mine.WeightTarget - theirTrack.WeightTarget) > 0.01 then
										mine:AdjustWeight(theirTrack.WeightTarget, 0.15)
									end
									-- Kept in step with them, unless your animations are sped up or reversed.
									if animationMultiplier() == 1 and mine.Length > 0 and math.abs(mine.TimePosition - theirTrack.TimePosition) > 0.3 then
										mine.TimePosition = theirTrack.TimePosition
									end
								end
							end
						end
						for id, mine in pairs(copycatState.tracks) do
							if not playing[id] then
								mine:Stop(0.15)
								copycatState.tracks[id] = nil
							end
						end
					end)
				end
				targetedSwitches["Copycat"] = setCopycat
				addQuickToggle(trollTabs.players, "Copycat", "Copy your target's animations and emotes as they do them. Right-click to follow them too", setCopycat, "copy", "users-round")

				-- Bow Down: you bow to the target over and over, facing them from in front, from behind or
				-- while circling round them. Where, how fast, how low, how far away and kneeling are in its
				-- settings card.
				local bowMode = { target = nil, standHeight = 3, last = nil, phase = 0, angle = nil }
				function bowMode.start(humanoid, root)
					local ground = groundBelow(root.Position, { humanoid.Parent })
					bowMode.standHeight = ground and math.clamp(root.Position.Y - ground, 1.5, 6) or 3
					bowMode.last = root.CFrame
					bowMode.phase, bowMode.angle = 0, nil
				end
				function bowMode.step(deltaTime, humanoid, root)
					local target = bowMode.target
					if not target or not target.Parent then
						notify("Bow Down", "They left the server")
						switchOff("Bow Down")
						return nil
					end
					local theirRoot = target.Character and getRoot(target.Character)
					if not theirRoot then return bowMode.last end
					local front = flat(theirRoot.CFrame.LookVector)
					front = front.Magnitude > 0.1 and front.Unit or Vector3.new(0, 0, -1)
					local distance = featureSettings.trollBowDistance
					local offset = front * distance
					if featureSettings.trollBowSpot == "Behind" then
						offset = -offset
					elseif featureSettings.trollBowSpot == "Around them" then
						-- Starts in front of them and goes round slowly.
						bowMode.angle = (bowMode.angle or math.atan2(front.Z, front.X)) + deltaTime * 0.8
						offset = Vector3.new(math.cos(bowMode.angle), 0, math.sin(bowMode.angle)) * distance
					end
					local spot = theirRoot.Position + offset
					local ground = groundBelow(spot, { humanoid.Parent, target.Character })
					-- Kneeling sinks you a little, so your legs fold into the floor.
					local height = bowMode.standHeight - (featureSettings.trollBowKneel and 1.3 or 0)
					local position = Vector3.new(spot.X, ground and ground + height or theirRoot.Position.Y, spot.Z)
					local towards = flat(theirRoot.Position - position)
					if towards.Magnitude > 0.1 then takeoverState.yaw = yawOf(towards) end
					bowMode.phase = (bowMode.phase + deltaTime * featureSettings.trollBowSpeed) % (math.pi * 2)
					local bow = (0.5 - 0.5 * math.cos(bowMode.phase)) * math.rad(featureSettings.trollBowDepth)
					bowMode.last = CFrame.new(position) * CFrame.Angles(0, takeoverState.yaw, 0) * CFrame.Angles(-bow, 0, 0)
					return bowMode.last
				end
				local function setBowDown(enabled)
					if not enabled then return endTakeover("Bow Down") end
					local target = targetFor("Bow Down")
					if not target then return false end
					bowMode.target = target
					return beginTakeover("Bow Down", bowMode)
				end
				targetedSwitches["Bow Down"] = setBowDown
				addQuickToggle(trollTabs.players, "Bow Down", "Bow down to your target, over and over. Right-click to change how", setBowDown, "crown", "hand")

				withIcon(trollTabs.players, "CreateSection", { name = "Get to them" }, "send", "navigation")
				-- Glide To: you fly smoothly over to the target, through walls, and stop just behind them.
				-- Like Orbit, it moves you by velocity rather than teleporting, so everyone sees the flight
				-- and the server agrees where you are, and it aims where they'll be once lag catches up. It
				-- switches itself off when you arrive, or after a minute. The speed is in its settings card.
				-- Server Tour flies the same way (glideTowards).
				local glideState = { loop = nil, noclip = nil, collisions = nil, humanoid = nil, started = 0 }
				-- keepPose: starting again on a new target, so you carry on flying.
				local function stopGlide(keepPose)
					if glideState.loop then
						glideState.loop:Disconnect()
						glideState.loop = nil
					end
					if glideState.noclip then
						glideState.noclip:Disconnect()
						glideState.noclip = nil
					end
					for part, canCollide in pairs(glideState.collisions or {}) do
						if part.Parent then part.CanCollide = canCollide end
					end
					glideState.collisions = nil
					if keepPose then return end
					local humanoid = glideState.humanoid
					glideState.humanoid = nil
					if not humanoid or not humanoid.Parent or humanoid.Health <= 0 then return end
					local root = getRoot(humanoid.Parent)
					humanoid.PlatformStand = false
					if root then
						root.AssemblyLinearVelocity = Vector3.zero
						root.AssemblyAngularVelocity = Vector3.zero
						-- Upright again, facing the way you were going.
						local look = flat(root.CFrame.LookVector)
						if look.Magnitude > 0.1 then root.CFrame = CFrame.lookAt(root.Position, root.Position + look) end
					end
					humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
				end
				-- Flies you over to target and lands you a few studs away, facing them: behind them, or in
				-- front of them with inFront. arrived runs once you've landed; gaveUp runs instead, with
				-- the reason, if they leave or a minute goes by first (with no reason after a respawn).
				-- False if your character isn't ready.
				local function glideTowards(target, inFront, arrived, gaveUp)
					stopGlide(true)
					local character, humanoid = myCharacter()
					if not humanoid then return false end
					glideState.humanoid = humanoid
					glideState.collisions = {}
					for _, part in ipairs(character:GetDescendants()) do
						if part:IsA("BasePart") then glideState.collisions[part] = part.CanCollide end
					end
					glideState.started = os.clock()
					-- The humanoid keeps turning collisions back on, so they're switched off every frame.
					glideState.noclip = RunService.Stepped:Connect(function()
						for part in pairs(glideState.collisions) do
							if part.Parent then part.CanCollide = false end
						end
					end)
					glideState.loop = RunService.Heartbeat:Connect(function(deltaTime)
						if not target.Parent then return gaveUp(menuModules.nameOf(target) .. " left the server") end
						local _, myHumanoid, myRoot = myCharacter()
						if not myHumanoid then return end
						-- A new character ends it.
						if myHumanoid ~= glideState.humanoid then return gaveUp(nil) end
						if os.clock() - glideState.started > 60 then
							return gaveUp("Couldn't get to " .. menuModules.nameOf(target) .. " within a minute.")
						end
						myHumanoid.PlatformStand = true
						myRoot.AssemblyAngularVelocity = Vector3.zero
						local theirRoot = target.Character and getRoot(target.Character)
						if not theirRoot then
							-- Hold still while they respawn.
							myRoot.AssemblyLinearVelocity = Vector3.zero
							return
						end
						-- Just behind them (or in front), where they'll be by the time they see you get there.
						local front = flat(theirRoot.CFrame.LookVector)
						front = front.Magnitude > 0.1 and front.Unit or Vector3.new(0, 0, -1)
						local lead = math.clamp(networkPing() * 2 + 0.05, 0, 0.5)
						local spot = theirRoot.Position + flat(theirRoot.AssemblyLinearVelocity) * lead + front * (inFront and 4 or -3)
						local offset = spot - myRoot.Position
						local distance = offset.Magnitude
						if distance < 1.5 then
							-- Landing facing them.
							local position = myRoot.Position
							local towards = flat(theirRoot.Position - position)
							if towards.Magnitude > 0.1 then myRoot.CFrame = CFrame.lookAt(position, position + towards) end
							stopGlide(false)
							return arrived()
						end
						-- Never faster than reaches the spot this frame, so you don't overshoot it.
						local speed = math.min(featureSettings.trollGlideSpeed, distance / math.max(deltaTime, 1 / 120))
						myRoot.AssemblyLinearVelocity = offset.Unit * speed
						-- Facing the way you're flying, leaning into it.
						local position = myRoot.Position
						local heading = flat(offset)
						if heading.Magnitude > 0.1 then
							myRoot.CFrame = CFrame.lookAt(position, position + heading) * CFrame.Angles(-math.rad(15), 0, 0)
						end
					end)
					return true
				end
				local function setGlide(enabled)
					if not enabled then return stopGlide(false) end
					local target = targetFor("Glide To")
					if not target then return false end
					if not myCharacter() then
						notify("Glide To", "Your character isn't ready yet.")
						return false
					end
					claimMovement("Glide To")
					-- Go Back can take you back to where the glide started.
					local _, _, startRoot = myCharacter()
					if startRoot and menuModules.rememberSpot then menuModules.rememberSpot(startRoot.Position) end
					glideTowards(target, false, function()
						notify("Glide To", "Got to " .. menuModules.nameOf(target), 2)
						switchOff("Glide To")
					end, function(reason)
						if reason then notify("Glide To", reason) end
						switchOff("Glide To")
					end)
				end
				targetedSwitches["Glide To"] = setGlide
				addQuickToggle(trollTabs.players, "Glide To", "Fly smoothly over to your target, through walls, and stop behind them. Right-click for the speed", setGlide, "send", "navigation")
				-- For the Players tab's button and the glideto command. A glide that's under way starts over,
				-- towards whoever is picked now, without landing first.
				function trolling.startGlide()
					local entry = quickToggleByName["Glide To"]
					if not entry then return end
					if not entry.state then return setQuickToggle(entry, true) end
					if setGlide(true) == false then switchOff("Glide To") end
				end

				-- Server Tour: you glide over to everyone in the server in turn, nearest first, land in
				-- front of them and wave, then fly on to the next. It switches itself off once everyone has
				-- had a visit, people who join on the way included. It needs no target.
				local tourState = { serial = 0, wave = nil }
				local function stopTourWave()
					if tourState.wave then
						pcall(function() tourState.wave:Stop(0.3) end)
						tourState.wave = nil
					end
				end
				local function setServerTour(enabled)
					-- Each tour has its own number, so the waits of one that's been stopped come to nothing.
					tourState.serial += 1
					local serial = tourState.serial
					stopTourWave()
					if not enabled then return stopGlide(false) end
					if #Players:GetPlayers() < 2 then
						notify("Server Tour", "There's nobody else in the server to visit.")
						return false
					end
					if not myCharacter() then
						notify("Server Tour", "Your character isn't ready yet.")
						return false
					end
					claimMovement("Server Tour")
					local visited, count = {}, 0
					local nextStop
					nextStop = function()
						if tourState.serial ~= serial then return end
						local _, _, root = myCharacter()
						local nearest, nearestDistance = nil, math.huge
						for _, player in ipairs(Players:GetPlayers()) do
							local theirRoot = player ~= localPlayer and not visited[player] and player.Character and getRoot(player.Character)
							if theirRoot then
								local distance = root and (theirRoot.Position - root.Position).Magnitude or 0
								if distance < nearestDistance then nearest, nearestDistance = player, distance end
							end
						end
						if not nearest then
							notify("Server Tour", "Tour over: you visited " .. count .. (count == 1 and " player." or " players."), 4)
							return switchOff("Server Tour")
						end
						visited[nearest] = true
						local started = glideTowards(nearest, true, function()
							if tourState.serial ~= serial then return end
							count += 1
							-- A wave, then on to the next.
							local _, humanoid = myCharacter()
							local wave = emoteByName["Wave"]
							if humanoid and wave then
								tourState.wave = playOnMe("rbxassetid://" .. tostring(isR15(humanoid) and wave.r15 or wave.r6))
							end
							task.delay(2.5, function()
								if tourState.serial ~= serial then return end
								stopTourWave()
								nextStop()
							end)
						end, function(reason)
							if tourState.serial ~= serial then return end
							-- A respawn ends the tour; someone leaving or out of reach is just skipped.
							if not reason then return switchOff("Server Tour") end
							nextStop()
						end)
						if not started then switchOff("Server Tour") end
					end
					nextStop()
				end
				addQuickToggle(trollTabs.players, "Server Tour", "Glide over to everyone in the server, one at a time, and wave at each of them", setServerTour, "map", "plane")

				-- Boo!: you pop up right in front of your target, face to face and roaring (on R15), for a
				-- moment, then vanish back to where you were. A one-off with a key box, like the moves. You
				-- pass through everything while you're there, so you never bump them, and anything else
				-- holding your character (Orbit, Handstand and so on) stops for it.
				do
					local boo = { running = false }
					function trolling.boo(player)
						if boo.running or flipping then return end
						local target = player or targetFor("Boo!")
						if not target then return end
						local character, humanoid, root = myCharacter()
						if not humanoid then return notify("Boo!", "Your character isn't ready yet.") end
						local theirRoot = target.Character and getRoot(target.Character)
						if not theirRoot then return notify("Boo!", menuModules.nameOf(target) .. " has no character right now.") end
						claimMovement("Boo!")
						boo.running = true
						task.spawn(function()
							local home = root.CFrame
							local collisions = {}
							for _, part in ipairs(character:GetDescendants()) do
								if part:IsA("BasePart") then collisions[part] = part.CanCollide end
							end
							-- The humanoid keeps turning collisions back on, so they're switched off every frame.
							local noclip = RunService.Stepped:Connect(function()
								for part in pairs(collisions) do
									if part.Parent then part.CanCollide = false end
								end
							end)
							local emote = emoteByName["Shrek Roar"]
							local id = emote and (isR15(humanoid) and emote.r15 or emote.r6)
							local track = id and playOnMe("rbxassetid://" .. tostring(id)) or nil
							if track then track.Looped = false end
							local started = os.clock()
							while os.clock() - started < 1.5 and root.Parent and theirRoot.Parent do
								-- Right in front of their face, whichever way they turn.
								local look = flat(theirRoot.CFrame.LookVector)
								look = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
								local spot = theirRoot.Position + look * 2.6
								root.CFrame = CFrame.lookAt(spot, Vector3.new(theirRoot.Position.X, spot.Y, theirRoot.Position.Z))
								root.AssemblyLinearVelocity = Vector3.zero
								RunService.Heartbeat:Wait()
							end
							if track then pcall(function() track:Stop(0.2) end) end
							noclip:Disconnect()
							for part, canCollide in pairs(collisions) do
								if part.Parent then part.CanCollide = canCollide end
							end
							-- And gone, back where you were.
							if root.Parent then
								root.CFrame = home
								root.AssemblyLinearVelocity = Vector3.zero
							end
							boo.running = false
						end)
					end
					local function booTarget() trolling.boo() end
					addQuickAction("Boo!", booTarget, withIcon(trollTabs.players, "CreateButton", {
						name = "Boo!",
						description = "Pop up right in front of your target for a second, roaring, then vanish back to where you were",
						callback = booTarget,
					}, "ghost", "zap"))
				end

				-- Walking after someone, for Weeping Angel and Bodyguard: round walls and up stairs by
				-- Roblox's pathfinding (jumping where the path needs it), straight there while a path is
				-- being worked out, and when you're stuck, or there's no way there on foot (they've climbed
				-- onto something), floating over to them through walls, the way Glide To flies. Each one
				-- is made once, then stepped every frame (after the controls) with where to go.
				local function newPath()
					local made, path = pcall(function()
						return PathService:CreatePath({ AgentRadius = 2, AgentHeight = 5, AgentCanJump = true, AgentCanClimb = true, WaypointSpacing = 4 })
					end)
					if made and path then return path end
					return PathService:CreatePath({ AgentRadius = 2, AgentHeight = 5, AgentCanJump = true })
				end
				local function newFollower()
					local follower = {
						waypoints = nil, index = 0, goal = nil, pathAt = 0, computing = false, serial = 0, noPath = false,
						jump = false, humanoid = nil, lastPosition = nil, lastMoveAt = 0, hopped = false,
						drifting = false, collisions = nil, noclip = nil, holdAt = nil,
						-- How fast it floats (studs a second), and how far away it floats rather than walks
						-- (nil: only when it has to). ignore is a character the ground check looks past.
						driftSpeed = 20, driftBeyond = nil, ignore = nil,
					}
					local function stopDrift()
						if not follower.drifting then return end
						follower.drifting = false
						follower.holdAt = nil
						if follower.noclip then
							follower.noclip:Disconnect()
							follower.noclip = nil
						end
						for part, canCollide in pairs(follower.collisions or {}) do
							if part.Parent then part.CanCollide = canCollide end
						end
						follower.collisions = nil
						-- Walking again from here, with a new path.
						follower.waypoints, follower.goal, follower.noPath, follower.farDrift = nil, nil, false, false
						follower.lastPosition = nil
						local humanoid = follower.humanoid
						if not humanoid or not humanoid.Parent or humanoid.Health <= 0 then return end
						humanoid.PlatformStand = false
						local root = getRoot(humanoid.Parent)
						if root then
							root.AssemblyLinearVelocity = Vector3.zero
							local look = flat(root.CFrame.LookVector)
							if look.Magnitude > 0.1 then root.CFrame = CFrame.lookAt(root.Position, root.Position + look) end
						end
						humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
					end
					local function startDrift(character)
						if follower.drifting then return end
						follower.drifting = true
						follower.waypoints = nil
						follower.collisions = {}
						for _, part in ipairs(character:GetDescendants()) do
							if part:IsA("BasePart") then follower.collisions[part] = part.CanCollide end
						end
						-- The humanoid keeps turning collisions back on, so they're switched off every frame.
						follower.noclip = RunService.Stepped:Connect(function()
							for part in pairs(follower.collisions) do
								if part.Parent then part.CanCollide = false end
							end
						end)
					end
					-- Back on your feet with no path, as at the start.
					function follower.reset()
						stopDrift()
						follower.serial += 1
						follower.waypoints, follower.goal, follower.noPath, follower.computing = nil, nil, false, false
						follower.jump, follower.hopped, follower.lastPosition = false, false, nil
					end
					-- Works out a path in the background; destination is kept to tell when it's moved on.
					local function requestPath(from, pathGoal, destination)
						follower.computing = true
						follower.pathAt = os.clock()
						follower.goal = destination
						local serial = follower.serial
						task.spawn(function()
							local path = nil
							local computed = pcall(function()
								path = newPath()
								path:ComputeAsync(from, pathGoal)
							end)
							if follower.serial ~= serial then return end
							follower.computing = false
							if computed and path.Status == Enum.PathStatus.Success then
								local waypoints = path:GetWaypoints()
								follower.waypoints, follower.index, follower.noPath = waypoints, 2, false
								follower.jump = waypoints[2] ~= nil and waypoints[2].Action == Enum.PathWaypointAction.Jump
							else
								follower.waypoints, follower.noPath = nil, true
							end
						end)
					end
					-- Which way to walk along the path, or nil once it's used up.
					local function pathDirection(root)
						local waypoints = follower.waypoints
						while waypoints and follower.index <= #waypoints do
							local offset = flat(waypoints[follower.index].Position - root.Position)
							if offset.Magnitude > 2 then return offset end
							follower.index += 1
							local upcoming = waypoints[follower.index]
							if upcoming and upcoming.Action == Enum.PathWaypointAction.Jump then follower.jump = true end
						end
						return nil
					end
					-- One frame: heads for destination, unless hold, when it stays put (in mid-air, if it's
					-- floating). True once it's within stopDistance of destination.
					function follower.step(deltaTime, character, humanoid, root, destination, stopDistance, hold)
						if humanoid ~= follower.humanoid then
							-- A new character starts from scratch.
							follower.reset()
							follower.humanoid = humanoid
						end
						local now = os.clock()
						local offset = destination - root.Position
						if follower.drifting then
							humanoid.PlatformStand = true
							root.AssemblyAngularVelocity = Vector3.zero
							if hold then
								follower.holdAt = follower.holdAt or root.Position
								root.AssemblyLinearVelocity = (follower.holdAt - root.Position) / math.max(deltaTime, 1 / 120)
								return false
							end
							follower.holdAt = nil
							local distance = offset.Magnitude
							if distance < 1.5 then
								stopDrift()
								return true
							end
							-- Floated over for being far off: within landWithin, it walks the rest.
							if follower.farDrift and follower.landWithin and distance < follower.landWithin then
								stopDrift()
								return false
							end
							-- Never faster than reaches the spot this frame, so it doesn't overshoot.
							root.AssemblyLinearVelocity = offset.Unit * math.min(follower.driftSpeed, distance / math.max(deltaTime, 1 / 120))
							local heading = flat(offset)
							if heading.Magnitude > 0.1 then root.CFrame = CFrame.lookAt(root.Position, root.Position + heading) end
							return false
						end
						local arrived = flat(offset).Magnitude < stopDistance and math.abs(offset.Y) < 4
						if hold or arrived then
							humanoid:Move(Vector3.zero, false)
							if hold then humanoid.Jump = false end
							follower.lastPosition, follower.lastMoveAt, follower.hopped = root.Position, now, false
							return arrived
						end
						-- Too far to walk, or no way there on foot: float there instead. (farDrift: floated
						-- for being far, so it can land once it's within landWithin.)
						if follower.noPath or (follower.driftBeyond and offset.Magnitude > follower.driftBeyond) then
							follower.farDrift = not follower.noPath
							startDrift(character)
							return false
						end
						-- A new path when there isn't one, or the destination has moved on from it.
						if not follower.computing and now - follower.pathAt > 1
							and (not follower.waypoints or not follower.goal or (destination - follower.goal).Magnitude > 4) then
							local ground = groundBelow(destination, { character, follower.ignore })
							requestPath(root.Position, ground and Vector3.new(destination.X, ground, destination.Z) or destination, destination)
						end
						local direction = pathDirection(root) or flat(offset)
						if direction.Magnitude > 0.05 then humanoid:Move(direction.Unit, false) end
						if follower.jump then
							follower.jump = false
							humanoid.Jump = true
						end
						-- Not getting anywhere: a hop, and if that doesn't do it, float over.
						if not follower.lastPosition or (root.Position - follower.lastPosition).Magnitude > 1.5 then
							follower.lastPosition, follower.lastMoveAt, follower.hopped = root.Position, now, false
						elseif now - follower.lastMoveAt > 2 then
							follower.farDrift = false
							startDrift(character)
						elseif now - follower.lastMoveAt > 0.8 and not follower.hopped then
							follower.hopped = true
							humanoid.Jump = true
						end
						return false
					end
					return follower
				end

				withIcon(trollTabs.players, "CreateSection", { name = "Follow them about" }, "footprints", "ghost")
				-- Weeping Angel: you creep up on your target, but the moment they turn towards you (with
				-- nothing in the way) you freeze mid-step, and creep on once they look away. Close up, you
				-- wait frozen right by them. If they climb up out of reach, you float up after them
				-- (freezing in mid-air when they look). From far off (spectating someone across the map,
				-- say) you fly over quickly, out of their sight, and creep the last stretch on foot. Your
				-- own keys don't move you while it's on.
				local angelState = { frozen = false, animate = nil }
				local angelFollower = newFollower()
				angelFollower.driftBeyond = 60
				angelFollower.landWithin = 40
				local angelParams = RaycastParams.new()
				angelParams.FilterType = Enum.RaycastFilterType.Exclude
				-- Frozen, your animations stop where they are. Roblox's Animate script is paused as well,
				-- or it would swap your walk for standing still the moment you stop moving.
				local function setAngelFrozen(frozen)
					if angelState.frozen == frozen then return end
					angelState.frozen = frozen
					local character, humanoid = myCharacter()
					local animate = character and character:FindFirstChild("Animate")
					if frozen and animate and animate:IsA("BaseScript") and not animate.Disabled and animate ~= heldAnimate then
						animate.Disabled = true
						angelState.animate = animate
					end
					trolling.angelFrozen = frozen
					updateSpeedLoop()
					local paused = not frozen and angelState.animate
					if paused then
						angelState.animate = nil
						if paused.Parent and paused.Disabled then
							if next(animateHolds) ~= nil then
								-- Something else wants it off now (Mannequin, say), so it's theirs to start again.
								heldAnimate = heldAnimate or paused
							else
								-- It starts over when it's switched back on, so the frozen poses go first.
								stopAllTracks(humanoid, 0.15)
								paused.Disabled = false
							end
						end
					end
				end
				-- Whether they could see you: you're within 60 degrees of the way they face, no more than 120
				-- studs off (any further and they couldn't make you out), and there's no wall in between.
				local function angelSeen(theirCharacter, theirRoot, character, root)
					local facing = flat(theirRoot.CFrame.LookVector)
					local toMe = flat(root.Position - theirRoot.Position)
					if toMe.Magnitude > 120 then return false end
					if facing.Magnitude < 0.1 or toMe.Magnitude < 0.1 then return true end
					if facing.Unit:Dot(toMe.Unit) < 0.5 then return false end
					local theirHead = theirCharacter:FindFirstChild("Head")
					local myHead = character:FindFirstChild("Head")
					local from = theirHead and theirHead.Position or theirRoot.Position
					local to = myHead and myHead.Position or root.Position
					angelParams.FilterDescendantsInstances = { theirCharacter, character }
					local hit = workspace:Raycast(from, to - from, angelParams)
					return hit == nil or hit.Instance.Transparency >= 0.8
				end
				local function setWeepingAngel(enabled)
					afterControls("SpreadCheeksWeepingAngel", nil)
					angelFollower.reset()
					setAngelFrozen(false)
					if not enabled then return end
					local target = targetFor("Weeping Angel")
					if not target then return false end
					if not myCharacter() then
						notify("Weeping Angel", "Your character isn't ready yet.")
						return false
					end
					claimMovement("Weeping Angel")
					afterControls("SpreadCheeksWeepingAngel", function(deltaTime)
						if not target.Parent then
							notify("Weeping Angel", menuModules.nameOf(target) .. " left the server")
							return switchOff("Weeping Angel")
						end
						local character, humanoid, root = myCharacter()
						if not humanoid then return end
						local theirCharacter = target.Character
						local theirRoot = theirCharacter and getRoot(theirCharacter)
						if not theirRoot then
							-- Waiting where you are while they respawn.
							angelFollower.step(deltaTime, character, humanoid, root, root.Position, 1, true)
							return setAngelFrozen(false)
						end
						local fromThem = flat(root.Position - theirRoot.Position)
						local close = fromThem.Magnitude < 4.5 and math.abs(root.Position.Y - theirRoot.Position.Y) < 4
						-- Stock still while they're watching, and once you're right by them.
						local still = close or angelSeen(theirCharacter, theirRoot, character, root)
						setAngelFrozen(still)
						-- Headed for just your side of them: flying fast while you're well out of sight, and
						-- slowly once you're near enough for it to be creepy.
						local side = fromThem.Magnitude > 0.1 and fromThem.Unit or -flat(theirRoot.CFrame.LookVector)
						angelFollower.driftSpeed = fromThem.Magnitude > 120 and 80 or 25
						angelFollower.ignore = theirCharacter
						angelFollower.step(deltaTime, character, humanoid, root, theirRoot.Position + side * 3, 1.5, still)
					end)
				end
				targetedSwitches["Weeping Angel"] = setWeepingAngel
				addQuickToggle(trollTabs.players, "Weeping Angel", "Creep up on your target, freezing mid-step whenever they turn round to look", setWeepingAngel, "ghost", "eye")

				-- Bodyguard: you stick by your target's side like security, on the side picked in its
				-- settings card. When anyone else gets within range of them you step in between and stare
				-- them down, and once they've gone you're back at your post. You walk, round walls and up
				-- stairs, and fly over when they're far off. Your own keys don't move you while it's on.
				local guardFollower = newFollower()
				guardFollower.driftSpeed = 40
				guardFollower.driftBeyond = 60
				-- Where your post is, from them: x is to their right and z is behind them.
				local guardPosts = {
					Right = Vector3.new(3, 0, 0.5), Left = Vector3.new(-3, 0, 0.5),
					Behind = Vector3.new(0, 0, 3.5), ["In front"] = Vector3.new(0, 0, -3.5),
				}
				local function setBodyguard(enabled)
					afterControls("SpreadCheeksBodyguard", nil)
					guardFollower.reset()
					if not enabled then return end
					local target = targetFor("Bodyguard")
					if not target then return false end
					if not myCharacter() then
						notify("Bodyguard", "Your character isn't ready yet.")
						return false
					end
					claimMovement("Bodyguard")
					afterControls("SpreadCheeksBodyguard", function(deltaTime)
						if not target.Parent then
							notify("Bodyguard", menuModules.nameOf(target) .. " left the server")
							return switchOff("Bodyguard")
						end
						local character, humanoid, root = myCharacter()
						if not humanoid then return end
						local theirCharacter = target.Character
						local theirRoot = theirCharacter and getRoot(theirCharacter)
						if not theirRoot then
							guardFollower.step(deltaTime, character, humanoid, root, root.Position, 1, true)
							return
						end
						-- The nearest other player inside their personal space, if anyone's there.
						local intruderRoot, nearest = nil, featureSettings.trollGuardRange
						for _, player in ipairs(Players:GetPlayers()) do
							local otherRoot = player ~= localPlayer and player ~= target and player.Character and getRoot(player.Character)
							if otherRoot then
								local distance = (otherRoot.Position - theirRoot.Position).Magnitude
								if distance < nearest then intruderRoot, nearest = otherRoot, distance end
							end
						end
						local post, facing
						if intruderRoot then
							-- In between them, facing whoever it is.
							local towards = flat(intruderRoot.Position - theirRoot.Position)
							towards = towards.Magnitude > 0.1 and towards.Unit or flat(theirRoot.CFrame.LookVector)
							post = theirRoot.Position + towards * 3
							facing = flat(intruderRoot.Position - root.Position)
						else
							post = theirRoot.CFrame:PointToWorldSpace(guardPosts[featureSettings.trollGuardSide] or guardPosts.Right)
							facing = flat(theirRoot.CFrame.LookVector)
						end
						guardFollower.ignore = theirCharacter
						if guardFollower.step(deltaTime, character, humanoid, root, post, 1.5, false) and facing.Magnitude > 0.1 then
							-- At your post: turning to face the way they face, or to stare someone down.
							local wanted = CFrame.lookAt(root.Position, root.Position + facing)
							root.CFrame = root.CFrame:Lerp(wanted, math.clamp(deltaTime * 10, 0, 1))
						end
					end)
				end
				targetedSwitches["Bodyguard"] = setBodyguard
				addQuickToggle(trollTabs.players, "Bodyguard", "Stick by your target like security and stare down anyone who gets close. Right-click for where you stand", setBodyguard, "shield-check", "shield")

				-- Nothing Personal: you stand just behind your target, and whenever they turn round to look
				-- at you (the same check as Weeping Angel), you vanish and reappear right behind them again,
				-- so they can never catch you in front of them. You walk after them as they move, and fly
				-- over when they're far off. How far behind and how long between blinks are in its settings
				-- card. Your own keys don't move you while it's on.
				local blinkFollower = newFollower()
				blinkFollower.driftSpeed = 40
				blinkFollower.driftBeyond = 60
				local blinkState = { lastBlink = 0 }
				local blinkParams = RaycastParams.new()
				blinkParams.FilterType = Enum.RaycastFilterType.Exclude
				-- Straight behind them first, then round to their sides, for when their back is to a wall.
				local blinkAngles = { 0, math.rad(45), math.rad(-45), math.rad(90), math.rad(-90) }
				-- Where to reappear: behind them (closer in if a wall's there), with floor under it. Nil if
				-- there's nowhere.
				local function spotBehind(theirCharacter, theirRoot, character)
					local back = -flat(theirRoot.CFrame.LookVector)
					back = back.Magnitude > 0.1 and back.Unit or Vector3.new(0, 0, 1)
					blinkParams.FilterDescendantsInstances = { theirCharacter, character }
					for _, angle in ipairs(blinkAngles) do
						local direction = CFrame.Angles(0, angle, 0):VectorToWorldSpace(back)
						local distance = featureSettings.trollBlinkDistance
						local wall = workspace:Raycast(theirRoot.Position, direction * (distance + 1), blinkParams)
						if wall then distance = (wall.Position - theirRoot.Position).Magnitude - 1.5 end
						if distance >= 1.5 then
							local spot = theirRoot.Position + direction * distance
							if groundBelow(spot, { theirCharacter, character }) then return spot end
						end
					end
					return nil
				end
				local function setNothingPersonal(enabled)
					afterControls("SpreadCheeksNothingPersonal", nil)
					blinkFollower.reset()
					if not enabled then return end
					local target = targetFor("Nothing Personal")
					if not target then return false end
					if not myCharacter() then
						notify("Nothing Personal", "Your character isn't ready yet.")
						return false
					end
					claimMovement("Nothing Personal")
					afterControls("SpreadCheeksNothingPersonal", function(deltaTime)
						if not target.Parent then
							notify("Nothing Personal", menuModules.nameOf(target) .. " left the server")
							return switchOff("Nothing Personal")
						end
						local character, humanoid, root = myCharacter()
						if not humanoid then return end
						local theirCharacter = target.Character
						local theirRoot = theirCharacter and getRoot(theirCharacter)
						if not theirRoot then
							-- Waiting where you are while they respawn.
							blinkFollower.step(deltaTime, character, humanoid, root, root.Position, 1, true)
							return
						end
						local now = os.clock()
						-- They've turned to look: gone, and behind them again.
						if now - blinkState.lastBlink > featureSettings.trollBlinkCooldown and angelSeen(theirCharacter, theirRoot, character, root) then
							local spot = spotBehind(theirCharacter, theirRoot, character)
							if spot then
								blinkState.lastBlink = now
								blinkFollower.reset()
								root.CFrame = CFrame.lookAt(spot, Vector3.new(theirRoot.Position.X, spot.Y, theirRoot.Position.Z))
								root.AssemblyLinearVelocity = Vector3.zero
								return
							end
						end
						-- The rest of the time, keeping your spot behind them, facing their back.
						local back = -flat(theirRoot.CFrame.LookVector)
						back = back.Magnitude > 0.1 and back.Unit or Vector3.new(0, 0, 1)
						blinkFollower.ignore = theirCharacter
						if blinkFollower.step(deltaTime, character, humanoid, root, theirRoot.Position + back * featureSettings.trollBlinkDistance, 1.5, false) then
							local facing = flat(theirRoot.Position - root.Position)
							if facing.Magnitude > 0.1 then
								root.CFrame = root.CFrame:Lerp(CFrame.lookAt(root.Position, root.Position + facing), math.clamp(deltaTime * 10, 0, 1))
							end
						end
					end)
				end
				targetedSwitches["Nothing Personal"] = setNothingPersonal
				addQuickToggle(trollTabs.players, "Nothing Personal", "Whenever your target turns to look at you, you vanish and reappear right behind them", setNothingPersonal, "zap", "ghost")

				-- Hype Man: you hang about in front of your target, off to one side and facing them, and
				-- every time they jump or do an emote you cheer them on with a random cheer. What sets you off
				-- is in its settings card. You walk after them as they move, and fly over when they're far
				-- off. Your own keys don't move you while it's on.
				local hypeFollower = newFollower()
				hypeFollower.driftSpeed = 40
				hypeFollower.driftBeyond = 60
				-- seen holds the target's animations that have already been noticed, so each new one counts once.
				local hypeState = { track = nil, lastCheer = 0, rising = false, animator = nil, seen = setmetatable({}, { __mode = "k" }), lastScan = 0 }
				-- Classic Cheer first: it's the one with an R6 version.
				local hypeCheers = { "Cheer", "Applaud", "Jumping Cheer", "Celebrate", "Stadium", "Louder" }
				local function stopHypeTrack()
					if hypeState.track then
						pcall(function() hypeState.track:Stop(0.3) end)
						hypeState.track = nil
					end
				end
				-- One cheer, at most every couple of seconds, stopping by itself.
				local function hypeCheer(humanoid)
					local now = os.clock()
					if now - hypeState.lastCheer < 2.5 then return end
					local choices = {}
					for _, name in ipairs(hypeCheers) do
						local emote = emoteByName[name]
						local id = emote and (isR15(humanoid) and emote.r15 or emote.r6)
						if id then table.insert(choices, id) end
					end
					if #choices == 0 then return end
					hypeState.lastCheer = now
					stopHypeTrack()
					local track = playOnMe("rbxassetid://" .. tostring(choices[math.random(1, #choices)]))
					hypeState.track = track
					if not track then return end
					track.Looped = false
					task.delay(2.2, function()
						if hypeState.track == track then stopHypeTrack() end
					end)
				end
				-- Whether they've started an emote since the last look: an action animation not seen before.
				-- The first look at a character only takes note of what's already playing.
				local function startedEmote(theirHumanoid)
					local animator = animatorOf(theirHumanoid)
					if not animator then return false end
					local firstLook = animator ~= hypeState.animator
					hypeState.animator = animator
					local started = false
					for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
						if not hypeState.seen[track] then
							hypeState.seen[track] = true
							local priority = track.Priority
							if not firstLook and priority ~= Enum.AnimationPriority.Core and priority.Value >= Enum.AnimationPriority.Action.Value then
								started = true
							end
						end
					end
					return started
				end
				local function setHypeMan(enabled)
					afterControls("SpreadCheeksHypeMan", nil)
					hypeFollower.reset()
					stopHypeTrack()
					hypeState.animator, hypeState.rising = nil, false
					if not enabled then return end
					local target = targetFor("Hype Man")
					if not target then return false end
					if not myCharacter() then
						notify("Hype Man", "Your character isn't ready yet.")
						return false
					end
					claimMovement("Hype Man")
					afterControls("SpreadCheeksHypeMan", function(deltaTime)
						if not target.Parent then
							notify("Hype Man", menuModules.nameOf(target) .. " left the server")
							return switchOff("Hype Man")
						end
						local character, humanoid, root = myCharacter()
						if not humanoid then return end
						local theirCharacter = target.Character
						local theirRoot = theirCharacter and getRoot(theirCharacter)
						if not theirRoot then
							hypeFollower.step(deltaTime, character, humanoid, root, root.Position, 1, true)
							return
						end
						-- A jump: they've just started going up fast.
						local rising = theirRoot.AssemblyLinearVelocity.Y > 12
						local jumped = rising and not hypeState.rising
						hypeState.rising = rising
						-- Emotes are looked for five times a second.
						local now = os.clock()
						local emoted = false
						if now - hypeState.lastScan > 0.2 then
							hypeState.lastScan = now
							emoted = startedEmote(theirCharacter:FindFirstChildOfClass("Humanoid"))
						end
						if (jumped and featureSettings.trollHypeJump) or (emoted and featureSettings.trollHypeEmote) then
							hypeCheer(humanoid)
						end
						-- In front of them and off to their right, a few studs away, facing them.
						local look = flat(theirRoot.CFrame.LookVector)
						look = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
						local spot = theirRoot.Position + CFrame.Angles(0, -math.rad(40), 0):VectorToWorldSpace(look) * 5
						hypeFollower.ignore = theirCharacter
						if hypeFollower.step(deltaTime, character, humanoid, root, spot, 1.5, false) then
							local facing = flat(theirRoot.Position - root.Position)
							if facing.Magnitude > 0.1 then
								root.CFrame = root.CFrame:Lerp(CFrame.lookAt(root.Position, root.Position + facing), math.clamp(deltaTime * 10, 0, 1))
							end
						end
					end)
				end
				targetedSwitches["Hype Man"] = setHypeMan
				addQuickToggle(trollTabs.players, "Hype Man", "Stand by your target and cheer every time they jump or do an emote. Right-click for what sets you off", setHypeMan, "party-popper", "megaphone")

				-- Echo: you do exactly what your target did a moment ago (2 seconds to start with, in its
				-- settings card): the same path, the same turns and the same jumps, like a delayed shadow.
				-- While it waits for the first moment to copy, you go to where they were then. Off their
				-- path by more than a few studs (starting far away, or knocked off it), you fly back onto it,
				-- faster than anyone runs, so you always catch up. Your own keys don't move you while it's on.
				do
					local echoFollower = newFollower()
					echoFollower.driftSpeed = 60
					echoFollower.driftBeyond = 8
					local echo = { samples = {}, lastSample = 0, wasJumping = false, catchingUp = false }
					local function setEcho(enabled)
						afterControls("SpreadCheeksEcho", nil)
						echoFollower.reset()
						table.clear(echo.samples)
						echo.lastSample, echo.wasJumping, echo.catchingUp = 0, false, false
						if not enabled then return end
						local target = targetFor("Echo")
						if not target then return false end
						if not myCharacter() then
							notify("Echo", "Your character isn't ready yet.")
							return false
						end
						claimMovement("Echo")
						notify("Echo", "Copying " .. menuModules.nameOf(target) .. ", " .. featureSettings.trollEchoDelay .. " seconds behind", 2.5)
						afterControls("SpreadCheeksEcho", function(deltaTime)
							if not target.Parent then
								notify("Echo", menuModules.nameOf(target) .. " left the server")
								return switchOff("Echo")
							end
							local character, humanoid, root = myCharacter()
							if not humanoid then return end
							local now = os.clock()
							local theirCharacter = target.Character
							local theirRoot = theirCharacter and getRoot(theirCharacter)
							local theirHumanoid = theirCharacter and theirCharacter:FindFirstChildOfClass("Humanoid")
							-- What they're doing now, twenty times a second, to do later.
							if theirRoot and now - echo.lastSample >= 0.05 then
								echo.lastSample = now
								-- Other players' jump state doesn't always reach you, so rising fast counts too.
								local jumping = theirRoot.AssemblyLinearVelocity.Y > 10
									or (theirHumanoid ~= nil and theirHumanoid:GetState() == Enum.HumanoidStateType.Jumping)
								table.insert(echo.samples, {
									at = now, position = theirRoot.Position, yaw = yawOf(theirRoot.CFrame.LookVector),
									jump = jumping and not echo.wasJumping,
								})
								echo.wasJumping = jumping
							end
							-- On to the moment you're copying, jumping where they jumped on the way.
							local playTime = now - featureSettings.trollEchoDelay
							local samples = echo.samples
							local jump = false
							while samples[2] and samples[2].at <= playTime do
								if table.remove(samples, 1).jump then jump = true end
							end
							local current, upcoming = samples[1], samples[2]
							-- Nothing of theirs yet (they're respawning, say): wait where you are.
							if not current then
								humanoid:Move(Vector3.zero, false)
								humanoid.Jump = false
								return
							end
							-- Too soon to copy anything: over to where they were, ready to start from there.
							if current.at > playTime then upcoming = nil end
							local alpha = upcoming and math.clamp((playTime - current.at) / math.max(upcoming.at - current.at, 0.001), 0, 1) or 0
							local wanted = upcoming and current.position:Lerp(upcoming.position, alpha) or current.position
							local offset = wanted - root.Position
							-- Off their path: fly back onto it first.
							if offset.Magnitude > 8 then
								echo.catchingUp = true
								echoFollower.ignore = theirCharacter
								echoFollower.step(deltaTime, character, humanoid, root, wanted, 2, false)
								return
							end
							if echo.catchingUp then
								echo.catchingUp = false
								echoFollower.reset()
							end
							-- Walking the way they walked, kept on their path, turned the way they faced.
							local travel = upcoming and flat(upcoming.position - current.position) or Vector3.zero
							humanoid:Move(travel.Magnitude > 0.05 and travel.Unit or Vector3.zero, false)
							humanoid.Jump = jump
							local frame = math.max(deltaTime, 1 / 120)
							local horizontal = flat(offset) / frame
							if horizontal.Magnitude > 60 then horizontal = horizontal.Unit * 60 end
							local vertical = math.abs(offset.Y) > 4 and math.clamp(offset.Y / frame, -60, 60) or root.AssemblyLinearVelocity.Y
							root.AssemblyLinearVelocity = Vector3.new(horizontal.X, vertical, horizontal.Z)
							root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, current.yaw, 0)
						end)
					end
					targetedSwitches["Echo"] = setEcho
					addQuickToggle(trollTabs.players, "Echo", "Do exactly what your target did a couple of seconds ago, like a delayed shadow. Right-click for how far behind", setEcho, "audio-waveform", "repeat")
				end

				-- Stare: you keep turning to stare straight at your target wherever they go, and walk about as
				-- normal while you do. Creepy, and harmless.
				do
					local stare = { humanoid = nil, autoRotate = true }
					local function letGo()
						if stare.humanoid and stare.humanoid.Parent then stare.humanoid.AutoRotate = stare.autoRotate end
						stare.humanoid = nil
					end
					local function setStare(enabled)
						afterControls("SpreadCheeksStare", nil)
						letGo()
						if not enabled then return end
						local target = targetFor("Stare")
						if not target then return false end
						claimMovement("Stare")
						afterControls("SpreadCheeksStare", function()
							if not target.Parent then
								notify("Stare", menuModules.nameOf(target) .. " left the server")
								return switchOff("Stare")
							end
							local _, humanoid, root = myCharacter()
							if not humanoid then return end
							-- Your own turning is off while it stares, on each new character too.
							if stare.humanoid ~= humanoid then
								letGo()
								stare.humanoid, stare.autoRotate = humanoid, humanoid.AutoRotate
								humanoid.AutoRotate = false
							end
							local theirRoot = target.Character and getRoot(target.Character)
							if not theirRoot then return end
							local towards = flat(theirRoot.Position - root.Position)
							if towards.Magnitude > 0.1 then root.CFrame = CFrame.lookAt(root.Position, root.Position + towards) end
						end)
					end
					targetedSwitches["Stare"] = setStare
					addQuickToggle(trollTabs.players, "Stare", "Keep staring right at your target wherever they go, while you walk about as normal", setStare, "eye", "scan-eye")
				end

				-- Scaredy Cat: you keep away from your target. Whenever they come within the distance in its
				-- settings card you run off, away from them and round anything in the way, and once you're
				-- well clear you stop and turn to peek back at them (shyly, on R15); backed into a corner, you
				-- cower. While they keep away you follow them about from a distance, too curious to leave
				-- (unless that's off in the card). Your own keys don't move you while it's on.
				do
					local scaredFollower = newFollower()
					scaredFollower.driftSpeed = 40
					scaredFollower.driftBeyond = 80
					scaredFollower.landWithin = 50
					local scared = { fleeing = false, fleeTo = nil, fleeAt = 0, lastReaction = 0, track = nil }
					local scaredParams = RaycastParams.new()
					scaredParams.FilterType = Enum.RaycastFilterType.Exclude
					-- Straight away from them first, then turning further off to either side.
					local fleeAngles = { 0, math.rad(35), math.rad(-35), math.rad(70), math.rad(-70), math.rad(110), math.rad(-110) }
					local function stopReaction()
						if scared.track then
							pcall(function() scared.track:Stop(0.3) end)
							scared.track = nil
						end
					end
					-- A gesture (Shy or Cower) played once, at most every few seconds. Both need R15.
					local function react(humanoid, name)
						local now = os.clock()
						if now - scared.lastReaction < 5 then return end
						local emote = emoteByName[name]
						local id = emote and (isR15(humanoid) and emote.r15 or emote.r6)
						if not id then return end
						scared.lastReaction = now
						stopReaction()
						local track = playOnMe("rbxassetid://" .. tostring(id))
						scared.track = track
						if not track then return end
						track.Looped = false
						task.delay(2.5, function()
							if scared.track == track then stopReaction() end
						end)
					end
					-- Somewhere to run to: away from them and a good way off (less if a wall's in the way),
					-- with floor under it. Nil when there's nowhere.
					local function fleeSpot(character, root, theirCharacter, away)
						scaredParams.FilterDescendantsInstances = { character, theirCharacter }
						for _, angle in ipairs(fleeAngles) do
							local direction = CFrame.Angles(0, angle, 0):VectorToWorldSpace(away)
							local distance = 18
							local wall = workspace:Raycast(root.Position, direction * distance, scaredParams)
							if wall then distance = (wall.Position - root.Position).Magnitude - 2 end
							if distance >= 6 then
								local spot = root.Position + direction * distance
								if groundBelow(spot, { character, theirCharacter }) then return spot end
							end
						end
						return nil
					end
					local function setScaredyCat(enabled)
						afterControls("SpreadCheeksScaredyCat", nil)
						scaredFollower.reset()
						stopReaction()
						scared.fleeing, scared.fleeTo = false, nil
						if not enabled then return end
						local target = targetFor("Scaredy Cat")
						if not target then return false end
						if not myCharacter() then
							notify("Scaredy Cat", "Your character isn't ready yet.")
							return false
						end
						claimMovement("Scaredy Cat")
						afterControls("SpreadCheeksScaredyCat", function(deltaTime)
							if not target.Parent then
								notify("Scaredy Cat", menuModules.nameOf(target) .. " left the server")
								return switchOff("Scaredy Cat")
							end
							local character, humanoid, root = myCharacter()
							if not humanoid then return end
							local theirCharacter = target.Character
							local theirRoot = theirCharacter and getRoot(theirCharacter)
							if not theirRoot then
								scaredFollower.step(deltaTime, character, humanoid, root, root.Position, 1, true)
								return
							end
							local now = os.clock()
							local away = flat(root.Position - theirRoot.Position)
							local distance = away.Magnitude
							if distance < 0.1 then
								away = flat(theirRoot.CFrame.LookVector)
								if away.Magnitude < 0.1 then away = Vector3.new(0, 0, 1) end
							end
							away = away.Unit
							local scareAt = featureSettings.trollScaredDistance
							local safeAt = scareAt + 8
							scaredFollower.ignore = theirCharacter
							if distance < scareAt and not scared.fleeing then
								-- Too close: off you run.
								scared.fleeing, scared.fleeTo = true, nil
								stopReaction()
							elseif scared.fleeing and distance >= safeAt then
								-- Well clear: you stop and peek back at them.
								scared.fleeing, scared.fleeTo = false, nil
								scaredFollower.reset()
								react(humanoid, "Shy")
							end
							if scared.fleeing then
								-- Which way to run, worked out again every half second as they come after you.
								if not scared.fleeTo or now - scared.fleeAt > 0.5 then
									scared.fleeTo = fleeSpot(character, root, theirCharacter, away)
									scared.fleeAt = now
								end
								if scared.fleeTo then
									scaredFollower.step(deltaTime, character, humanoid, root, scared.fleeTo, 1.5, false)
									return
								end
								-- Backed into a corner, with nowhere to run: you cower where you are.
								if scaredFollower.drifting then scaredFollower.reset() end
								scaredFollower.step(deltaTime, character, humanoid, root, root.Position, 1, true)
								react(humanoid, "Cower")
								return
							end
							if featureSettings.trollScaredFollow and distance > safeAt + 15 then
								-- They've wandered off: creeping after them, never too close.
								scaredFollower.step(deltaTime, character, humanoid, root, theirRoot.Position + away * safeAt, 2, false)
								return
							end
							-- Keeping your distance, on the ground, turned to watch them.
							if scaredFollower.drifting then scaredFollower.reset() end
							scaredFollower.step(deltaTime, character, humanoid, root, root.Position, 1, true)
							root.CFrame = root.CFrame:Lerp(CFrame.lookAt(root.Position, root.Position - away), math.clamp(deltaTime * 8, 0, 1))
						end)
					end
					targetedSwitches["Scaredy Cat"] = setScaredyCat
					addQuickToggle(trollTabs.players, "Scaredy Cat", "Run away whenever your target comes near, then peek back at them from a safe distance. Right-click for how near", setScaredyCat, "cat", "footprints")
				end

				-- Leapfrog: you leap right over your target's head, land on their other side, turn round and
				-- leap back again, over and over. Each leap clears their head by the height in its settings
				-- card, moves with them if they're walking, and passes through everything, so they never get
				-- bumped. Between leaps you get into place a few studs from them, walking round walls and up
				-- stairs, and flying over when they're far off. Your own keys don't move you while it's on.
				do
					local leapFollower = newFollower()
					leapFollower.driftSpeed = 40
					leapFollower.driftBeyond = 60
					leapFollower.landWithin = 25
					-- current: the leap under way, if any. readyAt: when the next one can start.
					local leap = { current = nil, readyAt = 0, noclip = nil, collisions = nil }
					local function stopNoclip()
						if leap.noclip then
							leap.noclip:Disconnect()
							leap.noclip = nil
						end
						for part, canCollide in pairs(leap.collisions or {}) do
							if part.Parent then part.CanCollide = canCollide end
						end
						leap.collisions = nil
					end
					-- Through everything while you leap. The humanoid keeps turning collisions back on, so
					-- they're switched off every frame.
					local function startNoclip(character)
						stopNoclip()
						leap.collisions = {}
						for _, part in ipairs(character:GetDescendants()) do
							if part:IsA("BasePart") then leap.collisions[part] = part.CanCollide end
						end
						leap.noclip = RunService.Stepped:Connect(function()
							for part in pairs(leap.collisions) do
								if part.Parent then part.CanCollide = false end
							end
						end)
					end
					local function endLeap()
						leap.current = nil
						stopNoclip()
					end
					local function setLeapfrog(enabled)
						afterControls("SpreadCheeksLeapfrog", nil)
						leapFollower.reset()
						endLeap()
						leap.readyAt = 0
						if not enabled then return end
						local target = targetFor("Leapfrog")
						if not target then return false end
						if not myCharacter() then
							notify("Leapfrog", "Your character isn't ready yet.")
							return false
						end
						claimMovement("Leapfrog")
						afterControls("SpreadCheeksLeapfrog", function(deltaTime)
							if not target.Parent then
								notify("Leapfrog", menuModules.nameOf(target) .. " left the server")
								return switchOff("Leapfrog")
							end
							local character, humanoid, root = myCharacter()
							if not humanoid then return endLeap() end
							local theirCharacter = target.Character
							local theirRoot = theirCharacter and getRoot(theirCharacter)
							if not theirRoot then
								endLeap()
								leapFollower.step(deltaTime, character, humanoid, root, root.Position, 1, true)
								return
							end
							local now = os.clock()
							local standing = isR15(humanoid) and (humanoid.HipHeight + root.Size.Y / 2) or 3
							local current = leap.current
							if current then
								-- In the air: along an arc that moves with them, flat across the top so you're
								-- high the whole way over them.
								local progress = math.clamp((now - current.started) / current.duration, 0, 1)
								local base = theirRoot.Position
								local across = current.from:Lerp(current.to, progress)
								local landing = groundBelow(base + current.to, { character, theirCharacter })
								local endY = landing and landing + standing or base.Y
								local head = theirCharacter:FindFirstChild("Head")
								local top = head and head:IsA("BasePart") and head.Position.Y + head.Size.Y / 2 or base.Y + 2.5
								local middle = current.startY + (endY - current.startY) * 0.5
								local rise = math.max(2, top + featureSettings.trollLeapHeight + standing - middle)
								local height = current.startY + (endY - current.startY) * progress + rise * (1 - (2 * progress - 1) ^ 4)
								local position = Vector3.new(base.X + across.X, height, base.Z + across.Z)
								root.AssemblyLinearVelocity = (position - root.Position) / math.max(deltaTime, 1 / 120)
								root.AssemblyAngularVelocity = Vector3.zero
								-- Leaning into it over the top.
								root.CFrame = CFrame.lookAt(position, position + current.direction) * CFrame.Angles(-math.rad(25) * math.sin(progress * math.pi), 0, 0)
								if progress >= 1 then
									endLeap()
									root.AssemblyLinearVelocity = flat(theirRoot.AssemblyLinearVelocity)
									leap.readyAt = now + featureSettings.trollLeapPause
									leapFollower.reset()
								end
								return
							end
							-- Into place a few studs from them, on whichever side you're on, facing them.
							local fromThem = flat(root.Position - theirRoot.Position)
							local side = fromThem
							if side.Magnitude < 0.1 then
								side = -flat(theirRoot.CFrame.LookVector)
								if side.Magnitude < 0.1 then side = Vector3.new(0, 0, 1) end
							end
							side = side.Unit
							leapFollower.ignore = theirCharacter
							if not leapFollower.step(deltaTime, character, humanoid, root, theirRoot.Position + side * 3.5, 1.2, false) then return end
							root.CFrame = root.CFrame:Lerp(CFrame.lookAt(root.Position, root.Position - side), math.clamp(deltaTime * 10, 0, 1))
							-- Then over them, to the same distance on their other side.
							if now < leap.readyAt or math.abs(root.Position.Y - theirRoot.Position.Y) > 6 then return end
							leap.current = {
								started = now, duration = 0.8, startY = root.Position.Y,
								from = fromThem, to = -side * 3.5, direction = -side,
							}
							startNoclip(character)
							humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
						end)
					end
					targetedSwitches["Leapfrog"] = setLeapfrog
					addQuickToggle(trollTabs.players, "Leapfrog", "Keep leaping right over your target's head, back and forth, without ever touching them. Right-click for how high", setLeapfrog, "rabbit", "chevrons-up")
				end

				-- Puppy: you follow your target about like a pet dog, trotting at their heels (as close as its
				-- settings card says). When they stop, you sit down in front of them looking up at them, with
				-- a happy hop now and then; when they jump, you jump too. Every so often while they're on the
				-- move you get the zoomies and race round them. Sitting and the zoomies can be switched off in
				-- the card. Your own keys don't move you while it's on.
				do
					local puppyFollower = newFollower()
					puppyFollower.driftSpeed = 40
					puppyFollower.driftBeyond = 60
					puppyFollower.landWithin = 25
					local puppy = { stillSince = nil, sitting = false, rising = false, zoomUntil = 0, nextZoom = 0, angle = 0, nextHop = 0 }
					local function standUp(humanoid)
						if not puppy.sitting then return end
						puppy.sitting = false
						if humanoid and humanoid.Parent then humanoid.Sit = false end
					end
					local function setPuppy(enabled)
						afterControls("SpreadCheeksPuppy", nil)
						puppyFollower.reset()
						local _, humanoid = myCharacter()
						standUp(humanoid)
						puppy.sitting, puppy.stillSince, puppy.rising, puppy.zoomUntil = false, nil, false, 0
						if not enabled then return end
						local target = targetFor("Puppy")
						if not target then return false end
						if not humanoid then
							notify("Puppy", "Your character isn't ready yet.")
							return false
						end
						claimMovement("Puppy")
						puppy.nextZoom = os.clock() + math.random(5, 10)
						afterControls("SpreadCheeksPuppy", function(deltaTime)
							if not target.Parent then
								notify("Puppy", menuModules.nameOf(target) .. " left the server")
								return switchOff("Puppy")
							end
							local character, myHumanoid, root = myCharacter()
							if not myHumanoid then return end
							local theirCharacter = target.Character
							local theirRoot = theirCharacter and getRoot(theirCharacter)
							if not theirRoot then
								standUp(myHumanoid)
								puppyFollower.step(deltaTime, character, myHumanoid, root, root.Position, 1, true)
								return
							end
							local now = os.clock()
							local velocity = theirRoot.AssemblyLinearVelocity
							local moving = flat(velocity).Magnitude > 2
							puppy.stillSince = not moving and (puppy.stillSince or now) or nil
							-- A jump: they've just started going up fast. You jump too.
							local rising = velocity.Y > 12
							local jumped = rising and not puppy.rising
							puppy.rising = rising
							local look = flat(theirRoot.CFrame.LookVector)
							look = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
							local right = Vector3.new(-look.Z, 0, look.X)
							local distance = featureSettings.trollPuppyDistance
							puppyFollower.ignore = theirCharacter
							-- The zoomies: a lap or two round them, every so often while they're moving.
							if featureSettings.trollPuppyZoomies and moving and now >= puppy.nextZoom then
								local fromThem = flat(root.Position - theirRoot.Position)
								puppy.angle = fromThem.Magnitude > 0.1 and math.atan2(fromThem.Z, fromThem.X) or 0
								puppy.zoomUntil = now + 4
								puppy.nextZoom = now + 4 + math.random(8, 16)
							end
							if now < puppy.zoomUntil then
								standUp(myHumanoid)
								local radius = distance + 2
								puppy.angle += deltaTime * 15 / radius
								local spot = theirRoot.Position + Vector3.new(math.cos(puppy.angle), 0, math.sin(puppy.angle)) * radius
								puppyFollower.step(deltaTime, character, myHumanoid, root, spot, 0.5, false)
								if jumped then myHumanoid.Jump = true end
								return
							end
							-- Stopped for a moment: sat in front of them, off to one side, looking up at them.
							if featureSettings.trollPuppySit and puppy.stillSince and now - puppy.stillSince > 1.2 then
								if not puppy.sitting then
									local spot = theirRoot.Position + (look * 0.85 + right * 0.5).Unit * distance
									if puppyFollower.step(deltaTime, character, myHumanoid, root, spot, 1.2, false) and myHumanoid.FloorMaterial ~= Enum.Material.Air then
										local facing = flat(theirRoot.Position - root.Position)
										if facing.Magnitude > 0.1 then root.CFrame = CFrame.lookAt(root.Position, root.Position + facing) end
										-- Sitting still isn't being stuck, so the walking starts afresh after.
										puppyFollower.reset()
										puppy.sitting = true
										myHumanoid.Sit = true
										puppy.nextHop = now + math.random(3, 7)
									end
									return
								end
								-- A happy hop now and then, and when they jump; you sit back down after.
								if jumped or now >= puppy.nextHop then
									standUp(myHumanoid)
									myHumanoid.Jump = true
									puppy.nextHop = now + math.random(4, 8)
								end
								return
							end
							-- On the move: trotting at their heels, a little off to one side.
							standUp(myHumanoid)
							local heel = theirRoot.Position - look * distance + right * 1.2
							if puppyFollower.step(deltaTime, character, myHumanoid, root, heel, 1.2, false) then
								root.CFrame = root.CFrame:Lerp(CFrame.lookAt(root.Position, root.Position + look), math.clamp(deltaTime * 10, 0, 1))
							end
							if jumped then myHumanoid.Jump = true end
						end)
					end
					targetedSwitches["Puppy"] = setPuppy
					addQuickToggle(trollTabs.players, "Puppy", "Follow your target like a pet dog: at their heels, sitting when they stop, zoomies now and then. Right-click for settings", setPuppy, "dog", "paw-print")
				end

				-- Parts (the Parts tab): loose parts your game lets you move, pulled into tricks and shapes.
				-- One parts trick has the parts at a time, so switching one on switches the others off. Each
				-- trick says where every part should be, and the parts are moved there by their velocity,
				-- which everyone sees as long as your client is in charge of them (in most games, loose parts
				-- near you). Parts keep a few studs away from every other player, so nobody gets hit or boxed
				-- in. Built in a function of its own, as it has a lot of parts of its own.
				do
					local partsBuilt, partsProblem = pcall(function()
						trollTabs.parts:CreateText({
							text = "These move the loose parts your game lets you move (usually ones near you), and everyone sees them. One at a time. Parts keep a few studs away from every player, so nobody gets hit or boxed in. Show Movable Parts shows which parts they can use.",
						})
						local partNames = {
							"Part Tornado", "Part Halo", "Part Art", "Part Snake", "Telekinesis", "Part Pets", "Magic Carpet",
							"Part Stairs", "Part Shield", "Zero Gravity", "Part Fountain", "Blender",
						}
						for index, first in ipairs(partNames) do
							for later = index + 1, #partNames do clash(first, partNames[later]) end
						end
						-- The carpet carries you about, so the tricks that move you clash with it too.
						for _, takeover in ipairs(takeoverSwitches) do clash("Magic Carpet", takeover) end

						-- items: { part, and whatever its trick keeps on it } for each part it has; has: the
						-- same parts as a set.
						local engine = { items = {}, has = {}, limit = 0, mode = nil, loop = nil, added = nil, serial = 0 }
						local function movable(part)
							if not part:IsA("BasePart") or part.Anchored or part.AssemblyRootPart ~= part then return false end
							if part.AssemblyMass > 500 or part:IsGrounded() then return false end
							-- Nothing that's part of a character, a player's or one the game runs.
							local model = part:FindFirstAncestorWhichIsA("Model")
							while model do
								if model:FindFirstChildOfClass("Humanoid") then return false end
								model = model:FindFirstAncestorWhichIsA("Model")
							end
							return true
						end
						-- How many parts a big trick takes, from its usual number, scaled by Most Parts (150
						-- is the usual).
						local function moreParts(count)
							return math.floor(count * featureSettings.partsMax / 150 + 0.5)
						end
						local function addPart(part)
							if engine.has[part] or #engine.items >= engine.limit or not movable(part) then return end
							engine.has[part] = true
							table.insert(engine.items, { part = part })
						end
						-- Lets go of the parts, dropped where they are.
						local function stopParts()
							engine.serial += 1
							if engine.loop then
								engine.loop:Disconnect()
								engine.loop = nil
							end
							if engine.added then
								engine.added:Disconnect()
								engine.added = nil
							end
							for _, item in ipairs(engine.items) do
								local part = item.part
								if part.Parent and not part.Anchored then
									pcall(function()
										part.AssemblyLinearVelocity = Vector3.zero
										part.AssemblyAngularVelocity = Vector3.zero
									end)
								end
							end
							table.clear(engine.items)
							table.clear(engine.has)
							engine.mode = nil
						end
						-- Where every other player is, to keep parts away from them.
						local function otherRoots()
							local roots = {}
							for _, player in ipairs(Players:GetPlayers()) do
								local root = player ~= localPlayer and player.Character and getRoot(player.Character)
								if root then table.insert(roots, root.Position) end
							end
							return roots
						end
						-- velocity, unless the part is within radius of someone: then out and away from them.
						-- Anyone but the player a trick is circling (at centre) gets the wider distance, wide,
						-- as fast parts cover more ground from one frame to the next.
						local function keepClear(part, velocity, roots, radius, wide, centre)
							for _, position in ipairs(roots) do
								local away = part.Position - position
								local limit = (centre and (position - centre).Magnitude < 0.5) and radius or wide
								if away.Magnitude < limit then
									return (away.Magnitude > 0.1 and away.Unit or Vector3.yAxis) * 30 + Vector3.new(0, 15, 0)
								end
							end
							return velocity
						end
						-- Starts a parts trick, from its mode:
						--   limit: how many parts at most, nearest you first (or lowest score(part, distance));
						--   range(): only parts that close to you;
						--   frame(now, deltaTime): set up each frame, returning false to skip it;
						--   place(item, index, count, now, deltaTime, mode): where a part goes, or nil to leave
						--     it be (item.velocity, if set, is used as it is, and item.spin spins it);
						--   orient(item, mode): turns a part; speed: the fastest parts move (studs a second,
						--     raised by Part Speed), or a function giving that outright;
						--   clear: how far parts keep from players; found(count): how many parts it got.
						local function startParts(mode)
							stopParts()
							engine.mode = mode
							engine.limit = mode.limit or 150
							local serial = engine.serial
							local _, _, root = myCharacter()
							local from = root and root.Position or workspace.CurrentCamera.CFrame.Position
							local range = mode.range and mode.range() or math.huge
							-- The map a few thousand at a time, so starting doesn't freeze the game.
							task.spawn(function()
								local found = {}
								for index, part in ipairs(workspace:GetDescendants()) do
									if index % 4000 == 0 then
										task.wait()
										if engine.serial ~= serial then return end
									end
									if part:IsA("BasePart") and not part.Anchored then
										local distance = (part.Position - from).Magnitude
										if distance <= range then
											table.insert(found, { part = part, score = mode.score and mode.score(part, distance) or distance })
										end
									end
								end
								table.sort(found, function(left, right) return left.score < right.score end)
								for _, entry in ipairs(found) do
									if engine.serial ~= serial or #engine.items >= engine.limit then break end
									if entry.part.Parent then addPart(entry.part) end
								end
								if engine.serial == serial and mode.found then mode.found(#engine.items) end
							end)
							engine.added = workspace.DescendantAdded:Connect(function(part)
								if not part:IsA("BasePart") then return end
								task.defer(function()
									if engine.serial ~= serial or not part.Parent then return end
									local _, _, myRoot = myCharacter()
									if mode.range and (not myRoot or (part.Position - myRoot.Position).Magnitude > mode.range()) then return end
									addPart(part)
								end)
							end)
							engine.loop = RunService.Heartbeat:Connect(function(deltaTime)
								-- Asking to be in charge of loose parts further away, where the executor allows it.
								if sethidden then pcall(sethidden, localPlayer, "SimulationRadius", 1e9) end
								local now = os.clock()
								if mode.frame and mode.frame(now, deltaTime) == false then return end
								local roots = otherRoots()
								local clear = mode.clear or 5
								local frame = math.max(deltaTime, 1 / 120)
								local fastest = type(mode.speed) == "function" and mode.speed()
									or (mode.speed or 150) * featureSettings.partsPower / 100
								local wide = clear + math.max(0, fastest - 150) * frame * 2
								local count = #engine.items
								local index = 1
								while index <= #engine.items do
									local item = engine.items[index]
									local part = item.part
									if not part.Parent or part.Anchored then
										engine.has[part] = nil
										table.remove(engine.items, index)
									else
										local goal = mode.place(item, index, count, now, deltaTime, mode)
										local velocity = item.velocity
										item.velocity = nil
										if goal and not velocity then
											velocity = (goal - part.Position) / frame
											if velocity.Magnitude > fastest then velocity = velocity.Unit * fastest end
										end
										if velocity then velocity = keepClear(part, velocity, roots, clear, wide, mode.centre) end
										pcall(function()
											if velocity then part.AssemblyLinearVelocity = velocity end
											part.AssemblyAngularVelocity = item.spin or Vector3.zero
											if mode.orient then mode.orient(item, mode) end
										end)
										index += 1
									end
								end
							end)
						end
						-- For the tricks round your target: keeps their root and character on mode each frame,
						-- calling mode.tick(mode) if it has one, and switches the trick off if they leave.
						local function aroundTarget(name, target, mode)
							mode.frame = function()
								if not target.Parent then
									notify(name, menuModules.nameOf(target) .. " left the server")
									switchOff(name)
									return false
								end
								local character = target.Character
								local root = character and getRoot(character)
								if not root then return false end
								mode.root, mode.character, mode.centre = root, character, root.Position
								if mode.tick then mode.tick(mode) end
								return true
							end
							mode.found = function(count)
								notify(name, count == 0 and "No loose parts here that you can move." or (count .. (count == 1 and " part" or " parts") .. " on the way to " .. menuModules.nameOf(target)), 3)
							end
							return mode
						end
						-- For the tricks round you: keeps your root and humanoid on mode, calling
						-- mode.tick(mode, now, deltaTime) if it has one.
						local function aroundYou(name, mode)
							mode.frame = function(now, deltaTime)
								local character, humanoid, root = myCharacter()
								if not root then return false end
								mode.root, mode.humanoid, mode.character = root, humanoid, character
								if mode.tick then mode.tick(mode, now, deltaTime) end
								return true
							end
							mode.found = function(count)
								notify(name, count == 0 and "No loose parts here that you can move." or (count .. (count == 1 and " part" or " parts") .. " found"), 3)
							end
							return mode
						end
						-- A switch for a parts trick. makeMode() gives the trick's mode when it's switched on,
						-- or nothing, and it stays off.
						local function partsSwitch(name, makeMode)
							return function(enabled)
								if not enabled then
									if engine.mode and engine.mode.name == name then stopParts() end
									return
								end
								local mode = makeMode()
								if not mode then return false end
								claimMovement(name)
								mode.name = name
								startParts(mode)
							end
						end
						-- Flat parts first (for standing on), then the biggest, then the nearest.
						local function flatScore(part, distance)
							local size = part.Size
							local flatness = size.Y <= math.min(size.X, size.Z) * 0.6 and 0 or 40
							return distance + flatness - math.min(size.X * size.Z, 100) * 0.3
						end
						-- How far below the root your feet are.
						local function legsOf(humanoid, root)
							return isR15(humanoid) and (humanoid.HipHeight + root.Size.Y / 2) or 3
						end
						-- Where part index of count goes swirling round center. shape: Ring, Sphere, Helix,
						-- Spiral or Wave. Ring parts each go round from the side they came in on, so none cross
						-- the middle.
						local function swirl(item, index, count, now, deltaTime, center, radius, speed, height, shape)
							if not item.angle then
								local outward = item.part.Position - center
								item.angle = math.atan2(outward.Z, outward.X)
								item.lift = math.random() * 8 - 2
								item.gap = math.random() * 3
							end
							item.angle += deltaTime * speed * 0.5
							if shape == "Sphere" then
								local down = math.acos(math.clamp(1 - 2 * (index - 0.5) / math.max(count, 1), -1, 1))
								local around = index * 2.39996 + now * speed * 0.3
								return center + Vector3.new(math.cos(around) * math.sin(down), math.cos(down), math.sin(around) * math.sin(down)) * radius + Vector3.new(0, height, 0)
							elseif shape == "Helix" then
								local along = math.floor((index - 1) / 2) / math.max(math.ceil(count / 2), 1)
								local around = along * math.pi * 4 + now * speed * 0.5 + (index % 2) * math.pi
								local reach = math.max(radius * 0.6, 5.5)
								return center + Vector3.new(math.cos(around) * reach, height - 2 + along * radius * 1.5, math.sin(around) * reach)
							elseif shape == "Spiral" then
								local around = index * 0.7 + now * speed * 0.3
								local reach = math.max(radius * 0.4, 5.5) + index / math.max(count, 1) * radius
								return center + Vector3.new(math.cos(around) * reach, height + math.sin(index) * 0.5, math.sin(around) * reach)
							elseif shape == "Wave" then
								local reach = radius + item.gap
								return center + Vector3.new(math.cos(item.angle) * reach, height + 2 + math.sin(now * 2 + item.angle * 3) * 3, math.sin(item.angle) * reach)
							end
							local reach = radius + item.gap
							return center + Vector3.new(math.cos(item.angle) * reach, height + item.lift, math.sin(item.angle) * reach)
						end
						-- A point share (0 to 1) of the way round a picture, on a square from -1 to 1.
						local function artPoint(shape, share)
							local turn = share * math.pi * 2
							if shape == "Heart" then
								return Vector2.new(16 * math.sin(turn) ^ 3, 13 * math.cos(turn) - 5 * math.cos(2 * turn) - 2 * math.cos(3 * turn) - math.cos(4 * turn)) / 17
							elseif shape == "Star" then
								-- Ten corners, out and in by turns, with the parts spread along the edges.
								local corner = share * 10
								local first = math.floor(corner)
								local function cornerAt(number)
									local reach = number % 2 == 0 and 1 or 0.42
									local angle = math.pi / 2 + number * math.pi / 5
									return Vector2.new(math.cos(angle), math.sin(angle)) * reach
								end
								return cornerAt(first):Lerp(cornerAt(first + 1), corner - first)
							end
							-- Smiley: the face round the outside, two eyes, then the smile.
							if share < 0.6 then
								local angle = share / 0.6 * math.pi * 2
								return Vector2.new(math.cos(angle), math.sin(angle))
							elseif share < 0.8 then
								local eyeTurn = (share - 0.6) / 0.1 * math.pi * 2
								local eyeX = share < 0.7 and -0.35 or 0.35
								return Vector2.new(eyeX + math.cos(eyeTurn) * 0.08, 0.35 + math.sin(eyeTurn) * 0.08)
							end
							local angle = math.pi + 0.35 + (share - 0.8) / 0.2 * (math.pi - 0.7)
							return Vector2.new(math.cos(angle) * 0.55, math.sin(angle) * 0.55 - 0.05)
						end

						-- Power, for every trick: how many parts the big ones take (Most Parts: the Tornado,
						-- Zero Gravity and the Blender take that many, Art and the Shield fewer in step) and
						-- how fast all of them move their parts into place (Part Speed). How many counts from
						-- the next time a trick starts; the speed straight away.
						withIcon(trollTabs.parts, "CreateSection", { name = "Power" }, "zap", "gauge")
						trolling.partsMaxSlider = withIcon(trollTabs.parts, "CreateSlider", {
							name = "Most Parts",
							range = { 50, 300 },
							value = featureSettings.partsMax,
							increment = 10,
							suffix = " parts",
							callback = function(value)
								if featureSettings.partsMax == value then return end
								featureSettings.partsMax = value
								saveFeatureSettings()
							end,
						}, "boxes", "layers")
						trolling.partsSpeedSlider = withIcon(trollTabs.parts, "CreateSlider", {
							name = "Part Speed",
							range = { 100, 200 },
							value = featureSettings.partsPower,
							increment = 10,
							suffix = "%",
							callback = function(value)
								if featureSettings.partsPower == value then return end
								featureSettings.partsPower = value
								saveFeatureSettings()
							end,
						}, "zap", "gauge")

						withIcon(trollTabs.parts, "CreateSection", { name = "Round your target" }, "tornado", "crosshair")
						-- Part Tornado: swirled round them in a ring, sphere, helix, spiral or wave.
						local setTornado = partsSwitch("Part Tornado", function()
							local target = targetFor("Part Tornado")
							if not target then return nil end
							-- Spins faster than 10 need faster parts to keep up, as far as 300 studs a second.
							local function top()
								return math.min(150 * math.max(1, featureSettings.trollTornadoSpeed / 10) * featureSettings.partsPower / 100, 300)
							end
							return aroundTarget("Part Tornado", target, {
								limit = moreParts(150),
								speed = top,
								place = function(item, index, count, now, deltaTime, mode)
									-- Never faster round than the parts can go, so none fall behind and cut
									-- across the middle; wide circles can't spin quite as fast.
									local spin = math.min(featureSettings.trollTornadoSpeed, 1.6 * top() / (featureSettings.trollTornadoRadius + 3))
									return swirl(item, index, count, now, deltaTime, mode.root.Position, featureSettings.trollTornadoRadius,
										spin, featureSettings.trollTornadoHeight, featureSettings.trollTornadoShape)
								end,
							})
						end)
						targetedSwitches["Part Tornado"] = setTornado
						addQuickToggle(trollTabs.parts, "Part Tornado", "Pull every loose part you can over to your target and swirl it round them. Right-click for the shape, size and speed", setTornado, "tornado", "boxes")
						-- Part Halo: a small ring spinning over their head.
						local setHalo = partsSwitch("Part Halo", function()
							local target = targetFor("Part Halo")
							if not target then return nil end
							return aroundTarget("Part Halo", target, {
								limit = 16, speed = 60, clear = 2.5,
								place = function(_, index, count, now, _, mode)
									local head = mode.character:FindFirstChild("Head")
									local top = head and head:IsA("BasePart") and (head.Position + Vector3.new(0, head.Size.Y / 2, 0)) or (mode.root.Position + Vector3.new(0, 3, 0))
									local around = index / math.max(count, 1) * math.pi * 2 + now * featureSettings.partHaloSpeed * 0.5
									local radius = featureSettings.partHaloRadius
									return top + Vector3.new(math.cos(around) * radius, featureSettings.partHaloHeight, math.sin(around) * radius)
								end,
							})
						end)
						targetedSwitches["Part Halo"] = setHalo
						addQuickToggle(trollTabs.parts, "Part Halo", "A ring of parts spinning over your target's head like a halo. Right-click for its size and speed", setHalo, "crown", "circle-dot")
						-- Part Art: a picture made of parts, up in the air in front of them, facing them.
						local setArt = partsSwitch("Part Art", function()
							local target = targetFor("Part Art")
							if not target then return nil end
							return aroundTarget("Part Art", target, {
								limit = moreParts(60),
								place = function(_, index, count, _, _, mode)
									local root = mode.root
									local look = flat(root.CFrame.LookVector)
									look = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
									local right = Vector3.new(-look.Z, 0, look.X)
									local size = featureSettings.partArtSize
									local center = root.Position + look * (size * 0.5 + 8) + Vector3.new(0, featureSettings.partArtHeight + size * 0.5, 0)
									local point = artPoint(featureSettings.partArtShape, (index - 0.5) / math.max(count, 1))
									return center + right * point.X * size * 0.5 + Vector3.new(0, point.Y * size * 0.5, 0)
								end,
							})
						end)
						targetedSwitches["Part Art"] = setArt
						addQuickToggle(trollTabs.parts, "Part Art", "Parts make a heart, smiley or star in the air in front of your target. Right-click for the picture and size", setArt, "heart", "smile")
						-- Part Snake: a line of parts slithering along behind them, the way they went.
						local setSnake = partsSwitch("Part Snake", function()
							local target = targetFor("Part Snake")
							if not target then return nil end
							-- Where they've been, about a stud apart, newest first.
							local trail = {}
							return aroundTarget("Part Snake", target, {
								limit = featureSettings.partSnakeLength, speed = 80, clear = 2,
								tick = function(mode)
									local position = mode.root.Position
									-- A respawn or a teleport starts the trail again.
									if trail[1] and (position - trail[1]).Magnitude > 30 then table.clear(trail) end
									if not trail[1] or (position - trail[1]).Magnitude >= 1 then
										table.insert(trail, 1, position)
										if #trail > 300 then table.remove(trail) end
									end
								end,
								place = function(_, index, _, _, _, mode)
									local back = 2 + index * featureSettings.partSnakeGap
									local point = trail[math.floor(back)]
									if not point then
										-- Past the end of the trail: on in a line behind them.
										local behind = -flat(mode.root.CFrame.LookVector)
										behind = behind.Magnitude > 0.1 and behind.Unit or Vector3.new(0, 0, 1)
										point = (trail[#trail] or mode.root.Position) + behind * math.max(back - #trail, 0)
									end
									return point - Vector3.new(0, 1.5, 0)
								end,
							})
						end)
						targetedSwitches["Part Snake"] = setSnake
						addQuickToggle(trollTabs.parts, "Part Snake", "A line of parts slithers along behind your target, the way they went. Right-click for its length", setSnake, "spline", "footprints")

						withIcon(trollTabs.parts, "CreateSection", { name = "Round you" }, "user-round", "hand")
						-- Telekinesis: hold its key and point at a loose part to pick it up; it follows your
						-- pointer, the scroll wheel moves it nearer or further, and letting go drops it. Its
						-- own loop, as it's one part at a time.
						local grabParams = RaycastParams.new()
						grabParams.FilterType = Enum.RaycastFilterType.Exclude
						local grab = { part = nil, distance = 0, keyDown = false, box = nil }
						local function dropGrab()
							local part = grab.part
							grab.part = nil
							if part and part.Parent then
								-- Let go with a gentle toss the way it was going, never a hard throw.
								pcall(function()
									local velocity = part.AssemblyLinearVelocity
									if velocity.Magnitude > 25 then part.AssemblyLinearVelocity = velocity.Unit * 25 end
								end)
							end
							if grab.box then
								grab.box:Destroy()
								grab.box = nil
							end
							pcall(function() ContextActionService:UnbindAction("SpreadCheeksTelekinesisWheel") end)
						end
						local function telekinesisStep(deltaTime)
							local camera = workspace.CurrentCamera
							if not camera then return end
							local keyOk, keyCode = pcall(function() return Enum.KeyCode[featureSettings.partGrabKey] end)
							local down = keyOk and keyCode ~= nil and UserInputService:IsKeyDown(keyCode) and not UserInputService:GetFocusedTextBox()
							local mouse = UserInputService:GetMouseLocation()
							local ray = camera:ViewportPointToRay(mouse.X, mouse.Y)
							if down and not grab.keyDown then
								grabParams.FilterDescendantsInstances = { localPlayer.Character }
								local hit = workspace:Raycast(ray.Origin, ray.Direction * 500, grabParams)
								local part = hit and hit.Instance:IsA("BasePart") and not hit.Instance.Anchored and hit.Instance.AssemblyRootPart or nil
								if part and movable(part) then
									grab.part = part
									grab.distance = (hit.Position - ray.Origin).Magnitude
									local box = Instance.new("SelectionBox")
									box.Name = "SpreadCheeksTelekinesis"
									box.Adornee = part
									box.LineThickness = 0.06
									box.Color3 = auxiliaryUiTheme.AccentText
									box.Parent = COREGUI
									grab.box = box
									-- The scroll wheel moves it while you hold it, instead of the camera.
									ContextActionService:BindActionAtPriority("SpreadCheeksTelekinesisWheel", function(_, inputState, input)
										if inputState == Enum.UserInputState.Change then
											grab.distance = math.clamp(grab.distance + input.Position.Z * 3, 4, 300)
										end
										return Enum.ContextActionResult.Sink
									end, false, 3000, Enum.UserInputType.MouseWheel)
								end
							elseif not down and grab.keyDown then
								dropGrab()
							end
							grab.keyDown = down
							local part = grab.part
							if not part then return end
							if not part.Parent or part.Anchored then return dropGrab() end
							if sethidden then pcall(sethidden, localPlayer, "SimulationRadius", 1e9) end
							local goal = ray.Origin + ray.Direction * grab.distance
							local velocity = (goal - part.Position) / math.max(deltaTime, 1 / 120)
							if velocity.Magnitude > 60 then velocity = velocity.Unit * 60 end
							velocity = keepClear(part, velocity, otherRoots(), 4)
							pcall(function()
								part.AssemblyLinearVelocity = velocity
								part.AssemblyAngularVelocity *= 0.9
							end)
						end
						addQuickToggle(trollTabs.parts, "Telekinesis", "Hold T and point at a loose part to pick it up and carry it; scroll to move it nearer or further. Right-click to change the key", function(enabled)
							dropGrab()
							if not enabled then return afterControls("SpreadCheeksTelekinesis", nil) end
							claimMovement("Telekinesis")
							-- A key already held when it's switched on doesn't grab anything.
							grab.keyDown = true
							afterControls("SpreadCheeksTelekinesis", telekinesisStep)
						end, "hand", "move")
						-- Part Pets: a few parts trail along behind you, bobbing.
						local setPets = partsSwitch("Part Pets", function()
							return aroundYou("Part Pets", {
								limit = featureSettings.partPetCount, speed = 60,
								place = function(_, index, count, now, _, mode)
									local root = mode.root
									local look = flat(root.CFrame.LookVector)
									look = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
									local right = Vector3.new(-look.Z, 0, look.X)
									local across = (count > 1 and (index - 1) / (count - 1) - 0.5 or 0) * math.min(count, 8) * 1.6
									local distance = featureSettings.partPetDistance + (index % 2) * 1.5
									return root.Position - look * distance + right * across + Vector3.new(0, -0.5 + math.sin(now * 3 + index) * 0.6, 0)
								end,
							})
						end)
						addQuickToggle(trollTabs.parts, "Part Pets", "A few loose parts follow you around like pets. Right-click for how many", setPets, "paw-print", "heart")
						-- Magic Carpet: the flattest loose part near you slides under your feet and stays there.
						-- Space takes it up (you jump and land on it higher) and Ctrl or Q down, and riding it
						-- you go at its speed the way you walk.
						local carpet = { height = nil, yaw = 0 }
						local carpetParams = RaycastParams.new()
						carpetParams.FilterType = Enum.RaycastFilterType.Exclude
						local setCarpet = partsSwitch("Magic Carpet", function()
							if not myCharacter() then
								notify("Magic Carpet", "Your character isn't ready yet.")
								return nil
							end
							carpet.height = nil
							return aroundYou("Magic Carpet", {
								limit = 1, speed = 200,
								range = function() return 80 end,
								score = flatScore,
								tick = function(mode, _, deltaTime)
									local item = engine.items[1]
									if not item then return end
									local root, humanoid = mode.root, mode.humanoid
									local feet = root.Position.Y - legsOf(humanoid, root)
									-- Starting off, or a long way from it: back under your feet.
									if not carpet.height or math.abs(carpet.height - feet) > 12 then carpet.height = feet end
									local typing = UserInputService:GetFocusedTextBox() ~= nil
									local sinking = UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.Q)
									local rise = (not typing and UserInputService:IsKeyDown(Enum.KeyCode.Space) and 1 or 0)
										- (not typing and sinking and 1 or 0)
									local speed = featureSettings.partCarpetSpeed
									carpet.height += rise * speed * 0.5 * deltaTime
									-- Riding it, you go faster than walking, stopping short of walls.
									local move = flat(humanoid.MoveDirection)
									local extra = speed - humanoid.WalkSpeed
									if move.Magnitude > 0.05 and extra > 0 then
										local distance = extra * deltaTime
										carpetParams.FilterDescendantsInstances = { mode.character, item.part }
										local hit = workspace:Raycast(root.Position, move.Unit * (distance + 1.5), carpetParams)
										if hit then distance = math.max(0, (hit.Position - root.Position).Magnitude - 1.5) end
										if distance > 0 then root.CFrame += move.Unit * distance end
									end
									local look = flat(root.CFrame.LookVector)
									if look.Magnitude > 0.1 then carpet.yaw = yawOf(look) end
								end,
								place = function(item, _, _, _, _, mode)
									if not carpet.height then return nil end
									local root = mode.root
									return Vector3.new(root.Position.X, carpet.height - item.part.Size.Y / 2, root.Position.Z)
								end,
								orient = function(item)
									local part = item.part
									part.CFrame = CFrame.new(part.Position) * CFrame.Angles(0, carpet.yaw, 0)
								end,
							})
						end)
						addQuickToggle(trollTabs.parts, "Magic Carpet", "Ride a loose part like a magic carpet: walk to fly along, Space to go up, Ctrl or Q to come down. Right-click for the speed", setCarpet, "wind", "plane")
						-- Part Stairs: a staircase of parts in front of you, the step under you holding you up.
						-- Walking forward climbs it; standing still stays put; Ctrl or Q goes back down.
						local stairs = { height = nil, last = nil }
						local setStairs = partsSwitch("Part Stairs", function()
							if not myCharacter() then
								notify("Part Stairs", "Your character isn't ready yet.")
								return nil
							end
							stairs.height, stairs.last = nil, nil
							return aroundYou("Part Stairs", {
								limit = featureSettings.partStairCount + 1, speed = 200,
								range = function() return 100 end,
								score = flatScore,
								tick = function(mode, _, deltaTime)
									local root, humanoid = mode.root, mode.humanoid
									local look = flat(root.CFrame.LookVector)
									mode.look = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
									local feet = root.Position.Y - legsOf(humanoid, root)
									if not stairs.height or math.abs(stairs.height - feet) > 8 then stairs.height = feet end
									-- Climbing as you walk forward, at the stairs' slope.
									local position = root.Position
									if stairs.last then
										local forward = flat(position - stairs.last):Dot(mode.look)
