			backdrop.InputBegan:Connect(function(input)
				if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
				local point = Vector2.new(input.Position.X, input.Position.Y)
				local panelPosition = panel.AbsolutePosition
				local panelSize = panel.AbsoluteSize
				local insidePanel = point.X >= panelPosition.X and point.X <= panelPosition.X + panelSize.X
					and point.Y >= panelPosition.Y and point.Y <= panelPosition.Y + panelSize.Y
				if not insidePanel then pickerGui.Enabled = false end
			end)
			closePicker.Activated:Connect(function() pickerGui.Enabled = false end)
			Players.PlayerAdded:Connect(refreshFaceCards)
			Players.PlayerRemoving:Connect(refreshFaceCards)
			refreshFaceCards()
			-- The Choose Player button on Player Pranks opens it too.
			function menuModules.openPlayerPicker()
				refreshFaceCards()
				searchInput.Text = ""
				pickerGui.Enabled = true
				fitTiles()
			end
			withIcon(playerTab, "CreateButton", {
				name = "Player picker",
				description = "Choose a player from their face and username",
				callback = menuModules.openPlayerPicker,
			}, "layout-grid")
		end
		buildFacePicker()
		-- Kept so the player info panel can sit right under it.
		menuModules.playerNameInput = withIcon(playerTab, "CreateInput", {
			name = "Player name",
			description = "Enter a username if the player is not in the list",
			placeholder = selectedPlayerName,
			callback = function(value)
				local name = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
				if name ~= "" then
					selectPlayer(name, "@" .. name)
				end
			end,
		}, "at-sign")

		local function runForSelectedPlayer(command)
			local name = tostring(selectedPlayerName or ""):gsub("^%s+", ""):gsub("%s+$", "")
			if name ~= "" then
				execCmd(command .. " " .. name, Players.LocalPlayer, true)
			end
		end

		withIcon(playerTab, "CreateSection", { name = "Player actions" }, "crosshair")
		withIcon(playerTab, "CreateToggle", {
			name = "View selected player",
			value = false,
			callback = function(enabled)
				if enabled then
					runForSelectedPlayer("view")
				else
					execCmd("unview", Players.LocalPlayer, true)
				end
			end,
		}, "eye")
		withIcon(playerTab, "CreateToggle", {
			name = "Loop goto selected player",
			description = "Keep teleporting to the selected player",
			value = false,
			callback = function(enabled)
				if enabled then
					runForSelectedPlayer("loopgoto")
				else
					execCmd("unloopgoto", Players.LocalPlayer, true)
				end
			end,
		}, "repeat")
		withIcon(playerTab, "CreateToggle", {
			name = "Locate selected player",
			description = "Shows where they are, through walls, until you turn this off",
			value = false,
			callback = function(enabled)
				if enabled then
					local name = tostring(selectedPlayerName or ""):gsub("^%s+", ""):gsub("%s+$", "")
					if name ~= "" then
						locatedPlayerName = name
						execCmd("locate " .. name, Players.LocalPlayer, true)
					end
				elseif locatedPlayerName then
					execCmd("nolocate " .. locatedPlayerName, Players.LocalPlayer, true)
					locatedPlayerName = nil
				end
			end,
		}, "locate", "crosshair")
		withIcon(playerTab, "CreateButton", {
			name = "Go to selected player",
			callback = function() runForSelectedPlayer("goto") end,
		}, "navigation")
		withIcon(playerTab, "CreateButton", {
			name = "Glide to selected player",
			description = "Fly smoothly over to them instead of teleporting. Its speed is on the Player Pranks tab, under Glide To",
			callback = function()
				if trolling.startGlide then trolling.startGlide() end
			end,
		}, "send", "navigation")
		withIcon(playerTab, "CreateButton", {
			name = "TP unanchored parts to selected player",
			description = "Move loose, unanchored parts to the selected player's character",
			callback = function() runForSelectedPlayer("tpunanchored") end,
		}, "magnet")
		-- Friends Online, built further down (menuModules.friendsOnline).
		withIcon(playerTab, "CreateSection", { name = "Friends" }, "users-round")
		withIcon(playerTab, "CreateButton", {
			name = "Friends Online",
			description = "See which of your friends are online and what they're playing, and join them",
			callback = function()
				if menuModules.friendsOnline then menuModules.friendsOnline.open() end
			end,
		}, "users-round", "user-plus")

		window:CreateSection({ name = "TOOLS" })
		local runTab = withIcon(window, "CreateTab", { name = "Command Bar" }, "square-terminal", "terminal-square")
		-- Command Bar: a console for running commands, drawn with our own cards like Home. As you type
		-- it shows the command's usage, other names and description, with other matches to pick
		-- from; under that are your recent commands and some handy syntax.
		local function buildCommandBarPage()
			local page = runTab and runTab.tabPage
			if typeof(page) ~= "Instance" then
				warn("[SpreadCheeksGUI] Couldn't build the Command Bar page; Rayfield's tab layout may have changed.")
				return
			end

			local function addCorner(object, radius)
				local corner = Instance.new("UICorner")
				corner.CornerRadius = radius or UDim.new(0, 12)
				corner.Parent = object
			end
			local function addPadding(object, vertical, horizontal)
				local padding = Instance.new("UIPadding")
				padding.PaddingTop = UDim.new(0, vertical)
				padding.PaddingBottom = UDim.new(0, vertical)
				padding.PaddingLeft = UDim.new(0, horizontal)
				padding.PaddingRight = UDim.new(0, horizontal)
				padding.Parent = object
			end
			local function addList(object, gap, horizontal)
				local layout = Instance.new("UIListLayout")
				layout.Padding = UDim.new(0, gap)
				layout.SortOrder = Enum.SortOrder.LayoutOrder
				if horizontal then
					layout.FillDirection = Enum.FillDirection.Horizontal
					layout.VerticalAlignment = Enum.VerticalAlignment.Center
					pcall(function() layout.Wraps = true end)
				end
				layout.Parent = object
				return layout
			end
			local function makeCard(parent, order)
				local card = Instance.new("Frame")
				card.LayoutOrder = order
				card.Size = UDim2.fromScale(1, 0)
				card.AutomaticSize = Enum.AutomaticSize.Y
				card.BorderSizePixel = 0
				bindAuxiliaryUiColor(card, "BackgroundColor3", "Card")
				addCorner(card)
				local stroke = Instance.new("UIStroke")
				stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				stroke.Transparency = 0.3
				bindAuxiliaryUiColor(stroke, "Color", "Stroke")
				stroke.Parent = card
				addPadding(card, 14, 14)
				addList(card, 10)
				card.Parent = parent
				return card
			end
			local function makeLabel(parent, options)
				local label = Instance.new("TextLabel")
				label.LayoutOrder = options.order or 0
				label.BackgroundTransparency = 1
				label.Font = options.font or Enum.Font.Gotham
				label.TextSize = options.size or 12
				label.Text = options.text or ""
				label.TextXAlignment = Enum.TextXAlignment.Left
				label.TextTruncate = Enum.TextTruncate.AtEnd
				label.Position = options.position or UDim2.new()
				label.Size = options.frameSize or UDim2.new(1, 0, 0, (options.size or 12) + 4)
				if options.autoWidth then
					label.AutomaticSize = Enum.AutomaticSize.X
					label.Size = UDim2.fromOffset(0, (options.size or 12) + 4)
				end
				if options.wrap then
					label.AutomaticSize = Enum.AutomaticSize.Y
					label.TextWrapped = true
					label.TextTruncate = Enum.TextTruncate.None
				end
				bindAuxiliaryUiColor(label, "TextColor3", options.role or "Text")
				label.Parent = parent
				return label
			end
			local function makeIcon(parent, size, role, ...)
				local icon = menuIcons.get(...)
				local image = Instance.new("ImageLabel")
				image.BackgroundTransparency = 1
				image.Size = UDim2.fromOffset(size, size)
				image.Visible = icon ~= nil
				if icon then menuIcons.apply(image, icon) end
				bindAuxiliaryUiColor(image, "ImageColor3", role)
				image.Parent = parent
				return image
			end
			-- A small rounded button or tag, as wide as its text, in the given background and text roles.
			local function makePill(parent, text, order, backgroundRole, textRole, className)
				local pill = Instance.new(className or "TextButton")
				pill.LayoutOrder = order or 0
				pill.AutomaticSize = Enum.AutomaticSize.X
				pill.Size = UDim2.fromOffset(0, 24)
				pill.BorderSizePixel = 0
				pill.Font = Enum.Font.GothamMedium
				pill.Text = text
				pill.TextSize = 12
				if pill:IsA("TextButton") then pill.AutoButtonColor = false end
				bindAuxiliaryUiColor(pill, "BackgroundColor3", backgroundRole or "Inset")
				bindAuxiliaryUiColor(pill, "TextColor3", textRole or "SubText")
				addCorner(pill, UDim.new(0, 7))
				local padding = Instance.new("UIPadding")
				padding.PaddingLeft = UDim.new(0, 10)
				padding.PaddingRight = UDim.new(0, 10)
				padding.Parent = pill
				pill.Parent = parent
				return pill
			end
			-- A titled line at the top of a card: icon, title, and anything put on its right.
			local function makeTitleRow(card, title, ...)
				local row = Instance.new("Frame")
				row.LayoutOrder = 0
				row.Size = UDim2.new(1, 0, 0, 24)
				row.BackgroundTransparency = 1
				row.Parent = card
				local icon = makeIcon(row, 16, "AccentText", ...)
				icon.Position = UDim2.fromOffset(0, 4)
				makeLabel(row, {
					text = title, font = Enum.Font.GothamBold, size = 14,
					position = UDim2.fromOffset(24, 3), frameSize = UDim2.new(1, -150, 0, 18),
				})
				return row
			end
			-- Rows here are rebuilt as things change, so their old theme bindings are cleared out.
			local function pruneDeadThemeBindings()
				for index = #auxiliaryUiColorBindings, 1, -1 do
					if not auxiliaryUiColorBindings[index][1].Parent then
						table.remove(auxiliaryUiColorBindings, index)
					end
				end
			end

			local root = Instance.new("Frame")
			root.Name = "CommandConsole"
			root.LayoutOrder = 1
			root.Size = UDim2.new(1, -20, 0, 0)
			root.AutomaticSize = Enum.AutomaticSize.Y
			root.BackgroundTransparency = 1
			root.Parent = page
			addList(root, 8)

			-- The console: the input, then what the command being typed does.
			local console = makeCard(root, 1)
			local consoleTitle = makeTitleRow(console, "Run a command", "square-terminal", "terminal-square")
			local commandCount = makePill(consoleTitle, "", 0, "Inset", "SubText", "TextLabel")
			commandCount.AnchorPoint = Vector2.new(1, 0)
			commandCount.Position = UDim2.fromScale(1, 0)

			local inputRow = Instance.new("Frame")
			inputRow.LayoutOrder = 1
			inputRow.Size = UDim2.new(1, 0, 0, 38)
			inputRow.BackgroundTransparency = 1
			inputRow.Parent = console
			local prefixMark = Instance.new("TextLabel")
			prefixMark.Size = UDim2.fromOffset(38, 38)
			prefixMark.BorderSizePixel = 0
			prefixMark.Font = Enum.Font.GothamBold
			prefixMark.Text = tostring(prefix or ";")
			prefixMark.TextSize = 16
			bindAuxiliaryUiColor(prefixMark, "BackgroundColor3", "Inset")
			bindAuxiliaryUiColor(prefixMark, "TextColor3", "AccentText")
			addCorner(prefixMark, UDim.new(0, 9))
			prefixMark.Parent = inputRow
			local inputBox = Instance.new("TextBox")
			inputBox.Position = UDim2.fromOffset(46, 0)
			inputBox.Size = UDim2.new(1, -46 - 84, 1, 0)
			inputBox.BorderSizePixel = 0
			inputBox.ClearTextOnFocus = false
			inputBox.Font = Enum.Font.Gotham
			inputBox.PlaceholderText = "Type a command, like fly or speed 32"
			inputBox.Text = ""
			inputBox.TextSize = 14
			inputBox.TextXAlignment = Enum.TextXAlignment.Left
			inputBox.TextTruncate = Enum.TextTruncate.AtEnd
			bindAuxiliaryUiColor(inputBox, "BackgroundColor3", "Inset")
			bindAuxiliaryUiColor(inputBox, "TextColor3", "Text")
			bindAuxiliaryUiColor(inputBox, "PlaceholderColor3", "Muted")
			addCorner(inputBox, UDim.new(0, 9))
			local inputPadding = Instance.new("UIPadding")
			inputPadding.PaddingLeft = UDim.new(0, 12)
			inputPadding.PaddingRight = UDim.new(0, 12)
			inputPadding.Parent = inputBox
			local inputStroke = Instance.new("UIStroke")
			inputStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			inputStroke.Transparency = 0.35
			bindAuxiliaryUiColor(inputStroke, "Color", "Stroke")
			inputStroke.Parent = inputBox
			inputBox.Parent = inputRow
			inputBox.Focused:Connect(function() inputStroke.Color = auxiliaryUiTheme.Accent end)
			inputBox.FocusLost:Connect(function() inputStroke.Color = auxiliaryUiTheme.Stroke end)
			local runButton = Instance.new("TextButton")
			runButton.AnchorPoint = Vector2.new(1, 0)
			runButton.Position = UDim2.fromScale(1, 0)
			runButton.Size = UDim2.fromOffset(76, 38)
			runButton.AutoButtonColor = false
			runButton.BorderSizePixel = 0
			runButton.Font = Enum.Font.GothamBold
			runButton.Text = "Run"
			runButton.TextSize = 13
			bindAuxiliaryUiColor(runButton, "BackgroundColor3", "Accent")
			bindAuxiliaryUiColor(runButton, "TextColor3", "OnAccent")
			addCorner(runButton, UDim.new(0, 9))
			runButton.Parent = inputRow

			-- What the command being typed does: its name and how it's used, its other names, and
			-- its description.
			local detail = Instance.new("Frame")
			detail.LayoutOrder = 2
			detail.Size = UDim2.fromScale(1, 0)
			detail.AutomaticSize = Enum.AutomaticSize.Y
			detail.BorderSizePixel = 0
			bindAuxiliaryUiColor(detail, "BackgroundColor3", "Inset")
			addCorner(detail, UDim.new(0, 10))
			addPadding(detail, 10, 12)
			addList(detail, 3)
			detail.Parent = console
			local detailHead = Instance.new("Frame")
			detailHead.LayoutOrder = 1
			detailHead.Size = UDim2.new(1, 0, 0, 18)
			detailHead.BackgroundTransparency = 1
			detailHead.Parent = detail
			addList(detailHead, 8, true)
			local detailName = makeLabel(detailHead, { order = 1, font = Enum.Font.GothamBold, size = 14, role = "AccentText", autoWidth = true })
			local detailUsage = makeLabel(detailHead, { order = 2, font = Enum.Font.GothamMedium, size = 12, role = "SubText", autoWidth = true })
			local detailAliases = makeLabel(detail, { order = 2, size = 11, role = "Muted" })
			local detailDescription = makeLabel(detail, { order = 3, size = 12, role = "Text", wrap = true })
			detailDescription.Size = UDim2.fromScale(1, 0)

			-- Other commands that match, to pick from.
			local suggestions = Instance.new("Frame")
			suggestions.LayoutOrder = 3
			suggestions.Size = UDim2.fromScale(1, 0)
			suggestions.AutomaticSize = Enum.AutomaticSize.Y
			suggestions.BackgroundTransparency = 1
			suggestions.Parent = console
			addList(suggestions, 6, true)

			local search = quickCommandBar.search
			local splitCommandText = quickCommandBar.splitCommandText
			local function describe()
				for _, child in ipairs(suggestions:GetChildren()) do
					if child:IsA("GuiObject") then child:Destroy() end
				end
				pruneDeadThemeBindings()
				local word, rest = "", ""
				if splitCommandText then
					local _, _, typedWord, typedRest = splitCommandText(inputBox.Text)
					word, rest = typedWord:lower(), typedRest
				end
				if word == "" or not search then
					detailName.Text = "Type a command"
					detailUsage.Text = ""
					detailAliases.Visible = false
					detailDescription.Text = "Like fly, speed 32 or goto someone. Matching commands appear as you type: click one to use it, or press Tab for the first. Enter or Run runs it."
					suggestions.Visible = false
					return
				end
				local matches = search(word)
				local best = matches[1]
				if not best then
					detailName.Text = word
					detailUsage.Text = ""
					detailAliases.Visible = false
					detailDescription.Text = "There's no command called that. Check the spelling, or browse the Admin Commands tabs."
					suggestions.Visible = false
					return
				end
				local entry = best.entry
				detailName.Text = best.name
				detailUsage.Text = entry.usage or ""
				local otherNames = {}
				for _, name in ipairs(entry.names) do
					if name ~= best.name then table.insert(otherNames, name) end
				end
				detailAliases.Visible = #otherNames > 0
				detailAliases.Text = "Also: " .. table.concat(otherNames, ", ")
				detailDescription.Text = entry.description ~= "" and entry.description or "No description for this one."
				-- Only while the command itself is being typed, not its arguments.
				suggestions.Visible = rest == ""
				if rest ~= "" then return end
				local shown = 0
				for index, match in ipairs(matches) do
					if shown >= 6 then break end
					if not (index == 1 and best.rank == 1) then
						shown += 1
						local name = match.name
						local pill = makePill(suggestions, name, index, "Card", "Text")
						pill.Activated:Connect(function()
							local pickBefore, pickLead, _, pickRest = splitCommandText(inputBox.Text)
							inputBox.Text = pickBefore .. pickLead .. name .. (pickRest ~= "" and pickRest or " ")
							inputBox:CaptureFocus()
							inputBox.CursorPosition = #inputBox.Text + 1
						end)
					end
				end
				suggestions.Visible = shown > 0
			end

			-- Recent commands, newest first: run one again, or put it in the box to change it.
			local recent = makeCard(root, 2)
			makeTitleRow(recent, "Recent commands", "history", "clock")
			local recentList = Instance.new("Frame")
			recentList.LayoutOrder = 1
			recentList.Size = UDim2.fromScale(1, 0)
			recentList.AutomaticSize = Enum.AutomaticSize.Y
			recentList.BackgroundTransparency = 1
			recentList.Parent = recent
			addList(recentList, 6)
			local recentEmpty = makeLabel(recent, {
				order = 2, size = 12, role = "SubText",
				text = "Commands you run, here or with the ; bar, show up here.",
			})

			local function run(text)
				text = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
				local commandPrefix = tostring(prefix or ";")
				if commandPrefix ~= "" and text:sub(1, #commandPrefix) == commandPrefix then
					text = text:sub(#commandPrefix + 1)
				end
				if text == "" then return end
				execCmd(text, Players.LocalPlayer, true)
			end

			local recentSignature = nil
			local function refreshRecent()
				local history = type(cmdHistory) == "table" and cmdHistory or {}
				local items = {}
				for index = 1, math.min(#history, 8) do
					table.insert(items, tostring(history[index]))
				end
				local signature = table.concat(items, "\n")
				if signature == recentSignature then return end
				recentSignature = signature
				for _, child in ipairs(recentList:GetChildren()) do
					if child:IsA("GuiObject") then child:Destroy() end
				end
				pruneDeadThemeBindings()
				recentEmpty.Visible = #items == 0
				recentList.Visible = #items > 0
				for index, commandText in ipairs(items) do
					local row = Instance.new("Frame")
					row.LayoutOrder = index
					row.Size = UDim2.new(1, 0, 0, 32)
					row.BorderSizePixel = 0
					bindAuxiliaryUiColor(row, "BackgroundColor3", "Inset")
					addCorner(row, UDim.new(0, 8))
					row.Parent = recentList
					makeLabel(row, {
						text = commandText, font = Enum.Font.GothamMedium, size = 12,
						position = UDim2.fromOffset(12, 0), frameSize = UDim2.new(1, -140, 1, 0),
					})
					local buttons = Instance.new("Frame")
					buttons.AnchorPoint = Vector2.new(1, 0.5)
					buttons.Position = UDim2.new(1, -4, 0.5, 0)
					buttons.Size = UDim2.fromOffset(0, 24)
					buttons.AutomaticSize = Enum.AutomaticSize.X
					buttons.BackgroundTransparency = 1
					buttons.Parent = row
					local buttonLayout = addList(buttons, 4, true)
					buttonLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
					local editButton = makePill(buttons, "Edit", 1, "Card", "SubText")
					editButton.Activated:Connect(function()
						inputBox.Text = commandText
						inputBox:CaptureFocus()
						inputBox.CursorPosition = #inputBox.Text + 1
					end)
					local againButton = makePill(buttons, "Run again", 2, "Accent", "OnAccent")
					againButton.Activated:Connect(function() run(commandText) end)
				end
			end

			-- Handy to know: counts, and the shortcuts and syntax Infinite Yield understands.
			local info = makeCard(root, 3)
			makeTitleRow(info, "Good to know", "info", "lightbulb")
			local counts = Instance.new("Frame")
			counts.LayoutOrder = 1
			counts.Size = UDim2.fromScale(1, 0)
			counts.AutomaticSize = Enum.AutomaticSize.Y
			counts.BackgroundTransparency = 1
			counts.Parent = info
			addList(counts, 6, true)
			local commandsTag = makePill(counts, "", 1, "Inset", "Text", "TextLabel")
			local pluginsTag = makePill(counts, "", 2, "Inset", "Text", "TextLabel")
			makePill(counts, "Prefix  " .. tostring(prefix or ";"), 3, "Inset", "Text", "TextLabel")
			local tips = {
				{ tostring(prefix or ";"), "Opens the quick command bar from anywhere in the game" },
				{ "Tab", "Fills in the first matching command" },
				{ "Up / Down", "Steps back through commands you've run" },
				{ "fly\\noclip", "Runs several commands, one after another" },
				{ "3^jump", "Runs a command 3 times" },
				{ "!goto", "Runs goto again with the arguments it had last time" },
			}
			for index, tip in ipairs(tips) do
				local line = Instance.new("Frame")
				line.LayoutOrder = 1 + index
				line.Size = UDim2.new(1, 0, 0, 24)
				line.BackgroundTransparency = 1
				line.Parent = info
				local key = makePill(line, tip[1], 0, "Inset", "AccentText", "TextLabel")
				key.Font = Enum.Font.GothamBold
				-- The descriptions line up after the widest key.
				makeLabel(line, {
					text = tip[2], size = 12, role = "SubText",
					position = UDim2.fromOffset(96, 4), frameSize = UDim2.new(1, -96, 0, 16),
				})
			end
			local function refreshCounts()
				local total, fromPlugins = 0, 0
				for _, command in ipairs(type(cmds) == "table" and cmds or {}) do
					if type(command) == "table" then
						total += 1
						if command.PLUGIN then fromPlugins += 1 end
					end
				end
				commandCount.Text = total .. " commands"
				commandsTag.Text = total .. " commands loaded"
				pluginsTag.Text = fromPlugins .. (fromPlugins == 1 and " from a plugin" or " from plugins")
				pluginsTag.Visible = fromPlugins > 0
				prefixMark.Text = tostring(prefix or ";")
			end

			-- Typing: Tab takes the first match, Enter runs it, and Up and Down go through history.
			local historyIndex = 0
			local settingText = false
			local function setText(text)
				settingText = true
				inputBox.Text = text
				inputBox.CursorPosition = #text + 1
				settingText = false
			end
			inputBox:GetPropertyChangedSignal("Text"):Connect(function()
				local text = inputBox.Text
				if text:find("\t", 1, true) then
					text = text:gsub("\t", "")
					local matches = search and splitCommandText and search((select(3, splitCommandText(text))):lower())
					local best = matches and matches[1]
					if best then
						local tabBefore, tabLead, _, tabRest = splitCommandText(text)
						text = tabBefore .. tabLead .. best.name .. (tabRest ~= "" and tabRest or " ")
					end
					setText(text)
					return
				end
				if not settingText then historyIndex = 0 end
				describe()
			end)
			local function runInput()
				local text = inputBox.Text
				if text:gsub("%s", "") == "" then return end
				run(text)
				historyIndex = 0
				setText("")
				-- The command lands in the history as it starts.
				task.delay(0.15, refreshRecent)
			end
			inputBox.FocusLost:Connect(function(enterPressed)
				if enterPressed then runInput() end
			end)
			runButton.Activated:Connect(runInput)
			if sharedEnv.SpreadCheeksConsoleHistory then
				pcall(function() sharedEnv.SpreadCheeksConsoleHistory:Disconnect() end)
			end
			sharedEnv.SpreadCheeksConsoleHistory = UserInputService.InputBegan:Connect(function(input)
				if not inputBox:IsFocused() then return end
				local history = type(cmdHistory) == "table" and cmdHistory or {}
				if input.KeyCode == Enum.KeyCode.Up and historyIndex < #history then
					historyIndex += 1
				elseif input.KeyCode == Enum.KeyCode.Down and historyIndex > 0 then
					historyIndex -= 1
				else
					return
				end
				setText(historyIndex > 0 and tostring(history[historyIndex]) or "")
				describe()
			end)

			describe()
			refreshCounts()
			refreshRecent()
			-- Commands run from the ; bar or keybinds show up too, while the tab is open.
			task.spawn(function()
				while root.Parent do
					task.wait(1)
					if page.Visible then
						refreshRecent()
						refreshCounts()
					end
				end
			end)
		end
		-- Kept separate so a problem on the Command Bar page can't stop the rest of the menu loading.
		local commandBarOk, commandBarError = pcall(buildCommandBarPage)
		if not commandBarOk then
			warn("[SpreadCheeksGUI] The Command Bar page couldn't be built: " .. tostring(commandBarError))
		end

		-- Servers: every public server of this game, from Roblox's server list (the same one
		-- ;serverhop uses), each with a button to join it. Drawn with our own cards inside the tab's
		-- page, like Home.
		local serversTab = withIcon(window, "CreateTab", { name = "Servers" }, "server", "globe")
		local function buildServerBrowser()
			local page = serversTab and serversTab.tabPage
			if typeof(page) ~= "Instance" then
				warn("[SpreadCheeksGUI] Couldn't build the Servers page; Rayfield's tab layout may have changed.")
				return
			end

			local function addCorner(object, radius)
				local corner = Instance.new("UICorner")
				corner.CornerRadius = radius or UDim.new(0, 12)
				corner.Parent = object
			end
			-- A card in the menu's row colours (role is the background's theme role, Card by default).
			local function makeCard(parent, className, role)
				local card = Instance.new(className or "Frame")
				card.BorderSizePixel = 0
				bindAuxiliaryUiColor(card, "BackgroundColor3", role or "Card")
				addCorner(card)
				local stroke = Instance.new("UIStroke")
				stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				stroke.Transparency = 0.3
				bindAuxiliaryUiColor(stroke, "Color", "Stroke")
				stroke.Parent = card
				card.Parent = parent
				return card, stroke
			end
			local function makeLabel(parent, options)
				local label = Instance.new("TextLabel")
				label.BackgroundTransparency = 1
				label.Font = options.font or Enum.Font.Gotham
				label.TextSize = options.size or 12
				label.Text = options.text or ""
				label.TextXAlignment = options.alignX or Enum.TextXAlignment.Left
				label.TextTruncate = Enum.TextTruncate.AtEnd
				label.Position = options.position or UDim2.new()
				label.Size = options.frameSize or UDim2.new(1, 0, 0, (options.size or 12) + 4)
				bindAuxiliaryUiColor(label, "TextColor3", options.role or "Text")
				label.Parent = parent
				return label
			end
			local function makeIcon(parent, size, role, ...)
				local icon = menuIcons.get(...)
				local image = Instance.new("ImageLabel")
				image.BackgroundTransparency = 1
				image.Size = UDim2.fromOffset(size, size)
				image.Visible = icon ~= nil
				if icon then menuIcons.apply(image, icon) end
				bindAuxiliaryUiColor(image, "ImageColor3", role)
				image.Parent = parent
				return image
			end
			-- A small rounded button that's as wide as its text.
			local function makePill(parent, text, order)
				local pill = Instance.new("TextButton")
				pill.LayoutOrder = order or 0
				pill.AutomaticSize = Enum.AutomaticSize.X
				pill.Size = UDim2.fromOffset(0, 26)
				pill.AutoButtonColor = false
				pill.BorderSizePixel = 0
				pill.Font = Enum.Font.GothamMedium
				pill.Text = text
				pill.TextSize = 12
				addCorner(pill, UDim.new(0, 8))
				local padding = Instance.new("UIPadding")
				padding.PaddingLeft = UDim.new(0, 11)
				padding.PaddingRight = UDim.new(0, 11)
				padding.Parent = pill
				pill.Parent = parent
				return pill
			end
			local function commas(number)
				local text = tostring(math.floor(number))
				local grouped = text:reverse():gsub("(%d%d%d)", "%1,"):reverse()
				return (grouped:gsub("^,", ""))
			end

			local root = Instance.new("Frame")
			root.Name = "ServerBrowser"
			root.LayoutOrder = 1
			root.Size = UDim2.new(1, -20, 0, 0)
			root.AutomaticSize = Enum.AutomaticSize.Y
			root.BackgroundTransparency = 1
			root.Parent = page
			local rootLayout = Instance.new("UIListLayout")
			rootLayout.Padding = UDim.new(0, 8)
			rootLayout.SortOrder = Enum.SortOrder.LayoutOrder
			rootLayout.Parent = root

			-- Header: what's loaded, Refresh, and how the list is sorted and filtered.
			local header = makeCard(root)
			header.LayoutOrder = 1
			header.Size = UDim2.fromScale(1, 0)
			header.AutomaticSize = Enum.AutomaticSize.Y
			local headerPadding = Instance.new("UIPadding")
			headerPadding.PaddingTop = UDim.new(0, 14)
			headerPadding.PaddingBottom = UDim.new(0, 14)
			headerPadding.PaddingLeft = UDim.new(0, 14)
			headerPadding.PaddingRight = UDim.new(0, 14)
			headerPadding.Parent = header
			-- Stacked, so the sort buttons can wrap onto a second line on a narrow menu.
			local headerLayout = Instance.new("UIListLayout")
			headerLayout.Padding = UDim.new(0, 8)
			headerLayout.SortOrder = Enum.SortOrder.LayoutOrder
			headerLayout.Parent = header
			local titleRow = Instance.new("Frame")
			titleRow.LayoutOrder = 1
			titleRow.Size = UDim2.new(1, 0, 0, 26)
			titleRow.BackgroundTransparency = 1
			titleRow.Parent = header
			local headerIcon = makeIcon(titleRow, 18, "AccentText", "server", "globe")
			headerIcon.Position = UDim2.fromOffset(0, 4)
			makeLabel(titleRow, {
				text = "Servers", font = Enum.Font.GothamBold, size = 15,
				position = UDim2.fromOffset(26, 3), frameSize = UDim2.new(1, -130, 0, 20),
			})
			local refresh = makePill(titleRow, "Refresh")
			refresh.AnchorPoint = Vector2.new(1, 0)
			refresh.Position = UDim2.fromScale(1, 0)
			local summary = makeLabel(header, {
				text = "Press Refresh to load this game's servers.", size = 12, role = "SubText",
				frameSize = UDim2.new(1, 0, 0, 16),
			})
			summary.LayoutOrder = 2
			local controls = Instance.new("Frame")
			controls.LayoutOrder = 3
			controls.Size = UDim2.fromScale(1, 0)
			controls.AutomaticSize = Enum.AutomaticSize.Y
			controls.BackgroundTransparency = 1
			controls.Parent = header
			local controlsLayout = Instance.new("UIListLayout")
			controlsLayout.FillDirection = Enum.FillDirection.Horizontal
			controlsLayout.Padding = UDim.new(0, 6)
			controlsLayout.SortOrder = Enum.SortOrder.LayoutOrder
			pcall(function() controlsLayout.Wraps = true end)
			controlsLayout.Parent = controls
			local footnote = makeLabel(header, {
				text = "Ping and FPS are what each server reports for its players.", size = 10, role = "Muted",
				frameSize = UDim2.new(1, 0, 0, 13),
			})
			footnote.LayoutOrder = 4
			-- This server: copy its Job ID (Roblox Account Manager's Join Server takes it, as does the
			-- copy button on each server below) or the Place ID, or rejoin and land back on your spot.
			local hereRow = Instance.new("Frame")
			hereRow.LayoutOrder = 5
			hereRow.Size = UDim2.fromScale(1, 0)
			hereRow.AutomaticSize = Enum.AutomaticSize.Y
			hereRow.BackgroundTransparency = 1
			hereRow.Parent = header
			local hereLayout = Instance.new("UIListLayout")
			hereLayout.FillDirection = Enum.FillDirection.Horizontal
			hereLayout.VerticalAlignment = Enum.VerticalAlignment.Center
			hereLayout.Padding = UDim.new(0, 6)
			hereLayout.SortOrder = Enum.SortOrder.LayoutOrder
			pcall(function() hereLayout.Wraps = true end)
			hereLayout.Parent = hereRow
			local hereLabel = makeLabel(hereRow, {
				text = "This server", font = Enum.Font.GothamBold, size = 12, role = "SubText", frameSize = UDim2.fromOffset(0, 26),
			})
			hereLabel.AutomaticSize = Enum.AutomaticSize.X
			local herePills = {
				{ "Copy Job ID", function() menuModules.copy(game.JobId, "this server's Job ID") end },
				{ "Copy Place ID", function() menuModules.copy(game.PlaceId, "the Place ID") end },
				{ "Rejoin here", function()
					if menuModules.rejoinHere then menuModules.rejoinHere() end
				end },
			}
			for index, pillInfo in ipairs(herePills) do
				local pill = makePill(hereRow, pillInfo[1], index)
				bindAuxiliaryUiColor(pill, "BackgroundColor3", "Inset")
				bindAuxiliaryUiColor(pill, "TextColor3", "Text")
				pill.Activated:Connect(pillInfo[2])
			end

			-- Shown instead of the list when there's nothing to list, or something went wrong.
			local statusCard = makeCard(root)
			statusCard.LayoutOrder = 2
			statusCard.Size = UDim2.fromScale(1, 0)
			statusCard.AutomaticSize = Enum.AutomaticSize.Y
			local statusPadding = Instance.new("UIPadding")
			statusPadding.PaddingTop = UDim.new(0, 14)
			statusPadding.PaddingBottom = UDim.new(0, 14)
			statusPadding.PaddingLeft = UDim.new(0, 14)
			statusPadding.PaddingRight = UDim.new(0, 14)
			statusPadding.Parent = statusCard
			local statusText = makeLabel(statusCard, {
				text = "The server list loads when you open this tab, or press Refresh.", size = 12, role = "SubText",
			})
			statusText.Size = UDim2.fromScale(1, 0)
			statusText.AutomaticSize = Enum.AutomaticSize.Y
			statusText.TextWrapped = true
			statusText.TextTruncate = Enum.TextTruncate.None

			local list = Instance.new("Frame")
			list.LayoutOrder = 3
			list.Size = UDim2.fromScale(1, 0)
			list.AutomaticSize = Enum.AutomaticSize.Y
			list.BackgroundTransparency = 1
			list.Parent = root
			local listLayout = Instance.new("UIListLayout")
			listLayout.Padding = UDim.new(0, 6)
			listLayout.SortOrder = Enum.SortOrder.LayoutOrder
			listLayout.Parent = list

			local loadMore, loadMoreStroke = makeCard(root, "TextButton")
			loadMore.LayoutOrder = 4
			loadMore.Size = UDim2.new(1, 0, 0, 40)
			loadMore.AutoButtonColor = false
			loadMore.Font = Enum.Font.GothamMedium
			loadMore.Text = "Load more servers"
			loadMore.TextSize = 13
			loadMore.Visible = false
			bindAuxiliaryUiColor(loadMore, "TextColor3", "Text")
			loadMore.MouseEnter:Connect(function() loadMoreStroke.Color = auxiliaryUiTheme.Accent end)
			loadMore.MouseLeave:Connect(function() loadMoreStroke.Color = auxiliaryUiTheme.Stroke end)

			-- Joining. Roblox says why a teleport fails (the server filled up or closed, say).
			local joining = false
			local function join(serverId)
				if joining then return end
				joining = true
				notify("Servers", "Joining that server...", 3)
				local started, problem = pcall(function()
					TeleportService:TeleportToPlaceInstance(game.PlaceId, serverId, Players.LocalPlayer)
				end)
				if not started then
					joining = false
					notify("Servers", "Couldn't join: " .. tostring(problem), 5)
					return
				end
				task.delay(10, function() joining = false end)
			end
			if sharedEnv.SpreadCheeksServerJoinFailed then
				pcall(function() sharedEnv.SpreadCheeksServerJoinFailed:Disconnect() end)
			end
			sharedEnv.SpreadCheeksServerJoinFailed = TeleportService.TeleportInitFailed:Connect(function(player, result, message)
				if player ~= Players.LocalPlayer then return end
				joining = false
				local reason = tostring(message or "")
				notify("Servers", "Couldn't join: " .. (reason ~= "" and reason or tostring(result)), 5)
			end)

			-- One server: how full it is, its ping and frame rate, and Join (or why not).
			local function makeServerRow(server, order)
				local playing = tonumber(server.playing) or 0
				local maxPlayers = tonumber(server.maxPlayers) or 0
				local isHere = server.id == game.JobId
				local isFull = maxPlayers > 0 and playing >= maxPlayers
				local row, rowStroke = makeCard(list, "Frame", isHere and "SelectedCard" or "Card")
				row.LayoutOrder = order
				row.Size = UDim2.new(1, 0, 0, 54)

				makeLabel(row, {
					text = playing .. " / " .. maxPlayers, font = Enum.Font.GothamBold, size = 14,
					position = UDim2.fromOffset(14, 9), frameSize = UDim2.fromOffset(78, 18),
				})
				local capacity = Instance.new("Frame")
				capacity.Position = UDim2.fromOffset(14, 33)
				capacity.Size = UDim2.fromOffset(70, 4)
				capacity.BorderSizePixel = 0
				bindAuxiliaryUiColor(capacity, "BackgroundColor3", "Inset")
				capacity.Parent = row
				addCorner(capacity, UDim.new(1, 0))
				local capacityFill = Instance.new("Frame")
				capacityFill.Size = UDim2.fromScale(maxPlayers > 0 and math.clamp(playing / maxPlayers, 0, 1) or 0, 1)
				capacityFill.BorderSizePixel = 0
				bindAuxiliaryUiColor(capacityFill, "BackgroundColor3", "Accent")
				capacityFill.Parent = capacity
				addCorner(capacityFill, UDim.new(1, 0))

				local ping, fps = tonumber(server.ping), tonumber(server.fps)
				local stats = {}
				if ping then table.insert(stats, math.floor(ping + 0.5) .. " ms ping") end
				if fps then table.insert(stats, math.floor(fps + 0.5) .. " fps") end
				local dot = Instance.new("Frame")
				dot.AnchorPoint = Vector2.new(0, 0.5)
				dot.Position = UDim2.fromOffset(104, 18)
				dot.Size = UDim2.fromOffset(7, 7)
				dot.BorderSizePixel = 0
				bindAuxiliaryUiColor(dot, "BackgroundColor3", not ping and "Muted" or (ping < 100 and "Good" or (ping < 200 and "Fair" or "Bad")))
				dot.Parent = row
				addCorner(dot, UDim.new(1, 0))
				makeLabel(row, {
					text = #stats > 0 and table.concat(stats, "  ·  ") or "No ping reported", font = Enum.Font.GothamMedium, size = 12,
					position = UDim2.fromOffset(117, 10), frameSize = UDim2.new(1, -255, 0, 16),
				})
				makeLabel(row, {
					text = (isHere and "Your server  ·  " or "Server ") .. string.sub(server.id, 1, 8), size = 10, role = isHere and "AccentText" or "Muted",
					position = UDim2.fromOffset(104, 30), frameSize = UDim2.new(1, -242, 0, 14),
				})
				-- Copies the server's Job ID, for Roblox Account Manager or a friend.
				local copyId = Instance.new("TextButton")
				copyId.AnchorPoint = Vector2.new(1, 0.5)
				copyId.Position = UDim2.new(1, -96, 0.5, 0)
				copyId.Size = UDim2.fromOffset(30, 30)
				copyId.AutoButtonColor = false
				copyId.BorderSizePixel = 0
				copyId.Font = Enum.Font.GothamBold
				copyId.TextSize = 10
				bindAuxiliaryUiColor(copyId, "BackgroundColor3", "Inset")
				bindAuxiliaryUiColor(copyId, "TextColor3", "SubText")
				copyId.Parent = row
				addCorner(copyId, UDim.new(0, 8))
				local copyIcon = makeIcon(copyId, 14, "SubText", "copy", "clipboard-copy")
				copyIcon.AnchorPoint = Vector2.new(0.5, 0.5)
				copyIcon.Position = UDim2.fromScale(0.5, 0.5)
				copyId.Text = copyIcon.Visible and "" or "ID"
				copyId.Activated:Connect(function() menuModules.copy(server.id, "that server's Job ID") end)

				local action = Instance.new("TextButton")
				action.AnchorPoint = Vector2.new(1, 0.5)
				action.Position = UDim2.new(1, -12, 0.5, 0)
				action.Size = UDim2.fromOffset(78, 30)
				action.AutoButtonColor = false
				action.BorderSizePixel = 0
				action.Font = Enum.Font.GothamBold
				action.TextSize = 12
				action.Parent = row
				addCorner(action, UDim.new(0, 8))
				if isHere then
					action.Text = "You're here"
					bindAuxiliaryUiColor(action, "BackgroundColor3", "Inset")
					bindAuxiliaryUiColor(action, "TextColor3", "AccentText")
				elseif isFull then
					action.Text = "Full"
					bindAuxiliaryUiColor(action, "BackgroundColor3", "Inset")
					bindAuxiliaryUiColor(action, "TextColor3", "Muted")
				else
					action.Text = "Join"
					bindAuxiliaryUiColor(action, "BackgroundColor3", "Accent")
					bindAuxiliaryUiColor(action, "TextColor3", "OnAccent")
					action.Activated:Connect(function() join(server.id) end)
				end
				row.MouseEnter:Connect(function() rowStroke.Color = auxiliaryUiTheme.Accent end)
				row.MouseLeave:Connect(function() rowStroke.Color = auxiliaryUiTheme.Stroke end)
			end

			-- What's loaded, and how it's shown. Most and Fewest players come sorted from Roblox;
			-- Best ping sorts whatever is loaded.
			local servers, nextCursor, fetchedOrder = {}, nil, nil
			local sortMode, hideFull, loading, loadSerial = "Most players", false, false, 0

			local sortChips = {}
			for index, mode in ipairs({ "Most players", "Fewest players", "Best ping" }) do
				sortChips[mode] = makePill(controls, mode, index)
			end
			local hideFullChip = makePill(controls, "Hide full", 10)
			local function paintChips()
				local theme = auxiliaryUiTheme
				for mode, chip in pairs(sortChips) do
					local selected = mode == sortMode
					chip.BackgroundColor3 = selected and theme.Accent or theme.Inset
					chip.TextColor3 = selected and theme.OnAccent or theme.SubText
				end
				hideFullChip.BackgroundColor3 = hideFull and theme.Accent or theme.Inset
				hideFullChip.TextColor3 = hideFull and theme.OnAccent or theme.SubText
				refresh.BackgroundColor3 = theme.Inset
				refresh.TextColor3 = loading and theme.Muted or theme.Text
			end
			table.insert(auxiliaryUiThemeListeners, paintChips)

			-- Rows are rebuilt on every load, so their old theme bindings are cleared out as they go.
			local function pruneDeadThemeBindings()
				for index = #auxiliaryUiColorBindings, 1, -1 do
					if not auxiliaryUiColorBindings[index][1].Parent then
						table.remove(auxiliaryUiColorBindings, index)
					end
				end
			end
			local function render()
				for _, child in ipairs(list:GetChildren()) do
					if child:IsA("GuiObject") then child:Destroy() end
				end
				pruneDeadThemeBindings()
				local shown = {}
				for _, server in ipairs(servers) do
					local full = (tonumber(server.playing) or 0) >= (tonumber(server.maxPlayers) or math.huge)
					if not (hideFull and full and server.id ~= game.JobId) then
						table.insert(shown, server)
					end
				end
				if sortMode == "Best ping" then
					table.sort(shown, function(left, right)
						return (tonumber(left.ping) or math.huge) < (tonumber(right.ping) or math.huge)
					end)
				end
				for index, server in ipairs(shown) do
					makeServerRow(server, index)
				end
				local totalPlayers = 0
				for _, server in ipairs(servers) do
					totalPlayers += tonumber(server.playing) or 0
				end
				summary.Text = commas(#servers) .. (#servers == 1 and " server" or " servers") .. "  ·  "
					.. commas(totalPlayers) .. " players" .. (nextCursor and "  ·  more to load" or "")
				statusCard.Visible = #shown == 0
				if #shown == 0 then
					statusText.Text = #servers == 0 and "No public servers are running right now."
						or "Every server loaded so far is full. Turn off Hide full, or load more."
				end
				loadMore.Visible = nextCursor ~= nil
			end

			local function friendlyError(problem)
				problem = tostring(problem or "")
				if problem:find("429") or problem:lower():find("too many") then
					return "Roblox is limiting how often the server list can load. Wait a few seconds, then press Refresh."
				end
				return "Couldn't load the server list. Your executor may not allow web requests to Roblox. (" .. problem .. ")"
			end
			-- One page (up to 100 servers) from Roblox's list, after the given cursor.
			local function requestPage(order, cursor)
				local url = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?limit=100&sortOrder=" .. order
				if cursor then
					url ..= "&cursor=" .. HttpService:UrlEncode(cursor)
				end
				local fetched, body = pcall(function() return game:HttpGet(url) end)
				if not fetched then return nil, body end
				local decoded, data = pcall(function() return HttpService:JSONDecode(body) end)
				if not decoded or type(data) ~= "table" then return nil, "Roblox sent back something unreadable." end
				if type(data.errors) == "table" and data.errors[1] then
					return nil, tostring(data.errors[1].message or "Roblox refused the request.")
				end
				return data
			end
			-- Loads the list from the start, or (append) the next page onto what's there.
			local function load(append)
				if loading or (append and not nextCursor) then return end
				loading = true
				loadSerial += 1
				local serial = loadSerial
				local order = append and fetchedOrder or (sortMode == "Fewest players" and "Asc" or "Desc")
				refresh.Text = "Loading..."
				loadMore.Text = append and "Loading..." or "Load more servers"
				if not append then summary.Text = "Loading this game's servers..." end
				paintChips()
				task.spawn(function()
					local data, problem = requestPage(order, append and nextCursor or nil)
					if serial ~= loadSerial or not root.Parent then return end
					loading = false
					refresh.Text = "Refresh"
					loadMore.Text = "Load more servers"
					paintChips()
					if not data then
						if append then
							notify("Servers", friendlyError(problem), 6)
						else
							servers, nextCursor = {}, nil
							render()
							statusCard.Visible = true
							statusText.Text = friendlyError(problem)
							summary.Text = "The server list didn't load."
						end
						return
					end
					if not append then
						servers = {}
						fetchedOrder = order
					end
					for _, server in ipairs(type(data.data) == "table" and data.data or {}) do
						if type(server) == "table" and type(server.id) == "string" then
							table.insert(servers, server)
						end
					end
					nextCursor = type(data.nextPageCursor) == "string" and data.nextPageCursor ~= "" and data.nextPageCursor or nil
					render()
				end)
			end

			refresh.Activated:Connect(function() load(false) end)
			loadMore.Activated:Connect(function() load(true) end)
			for mode, chip in pairs(sortChips) do
				chip.Activated:Connect(function()
					if mode == sortMode then return end
					sortMode = mode
					paintChips()
					-- Players sorts come from Roblox, so a different one means loading again.
					local wanted = mode == "Fewest players" and "Asc" or (mode == "Most players" and "Desc" or nil)
					if wanted and wanted ~= fetchedOrder then
						load(false)
					else
						render()
					end
				end)
			end
			hideFullChip.Activated:Connect(function()
				hideFull = not hideFull
				paintChips()
				render()
			end)
			paintChips()

			-- Loads by itself the first time the tab is opened (Refresh does it otherwise).
			local loadedOnce = false
			local function loadOnFirstView()
				if loadedOnce or not page.Visible then return end
				loadedOnce = true
				load(false)
			end
			page:GetPropertyChangedSignal("Visible"):Connect(loadOnFirstView)
			refresh.Activated:Connect(function() loadedOnce = true end)
		end
		-- Kept separate so a problem on the Servers page can't stop the rest of the menu loading.
		local serversOk, serversError = pcall(buildServerBrowser)
		if not serversOk then
			warn("[SpreadCheeksGUI] The Servers page couldn't be built: " .. tostring(serversError))
		end

		-- IY Settings: Infinite Yield's own settings, which otherwise live in the hidden classic
		-- window. Its keybinds (any command, Click Teleport, Click Delete), prefix, staying loaded
		-- after a teleport, aliases, waypoints and plugins, all saved to IY's own file as before.
		local iySettingsTab = withIcon(window, "CreateTab", { name = "IY Settings" }, "settings-2", "settings", "cog")
		local function buildIySettingsPage()
			local page = iySettingsTab and iySettingsTab.tabPage
			if typeof(page) ~= "Instance" then
				warn("[SpreadCheeksGUI] Couldn't build the IY Settings page; Rayfield's tab layout may have changed.")
				return
			end

			local function addCorner(object, radius)
				local corner = Instance.new("UICorner")
				corner.CornerRadius = radius or UDim.new(0, 12)
				corner.Parent = object
			end
			local function addList(object, gap, horizontal)
				local layout = Instance.new("UIListLayout")
				layout.Padding = UDim.new(0, gap)
				layout.SortOrder = Enum.SortOrder.LayoutOrder
				if horizontal then
					layout.FillDirection = Enum.FillDirection.Horizontal
					layout.VerticalAlignment = Enum.VerticalAlignment.Center
				end
				layout.Parent = object
				return layout
			end
			local function makeFrame(parent, order, height)
				local frame = Instance.new("Frame")
				frame.LayoutOrder = order or 0
				frame.Size = UDim2.new(1, 0, 0, height or 0)
				if not height then frame.AutomaticSize = Enum.AutomaticSize.Y end
				frame.BackgroundTransparency = 1
				frame.Parent = parent
				return frame
			end
			local function makeCard(parent, order)
				local card = Instance.new("Frame")
				card.LayoutOrder = order
				card.Size = UDim2.fromScale(1, 0)
				card.AutomaticSize = Enum.AutomaticSize.Y
				card.BorderSizePixel = 0
				bindAuxiliaryUiColor(card, "BackgroundColor3", "Card")
				addCorner(card)
				local stroke = Instance.new("UIStroke")
				stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				stroke.Transparency = 0.3
				bindAuxiliaryUiColor(stroke, "Color", "Stroke")
				stroke.Parent = card
				local padding = Instance.new("UIPadding")
				padding.PaddingTop = UDim.new(0, 14)
				padding.PaddingBottom = UDim.new(0, 14)
				padding.PaddingLeft = UDim.new(0, 14)
				padding.PaddingRight = UDim.new(0, 14)
				padding.Parent = card
				addList(card, 10)
				card.Parent = parent
				return card
			end
			local function makeLabel(parent, options)
				local label = Instance.new("TextLabel")
				label.LayoutOrder = options.order or 0
				label.BackgroundTransparency = 1
				label.Font = options.font or Enum.Font.Gotham
				label.TextSize = options.size or 12
				label.Text = options.text or ""
				label.TextXAlignment = Enum.TextXAlignment.Left
				label.TextTruncate = Enum.TextTruncate.AtEnd
				label.Position = options.position or UDim2.new()
				label.Size = options.frameSize or UDim2.new(1, 0, 0, (options.size or 12) + 4)
				if options.wrap then
					label.Size = UDim2.fromScale(1, 0)
					label.AutomaticSize = Enum.AutomaticSize.Y
					label.TextWrapped = true
					label.TextTruncate = Enum.TextTruncate.None
				end
				bindAuxiliaryUiColor(label, "TextColor3", options.role or "Text")
				label.Parent = parent
				return label
			end
			local function makeIcon(parent, size, role, ...)
				local icon = menuIcons.get(...)
				local image = Instance.new("ImageLabel")
				image.BackgroundTransparency = 1
				image.Size = UDim2.fromOffset(size, size)
				image.Visible = icon ~= nil
				if icon then menuIcons.apply(image, icon) end
				bindAuxiliaryUiColor(image, "ImageColor3", role)
				image.Parent = parent
				return image
			end
			-- A small rounded button or tag, as wide as its text, in the given background and text roles.
			local function makePill(parent, text, order, backgroundRole, textRole, className)
				local pill = Instance.new(className or "TextButton")
				pill.LayoutOrder = order or 0
				pill.AutomaticSize = Enum.AutomaticSize.X
				pill.Size = UDim2.fromOffset(0, 26)
				pill.BorderSizePixel = 0
				pill.Font = Enum.Font.GothamMedium
				pill.Text = text
				pill.TextSize = 12
				if pill:IsA("TextButton") then pill.AutoButtonColor = false end
				bindAuxiliaryUiColor(pill, "BackgroundColor3", backgroundRole or "Inset")
				bindAuxiliaryUiColor(pill, "TextColor3", textRole or "SubText")
				addCorner(pill, UDim.new(0, 7))
				local padding = Instance.new("UIPadding")
				padding.PaddingLeft = UDim.new(0, 11)
				padding.PaddingRight = UDim.new(0, 11)
				padding.Parent = pill
				pill.Parent = parent
				return pill
			end
			local function makeTitleRow(card, title, ...)
				local row = makeFrame(card, 0, 24)
				local icon = makeIcon(row, 16, "AccentText", ...)
				icon.Position = UDim2.fromOffset(0, 4)
				makeLabel(row, {
					text = title, font = Enum.Font.GothamBold, size = 14,
					position = UDim2.fromOffset(24, 3), frameSize = UDim2.new(1, -150, 0, 18),
				})
				return row
			end
			local function makeHeading(parent, order, text)
				return makeLabel(parent, { order = order, text = text, font = Enum.Font.GothamBold, size = 10, role = "Muted" })
			end
			local function makeTextBox(parent, order, placeholder)
				local box = Instance.new("TextBox")
				box.LayoutOrder = order or 0
				box.Size = UDim2.new(1, 0, 0, 34)
				box.BorderSizePixel = 0
				box.ClearTextOnFocus = false
				box.Font = Enum.Font.Gotham
				box.PlaceholderText = placeholder
				box.Text = ""
				box.TextSize = 13
				box.TextXAlignment = Enum.TextXAlignment.Left
				box.TextTruncate = Enum.TextTruncate.AtEnd
				bindAuxiliaryUiColor(box, "BackgroundColor3", "Inset")
				bindAuxiliaryUiColor(box, "TextColor3", "Text")
				bindAuxiliaryUiColor(box, "PlaceholderColor3", "Muted")
				addCorner(box, UDim.new(0, 8))
				local padding = Instance.new("UIPadding")
				padding.PaddingLeft = UDim.new(0, 10)
				padding.PaddingRight = UDim.new(0, 10)
				padding.Parent = box
				local stroke = Instance.new("UIStroke")
				stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				stroke.Transparency = 0.35
				bindAuxiliaryUiColor(stroke, "Color", "Stroke")
				stroke.Parent = box
				box.Focused:Connect(function() stroke.Color = auxiliaryUiTheme.Accent end)
				box.FocusLost:Connect(function() stroke.Color = auxiliaryUiTheme.Stroke end)
				box.Parent = parent
				return box
			end
			local function trimmed(text)
				return (tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", ""))
			end
			-- A command typed with the prefix works too.
			local function withoutPrefix(text)
				text = trimmed(text)
				local commandPrefix = tostring(prefix or ";")
				if commandPrefix ~= "" and text:sub(1, #commandPrefix) == commandPrefix then
					text = trimmed(text:sub(#commandPrefix + 1))
				end
				return text
			end

			-- Colours that depend on state (switches, choices) are set again on a theme change.
			local refreshers = {}
			local function repaint()
				for _, refresher in ipairs(refreshers) do refresher() end
			end
			table.insert(auxiliaryUiThemeListeners, repaint)
			-- Buttons, one per choice, like the ESP colour modes.
			local function makeChoice(parent, order, options, get, set)
				local row = makeFrame(parent, order, 28)
				local width = Instance.new("UISizeConstraint")
				width.MaxSize = Vector2.new(130 * #options, 28)
				width.Parent = row
				addList(row, 6, true)
				local buttons = {}
				for index, option in ipairs(options) do
					local button = Instance.new("TextButton")
					button.LayoutOrder = index
					button.Size = UDim2.new(1 / #options, -6 * (#options - 1) / #options, 1, 0)
					button.AutoButtonColor = false
					button.BorderSizePixel = 0
					button.Font = Enum.Font.GothamMedium
					button.Text = option
					button.TextSize = 12
					addCorner(button, UDim.new(0, 8))
					button.Parent = row
					button.Activated:Connect(function()
						set(option)
						repaint()
					end)
					buttons[option] = button
				end
				table.insert(refreshers, function()
					local theme = auxiliaryUiTheme
					local current = get()
					for option, button in pairs(buttons) do
						button.BackgroundColor3 = current == option and theme.Accent or theme.Inset
						button.TextColor3 = current == option and theme.OnAccent or theme.SubText
					end
				end)
				return row
			end
			-- An on/off line: the whole line is clickable, with a switch on the right.
			local function makeSwitch(parent, order, text, get, set)
				local cell = Instance.new("TextButton")
				cell.LayoutOrder = order
				cell.Size = UDim2.new(1, 0, 0, 34)
				cell.AutoButtonColor = false
				cell.BorderSizePixel = 0
				cell.Text = ""
				bindAuxiliaryUiColor(cell, "BackgroundColor3", "Inset")
				addCorner(cell, UDim.new(0, 8))
				cell.Parent = parent
				makeLabel(cell, { text = text, size = 13, position = UDim2.fromOffset(12, 0), frameSize = UDim2.new(1, -70, 1, 0) })
				local track = Instance.new("Frame")
				track.AnchorPoint = Vector2.new(1, 0.5)
				track.Position = UDim2.new(1, -10, 0.5, 0)
				track.Size = UDim2.fromOffset(34, 18)
				track.BorderSizePixel = 0
				addCorner(track, UDim.new(1, 0))
				track.Parent = cell
				local trackStroke = Instance.new("UIStroke")
				trackStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				trackStroke.Parent = track
				local knob = Instance.new("Frame")
				knob.AnchorPoint = Vector2.new(0, 0.5)
				knob.Size = UDim2.fromOffset(14, 14)
				knob.BorderSizePixel = 0
				addCorner(knob, UDim.new(1, 0))
				knob.Parent = track
				cell.Activated:Connect(function()
					set(not get())
					repaint()
				end)
				table.insert(refreshers, function()
					local theme = auxiliaryUiTheme
					local on = get() == true
					track.BackgroundColor3 = on and theme.Accent or theme.Card
					trackStroke.Color = on and theme.Accent or theme.Stroke
					knob.BackgroundColor3 = on and Color3.new(1, 1, 1) or theme.SubText
					knob.Position = on and UDim2.new(1, -16, 0.5, 0) or UDim2.new(0, 2, 0.5, 0)
				end)
				return cell
			end
			-- Lists here are rebuilt as things change, so their old theme bindings are cleared out.
			local function pruneDeadThemeBindings()
				for index = #auxiliaryUiColorBindings, 1, -1 do
					if not auxiliaryUiColorBindings[index][1].Parent then
						table.remove(auxiliaryUiColorBindings, index)
					end
				end
			end
			local function clearList(list)
				for _, child in ipairs(list:GetChildren()) do
					if child:IsA("GuiObject") then child:Destroy() end
				end
				pruneDeadThemeBindings()
			end
			-- One line of a list: an optional tag (a key, say), the main text with a note under it,
			-- and buttons on the right. Each button is { text, onClick, primary }.
			local function makeListRow(parent, order, tagText, text, note, buttons)
				local row = Instance.new("Frame")
				row.LayoutOrder = order
				row.Size = UDim2.new(1, 0, 0, note and 40 or 32)
				row.BorderSizePixel = 0
				bindAuxiliaryUiColor(row, "BackgroundColor3", "Inset")
				addCorner(row, UDim.new(0, 8))
				row.Parent = parent
				local textX = 12
				if tagText then
					local tag = makePill(row, tagText, 0, "Card", "AccentText", "TextLabel")
					tag.Font = Enum.Font.GothamBold
					tag.AutomaticSize = Enum.AutomaticSize.None
					tag.Size = UDim2.fromOffset(92, 24)
					tag.TextTruncate = Enum.TextTruncate.AtEnd
					tag.AnchorPoint = Vector2.new(0, 0.5)
					tag.Position = UDim2.new(0, 6, 0.5, 0)
					textX = 108
				end
				local buttonsWidth = 0
				for _, button in ipairs(buttons) do
					buttonsWidth += TextService:GetTextSize(button[1], 12, Enum.Font.GothamMedium, Vector2.new(1000, 26)).X + 26
				end
				makeLabel(row, {
					text = text, font = Enum.Font.GothamMedium, size = 12,
					position = UDim2.fromOffset(textX, note and 5 or 0), frameSize = UDim2.new(1, -(textX + buttonsWidth + 8), 0, note and 16 or 32),
				})
				if note then
					makeLabel(row, {
						text = note, size = 10, role = "Muted",
						position = UDim2.fromOffset(textX, 21), frameSize = UDim2.new(1, -(textX + buttonsWidth + 8), 0, 13),
					})
				end
				local buttonRow = Instance.new("Frame")
				buttonRow.AnchorPoint = Vector2.new(1, 0.5)
				buttonRow.Position = UDim2.new(1, -5, 0.5, 0)
				buttonRow.Size = UDim2.fromOffset(0, 26)
				buttonRow.AutomaticSize = Enum.AutomaticSize.X
				buttonRow.BackgroundTransparency = 1
				buttonRow.Parent = row
				addList(buttonRow, 4, true)
				for index, button in ipairs(buttons) do
					local pill = makePill(buttonRow, button[1], index, button[3] and "Accent" or "Card", button[3] and "OnAccent" or "SubText")
					pill.Activated:Connect(button[2])
				end
				return row
			end

			local root = Instance.new("Frame")
			root.Name = "IySettings"
			root.LayoutOrder = 1
			root.Size = UDim2.new(1, -20, 0, 0)
			root.AutomaticSize = Enum.AutomaticSize.Y
			root.BackgroundTransparency = 1
			root.Parent = page
			addList(root, 8)

			------------------------------------------------------------------------------------------
			-- Keybinds: Infinite Yield's own, which run a command (or click teleport / click delete)
			-- when a key is pressed. They also show in the on-screen keybind list.
			local keybindsCard = makeCard(root, 1)
			local keybindsTitle = makeTitleRow(keybindsCard, "Keybinds", "keyboard")
			local keybindCount = makePill(keybindsTitle, "", 0, "Inset", "SubText", "TextLabel")
			keybindCount.AnchorPoint = Vector2.new(1, 0)
			keybindCount.Position = UDim2.fromScale(1, 0)
			keybindCount.Size = UDim2.fromOffset(0, 24)
			makeLabel(keybindsCard, {
				order = 1, size = 12, role = "SubText", wrap = true,
				text = "Run any command with a key, or teleport and delete with a click while you hold one. Keys for the Quick Controls switches are set on the switches themselves.",
			})
			local bindList = makeFrame(keybindsCard, 2)
			addList(bindList, 6)
			local bindEmpty = makeLabel(keybindsCard, { order = 3, size = 12, role = "Muted", text = "No keybinds yet. Add one below." })

			makeHeading(keybindsCard, 4, "ADD A KEYBIND")
			local chosenKey, recordingKey = nil, false
			local bindAction, bindTrigger = "Command", "Key down"
			local keyRow = makeFrame(keybindsCard, 5, 28)
			local keyButton = makePill(keyRow, "Choose a key", 0, "Inset", "Text")
			keyButton.Size = UDim2.fromOffset(0, 28)
			local keyStroke = Instance.new("UIStroke")
			keyStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			keyStroke.Transparency = 0.35
			bindAuxiliaryUiColor(keyStroke, "Color", "Stroke")
			keyStroke.Parent = keyButton
			makeLabel(keyRow, {
				text = "Click, then press a key or click a mouse button in the game. Esc cancels.", size = 11, role = "Muted",
				position = UDim2.fromOffset(150, 0), frameSize = UDim2.new(1, -150, 1, 0),
			})
			makeChoice(keybindsCard, 6, { "Command", "Click Teleport", "Click Delete" }, function() return bindAction end, function(option)
				bindAction = option
			end)
			local commandBox = makeTextBox(keybindsCard, 7, "Command to run, like fly or speed 50")
			local triggerChoice = makeChoice(keybindsCard, 8, { "Key down", "Key up", "Toggle" }, function() return bindTrigger end, function(option)
				bindTrigger = option
			end)
			local toggleBox = makeTextBox(keybindsCard, 9, "Command for the next press, like unfly")
			local bindHint = makeLabel(keybindsCard, { order = 10, size = 11, role = "SubText", wrap = true })
			local bindButtons = makeFrame(keybindsCard, 11, 28)
			addList(bindButtons, 6, true)
			local addBindButton = makePill(bindButtons, "Add keybind", 1, "Accent", "OnAccent")
			addBindButton.Size = UDim2.fromOffset(0, 28)
			local clearBindsButton = makePill(bindButtons, "Clear all", 2, "Inset", "SubText")
			clearBindsButton.Size = UDim2.fromOffset(0, 28)

			local function keyText(key)
				if key == "LeftClick" then return "Left click" end
				if key == "RightClick" then return "Right click" end
				return (tostring(key):gsub("^Enum%.KeyCode%.", ""))
			end
			local function showKeyButton()
				keyButton.Text = recordingKey and "Press a key..." or (chosenKey and keyText(chosenKey) or "Choose a key")
				keyStroke.Color = recordingKey and auxiliaryUiTheme.Accent or auxiliaryUiTheme.Stroke
				keyStroke.Transparency = recordingKey and 0 or 0.35
			end
			-- Which fields show, and what the chosen kind of keybind does.
			table.insert(refreshers, function()
				local isCommand = bindAction == "Command"
				commandBox.Visible = isCommand
				triggerChoice.Visible = isCommand
				toggleBox.Visible = isCommand and bindTrigger == "Toggle"
				if bindAction == "Click Teleport" then
					bindHint.Text = "Hold the key and click somewhere to teleport there."
				elseif bindAction == "Click Delete" then
					bindHint.Text = "Hold the key and click a part to delete it. Only you see it go."
				elseif bindTrigger == "Key up" then
					bindHint.Text = "Runs the command when you let go of the key."
				elseif bindTrigger == "Toggle" then
					bindHint.Text = "Runs the first command, then the second on the next press, and so on (fly, then unfly)."
				else
					bindHint.Text = "Runs the command when you press the key."
				end
				showKeyButton()
			end)
			keyButton.Activated:Connect(function()
				recordingKey = not recordingKey
				showKeyButton()
			end)

			local function describeBind(bind)
				local command = tostring(bind.COMMAND)
				if command == "clicktp" then return "Click Teleport", "Hold it, then click where to go" end
				if command == "clickdel" then return "Click Delete", "Hold it, then click a part to delete" end
				if bind.TOGGLE then return command, "Then " .. tostring(bind.TOGGLE) .. " on the next press" end
				return command, bind.ISKEYUP and "Runs when you let go" or "Runs when you press it"
			end
			local bindSignature = nil
			local function refreshBindList(force)
				local list = type(binds) == "table" and binds or {}
				local parts = {}
				for _, bind in ipairs(list) do
					table.insert(parts, tostring(bind.KEY) .. "|" .. tostring(bind.COMMAND) .. "|" .. tostring(bind.TOGGLE) .. "|" .. tostring(bind.ISKEYUP))
				end
				local signature = table.concat(parts, "\n")
				if signature == bindSignature and not force then return end
				bindSignature = signature
				clearList(bindList)
				for index, bind in ipairs(list) do
					local text, note = describeBind(bind)
					makeListRow(bindList, index, keyText(bind.KEY), text, note, {
						{ "Remove", function() unkeybind(bind.COMMAND, bind.KEY) refreshBindList() end },
					})
				end
				bindList.Visible = #list > 0
				bindEmpty.Visible = #list == 0
				keybindCount.Text = #list == 1 and "1 keybind" or (#list .. " keybinds")
			end

			addBindButton.Activated:Connect(function()
				if not chosenKey then
					notify("Keybinds", "Choose a key first: click Choose a key, then press one.")
					return
				end
				local summary
				if bindAction == "Click Teleport" then
					addbind("clicktp", chosenKey, false)
					summary = "click teleport"
				elseif bindAction == "Click Delete" then
					addbind("clickdel", chosenKey, false)
					summary = "click delete"
				else
					local command = withoutPrefix(commandBox.Text)
					local second = withoutPrefix(toggleBox.Text)
					if command == "" then
						notify("Keybinds", "Type the command to run first.")
						return
					end
					if command:find("\\\\", 1, true) or second:find("\\\\", 1, true) then
						notify("Keybinds", "Use one backslash between commands to run several from one key.")
						return
					end
					if bindTrigger == "Toggle" then
						if second == "" then
							notify("Keybinds", "Type the command for the next press too, like unfly.")
							return
						end
						addbind(command, chosenKey, false, second)
						summary = command .. " / " .. second
					else
						addbind(command, chosenKey, bindTrigger == "Key up")
						summary = command
					end
				end
				refreshbinds()
				updatesaves()
				notify("Keybinds", keyText(chosenKey) .. " now runs " .. summary)
				chosenKey = nil
				commandBox.Text = ""
				toggleBox.Text = ""
				repaint()
				refreshBindList()
			end)
			local clearConfirmUntil = 0
			clearBindsButton.Activated:Connect(function()
				local count = type(binds) == "table" and #binds or 0
				if count == 0 then
					notify("Keybinds", "There are no keybinds to clear.")
					return
				end
				if os.clock() > clearConfirmUntil then
					clearConfirmUntil = os.clock() + 4
					notify("Clear all keybinds?", "Click Clear all again to remove " .. (count == 1 and "your keybind" or ("all " .. count .. " keybinds")) .. ".", 4)
					return
				end
				clearConfirmUntil = 0
				binds = {}
				refreshbinds()
				updatesaves()
				notify("Keybinds", "Removed all keybinds")
				refreshBindList()
			end)

			-- Setting a key: the next key press, or a click in the game (clicks on this menu don't
			-- count, so the box can be clicked again to cancel).
			if sharedEnv.SpreadCheeksIyKeyCapture then
				pcall(function() sharedEnv.SpreadCheeksIyKeyCapture:Disconnect() end)
			end
			sharedEnv.SpreadCheeksIyKeyCapture = UserInputService.InputBegan:Connect(function(input)
				if not recordingKey or UserInputService:GetFocusedTextBox() then return end
				if input.UserInputType == Enum.UserInputType.Keyboard then
					if input.KeyCode == Enum.KeyCode.Escape then
						recordingKey = false
						showKeyButton()
						return
					end
					if input.KeyCode == Enum.KeyCode.Semicolon or isMenuToggleKey(input.KeyCode) then
						notify("Keybinds", input.KeyCode.Name .. " is already used by this menu, pick another key")
						return
					end
					chosenKey = tostring(input.KeyCode)
				elseif input.UserInputType == Enum.UserInputType.MouseButton1 and not pointerOverMenu() then
					chosenKey = "LeftClick"
				elseif input.UserInputType == Enum.UserInputType.MouseButton2 and not pointerOverMenu() then
					chosenKey = "RightClick"
				else
					return
				end
				recordingKey = false
				showKeyButton()
			end)

			------------------------------------------------------------------------------------------
			-- General: the command prefix, and loading again after a teleport.
			local generalCard = makeCard(root, 2)
			makeTitleRow(generalCard, "General", "sliders-horizontal", "settings")
			local prefixRow = makeFrame(generalCard, 1, 34)
			makeLabel(prefixRow, { text = "Command prefix", size = 13, position = UDim2.fromOffset(0, 0), frameSize = UDim2.new(1, -90, 1, 0) })
			local prefixBox = makeTextBox(prefixRow, 0, ";")
			prefixBox.AnchorPoint = Vector2.new(1, 0)
			prefixBox.Position = UDim2.fromScale(1, 0)
			prefixBox.Size = UDim2.fromOffset(80, 34)
			prefixBox.TextXAlignment = Enum.TextXAlignment.Center
			prefixBox.Text = tostring(prefix or ";")
			prefixBox.FocusLost:Connect(function()
				local newPrefix = trimmed(prefixBox.Text)
				if newPrefix == "" or newPrefix:find("%s") then
					prefixBox.Text = tostring(prefix or ";")
					return
				end
				if newPrefix == prefix then return end
				-- Infinite Yield's own prefix box saves it and updates its command bar.
				local changed = pcall(function() PrefixBox.Text = newPrefix end)
				if not changed or prefix ~= newPrefix then
					prefix = newPrefix
					updatesaves()
				end
				notify("Prefix", "Commands in chat and the classic bar now start with " .. newPrefix)
			end)
			makeLabel(generalCard, {
				order = 2, size = 11, role = "SubText", wrap = true,
				text = "What chat commands start with, like ;fly. The ; key still opens the quick command bar.",
			})
			local canKeep = type(queueteleport) == "function"
			makeSwitch(generalCard, 3, "Load again after a teleport", function()
				return canKeep and KeepInfYield == true
			end, function(on)
				if not canKeep then
					notify("Keep loaded", "Your executor can't do this (it has no queue_on_teleport).")
					return
				end
				KeepInfYield = on
				updatesaves()
			end)
			makeLabel(generalCard, {
				order = 4, size = 11, role = "SubText", wrap = true,
				text = canKeep and "Runs this script again when you join another server or game. It loads 'Infinite Yield - UI polish.txt' from your executor's workspace folder, so keep it there."
					or "Your executor can't run scripts after a teleport, so this stays off.",
			})

			------------------------------------------------------------------------------------------
			-- Aliases: other names for commands.
			local aliasesCard = makeCard(root, 3)
			makeTitleRow(aliasesCard, "Aliases", "tag")
			makeLabel(aliasesCard, {
				order = 1, size = 12, role = "SubText", wrap = true,
				text = "Give a command another name: with fly and f, typing f runs fly.",
			})
			local aliasList = makeFrame(aliasesCard, 2)
			addList(aliasList, 6)
			local aliasEmpty = makeLabel(aliasesCard, { order = 3, size = 12, role = "Muted", text = "No aliases yet." })
			makeHeading(aliasesCard, 4, "ADD AN ALIAS")
			local aliasCommandBox = makeTextBox(aliasesCard, 5, "Command, like fly")
			local aliasNameBox = makeTextBox(aliasesCard, 6, "New name for it, like f")
			local addAliasButton = makePill(aliasesCard, "Add alias", 7, "Accent", "OnAccent")
			addAliasButton.Size = UDim2.fromOffset(0, 28)
			local aliasSignature = nil
			local function refreshAliasList()
				local list = type(aliases) == "table" and aliases or {}
				local parts = {}
				for _, alias in ipairs(list) do
					table.insert(parts, tostring(alias.ALIAS) .. "|" .. tostring(alias.CMD))
				end
				local signature = table.concat(parts, "\n")
				if signature == aliasSignature then return end
				aliasSignature = signature
				clearList(aliasList)
				for index, alias in ipairs(list) do
					local name = tostring(alias.ALIAS)
					makeListRow(aliasList, index, nil, name .. "  →  " .. tostring(alias.CMD), nil, {
						{ "Remove", function()
							execCmd("removealias " .. name, Players.LocalPlayer)
							task.delay(0.1, refreshAliasList)
						end },
					})
				end
				aliasList.Visible = #list > 0
				aliasEmpty.Visible = #list == 0
			end
			addAliasButton.Activated:Connect(function()
				local command = withoutPrefix(aliasCommandBox.Text):lower()
				local name = withoutPrefix(aliasNameBox.Text):lower()
				if command == "" or name == "" or command:find("%s") or name:find("%s") then
					notify("Aliases", "Type a command and a one-word name for it.")
					return
				end
				if not findCmd(command) then
					notify("Aliases", "There's no command called " .. command .. ".")
					return
				end
				execCmd("addalias " .. command .. " " .. name, Players.LocalPlayer)
				aliasCommandBox.Text = ""
				aliasNameBox.Text = ""
				task.delay(0.1, refreshAliasList)
			end)

			------------------------------------------------------------------------------------------
			-- Waypoints: saved spots in this game to teleport back to.
			local waypointsCard = makeCard(root, 4)
			makeTitleRow(waypointsCard, "Waypoints", "map-pin")
			makeLabel(waypointsCard, {
				order = 1, size = 12, role = "SubText", wrap = true,
				text = "Save where you're standing and teleport back any time. Waypoints are kept for each game.",
			})
			local waypointList = makeFrame(waypointsCard, 2)
			addList(waypointList, 6)
			local waypointEmpty = makeLabel(waypointsCard, { order = 3, size = 12, role = "Muted", text = "No waypoints in this game yet." })
			makeHeading(waypointsCard, 4, "SAVE A WAYPOINT")
			local waypointNameBox = makeTextBox(waypointsCard, 5, "Name, like base or spawn")
			local saveWaypointButton = makePill(waypointsCard, "Save where I'm standing", 6, "Accent", "OnAccent")
			saveWaypointButton.Size = UDim2.fromOffset(0, 28)
			local markersShown = false
			makeSwitch(waypointsCard, 7, "Show markers in the world", function() return markersShown end, function(on)
				markersShown = on
				execCmd(on and "showwaypoints" or "hidewaypoints", Players.LocalPlayer)
			end)
			local waypointSignature = nil
			local function refreshWaypointList()
				local list = type(WayPoints) == "table" and WayPoints or {}
				local parts = {}
				for _, waypoint in ipairs(list) do
					table.insert(parts, tostring(waypoint.NAME) .. "|" .. table.concat(waypoint.COORD or {}, ","))
				end
				local signature = table.concat(parts, "\n")
				if signature == waypointSignature then return end
				waypointSignature = signature
				clearList(waypointList)
				for index, waypoint in ipairs(list) do
					local name = tostring(waypoint.NAME)
					local coord = waypoint.COORD or {}
					local where = string.format("%s, %s, %s", tostring(coord[1] or "?"), tostring(coord[2] or "?"), tostring(coord[3] or "?"))
					makeListRow(waypointList, index, nil, name, where, {
						{ "Go", function() execCmd("waypoint " .. name, Players.LocalPlayer) end, true },
						{ "Remove", function()
							execCmd("deletewaypoint " .. name, Players.LocalPlayer)
							task.delay(0.1, refreshWaypointList)
						end },
					})
				end
				waypointList.Visible = #list > 0
				waypointEmpty.Visible = #list == 0
			end
			saveWaypointButton.Activated:Connect(function()
				local name = trimmed(waypointNameBox.Text)
				if name == "" then
					notify("Waypoints", "Type a name for this spot first.")
					return
				end
				execCmd("setwaypoint " .. name, Players.LocalPlayer)
				waypointNameBox.Text = ""
				task.delay(0.1, refreshWaypointList)
			end)

			------------------------------------------------------------------------------------------
			-- Plugins: extra commands from .iy files in the executor's workspace folder.
			local pluginsCard = makeCard(root, 5)
			makeTitleRow(pluginsCard, "Plugins", "puzzle")
			makeLabel(pluginsCard, {
				order = 1, size = 12, role = "SubText", wrap = true,
				text = "Add commands from Infinite Yield plugin files (.iy). Put the file in your executor's workspace folder, then add it by name.",
			})
			local pluginList = makeFrame(pluginsCard, 2)
			addList(pluginList, 6)
			local pluginEmpty = makeLabel(pluginsCard, { order = 3, size = 12, role = "Muted", text = "No plugins added." })
			local pluginNameBox = makeTextBox(pluginsCard, 4, "Plugin file name, like myplugin.iy")
			local addPluginButton = makePill(pluginsCard, "Add plugin", 5, "Accent", "OnAccent")
			addPluginButton.Size = UDim2.fromOffset(0, 28)
			local pluginSignature = nil
			local function refreshPluginList()
				local list = type(PluginsTable) == "table" and PluginsTable or {}
				local signature = table.concat(list, "\n")
				if signature == pluginSignature then return end
				pluginSignature = signature
				clearList(pluginList)
				for index, fileName in ipairs(list) do
					local pluginName = tostring(fileName)
					makeListRow(pluginList, index, nil, pluginName, nil, {
						{ "Remove", function()
							pcall(deletePlugin, pluginName)
							task.delay(0.1, refreshPluginList)
						end },
					})
				end
				pluginList.Visible = #list > 0
				pluginEmpty.Visible = #list == 0
			end
			addPluginButton.Activated:Connect(function()
				local name = trimmed(pluginNameBox.Text)
				if name == "" then
					notify("Plugins", "Type the plugin's file name first.")
					return
				end
				local added, problem = pcall(addPlugin, name)
				if not added then
					notify("Plugins", "Couldn't add it: " .. tostring(problem))
				end
				pluginNameBox.Text = ""
				task.delay(0.2, refreshPluginList)
			end)

			repaint()
			refreshBindList(true)
			refreshAliasList()
			refreshWaypointList()
			refreshPluginList()
			-- Changes made with commands (;addalias, ;swp...) show up too, while the tab is open.
			task.spawn(function()
				while root.Parent do
					task.wait(1)
					if page.Visible then
						refreshBindList()
						refreshAliasList()
						refreshWaypointList()
						refreshPluginList()
						if not prefixBox:IsFocused() then
							prefixBox.Text = tostring(prefix or ";")
						end
					end
				end
			end)
		end
		-- Kept separate so a problem on this page can't stop the rest of the menu loading.
		local iySettingsOk, iySettingsError = pcall(buildIySettingsPage)
		if not iySettingsOk then
			warn("[SpreadCheeksGUI] The IY Settings page couldn't be built: " .. tostring(iySettingsError))
		end

		-- Configs: your whole setup saved under a name (aimbot, trigger bot, ESP look, speeds, the
		-- theme, switch keybinds and which switches are on), to load again later, load by itself on
		-- start, or share as text. Kept in SpreadCheeksGUI_Configs.json.
		local configsTab = withIcon(window, "CreateTab", { name = "Configs" }, "folder-cog", "folder", "save")
		local function buildConfigsPage()
			local configFile = "SpreadCheeksGUI_Configs.json"
			-- Settings that are about this screen or are really switches, so they're left out of the
			-- saved settings (switches are saved on their own, below).
			local notConfigSettings = {
				performanceStats = true, cheatDetector = true, keybindList = true, radar = true, logsWindow = true, joinAlerts = true,
				mentionAlerts = true, favouritesBar = true, favourites = true, targetHud = true, emoteWheel = true,
				keybindListX = true, keybindListY = true, performanceStatsX = true, performanceStatsY = true,
				radarX = true, radarY = true, logsWindowX = true, logsWindowY = true, favouritesBarX = true, favouritesBarY = true,
				targetHudX = true, targetHudY = true, fpsCap = true,
				lastSeenVersion = true, whatsNewX = true, whatsNewY = true, finderX = true, finderY = true,
				spectateBarX = true, spectateBarY = true, outfitX = true, outfitY = true, playerNotes = true, cleanScreenKeySet = true,
				safeTeleport = true, antiVoid = true, autoRejoin = true, objectFinder = true, spectateBar = true, zoomKey = true,
				timeOfDay = true, fpsBoost = true, muteMusic = true, muteOthers = true, streamerMode = true, healthWarnings = true,
				objectEsp = true, trollPanel = true, trollPanelX = true, trollPanelY = true, ctrlClickSelect = true,
				aimTrainerX = true, aimTrainerY = true, aimTrainerBests = true, weather = true, graphicsPresets = true, panicKeySet = true,
				autoGoBack = true, themeMakerX = true, themeMakerY = true, sessionStats = true, sessionStatsX = true, sessionStatsY = true,
				sessionTotals = true, friendsX = true, friendsY = true, aimWarning = true, hitMarkers = true, crosshair = true,
				spotify = true, spotifyX = true, spotifyY = true,
			}
			-- gameConfigs: the config to load in each game, by game ID (the "This game" button).
			local store = { configs = {}, autoload = "", applySwitches = true, gameConfigs = {} }
			if readfile then
				local readOk, contents = readfile(configFile, true)
				if readOk and type(contents) == "string" and contents ~= "" then
					local decodeOk, data = pcall(function() return HttpService:JSONDecode(contents) end)
					if decodeOk and type(data) == "table" then
						-- Anything in the file that isn't a named config is skipped.
						for name, config in pairs(type(data.configs) == "table" and data.configs or {}) do
							if type(name) == "string" and type(config) == "table" then
								store.configs[name] = config
							end
						end
						if type(data.autoload) == "string" then store.autoload = data.autoload end
						if type(data.applySwitches) == "boolean" then store.applySwitches = data.applySwitches end
						for gameId, name in pairs(type(data.gameConfigs) == "table" and data.gameConfigs or {}) do
							if type(gameId) == "string" and type(name) == "string" then store.gameConfigs[gameId] = name end
						end
					end
				end
			end
			local function saveStore()
				if writefile then
					writefile(configFile, HttpService:JSONEncode(store), true)
				end
			end

			-- Everything a config holds, from how things are set right now.
			local function captureConfig()
				local features = {}
				for key, value in pairs(featureSettings) do
					-- Lists (the watch list) are copied, so the config doesn't change along with them.
					if not notConfigSettings[key] then features[key] = type(value) == "table" and table.clone(value) or value end
				end
				local esp = {}
				for key in pairs(espDefaultSettings) do
					esp[key] = espSettings[key]
				end
				local keys, switches = {}, {}
				-- "" is no key, so loading the config takes off a key set since; a switch a config
				-- doesn't mention at all (one added since it was saved) keeps its key.
				for _, entry in ipairs(quickToggles) do
					keys[entry.name] = entry.key and entry.key.Name or ""
					-- noConfig switches (Fake Dead, and the ones that need a player) stay as they are.
					if not entry.noConfig then switches[entry.name] = entry.state == true end
				end
				-- Keys on Go Back and the moves, kept apart from switch names the way the keybinds file does.
				for _, action in ipairs(quickActions) do
					keys["action:" .. action.name] = action.key and action.key.Name or ""
				end
				switches["Aimbot"] = aimbotState.enabled == true
				switches["Keybind List"] = featureSettings.keybindList == true
				-- Version 2: keys lists every key box, with "" for none (see applyConfig).
				return { version = 2, savedAt = os.time(), features = features, esp = esp, keys = keys, switches = switches }
			end

			-- Puts a config's settings in place, and (withSwitches) turns switches on and off to match.
			local function applyConfig(config, withSwitches)
				if type(config) ~= "table" then return false end
				if type(config.features) == "table" then
					for key, default in pairs(featureSettings) do
						local value = config.features[key]
						if not notConfigSettings[key] and value ~= nil and type(value) == type(default) then
							featureSettings[key] = type(value) == "table" and table.clone(value) or value
						end
					end
					for key, limits in pairs(featureLimits) do
						featureSettings[key] = math.clamp(featureSettings[key], limits[1], limits[2])
					end
					iyflyspeed = featureSettings.flySpeed
					vehicleflyspeed = featureSettings.vehicleFlySpeed
					NAV_KEYBOARD_SPEED = Vector3.new(featureSettings.freecamSpeed, featureSettings.freecamSpeed, featureSettings.freecamSpeed)
					QEfly = featureSettings.flyUpDownKeys
					saveFeatureSettings()
					local palette = paletteNamed(featureSettings.theme)
					-- The config may have brought the Custom theme's colours, so they're worked out again.
					if palette and palette.refresh then palette.refresh() end
					if palette and (palette ~= currentPalette or palette.refresh) then
						applyTheme(palette)
						pcall(function() themeDropdown:Set(palette.name, true) end)
					end
					if aimbotState.refreshKey then aimbotState.refreshKey() end
					-- The animation pack, spin speed and so on go on straight away.
					if trolling.applySettings then pcall(trolling.applySettings) end
				end
				if type(config.esp) == "table" then
					for key, default in pairs(espDefaultSettings) do
						local value = config.esp[key]
						if value ~= nil and type(value) == type(default) then espSettings[key] = value end
					end
					saveEspSettings()
				end
				if type(config.keys) == "table" then
					stopKeyRecording()
					-- Every key box, under the name the config keeps its key by.
					local boxes = {}
					for _, entry in ipairs(quickToggles) do table.insert(boxes, { entry = entry, name = entry.name }) end
					for _, action in ipairs(quickActions) do table.insert(boxes, { entry = action, name = "action:" .. action.name }) end
					-- Configs saved since every key box was listed ("" for no key) leave a box they don't
					-- mention as it is, as it's on a switch or move added since, unless they give its key
					-- to something else. Older configs only listed the keys that were set, so in those
					-- a box that isn't listed has no key.
					local complete = (tonumber(config.version) or 1) >= 2
					if not complete then
						for _, listed in pairs(config.keys) do
							if listed == "" then
								complete = true
								break
							end
						end
					end
					local given = {}
					for _, box in ipairs(boxes) do
						local keyName = config.keys[box.name]
						if keyName == nil and not complete then keyName = "" end
						if keyName ~= nil then
							local keyOk, keyCode = pcall(function() return Enum.KeyCode[keyName] end)
							local usable = not box.entry.noKeybind and type(keyName) == "string" and keyOk and keyCode and not reservedKeys[keyCode]
							box.entry.key = usable and keyCode or nil
							if box.entry.key then given[box.entry.key] = true end
						end
					end
					for _, box in ipairs(boxes) do
						if config.keys[box.name] == nil and box.entry.key and given[box.entry.key] then box.entry.key = nil end
						refreshKeyChip(box.entry)
					end
					saveQuickKeybinds()
				end
				if withSwitches and type(config.switches) == "table" then
					-- A switch the config doesn't mention (one added since it was saved) is left as it is.
					for _, entry in ipairs(quickToggles) do
						local saved = config.switches[entry.name]
						local on = saved == true
						if not entry.noConfig and saved ~= nil and entry.state ~= on then setQuickToggle(entry, on) end
					end
					applyAimbot(config.switches["Aimbot"] == true)
					pcall(function() aimbotToggle:Set(aimbotState.enabled, true) end)
					showKeybindList(config.switches["Keybind List"] == true)
					pcall(function() keybindListToggle:Set(featureSettings.keybindList, true) end)
				end
				return true
			end

			local function cleanName(text)
				local name = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
				return name:sub(1, 32)
			end
			local function configNames()
				local names = {}
				for name in pairs(store.configs) do table.insert(names, name) end
				-- Most recently saved first.
				table.sort(names, function(left, right)
					local leftTime = tonumber(store.configs[left].savedAt) or 0
					local rightTime = tonumber(store.configs[right].savedAt) or 0
					if leftTime ~= rightTime then return leftTime > rightTime end
					return left:lower() < right:lower()
				end)
				return names
			end
			local function findConfig(name)
				name = cleanName(name):lower()
				for existing in pairs(store.configs) do
					if existing:lower() == name then return existing end
				end
				return nil
			end
			local refreshList
			local api = {}
			function api.save(name)
				name = cleanName(name)
				if name == "" then
					notify("Configs", "Give the config a name first.")
					return false
				end
				local existing = findConfig(name)
				if existing then store.configs[existing] = nil end
				store.configs[name] = captureConfig()
				-- Saving over a config under different capitals keeps what it loads for.
				if existing and existing ~= name then
					if store.autoload == existing then store.autoload = name end
					for gameId, linked in pairs(store.gameConfigs) do
						if linked == existing then store.gameConfigs[gameId] = name end
					end
				end
				saveStore()
				notify("Configs", (existing and "Updated " or "Saved ") .. name, 3)
				if refreshList then refreshList() end
				return true
			end
			function api.load(name, quiet)
				local existing = findConfig(name)
				if not existing then
					if not quiet then notify("Configs", "There's no config called " .. cleanName(name) .. ".") end
					return false
				end
				local loaded = applyConfig(store.configs[existing], store.applySwitches)
				if loaded then notify("Configs", "Loaded " .. existing, 3) end
				return loaded
			end
			function api.names()
				return configNames()
			end
			-- The config picked for this game (This game), or else the autoload config, goes in once the
			-- rest of the menu has finished building.
			local gameConfig = store.gameConfigs[tostring(game.GameId)]
			local startupConfig = (gameConfig and store.configs[gameConfig]) and gameConfig or store.autoload
			if startupConfig ~= "" then
				task.defer(function()
					if store.configs[startupConfig] then
						api.load(startupConfig, true)
					end
				end)
			end

			------------------------------------------------------------------------------------------
			-- The page, drawn with our own cards like the other tools.
			local page = configsTab and configsTab.tabPage
			if typeof(page) ~= "Instance" then
				warn("[SpreadCheeksGUI] Couldn't build the Configs page; Rayfield's tab layout may have changed.")
				return api
			end
			local function addCorner(object, radius)
				local corner = Instance.new("UICorner")
				corner.CornerRadius = radius or UDim.new(0, 12)
				corner.Parent = object
			end
			local function addList(object, gap, horizontal)
				local layout = Instance.new("UIListLayout")
				layout.Padding = UDim.new(0, gap)
				layout.SortOrder = Enum.SortOrder.LayoutOrder
				if horizontal then
					layout.FillDirection = Enum.FillDirection.Horizontal
					layout.VerticalAlignment = Enum.VerticalAlignment.Center
				end
				layout.Parent = object
				return layout
			end
			local function makeFrame(parent, order, height)
				local frame = Instance.new("Frame")
				frame.LayoutOrder = order or 0
				frame.Size = UDim2.new(1, 0, 0, height or 0)
				if not height then frame.AutomaticSize = Enum.AutomaticSize.Y end
				frame.BackgroundTransparency = 1
				frame.Parent = parent
				return frame
			end
			local function makeCard(parent, order)
				local card = Instance.new("Frame")
				card.LayoutOrder = order
				card.Size = UDim2.fromScale(1, 0)
				card.AutomaticSize = Enum.AutomaticSize.Y
				card.BorderSizePixel = 0
				bindAuxiliaryUiColor(card, "BackgroundColor3", "Card")
				addCorner(card)
				local stroke = Instance.new("UIStroke")
				stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				stroke.Transparency = 0.3
				bindAuxiliaryUiColor(stroke, "Color", "Stroke")
				stroke.Parent = card
				local padding = Instance.new("UIPadding")
				padding.PaddingTop = UDim.new(0, 14)
				padding.PaddingBottom = UDim.new(0, 14)
				padding.PaddingLeft = UDim.new(0, 14)
				padding.PaddingRight = UDim.new(0, 14)
				padding.Parent = card
				addList(card, 10)
				card.Parent = parent
				return card
			end
			local function makeLabel(parent, options)
				local label = Instance.new("TextLabel")
				label.LayoutOrder = options.order or 0
				label.BackgroundTransparency = 1
				label.Font = options.font or Enum.Font.Gotham
				label.TextSize = options.size or 12
				label.Text = options.text or ""
				label.TextXAlignment = Enum.TextXAlignment.Left
				label.TextTruncate = Enum.TextTruncate.AtEnd
				label.Position = options.position or UDim2.new()
				label.Size = options.frameSize or UDim2.new(1, 0, 0, (options.size or 12) + 4)
				if options.wrap then
					label.Size = UDim2.fromScale(1, 0)
					label.AutomaticSize = Enum.AutomaticSize.Y
					label.TextWrapped = true
					label.TextTruncate = Enum.TextTruncate.None
				end
				bindAuxiliaryUiColor(label, "TextColor3", options.role or "Text")
				label.Parent = parent
				return label
			end
			local function makeIcon(parent, size, role, ...)
				local icon = menuIcons.get(...)
				local image = Instance.new("ImageLabel")
				image.BackgroundTransparency = 1
				image.Size = UDim2.fromOffset(size, size)
				image.Visible = icon ~= nil
				if icon then menuIcons.apply(image, icon) end
				bindAuxiliaryUiColor(image, "ImageColor3", role)
				image.Parent = parent
				return image
			end
			-- A small rounded button or tag, as wide as its text, in the given background and text roles.
			local function makePill(parent, text, order, backgroundRole, textRole, className)
				local pill = Instance.new(className or "TextButton")
				pill.LayoutOrder = order or 0
				pill.AutomaticSize = Enum.AutomaticSize.X
				pill.Size = UDim2.fromOffset(0, 26)
				pill.BorderSizePixel = 0
				pill.Font = Enum.Font.GothamMedium
				pill.Text = text
				pill.TextSize = 12
				if pill:IsA("TextButton") then pill.AutoButtonColor = false end
				bindAuxiliaryUiColor(pill, "BackgroundColor3", backgroundRole or "Inset")
				bindAuxiliaryUiColor(pill, "TextColor3", textRole or "SubText")
				addCorner(pill, UDim.new(0, 7))
				local padding = Instance.new("UIPadding")
				padding.PaddingLeft = UDim.new(0, 11)
				padding.PaddingRight = UDim.new(0, 11)
				padding.Parent = pill
				pill.Parent = parent
				return pill
			end
			local function makeTitleRow(card, title, ...)
				local row = makeFrame(card, 0, 24)
				local icon = makeIcon(row, 16, "AccentText", ...)
				icon.Position = UDim2.fromOffset(0, 4)
				makeLabel(row, {
					text = title, font = Enum.Font.GothamBold, size = 14,
					position = UDim2.fromOffset(24, 3), frameSize = UDim2.new(1, -150, 0, 18),
				})
				return row
			end
			local function makeTextBox(parent, order, placeholder)
				local box = Instance.new("TextBox")
				box.LayoutOrder = order or 0
				box.Size = UDim2.new(1, 0, 0, 34)
				box.BorderSizePixel = 0
				box.ClearTextOnFocus = false
				box.Font = Enum.Font.Gotham
				box.PlaceholderText = placeholder
				box.Text = ""
				box.TextSize = 13
				box.TextXAlignment = Enum.TextXAlignment.Left
				box.TextTruncate = Enum.TextTruncate.AtEnd
				bindAuxiliaryUiColor(box, "BackgroundColor3", "Inset")
				bindAuxiliaryUiColor(box, "TextColor3", "Text")
				bindAuxiliaryUiColor(box, "PlaceholderColor3", "Muted")
				addCorner(box, UDim.new(0, 8))
				local padding = Instance.new("UIPadding")
				padding.PaddingLeft = UDim.new(0, 10)
				padding.PaddingRight = UDim.new(0, 10)
				padding.Parent = box
				local stroke = Instance.new("UIStroke")
				stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				stroke.Transparency = 0.35
				bindAuxiliaryUiColor(stroke, "Color", "Stroke")
				stroke.Parent = box
				box.Focused:Connect(function() stroke.Color = auxiliaryUiTheme.Accent end)
				box.FocusLost:Connect(function() stroke.Color = auxiliaryUiTheme.Stroke end)
				box.Parent = parent
				return box
			end
			local function timeAgo(timestamp)
				local seconds = math.max(0, os.time() - (tonumber(timestamp) or os.time()))
				if seconds < 60 then return "just now" end
				if seconds < 3600 then return math.floor(seconds / 60) .. "m ago" end
				if seconds < 86400 then return math.floor(seconds / 3600) .. "h ago" end
				return math.floor(seconds / 86400) .. "d ago"
			end
			-- Lists here are rebuilt as things change, so their old theme bindings are cleared out.
			local function pruneDeadThemeBindings()
				for index = #auxiliaryUiColorBindings, 1, -1 do
					if not auxiliaryUiColorBindings[index][1].Parent then
						table.remove(auxiliaryUiColorBindings, index)
					end
				end
			end
			-- A second click within four seconds confirms something that can't be undone.
			local confirmUntil = {}
			local function confirmed(action, message)
				if (confirmUntil[action] or 0) > os.clock() then
					confirmUntil[action] = nil
					return true
				end
				confirmUntil[action] = os.clock() + 4
				notify("Configs", message, 4)
				return false
			end

			local root = Instance.new("Frame")
			root.Name = "Configs"
			root.LayoutOrder = 1
			root.Size = UDim2.new(1, -20, 0, 0)
			root.AutomaticSize = Enum.AutomaticSize.Y
			root.BackgroundTransparency = 1
			root.Parent = page
			addList(root, 8)

			-- Save the current setup.
			local saveCard = makeCard(root, 1)
			makeTitleRow(saveCard, "Save a config", "save")
			makeLabel(saveCard, {
				order = 1, size = 12, role = "SubText", wrap = true,
				text = "Saves how everything is set right now: aimbot, trigger bot and ESP settings, speeds, the theme, switch keybinds and which switches are on.",
			})
			local nameBox = makeTextBox(saveCard, 2, "Config name, like PvP or Chill")
			local saveButton = makePill(saveCard, "Save config", 3, "Accent", "OnAccent")
			saveButton.Size = UDim2.fromOffset(0, 28)
			saveButton.Activated:Connect(function()
				local name = cleanName(nameBox.Text)
				local existing = name ~= "" and findConfig(name)
				if existing and not confirmed("overwrite:" .. existing:lower(), "Click Save config again to replace " .. existing .. ".") then
					return
				end
				if api.save(name) then nameBox.Text = "" end
			end)

			-- Saved configs.
			local listCard = makeCard(root, 2)
			local listTitle = makeTitleRow(listCard, "Your configs", "folder", "folder-open")
			local countTag = makePill(listTitle, "", 0, "Inset", "SubText", "TextLabel")
			countTag.AnchorPoint = Vector2.new(1, 0)
			countTag.Position = UDim2.fromScale(1, 0)
			countTag.Size = UDim2.fromOffset(0, 24)
			local list = makeFrame(listCard, 1)
			addList(list, 6)
			local emptyLabel = makeLabel(listCard, { order = 2, size = 12, role = "Muted", text = "No configs yet. Save one above." })
			-- Whether loading also turns switches on and off to match, a switch for the whole list.
			local switchesCell = Instance.new("TextButton")
			switchesCell.LayoutOrder = 3
			switchesCell.Size = UDim2.new(1, 0, 0, 34)
			switchesCell.AutoButtonColor = false
			switchesCell.BorderSizePixel = 0
			switchesCell.Text = ""
			bindAuxiliaryUiColor(switchesCell, "BackgroundColor3", "Inset")
			addCorner(switchesCell, UDim.new(0, 8))
			switchesCell.Parent = listCard
			makeLabel(switchesCell, {
				text = "Loading turns switches on and off to match", size = 13,
				position = UDim2.fromOffset(12, 0), frameSize = UDim2.new(1, -70, 1, 0),
			})
			local track = Instance.new("Frame")
			track.AnchorPoint = Vector2.new(1, 0.5)
			track.Position = UDim2.new(1, -10, 0.5, 0)
			track.Size = UDim2.fromOffset(34, 18)
			track.BorderSizePixel = 0
			addCorner(track, UDim.new(1, 0))
			track.Parent = switchesCell
			local trackStroke = Instance.new("UIStroke")
			trackStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			trackStroke.Parent = track
			local knob = Instance.new("Frame")
			knob.AnchorPoint = Vector2.new(0, 0.5)
			knob.Size = UDim2.fromOffset(14, 14)
			knob.BorderSizePixel = 0
			addCorner(knob, UDim.new(1, 0))
			knob.Parent = track
			local function showSwitch()
				local theme = auxiliaryUiTheme
				local on = store.applySwitches
				track.BackgroundColor3 = on and theme.Accent or theme.Card
				trackStroke.Color = on and theme.Accent or theme.Stroke
				knob.BackgroundColor3 = on and Color3.new(1, 1, 1) or theme.SubText
				knob.Position = on and UDim2.new(1, -16, 0.5, 0) or UDim2.new(0, 2, 0.5, 0)
			end
			switchesCell.Activated:Connect(function()
				store.applySwitches = not store.applySwitches
				saveStore()
				showSwitch()
			end)
			table.insert(auxiliaryUiThemeListeners, showSwitch)
			makeLabel(listCard, {
				order = 4, size = 11, role = "SubText", wrap = true,
				text = "Autoload loads that config by itself each time the script starts; This game does the same in this game only, ahead of Autoload. Copy puts a config on your clipboard to share; paste it under Import.",
			})

			refreshList = function()
				for _, child in ipairs(list:GetChildren()) do
					if child:IsA("GuiObject") then child:Destroy() end
				end
				pruneDeadThemeBindings()
				local names = configNames()
				list.Visible = #names > 0
				emptyLabel.Visible = #names == 0
				countTag.Text = #names == 1 and "1 config" or (#names .. " configs")
				for index, name in ipairs(names) do
					local config = store.configs[name]
					local isAutoload = store.autoload == name
					local row = Instance.new("Frame")
					row.LayoutOrder = index
					row.Size = UDim2.new(1, 0, 0, 42)
					row.BorderSizePixel = 0
					bindAuxiliaryUiColor(row, "BackgroundColor3", "Inset")
					addCorner(row, UDim.new(0, 8))
					row.Parent = list
					local buttons = Instance.new("Frame")
					buttons.AnchorPoint = Vector2.new(1, 0.5)
					buttons.Position = UDim2.new(1, -6, 0.5, 0)
					buttons.Size = UDim2.fromOffset(0, 26)
					buttons.AutomaticSize = Enum.AutomaticSize.X
					buttons.BackgroundTransparency = 1
					buttons.Parent = row
					addList(buttons, 4, true)
					local loadButton = makePill(buttons, "Load", 1, "Accent", "OnAccent")
					loadButton.Activated:Connect(function() api.load(name) end)
					local autoloadButton = makePill(buttons, isAutoload and "Autoloads" or "Autoload", 2, isAutoload and "SelectedCard" or "Card", isAutoload and "AccentText" or "SubText")
					autoloadButton.Activated:Connect(function()
						store.autoload = isAutoload and "" or name
						saveStore()
						notify("Configs", isAutoload and ("Nothing loads on start now") or (name .. " will load each time the script starts"), 3)
						refreshList()
					end)
					-- This game: loads by itself whenever the script starts in this game (before Autoload).
					local gameKey = tostring(game.GameId)
					local isGameConfig = store.gameConfigs[gameKey] == name
					local gameButton = makePill(buttons, "This game", 3, isGameConfig and "SelectedCard" or "Card", isGameConfig and "AccentText" or "SubText")
					gameButton.Activated:Connect(function()
						store.gameConfigs[gameKey] = not isGameConfig and name or nil
						saveStore()
						notify("Configs", isGameConfig and ("Nothing's picked for this game now") or (name .. " will load each time the script starts in this game"), 3)
						refreshList()
					end)
					local copyButton = makePill(buttons, "Copy", 4, "Card", "SubText")
					copyButton.Activated:Connect(function()
						local encodeOk, text = pcall(function()
							return HttpService:JSONEncode({ spreadCheeksConfig = 1, name = name, config = store.configs[name] })
						end)
						if encodeOk then toClipboard(text) end
					end)
					local deleteButton = makePill(buttons, "Delete", 5, "Card", "SubText")
					deleteButton.Activated:Connect(function()
						if not confirmed("delete:" .. name:lower(), "Click Delete again to delete " .. name .. ".") then return end
						store.configs[name] = nil
						if store.autoload == name then store.autoload = "" end
						for linkedGame, linked in pairs(store.gameConfigs) do
							if linked == name then store.gameConfigs[linkedGame] = nil end
						end
						saveStore()
						notify("Configs", "Deleted " .. name, 3)
						refreshList()
					end)
					-- The buttons take about 330px together; the name and note get the rest.
					makeLabel(row, {
						text = name, font = Enum.Font.GothamMedium, size = 13,
						position = UDim2.fromOffset(12, 5), frameSize = UDim2.new(1, -350, 0, 17),
					})
					local switchesOn = 0
					for _, on in pairs(type(config.switches) == "table" and config.switches or {}) do
						if on == true then switchesOn += 1 end
					end
					local theme = type(config.features) == "table" and config.features.theme or nil
					makeLabel(row, {
						text = "Saved " .. timeAgo(config.savedAt) .. "  ·  " .. switchesOn .. (switchesOn == 1 and " switch on" or " switches on")
							.. (theme and ("  ·  " .. tostring(theme)) or "") .. (isGameConfig and "  ·  loads in this game" or (isAutoload and "  ·  loads on start" or "")),
						size = 10, role = (isAutoload or isGameConfig) and "AccentText" or "Muted",
						position = UDim2.fromOffset(12, 23), frameSize = UDim2.new(1, -350, 0, 13),
					})
				end
			end

			-- Import a config someone shared.
			local importCard = makeCard(root, 3)
			makeTitleRow(importCard, "Import", "clipboard-paste", "download")
			makeLabel(importCard, {
				order = 1, size = 12, role = "SubText", wrap = true,
				text = "Paste a config copied with Copy, give it a name if you like, then import it.",
			})
			local importBox = makeTextBox(importCard, 2, "Paste the config here (Ctrl+V)")
			local importNameBox = makeTextBox(importCard, 3, "Name (optional)")
			local importButton = makePill(importCard, "Import config", 4, "Accent", "OnAccent")
			importButton.Size = UDim2.fromOffset(0, 28)
			importButton.Activated:Connect(function()
				local decodeOk, data = pcall(function() return HttpService:JSONDecode(importBox.Text) end)
				local config = decodeOk and type(data) == "table" and (type(data.config) == "table" and data.config or data) or nil
				if not config or (type(config.features) ~= "table" and type(config.esp) ~= "table") then
					notify("Configs", "That doesn't look like a config. Copy it again with the Copy button.")
					return
				end
				local name = cleanName(importNameBox.Text)
				if name == "" then name = cleanName(type(data.name) == "string" and data.name or "Imported") end
				if name == "" then name = "Imported" end
				-- Never replaces a config you have: picks a free name instead.
				local baseName, number = name, 2
				while findConfig(name) do
					name = cleanName(baseName .. " " .. number)
					number += 1
				end
				config.savedAt = os.time()
				store.configs[name] = config
				saveStore()
				importBox.Text = ""
				importNameBox.Text = ""
				notify("Configs", "Imported " .. name .. ". Press Load to use it.", 4)
				refreshList()
			end)

			showSwitch()
			refreshList()
			-- Keeps the "saved ... ago" notes current while the tab is open.
			task.spawn(function()
				while root.Parent do
					task.wait(30)
					if page.Visible then refreshList() end
				end
			end)
			return api
		end
		-- Kept separate so a problem here can't stop the rest of the menu loading.
		local configsOk, configsApi = pcall(buildConfigsPage)
		if not configsOk then
			warn("[SpreadCheeksGUI] The Configs page couldn't be built: " .. tostring(configsApi))
			configsApi = nil
		end

		window:CreateSection({ name = "ADMIN COMMANDS" })
		for _, category in ipairs(categories) do
			local categoryCommands = commandsByCategory[category.name]
			if #categoryCommands > 0 then
				local tab = withIcon(window, "CreateTab", { name = category.name }, category.icon)
				withIcon(tab, "CreateSection", { name = category.section }, category.icon)
				tab:CreateText({
					text = "Tap a command to run it. Use Command Bar when you need to add arguments.",
				})
				for _, command in ipairs(categoryCommands) do
					local commandName = command.NAME
					withIcon(tab, "CreateButton", {
						name = commandName,
						callback = function()
							execCmd(commandName, Players.LocalPlayer, true)
						end,
					}, menuIcons.forCommand(commandName, category.icon))
				end
			end
		end

		-- Runs one part of the menu's setup, so a problem in it can't stop the rest from loading.
		local function safeBuild(label, build)
			local built, problem = pcall(build)
			if not built then
				warn("[SpreadCheeksGUI] " .. label .. " couldn't be added: " .. tostring(problem))
			end
		end

		-- A small window of its own on screen, like the keybind list and Performance Stats: a header
		-- with an icon, title and room on the right for buttons, a body below, dragged by its header
		-- to anywhere, its spot remembered (as a share of the screen, in featureSettings[xKey/yKey]),
		-- fading in and out. The caller fills body and calls setShown.
		function menuModules.makeWindow(options)
			local playerGui = Players.LocalPlayer:FindFirstChildOfClass("PlayerGui") or Players.LocalPlayer:WaitForChild("PlayerGui")
			local previousGui = playerGui:FindFirstChild(options.name)
			if previousGui then previousGui:Destroy() end
			-- Kept in the shared environment so running the script again drops the old listeners.
			local sharedKey = options.name .. "Connections"
			if sharedEnv[sharedKey] then
				for _, connection in ipairs(sharedEnv[sharedKey]) do
					pcall(function() connection:Disconnect() end)
				end
			end
			local connections = {}
			sharedEnv[sharedKey] = connections

			local headerHeight = 36
			local size = Vector2.new(options.width, options.height)
			local gui = Instance.new("ScreenGui")
			gui.Name = options.name
			gui.ResetOnSpawn = false
			gui.IgnoreGuiInset = true
			-- Level with the keybind list: under the ; bar (1000) and the notifications (10001).
			gui.DisplayOrder = 999
			gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
			gui.Enabled = false
			gui.Parent = playerGui
			local panel = Instance.new("Frame")
			panel.Name = "Window"
			panel.Active = true
			panel.BackgroundTransparency = 0.04
			panel.BorderSizePixel = 0
			panel.ClipsDescendants = true
			panel.Size = UDim2.fromOffset(size.X, size.Y)
			bindAuxiliaryUiColor(panel, "BackgroundColor3", "Background")
			panel.Parent = gui
			local panelCorner = Instance.new("UICorner")
			panelCorner.CornerRadius = UDim.new(0, 12)
			panelCorner.Parent = panel
			local panelStroke = Instance.new("UIStroke")
			panelStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			panelStroke.Transparency = 0.3
			bindAuxiliaryUiColor(panelStroke, "Color", "Stroke")
			panelStroke.Parent = panel

			-- The header is the handle the window is dragged by.
			local handle = Instance.new("TextButton")
			handle.Name = "DragHandle"
			handle.Size = UDim2.new(1, 0, 0, headerHeight)
			handle.AutoButtonColor = false
			handle.BackgroundTransparency = 1
			handle.Text = ""
			handle.Parent = panel
			local icon = Instance.new("ImageLabel")
			icon.AnchorPoint = Vector2.new(0, 0.5)
			icon.Position = UDim2.new(0, 12, 0, headerHeight / 2)
			icon.Size = UDim2.fromOffset(15, 15)
			icon.BackgroundTransparency = 1
			local iconImage = menuIcons.get(table.unpack(options.icons or {}))
			if iconImage then menuIcons.apply(icon, iconImage) end
			icon.Visible = iconImage ~= nil
			bindAuxiliaryUiColor(icon, "ImageColor3", "AccentText")
			icon.Parent = panel
			local title = Instance.new("TextLabel")
			title.AnchorPoint = Vector2.new(0, 0.5)
			title.Position = UDim2.new(0, 35, 0, headerHeight / 2)
			title.Size = UDim2.new(0.5, -35, 0, 16)
			title.BackgroundTransparency = 1
			title.Font = Enum.Font.GothamBold
			title.Text = options.title
			title.TextSize = 13
			title.TextXAlignment = Enum.TextXAlignment.Left
			title.TextTruncate = Enum.TextTruncate.AtEnd
			bindAuxiliaryUiColor(title, "TextColor3", "Text")
			title.Parent = panel
			local headerRight = Instance.new("Frame")
			headerRight.AnchorPoint = Vector2.new(1, 0.5)
			headerRight.Position = UDim2.new(1, -8, 0, headerHeight / 2)
			headerRight.Size = UDim2.fromOffset(0, 24)
			headerRight.AutomaticSize = Enum.AutomaticSize.X
			headerRight.BackgroundTransparency = 1
			headerRight.ZIndex = 2
			headerRight.Parent = panel
			local headerRightLayout = Instance.new("UIListLayout")
			headerRightLayout.FillDirection = Enum.FillDirection.Horizontal
			headerRightLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
			headerRightLayout.VerticalAlignment = Enum.VerticalAlignment.Center
			headerRightLayout.Padding = UDim.new(0, 4)
			headerRightLayout.SortOrder = Enum.SortOrder.LayoutOrder
			headerRightLayout.Parent = headerRight
			local body = Instance.new("Frame")
			body.Name = "Body"
			body.Position = UDim2.fromOffset(0, headerHeight)
			body.Size = UDim2.new(1, 0, 1, -headerHeight)
			body.BackgroundTransparency = 1
			body.Parent = panel

			local shown, ready, wantShown = false, false, false
			local dragInput, dragFrom, panelFrom = nil, nil, nil
			local function screenSize()
				local camera = workspace.CurrentCamera
				return camera and camera.ViewportSize or gui.AbsoluteSize
			end
			local function clampToScreen(x, y)
				local screen = screenSize()
				x = math.clamp(x, 0, math.max(0, screen.X - size.X))
				y = math.clamp(y, 0, math.max(0, screen.Y - size.Y))
				return UDim2.fromOffset(math.floor(x + 0.5), math.floor(y + 0.5))
			end
			local function placePanel()
				local screen = screenSize()
				local savedX, savedY = featureSettings[options.xKey], featureSettings[options.yKey]
				if savedX >= 0 and savedY >= 0 then
					panel.Position = clampToScreen(savedX * screen.X, savedY * screen.Y)
				else
					local x, y = options.defaultPosition(screen, size)
					panel.Position = clampToScreen(x, y)
				end
			end
			handle.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
					dragInput = input
					dragFrom = Vector2.new(input.Position.X, input.Position.Y)
					panelFrom = Vector2.new(panel.Position.X.Offset, panel.Position.Y.Offset)
					panelStroke.Color = auxiliaryUiTheme.Accent
				end
			end)
			table.insert(connections, UserInputService.InputChanged:Connect(function(input)
				if dragInput and (input.UserInputType == Enum.UserInputType.MouseMovement or input == dragInput) then
					panel.Position = clampToScreen(panelFrom.X + input.Position.X - dragFrom.X, panelFrom.Y + input.Position.Y - dragFrom.Y)
				end
			end))
			table.insert(connections, UserInputService.InputEnded:Connect(function(input)
				if dragInput and (input == dragInput or input.UserInputType == Enum.UserInputType.MouseButton1) then
					dragInput = nil
					panelStroke.Color = auxiliaryUiTheme.Stroke
					local screen = screenSize()
					featureSettings[options.xKey] = panel.Position.X.Offset / math.max(screen.X, 1)
					featureSettings[options.yKey] = panel.Position.Y.Offset / math.max(screen.Y, 1)
					saveFeatureSettings()
				end
			end))

			-- Fading: each part goes fully see-through and back to the transparency it was made with,
			-- recorded the first time it's seen (always at rest).
			local resting = setmetatable({}, { __mode = "k" })
			local fadeProperties = {
				{ "GuiObject", "BackgroundTransparency" },
				{ "TextLabel", "TextTransparency" },
				{ "TextButton", "TextTransparency" },
				{ "TextBox", "TextTransparency" },
				{ "ImageLabel", "ImageTransparency" },
				{ "UIStroke", "Transparency" },
			}
			local function fadeParts()
				local parts = {}
				local function visit(object)
					local record = resting[object]
					if not record then
						record = {}
						for _, entry in ipairs(fadeProperties) do
							if object:IsA(entry[1]) then record[entry[2]] = object[entry[2]] end
						end
						resting[object] = record
					end
					for property, value in pairs(record) do
						if value < 1 then table.insert(parts, { object, property, value }) end
					end
				end
				visit(panel)
				for _, descendant in ipairs(panel:GetDescendants()) do visit(descendant) end
				return parts
			end
			local windowApi = { gui = gui, panel = panel, body = body, headerRight = headerRight, connections = connections }
			local fadeSerial = 0
			local function applyShown()
				local visible = wantShown and ready
				if visible == shown then return end
				fadeSerial += 1
				local serial = fadeSerial
				if visible then
					if windowApi.onShown then pcall(windowApi.onShown) end
					shown = true
					placePanel()
					local parts = fadeParts()
					for _, part in ipairs(parts) do part[1][part[2]] = 1 end
					gui.Enabled = true
					local info = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
					for _, part in ipairs(parts) do
						TweenService:Create(part[1], info, { [part[2]] = part[3] }):Play()
					end
				else
					shown = false
					dragInput = nil
					local info = TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
					for _, part in ipairs(fadeParts()) do
						TweenService:Create(part[1], info, { [part[2]] = 1 }):Play()
					end
					-- Switched off once faded, so the hidden window can't be clicked.
					task.delay(0.2, function()
						if fadeSerial == serial then gui.Enabled = false end
					end)
				end
			end
			function windowApi.setShown(on)
				wantShown = on == true
				applyShown()
			end
			function windowApi.isShown()
				return shown
			end
			-- For a window whose contents come and go (the Favourites bar): a new size, kept on screen.
			function windowApi.resize(width, height)
				size = Vector2.new(width, height)
				panel.Size = UDim2.fromOffset(width, height)
				if shown and not dragInput then placePanel() end
			end
			-- Stays on screen when the screen changes size.
			local lastScreen = nil
			table.insert(connections, RunService.Heartbeat:Connect(function()
				if not shown or dragInput then return end
				local screen = screenSize()
				if screen ~= lastScreen then
					lastScreen = screen
					placePanel()
				end
			end))
			-- Appears as the menu finishes opening, along with everything in it.
			task.spawn(function()
				local waited = 0
				while not windowOpenedAt and waited < 15 do
					waited += task.wait(0.1)
				end
				task.wait(math.max(0, (windowOpenedAt or os.clock()) + 1.45 - os.clock()))
				ready = true
				applyShown()
			end)
			return windowApi
		end

		-- Turns colours into RichText's #RRGGBB, and makes text safe to put inside RichText.
		function menuModules.hex(color)
			return string.format("#%02X%02X%02X", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
		end
		function menuModules.escape(text)
			return (tostring(text):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
		end

		------------------------------------------------------------------------------------------
		-- Logs: a window with three lists. Chat is everything said in the server since the script
		-- started, Joins is who came and went, and Alerts is the menu's recent notifications. Each
		-- list keeps its last 200 lines (Alerts its last 100) and can be searched.
		safeBuild("The Logs window", function()
			local logWindow = menuModules.makeWindow({
				name = "SpreadCheeksLogs", title = "Logs", icons = { "scroll-text", "message-square" },
				width = 340, height = 330, xKey = "logsWindowX", yKey = "logsWindowY",
				-- Bottom left, above Roblox's chat bar.
				defaultPosition = function(screen, size) return 16, screen.Y - size.Y - 110 end,
			})
			local body = logWindow.body
			local logs = { Chat = {}, Joins = {} }
			local currentTab, query = "Chat", ""

			-- Tabs in the header.
			local tabPills = {}
			for index, tabName in ipairs({ "Chat", "Joins", "Alerts" }) do
				local pill = Instance.new("TextButton")
				pill.LayoutOrder = index
				pill.AutomaticSize = Enum.AutomaticSize.X
				pill.Size = UDim2.fromOffset(0, 22)
				pill.AutoButtonColor = false
				pill.BorderSizePixel = 0
				pill.Font = Enum.Font.GothamMedium
				pill.Text = tabName
				pill.TextSize = 11
				pill.ZIndex = 3
				local pillCorner = Instance.new("UICorner")
				pillCorner.CornerRadius = UDim.new(0, 7)
				pillCorner.Parent = pill
				local pillPadding = Instance.new("UIPadding")
				pillPadding.PaddingLeft = UDim.new(0, 9)
				pillPadding.PaddingRight = UDim.new(0, 9)
				pillPadding.Parent = pill
				pill.Parent = logWindow.headerRight
				tabPills[tabName] = pill
			end

			-- Search, Clear, and the list.
			local search = Instance.new("TextBox")
			search.Position = UDim2.fromOffset(10, 2)
			search.Size = UDim2.new(1, -78, 0, 28)
			search.BorderSizePixel = 0
			search.ClearTextOnFocus = false
			search.Font = Enum.Font.Gotham
			search.PlaceholderText = "Search"
			search.Text = ""
			search.TextSize = 12
			search.TextXAlignment = Enum.TextXAlignment.Left
			bindAuxiliaryUiColor(search, "BackgroundColor3", "Inset")
			bindAuxiliaryUiColor(search, "TextColor3", "Text")
			bindAuxiliaryUiColor(search, "PlaceholderColor3", "Muted")
			local searchCorner = Instance.new("UICorner")
			searchCorner.CornerRadius = UDim.new(0, 8)
			searchCorner.Parent = search
			local searchPadding = Instance.new("UIPadding")
			searchPadding.PaddingLeft = UDim.new(0, 10)
			searchPadding.PaddingRight = UDim.new(0, 10)
			searchPadding.Parent = search
			search.Parent = body
			local clear = Instance.new("TextButton")
			clear.AnchorPoint = Vector2.new(1, 0)
			clear.Position = UDim2.new(1, -10, 0, 2)
			clear.Size = UDim2.fromOffset(60, 28)
			clear.AutoButtonColor = false
			clear.BorderSizePixel = 0
			clear.Font = Enum.Font.GothamMedium
			clear.Text = "Clear"
			clear.TextSize = 12
			bindAuxiliaryUiColor(clear, "BackgroundColor3", "Inset")
			bindAuxiliaryUiColor(clear, "TextColor3", "SubText")
			local clearCorner = Instance.new("UICorner")
			clearCorner.CornerRadius = UDim.new(0, 8)
			clearCorner.Parent = clear
			clear.Parent = body
			local list = Instance.new("ScrollingFrame")
			list.Position = UDim2.fromOffset(6, 38)
			list.Size = UDim2.new(1, -12, 1, -44)
			list.BackgroundTransparency = 1
			list.BorderSizePixel = 0
			list.ScrollBarThickness = 3
			list.ScrollingDirection = Enum.ScrollingDirection.Y
			list.AutomaticCanvasSize = Enum.AutomaticSize.Y
			list.CanvasSize = UDim2.new()
			bindAuxiliaryUiColor(list, "ScrollBarImageColor3", "Muted")
			list.Parent = body
			local listLayout = Instance.new("UIListLayout")
			listLayout.Padding = UDim.new(0, 3)
			listLayout.SortOrder = Enum.SortOrder.LayoutOrder
			listLayout.Parent = list
			local listPadding = Instance.new("UIPadding")
			listPadding.PaddingLeft = UDim.new(0, 4)
			listPadding.PaddingRight = UDim.new(0, 8)
			listPadding.Parent = list
			local emptyLabel = Instance.new("TextLabel")
			emptyLabel.AnchorPoint = Vector2.new(0.5, 0.5)
			emptyLabel.Position = UDim2.new(0.5, 0, 0.5, 18)
			emptyLabel.Size = UDim2.new(1, -40, 0, 32)
			emptyLabel.BackgroundTransparency = 1
			emptyLabel.Font = Enum.Font.Gotham
			emptyLabel.TextSize = 12
			emptyLabel.TextWrapped = true
			bindAuxiliaryUiColor(emptyLabel, "TextColor3", "Muted")
			emptyLabel.Parent = body

			local function entriesFor(tabName)
				return tabName == "Alerts" and menuModules.notificationLog or logs[tabName]
			end
			-- One line, as RichText: the time, who (or what), and the text.
			local function lineText(tabName, entry)
				local theme = auxiliaryUiTheme
				local hex, escape = menuModules.hex, menuModules.escape
				local clock = os.date("*t", entry.at)
				local time = '<font color="' .. hex(theme.Muted) .. '">' .. string.format("%02d:%02d", clock.hour, clock.min) .. "</font>  "
				-- With Streamer Mode on, people go by their "Player 3" names and usernames are left out.
				local name = entry.player and featureSettings.streamerMode and menuModules.nameOf(entry.player) or entry.name
				if tabName == "Chat" then
					return time .. '<b><font color="' .. hex(theme.AccentText) .. '">' .. escape(name) .. "</font></b>  " .. escape(entry.text)
				elseif tabName == "Joins" then
					local verb = entry.joined and ('<font color="' .. hex(theme.Good) .. '">joined</font>') or ('<font color="' .. hex(theme.Bad) .. '">left</font>')
					local user = featureSettings.streamerMode and "" or ('  <font color="' .. hex(theme.Muted) .. '">@' .. escape(entry.user) .. "</font>")
					return time .. "<b>" .. escape(name) .. "</b> " .. verb .. user
				end
				return time .. "<b>" .. escape(entry.title) .. "</b>  " .. escape(entry.message)
			end
			local function matches(tabName, entry)
				if query == "" then return true end
				local haystack = tabName == "Alerts" and (entry.title .. " " .. entry.message) or (entry.name .. " " .. (entry.user or "") .. " " .. (entry.text or ""))
				return haystack:lower():find(query, 1, true) ~= nil
			end
			local lineCount = 0
			local function addLine(tabName, entry)
				lineCount += 1
				local line = Instance.new("TextLabel")
				line.LayoutOrder = lineCount
				line.Size = UDim2.fromScale(1, 0)
				line.AutomaticSize = Enum.AutomaticSize.Y
				line.BackgroundTransparency = 1
				line.Font = Enum.Font.Gotham
				line.RichText = true
				line.Text = lineText(tabName, entry)
				line.TextSize = 12
				line.TextWrapped = true
				line.TextXAlignment = Enum.TextXAlignment.Left
				bindAuxiliaryUiColor(line, "TextColor3", "Text")
				line.Parent = list
				return line
			end
			local function scrollToEnd()
				task.defer(function()
					list.CanvasPosition = Vector2.new(0, math.max(0, list.AbsoluteCanvasSize.Y - list.AbsoluteWindowSize.Y))
				end)
			end
			local function pruneDeadThemeBindings()
				for index = #auxiliaryUiColorBindings, 1, -1 do
					if not auxiliaryUiColorBindings[index][1].Parent then
						table.remove(auxiliaryUiColorBindings, index)
					end
				end
			end
			local function render()
				for _, child in ipairs(list:GetChildren()) do
					if child:IsA("TextLabel") then child:Destroy() end
				end
				pruneDeadThemeBindings()
				local shownCount = 0
				for _, entry in ipairs(entriesFor(currentTab)) do
					if matches(currentTab, entry) then
						addLine(currentTab, entry)
						shownCount += 1
					end
				end
				local emptyText = { Chat = "No chat yet.", Joins = "No one has joined or left yet.", Alerts = "No notifications yet." }
				emptyLabel.Text = query ~= "" and "Nothing matches your search." or emptyText[currentTab]
				emptyLabel.Visible = shownCount == 0
				scrollToEnd()
			end
			local function paintTabs()
				local theme = auxiliaryUiTheme
				for tabName, pill in pairs(tabPills) do
					local selected = tabName == currentTab
					pill.BackgroundColor3 = selected and theme.Accent or theme.Inset
					pill.TextColor3 = selected and theme.OnAccent or theme.SubText
				end
			end
			for tabName, pill in pairs(tabPills) do
				pill.Activated:Connect(function()
					currentTab = tabName
					paintTabs()
					render()
				end)
			end
			search:GetPropertyChangedSignal("Text"):Connect(function()
				query = search.Text:lower()
				render()
			end)
			clear.Activated:Connect(function()
				table.clear(entriesFor(currentTab))
				render()
			end)
			-- Colours are written into each line, so lines are redrawn after a theme change.
			table.insert(auxiliaryUiThemeListeners, function()
				paintTabs()
				if logWindow.isShown() then render() end
			end)
			table.insert(menuModules.nameListeners, function()
				if logWindow.isShown() then render() end
			end)
			logWindow.onShown = render

			-- A new line for one of the lists: added to the end when that list is showing, and the
			-- oldest dropped once there are more than 200.
			local function push(tabName, entry)
				local entries = logs[tabName]
				table.insert(entries, entry)
				if #entries > 200 then table.remove(entries, 1) end
				if not logWindow.isShown() or currentTab ~= tabName or not matches(tabName, entry) then return end
				local nearEnd = list.CanvasPosition.Y >= list.AbsoluteCanvasSize.Y - list.AbsoluteWindowSize.Y - 40
				addLine(tabName, entry)
				emptyLabel.Visible = false
				local lines = {}
				for _, child in ipairs(list:GetChildren()) do
					if child:IsA("TextLabel") then table.insert(lines, child) end
				end
				if #lines > 200 then
					table.sort(lines, function(left, right) return left.LayoutOrder < right.LayoutOrder end)
					lines[1]:Destroy()
				end
				-- Follows new lines, unless you've scrolled up to read something.
				if nearEnd then scrollToEnd() end
			end
			menuModules.onNotification = function()
				if logWindow.isShown() and currentTab == "Alerts" then render() end
			end

			-- Chat, from Roblox's newer chat or the legacy one, whichever the game uses.
			local function addChat(player, text)
				if not player or type(text) ~= "string" or text == "" then return end
				push("Chat", { at = os.time(), name = player.DisplayName, user = player.Name, player = player, text = text })
			end
			if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
				table.insert(logWindow.connections, TextChatService.MessageReceived:Connect(function(message)
					local source = message.TextSource
					if source then
						addChat(Players:GetPlayerByUserId(source.UserId), message.Text)
					end
				end))
			else
				local function listenTo(player)
					table.insert(logWindow.connections, player.Chatted:Connect(function(text)
						addChat(player, text)
					end))
				end
				for _, player in ipairs(Players:GetPlayers()) do listenTo(player) end
				table.insert(logWindow.connections, Players.PlayerAdded:Connect(listenTo))
			end
			table.insert(logWindow.connections, Players.PlayerAdded:Connect(function(player)
				push("Joins", { at = os.time(), name = player.DisplayName, user = player.Name, player = player, joined = true })
			end))
			table.insert(logWindow.connections, Players.PlayerRemoving:Connect(function(player)
				push("Joins", { at = os.time(), name = player.DisplayName, user = player.Name, player = player, joined = false })
			end))

			paintTabs()
			menuModules.logs = { setShown = logWindow.setShown }
			if featureSettings.logsWindow and quickToggleByName["Logs"] then
				setQuickToggle(quickToggleByName["Logs"], true)
			end
		end)

		------------------------------------------------------------------------------------------
		-- Favourites bar: the switches and moves you've starred, as tiles on screen. A switch's tile
		-- lights up while it's on and flips it when clicked; a move's tile does the move. Right-click
		-- a tile to take it off. Switches get starred on their rows; moves are added in the bar
		-- switch's settings card, which also puts the tiles in order.
		safeBuild("The Favourites bar", function()
			local tileWidth, tileHeight, gap, edge, perRow = 72, 58, 6, 8, 6
			local barWindow = menuModules.makeWindow({
				name = "SpreadCheeksFavourites", title = "Favourites", icons = { "star", "bookmark" },
				width = 250, height = 86, xKey = "favouritesBarX", yKey = "favouritesBarY",
				-- Top middle, under Roblox's buttons.
				defaultPosition = function(screen, size) return (screen.X - size.X) / 2, 64 end,
			})
			local tiles = Instance.new("Frame")
			tiles.Name = "Tiles"
			tiles.Position = UDim2.fromOffset(edge, 0)
			tiles.Size = UDim2.new(1, -edge * 2, 1, -edge)
			tiles.BackgroundTransparency = 1
			tiles.Parent = barWindow.body
			local tilesLayout = Instance.new("UIGridLayout")
			tilesLayout.CellSize = UDim2.fromOffset(tileWidth, tileHeight)
			tilesLayout.CellPadding = UDim2.fromOffset(gap, gap)
			tilesLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
			tilesLayout.SortOrder = Enum.SortOrder.LayoutOrder
			tilesLayout.Parent = tiles
			local emptyLabel = Instance.new("TextLabel")
			emptyLabel.Position = UDim2.fromOffset(14, 0)
			emptyLabel.Size = UDim2.new(1, -28, 1, -edge)
			emptyLabel.BackgroundTransparency = 1
			emptyLabel.Font = Enum.Font.Gotham
			emptyLabel.Text = "Nothing here yet. Hover over a switch in the menu and click its star."
			emptyLabel.TextSize = 12
			emptyLabel.TextWrapped = true
			bindAuxiliaryUiColor(emptyLabel, "TextColor3", "Muted")
			emptyLabel.Parent = barWindow.body

			-- What a favourite stands for: a switch, or a move to do.
			local movesByName = {}
			for _, move in ipairs(trolling.moves or {}) do movesByName[move.name] = move end
			local function resolve(key)
				local kind, name = tostring(key):match("^(%a+):(.+)$")
				local entry = kind == "switch" and quickToggleByName[name]
				if entry then return { name = name, icons = entry.icons, entry = entry } end
				local move = kind == "move" and movesByName[name]
				if move then return { name = name, icons = move.icons, run = move.run } end
				return nil
			end

			-- Tile colours depend on the switch being on, so they're painted here rather than bound.
			local shownTiles = {}
			local function paintTile(tile)
				local theme = auxiliaryUiTheme
				tile.on = tile.entry ~= nil and tile.entry.state
				local lit = tile.on or tile.flash
				tile.button.BackgroundColor3 = lit and theme.Accent or theme.Inset
				tile.stroke.Color = tile.hovered and theme.Accent or theme.Stroke
				tile.icon.ImageColor3 = lit and theme.OnAccent or (tile.entry and theme.SubText or theme.AccentText)
				tile.label.TextColor3 = lit and theme.OnAccent or theme.Text
			end
			local function render()
				for _, child in ipairs(tiles:GetChildren()) do
					if child:IsA("GuiObject") then child:Destroy() end
				end
				table.clear(shownTiles)
				for _, key in ipairs(featureSettings.favourites) do
					local favourite = resolve(key)
					if favourite then
						local tile = { entry = favourite.entry, run = favourite.run }
						local button = Instance.new("TextButton")
						button.LayoutOrder = #shownTiles + 1
						button.AutoButtonColor = false
						button.BorderSizePixel = 0
						button.Text = ""
						button.Parent = tiles
						local corner = Instance.new("UICorner")
						corner.CornerRadius = UDim.new(0, 9)
						corner.Parent = button
						local stroke = Instance.new("UIStroke")
						stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
						stroke.Transparency = 0.4
						stroke.Parent = button
						local icon = Instance.new("ImageLabel")
						icon.AnchorPoint = Vector2.new(0.5, 0)
						icon.Position = UDim2.new(0.5, 0, 0, 9)
						icon.Size = UDim2.fromOffset(18, 18)
						icon.BackgroundTransparency = 1
						local iconImage = menuIcons.get(table.unpack(favourite.icons or {})) or menuIcons.get("star")
						if iconImage then menuIcons.apply(icon, iconImage) end
						icon.Parent = button
						local label = Instance.new("TextLabel")
						label.Position = UDim2.fromOffset(4, 31)
						label.Size = UDim2.new(1, -8, 0, 22)
						label.BackgroundTransparency = 1
						label.Font = Enum.Font.GothamMedium
						label.Text = favourite.name
						label.TextSize = 10
						label.TextWrapped = true
						label.TextTruncate = Enum.TextTruncate.AtEnd
						label.TextYAlignment = Enum.TextYAlignment.Top
						label.Parent = button
						tile.button, tile.stroke, tile.icon, tile.label = button, stroke, icon, label
						button.MouseEnter:Connect(function()
							tile.hovered = true
							paintTile(tile)
						end)
						button.MouseLeave:Connect(function()
							tile.hovered = false
							paintTile(tile)
						end)
						button.Activated:Connect(function()
							if tile.entry then
								setQuickToggle(tile.entry, not tile.entry.state)
							else
								-- A quick flash, so you can tell it went.
								tile.flash = true
								task.delay(0.18, function()
									tile.flash = false
									if button.Parent then paintTile(tile) end
								end)
								local ran, problem = pcall(tile.run)
								if not ran then warn("[SpreadCheeksGUI] " .. favourite.name .. " didn't work: " .. tostring(problem)) end
							end
							paintTile(tile)
						end)
						button.MouseButton2Click:Connect(function()
							favourites.set(key, false)
							notify("Favourites", favourite.name .. " is off your Favourites bar", 2)
						end)
						paintTile(tile)
						table.insert(shownTiles, tile)
					end
				end
				-- Up to six tiles a line, and the window sized to fit them.
				local count = #shownTiles
				emptyLabel.Visible = count == 0
				local columns = math.clamp(count, 1, perRow)
				local rows = math.max(1, math.ceil(count / perRow))
				local width = count == 0 and 250 or math.max(150, edge * 2 + columns * tileWidth + (columns - 1) * gap)
				local height = 36 + (count == 0 and 50 or rows * tileHeight + (rows - 1) * gap + edge)
				barWindow.resize(width, height)
			end
			table.insert(favourites.listeners, render)
			table.insert(auxiliaryUiThemeListeners, function()
				for _, tile in ipairs(shownTiles) do paintTile(tile) end
			end)
			-- Switches also change from keys, commands and the menu, so the tiles keep checking.
			task.spawn(function()
				while barWindow.gui.Parent do
					task.wait(0.2)
					if barWindow.isShown() then
						for _, tile in ipairs(shownTiles) do
							if tile.entry and tile.on ~= tile.entry.state then paintTile(tile) end
						end
					end
				end
			end)
			render()

			-- Settings: moves to add, and the order of the tiles.
			local barEntry = quickToggleByName["Favourites Bar"]
			local card = barEntry and createSettingsCard(barEntry)
			if card then
				card.addSectionLabel("MOVES", "zap", "sparkles")
				local moveOptions = {}
				for _, move in ipairs(trolling.moves or {}) do
					table.insert(moveOptions, {
						text = move.name,
						get = function() return favourites.has("move:" .. move.name) end,
						set = function(on) favourites.set("move:" .. move.name, on) end,
					})
				end
				card.addSwitchGrid(moveOptions, 2)
				card.addSectionLabel("ON THE BAR", "star", "bookmark")
				card.addHint("Top to bottom here is left to right on the bar. To add a switch, hover over it in the menu and click its star; right-click a tile on the bar to take it off.")
				local list = Instance.new("Frame")
				list.LayoutOrder = card.nextOrder()
				list.Size = UDim2.fromScale(1, 0)
				list.AutomaticSize = Enum.AutomaticSize.Y
				list.BackgroundTransparency = 1
				list.Parent = card.content
				local listLayout = Instance.new("UIListLayout")
				listLayout.Padding = UDim.new(0, 4)
				listLayout.SortOrder = Enum.SortOrder.LayoutOrder
				listLayout.Parent = list
				-- A small button at the right of a row, showing an icon (or text, without one).
				local function rowButton(row, rightInset, width, iconName, text)
					local button = Instance.new("TextButton")
					button.AnchorPoint = Vector2.new(1, 0.5)
					button.Position = UDim2.new(1, -rightInset, 0.5, 0)
					button.Size = UDim2.fromOffset(width, 22)
					button.AutoButtonColor = false
					button.BorderSizePixel = 0
					button.Font = Enum.Font.GothamMedium
					button.TextSize = 11
					button.BackgroundColor3 = auxiliaryUiTheme.Card
					button.TextColor3 = auxiliaryUiTheme.SubText
					local buttonCorner = Instance.new("UICorner")
					buttonCorner.CornerRadius = UDim.new(0, 6)
					buttonCorner.Parent = button
					local iconImage = iconName and menuIcons.get(iconName)
					button.Text = iconImage and "" or text
					if iconImage then
						local arrow = Instance.new("ImageLabel")
						arrow.AnchorPoint = Vector2.new(0.5, 0.5)
						arrow.Position = UDim2.fromScale(0.5, 0.5)
						arrow.Size = UDim2.fromOffset(14, 14)
						arrow.BackgroundTransparency = 1
						arrow.ImageColor3 = auxiliaryUiTheme.SubText
						menuIcons.apply(arrow, iconImage)
						arrow.Parent = button
					end
					button.Parent = row
					return button
				end
				local function showList()
					for _, child in ipairs(list:GetChildren()) do
						if child:IsA("GuiObject") then child:Destroy() end
					end
					local theme = auxiliaryUiTheme
					local keys = featureSettings.favourites
					if #keys == 0 then
						local none = Instance.new("TextLabel")
						none.Size = UDim2.new(1, 0, 0, 18)
						none.BackgroundTransparency = 1
						none.Font = Enum.Font.Gotham
						none.Text = "Nothing on the bar yet."
						none.TextSize = 11
						none.TextXAlignment = Enum.TextXAlignment.Left
						none.TextColor3 = theme.Muted
						none.Parent = list
						return
					end
					for index, key in ipairs(keys) do
						local favourite = resolve(key)
						local row = Instance.new("Frame")
						row.LayoutOrder = index
						row.Size = UDim2.new(1, 0, 0, 28)
						row.BorderSizePixel = 0
						row.BackgroundColor3 = theme.Inset
						local rowCorner = Instance.new("UICorner")
						rowCorner.CornerRadius = UDim.new(0, 7)
						rowCorner.Parent = row
						row.Parent = list
						local label = Instance.new("TextLabel")
						label.Position = UDim2.fromOffset(10, 0)
						label.Size = UDim2.new(1, -144, 1, 0)
						label.BackgroundTransparency = 1
						label.Font = Enum.Font.GothamMedium
						label.RichText = true
						-- A favourite this version doesn't have (a renamed switch) stays listed, so it can be removed.
						local name = favourite and favourite.name or (tostring(key):gsub("^%a+:", ""))
						local kind = favourite and (favourite.entry and "switch" or "move") or "not found"
						label.Text = menuModules.escape(name) .. '  <font color="' .. menuModules.hex(theme.Muted) .. '">' .. kind .. "</font>"
						label.TextSize = 12
						label.TextXAlignment = Enum.TextXAlignment.Left
						label.TextTruncate = Enum.TextTruncate.AtEnd
						label.TextColor3 = theme.Text
						label.Parent = row
						local up = rowButton(row, 106, 24, "chevron-up", "^")
						up.Visible = index > 1
						up.Activated:Connect(function() favourites.shift(key, -1) end)
						local down = rowButton(row, 78, 24, "chevron-down", "v")
						down.Visible = index < #keys
						down.Activated:Connect(function() favourites.shift(key, 1) end)
						local remove = rowButton(row, 4, 70, nil, "Remove")
						remove.Activated:Connect(function() favourites.set(key, false) end)
					end
				end
				-- Colours here depend on the list, so the list is redrawn with the card.
				table.insert(card.refreshers, showList)
				table.insert(favourites.listeners, card.refresh)
				card.refresh()
			end

			menuModules.favouritesBar = { setShown = barWindow.setShown }
			if featureSettings.favouritesBar and barEntry then
				setQuickToggle(barEntry, true)
			end
		end)

		------------------------------------------------------------------------------------------
		-- Radar: a round minimap of players around you. You're in the middle and the top is the way
		-- the camera faces; players further than its range sit on the edge, faded. Right-click its
		-- switch for the range and names.
		safeBuild("The radar", function()
			local radarWindow = menuModules.makeWindow({
				name = "SpreadCheeksRadar", title = "Radar", icons = { "radar", "map" },
				width = 204, height = 240, xKey = "radarX", yKey = "radarY",
				-- Bottom right, clear of the keybind list and Performance Stats.
				defaultPosition = function(screen, size) return screen.X - size.X - 16, screen.Y - size.Y - 110 end,
			})
			local body = radarWindow.body
			local rangeLabel = Instance.new("TextLabel")
			rangeLabel.AutomaticSize = Enum.AutomaticSize.X
			rangeLabel.Size = UDim2.fromOffset(0, 20)
			rangeLabel.BackgroundTransparency = 1
			rangeLabel.Font = Enum.Font.GothamMedium
			rangeLabel.TextSize = 11
			bindAuxiliaryUiColor(rangeLabel, "TextColor3", "SubText")
			rangeLabel.Parent = radarWindow.headerRight

			local mapSize = 188
			local map = Instance.new("Frame")
			map.AnchorPoint = Vector2.new(0.5, 0)
			map.Position = UDim2.new(0.5, 0, 0, 2)
			map.Size = UDim2.fromOffset(mapSize, mapSize)
			map.BorderSizePixel = 0
			bindAuxiliaryUiColor(map, "BackgroundColor3", "Inset")
			map.Parent = body
			local mapCorner = Instance.new("UICorner")
			mapCorner.CornerRadius = UDim.new(1, 0)
			mapCorner.Parent = map
			local mapStroke = Instance.new("UIStroke")
			mapStroke.Transparency = 0.4
			bindAuxiliaryUiColor(mapStroke, "Color", "Stroke")
			mapStroke.Parent = map
			-- A ring at half the range, and lines through the middle.
			local ring = Instance.new("Frame")
			ring.AnchorPoint = Vector2.new(0.5, 0.5)
			ring.Position = UDim2.fromScale(0.5, 0.5)
			ring.Size = UDim2.fromOffset(mapSize / 2, mapSize / 2)
			ring.BackgroundTransparency = 1
			ring.Parent = map
			local ringCorner = Instance.new("UICorner")
			ringCorner.CornerRadius = UDim.new(1, 0)
			ringCorner.Parent = ring
			local ringStroke = Instance.new("UIStroke")
			ringStroke.Transparency = 0.55
			bindAuxiliaryUiColor(ringStroke, "Color", "Stroke")
			ringStroke.Parent = ring
			for _, vertical in ipairs({ true, false }) do
				local line = Instance.new("Frame")
				line.AnchorPoint = Vector2.new(0.5, 0.5)
				line.Position = UDim2.fromScale(0.5, 0.5)
				line.Size = vertical and UDim2.new(0, 1, 1, -12) or UDim2.new(1, -12, 0, 1)
				line.BackgroundTransparency = 0.6
				line.BorderSizePixel = 0
				bindAuxiliaryUiColor(line, "BackgroundColor3", "Stroke")
				line.Parent = map
			end
			-- You: an arrow pointing the way the camera faces.
			local you = Instance.new("ImageLabel")
			you.AnchorPoint = Vector2.new(0.5, 0.5)
			you.Position = UDim2.fromScale(0.5, 0.5)
			you.Size = UDim2.fromOffset(14, 14)
			you.BackgroundTransparency = 1
			-- Rayfield's dropdown arrow, which points up.
			you.Image = "rbxassetid://88479147175134"
			you.ZIndex = 3
			bindAuxiliaryUiColor(you, "ImageColor3", "AccentText")
			you.Parent = map

			-- A dot (and name) for each other player, reused while they're in the server.
			local markers = {}
			local function markerFor(player)
				local marker = markers[player]
				if marker then return marker end
				local dot = Instance.new("Frame")
				dot.AnchorPoint = Vector2.new(0.5, 0.5)
				dot.Size = UDim2.fromOffset(8, 8)
				dot.BorderSizePixel = 0
				dot.ZIndex = 2
				dot.Parent = map
				local dotCorner = Instance.new("UICorner")
				dotCorner.CornerRadius = UDim.new(1, 0)
				dotCorner.Parent = dot
				local dotStroke = Instance.new("UIStroke")
				dotStroke.Color = Color3.new(0, 0, 0)
				dotStroke.Transparency = 0.5
				dotStroke.Parent = dot
				local name = Instance.new("TextLabel")
				name.AnchorPoint = Vector2.new(0.5, 0)
				name.Position = UDim2.new(0.5, 0, 1, 1)
				name.Size = UDim2.fromOffset(80, 11)
				name.BackgroundTransparency = 1
				name.Font = Enum.Font.GothamMedium
				name.Text = menuModules.nameOf(player)
				name.TextSize = 9
				name.TextStrokeTransparency = 0.5
				name.TextTruncate = Enum.TextTruncate.AtEnd
				name.ZIndex = 2
				bindAuxiliaryUiColor(name, "TextColor3", "Text")
				name.Parent = dot
				marker = { dot = dot, name = name }
				markers[player] = marker
				return marker
			end
			table.insert(menuModules.nameListeners, function()
				for player, marker in pairs(markers) do
					marker.name.Text = menuModules.nameOf(player)
				end
			end)
			table.insert(radarWindow.connections, Players.PlayerRemoving:Connect(function(player)
				if markers[player] then
					markers[player].dot:Destroy()
					markers[player] = nil
				end
			end))

			local sinceUpdate = 0
			table.insert(radarWindow.connections, RunService.RenderStepped:Connect(function(deltaTime)
				if not radarWindow.isShown() then return end
				-- About 30 times a second is plenty for a map.
				sinceUpdate += deltaTime
				if sinceUpdate < 1 / 30 then return end
				sinceUpdate = 0
				local range = featureSettings.radarRange
				rangeLabel.Text = range .. " studs"
				local camera = workspace.CurrentCamera
				local myCharacter = Players.LocalPlayer.Character
				local myRoot = myCharacter and getRoot(myCharacter)
				-- Up on the map is the way the camera faces, flattened onto the ground.
				local look = camera and camera.CFrame.LookVector or Vector3.new(0, 0, -1)
				local flat = Vector2.new(look.X, look.Z)
				flat = flat.Magnitude > 1e-3 and flat.Unit or Vector2.new(0, -1)
				local radius = mapSize / 2 - 7
				local scale = radius / range
				for _, player in ipairs(Players:GetPlayers()) do
					if player ~= Players.LocalPlayer then
						local character = player.Character
						local root = character and getRoot(character)
						local marker = markerFor(player)
						if not root or not myRoot then
							marker.dot.Visible = false
						else
							local offset = root.Position - myRoot.Position
							local along = offset.X * flat.X + offset.Z * flat.Y
							local across = offset.X * -flat.Y + offset.Z * flat.X
							local x, y = across * scale, -along * scale
							local distance = math.sqrt(x * x + y * y)
							local outside = distance > radius
							if outside then
								x, y = x / distance * radius, y / distance * radius
							end
							marker.dot.Visible = true
							marker.dot.Position = UDim2.new(0.5, x, 0.5, y)
							-- Team colours when there are teams, otherwise the menu's accent.
							local useTeam = not player.Neutral and not Players.LocalPlayer.Neutral
							marker.dot.BackgroundColor3 = useTeam and player.TeamColor.Color or auxiliaryUiTheme.AccentText
							marker.dot.BackgroundTransparency = outside and 0.55 or 0
							marker.name.Visible = featureSettings.radarNames and not outside
						end
					end
				end
			end))

			-- Settings, opened by right-clicking the switch.
			local entry = quickToggleByName["Radar"]
			local card = entry and createSettingsCard(entry)
			if card then
				card.addSectionLabel("MAP", "map", "radar")
				card.addSlider({
					text = "Range",
					icon = { "ruler", "move" },
					min = 50, max = 500, step = 10,
					get = function() return featureSettings.radarRange end,
					set = function(value) featureSettings.radarRange = value end,
					commit = saveFeatureSettings,
					format = function(value) return math.floor(value + 0.5) .. " studs" end,
				})
				card.addSwitchGrid({
					{
						text = "Show names",
						get = function() return featureSettings.radarNames == true end,
						set = function(on)
							featureSettings.radarNames = on
							saveFeatureSettings()
						end,
					},
				}, 1)
				card.addHint("Up on the map is the way your camera faces. Players further than the range sit on the edge, faded.")
				card.refresh()
			end

			menuModules.radar = { setShown = radarWindow.setShown }
			if featureSettings.radar and quickToggleByName["Radar"] then
				setQuickToggle(quickToggleByName["Radar"], true)
			end
		end)

		------------------------------------------------------------------------------------------
		-- Join Alerts: a notification when a friend, someone on your watch list, or (if you want)
		-- anyone joins or leaves. Right-click its switch to choose who, and to edit the watch list.
		safeBuild("Join Alerts", function()
			local localPlayer = Players.LocalPlayer
			-- Whether someone is your friend takes a web request, so the answer is remembered.
			local friendCache = {}
			local function isFriend(player)
				if friendCache[player.UserId] == nil then
					local checked, friends = pcall(function() return localPlayer:IsFriendsWith(player.UserId) end)
					friendCache[player.UserId] = checked and friends == true
				end
				return friendCache[player.UserId]
			end
			local function watchList()
				return type(featureSettings.watchList) == "table" and featureSettings.watchList or {}
			end
			local function isWatched(player)
				for _, name in ipairs(watchList()) do
					local lowered = tostring(name):lower()
					if lowered == player.Name:lower() or lowered == player.DisplayName:lower() then return true end
				end
				return false
			end
			local function enabled()
				local entry = quickToggleByName["Join Alerts"]
				return entry ~= nil and entry.state
			end
			-- Why to say something about this player, or nil to stay quiet.
			local function reasonFor(player)
				if player == localPlayer then return nil end
				if isWatched(player) then return "Watched player" end
				if featureSettings.joinAlertFriends and isFriend(player) then return "Friend" end
				if featureSettings.joinAlertEveryone then return "Player" end
				return nil
			end
			local function describe(player)
				return menuModules.labelOf(player)
			end
			local connections = {}
			if sharedEnv.SpreadCheeksJoinAlerts then
				for _, connection in ipairs(sharedEnv.SpreadCheeksJoinAlerts) do
					pcall(function() connection:Disconnect() end)
				end
			end
			sharedEnv.SpreadCheeksJoinAlerts = connections
			table.insert(connections, Players.PlayerAdded:Connect(function(player)
				if not enabled() then return end
				local reason = reasonFor(player)
				if reason then notify(reason .. " joined", describe(player) .. " joined the server", 5) end
			end))
			table.insert(connections, Players.PlayerRemoving:Connect(function(player)
				if not enabled() then return end
				local reason = reasonFor(player)
				if reason then notify(reason .. " left", describe(player) .. " left the server", 5) end
			end))

			-- When it's switched on: who of note is already here.
			local function announceHere()
				task.spawn(function()
					local here = {}
					for _, player in ipairs(Players:GetPlayers()) do
						if player ~= localPlayer and (isWatched(player) or (featureSettings.joinAlertFriends and isFriend(player))) then
							table.insert(here, describe(player))
						end
					end
					if #here > 0 then
						notify("Join Alerts", "Already here: " .. table.concat(here, ", "), 6)
					end
				end)
			end

			-- Settings: who to alert about, and the watch list.
			local entry = quickToggleByName["Join Alerts"]
			local card = entry and createSettingsCard(entry)
			if card then
				card.addSectionLabel("ALERT ME ABOUT", "bell")
				card.addSwitchGrid({
					{
						text = "Friends",
						get = function() return featureSettings.joinAlertFriends == true end,
						set = function(on)
							featureSettings.joinAlertFriends = on
							saveFeatureSettings()
						end,
					},
					{
						text = "Everyone",
						get = function() return featureSettings.joinAlertEveryone == true end,
						set = function(on)
							featureSettings.joinAlertEveryone = on
							saveFeatureSettings()
						end,
					},
				})
				card.addSectionLabel("WATCH LIST", "eye")
				card.addHint("Usernames or display names to always tell you about, friend or not.")
				-- Add a name: a box and a button on one line.
				local addRow = Instance.new("Frame")
				addRow.LayoutOrder = card.nextOrder()
				addRow.Size = UDim2.new(1, 0, 0, 30)
				addRow.BackgroundTransparency = 1
				addRow.Parent = card.content
				local nameBox = Instance.new("TextBox")
				nameBox.Size = UDim2.new(1, -78, 1, 0)
				nameBox.BorderSizePixel = 0
				nameBox.ClearTextOnFocus = false
				nameBox.Font = Enum.Font.Gotham
				nameBox.PlaceholderText = "Username"
				nameBox.Text = ""
				nameBox.TextSize = 12
				nameBox.TextXAlignment = Enum.TextXAlignment.Left
				bindAuxiliaryUiColor(nameBox, "BackgroundColor3", "Inset")
				bindAuxiliaryUiColor(nameBox, "TextColor3", "Text")
				bindAuxiliaryUiColor(nameBox, "PlaceholderColor3", "Muted")
				local nameCorner = Instance.new("UICorner")
				nameCorner.CornerRadius = UDim.new(0, 8)
				nameCorner.Parent = nameBox
				local namePadding = Instance.new("UIPadding")
				namePadding.PaddingLeft = UDim.new(0, 10)
				namePadding.PaddingRight = UDim.new(0, 10)
				namePadding.Parent = nameBox
				nameBox.Parent = addRow
				local addButton = Instance.new("TextButton")
				addButton.AnchorPoint = Vector2.new(1, 0)
				addButton.Position = UDim2.fromScale(1, 0)
				addButton.Size = UDim2.new(0, 70, 1, 0)
				addButton.AutoButtonColor = false
				addButton.BorderSizePixel = 0
				addButton.Font = Enum.Font.GothamBold
				addButton.Text = "Watch"
				addButton.TextSize = 12
				bindAuxiliaryUiColor(addButton, "BackgroundColor3", "Accent")
				bindAuxiliaryUiColor(addButton, "TextColor3", "OnAccent")
				local addCorner = Instance.new("UICorner")
				addCorner.CornerRadius = UDim.new(0, 8)
				addCorner.Parent = addButton
				addButton.Parent = addRow
				-- The names, each with a remove button.
				local names = Instance.new("Frame")
				names.LayoutOrder = card.nextOrder()
				names.Size = UDim2.fromScale(1, 0)
				names.AutomaticSize = Enum.AutomaticSize.Y
				names.BackgroundTransparency = 1
				names.Parent = card.content
				local namesLayout = Instance.new("UIListLayout")
				namesLayout.Padding = UDim.new(0, 4)
				namesLayout.SortOrder = Enum.SortOrder.LayoutOrder
				namesLayout.Parent = names
				local function showNames()
					for _, child in ipairs(names:GetChildren()) do
						if child:IsA("GuiObject") then child:Destroy() end
					end
					local list = watchList()
					if #list == 0 then
						local none = Instance.new("TextLabel")
						none.Size = UDim2.new(1, 0, 0, 18)
						none.BackgroundTransparency = 1
						none.Font = Enum.Font.Gotham
						none.Text = "No one on your watch list."
						none.TextSize = 11
						none.TextXAlignment = Enum.TextXAlignment.Left
						none.TextColor3 = auxiliaryUiTheme.Muted
						none.Parent = names
						return
					end
					for index, name in ipairs(list) do
						local row = Instance.new("Frame")
						row.LayoutOrder = index
						row.Size = UDim2.new(1, 0, 0, 28)
						row.BorderSizePixel = 0
						row.BackgroundColor3 = auxiliaryUiTheme.Inset
						local rowCorner = Instance.new("UICorner")
						rowCorner.CornerRadius = UDim.new(0, 7)
						rowCorner.Parent = row
						row.Parent = names
						local label = Instance.new("TextLabel")
						label.Position = UDim2.fromOffset(10, 0)
						label.Size = UDim2.new(1, -90, 1, 0)
						label.BackgroundTransparency = 1
						label.Font = Enum.Font.GothamMedium
						label.Text = tostring(name)
						label.TextSize = 12
						label.TextXAlignment = Enum.TextXAlignment.Left
						label.TextTruncate = Enum.TextTruncate.AtEnd
						label.TextColor3 = auxiliaryUiTheme.Text
						label.Parent = row
						local remove = Instance.new("TextButton")
						remove.AnchorPoint = Vector2.new(1, 0.5)
						remove.Position = UDim2.new(1, -4, 0.5, 0)
						remove.Size = UDim2.fromOffset(70, 22)
						remove.AutoButtonColor = false
						remove.BorderSizePixel = 0
						remove.Font = Enum.Font.GothamMedium
						remove.Text = "Remove"
						remove.TextSize = 11
						remove.BackgroundColor3 = auxiliaryUiTheme.Card
						remove.TextColor3 = auxiliaryUiTheme.SubText
						local removeCorner = Instance.new("UICorner")
						removeCorner.CornerRadius = UDim.new(0, 6)
						removeCorner.Parent = remove
						remove.Parent = row
						remove.Activated:Connect(function()
							table.remove(watchList(), index)
							saveFeatureSettings()
							showNames()
						end)
					end
				end
				-- Colours here depend on the list, so the list is redrawn with the card.
				table.insert(card.refreshers, showNames)
				local function addName()
					local name = nameBox.Text:gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")
					if name == "" or name:find("%s") then return end
					if type(featureSettings.watchList) ~= "table" then featureSettings.watchList = {} end
					for _, existing in ipairs(featureSettings.watchList) do
						if tostring(existing):lower() == name:lower() then
							nameBox.Text = ""
							return
						end
					end
					table.insert(featureSettings.watchList, name)
					saveFeatureSettings()
					nameBox.Text = ""
					showNames()
					notify("Join Alerts", "Watching " .. name, 2)
				end
				addButton.Activated:Connect(addName)
				nameBox.FocusLost:Connect(function(enterPressed)
					if enterPressed then addName() end
				end)
				card.refresh()
			end

			menuModules.joinAlerts = {
				announceHere = announceHere,
				-- For the watch and unwatch commands.
				watch = function(name)
					name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")
					if name == "" then return false end
					if type(featureSettings.watchList) ~= "table" then featureSettings.watchList = {} end
					for _, existing in ipairs(featureSettings.watchList) do
						if tostring(existing):lower() == name:lower() then return true end
					end
					table.insert(featureSettings.watchList, name)
					saveFeatureSettings()
					if card then card.refresh() end
					return true
				end,
				unwatch = function(name)
					name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", ""):lower()
					local list = watchList()
					for index = #list, 1, -1 do
						if tostring(list[index]):lower() == name then
							table.remove(list, index)
							saveFeatureSettings()
							if card then card.refresh() end
							return true
						end
					end
					return false
				end,
			}
			if featureSettings.joinAlerts and quickToggleByName["Join Alerts"] then
				setQuickToggle(quickToggleByName["Join Alerts"], true)
			end
		end)

		------------------------------------------------------------------------------------------
		-- Mention Alerts: a notification, with a ping, when someone says your name in chat: your
		-- username, your display name, or another word you add (a nickname, say). A word only counts
		-- on its own, so "sam" doesn't go off on "same". Right-click its switch for what counts.
		safeBuild("Mention Alerts", function()
			local localPlayer = Players.LocalPlayer
			local function enabled()
				local entry = quickToggleByName["Mention Alerts"]
				return entry ~= nil and entry.state
			end
			local function wordList()
				return type(featureSettings.mentionWords) == "table" and featureSettings.mentionWords or {}
			end
			-- Everything that counts as you, in lower case.
			local function myWords()
				local words = {}
				if featureSettings.mentionUsername then table.insert(words, localPlayer.Name:lower()) end
				local displayName = localPlayer.DisplayName:lower()
				if featureSettings.mentionDisplayName and not table.find(words, displayName) then table.insert(words, displayName) end
				for _, word in ipairs(wordList()) do
					word = tostring(word):lower()
					if word ~= "" and not table.find(words, word) then table.insert(words, word) end
				end
				return words
			end
			-- Whether text has word in it on its own: a letter, digit or underscore either side would
			-- make it part of a longer word. An @ in front is fine.
			local function says(text, word)
				local from = 1
				while true do
					local first, last = text:find(word, from, true)
					if not first then return false end
					local before = text:sub(first - 1, first - 1)
					local after = text:sub(last + 1, last + 1)
					if not before:find("[%w_]") and not after:find("[%w_]") then return true end
					from = first + 1
				end
			end

			local lastAlert = {}
			local function heard(player, text)
				if not enabled() or not player or player == localPlayer or type(text) ~= "string" then return end
				local lowered = text:lower()
				local mentioned = false
				for _, word in ipairs(myWords()) do
					if says(lowered, word) then
						mentioned = true
						break
					end
				end
				if not mentioned then return end
				-- One alert every few seconds from each player is plenty.
				local now = os.clock()
				if lastAlert[player.UserId] and now - lastAlert[player.UserId] < 3 then return end
				lastAlert[player.UserId] = now
				notify("Mentioned by " .. menuModules.labelOf(player), text, 6)
				if featureSettings.mentionSound then
					local ping = Instance.new("Sound")
					ping.SoundId = "rbxasset://sounds/electronicpingshort.wav"
					ping.Volume = 0.6
					ping.Parent = SoundService
					ping:Play()
					task.delay(3, function() ping:Destroy() end)
				end
			end
			local connections = {}
			if sharedEnv.SpreadCheeksMentionAlerts then
				for _, connection in ipairs(sharedEnv.SpreadCheeksMentionAlerts) do
					pcall(function() connection:Disconnect() end)
				end
			end
			sharedEnv.SpreadCheeksMentionAlerts = connections
			-- Chat, from Roblox's newer chat or the legacy one, whichever the game uses.
			if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
				table.insert(connections, TextChatService.MessageReceived:Connect(function(message)
					local source = message.TextSource
					if source then heard(Players:GetPlayerByUserId(source.UserId), message.Text) end
				end))
			else
				local function listenTo(player)
					table.insert(connections, player.Chatted:Connect(function(text) heard(player, text) end))
				end
				for _, player in ipairs(Players:GetPlayers()) do listenTo(player) end
				table.insert(connections, Players.PlayerAdded:Connect(listenTo))
			end

			-- Adding and taking off words, for the settings card and the mentionword commands.
			local function cleanWord(word)
				local cleaned = tostring(word or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")
				return cleaned
			end
			local function addWord(word)
				word = cleanWord(word)
				if word == "" or #word > 30 then return false end
				if type(featureSettings.mentionWords) ~= "table" then featureSettings.mentionWords = {} end
				for _, existing in ipairs(featureSettings.mentionWords) do
					if tostring(existing):lower() == word:lower() then return true end
				end
				table.insert(featureSettings.mentionWords, word)
				saveFeatureSettings()
				return true
			end
			local function removeWord(word)
				word = cleanWord(word):lower()
				local list = wordList()
				for index = #list, 1, -1 do
					if tostring(list[index]):lower() == word then
						table.remove(list, index)
						saveFeatureSettings()
						return true
					end
				end
				return false
			end

			-- Settings: what counts as you, other words, and the ping.
			local entry = quickToggleByName["Mention Alerts"]
			local card = entry and createSettingsCard(entry)
			if card then
				card.addSectionLabel("LISTEN FOR", "at-sign")
				card.addSwitchGrid({
					{
						text = "Username",
						get = function() return featureSettings.mentionUsername == true end,
						set = function(on)
							featureSettings.mentionUsername = on
							saveFeatureSettings()
						end,
					},
					{
						text = "Display name",
						get = function() return featureSettings.mentionDisplayName == true end,
						set = function(on)
							featureSettings.mentionDisplayName = on
							saveFeatureSettings()
						end,
					},
				})
				card.addHint(function()
					local words = myWords()
					if #words == 0 then return "Nothing to listen for: turn on Username or Display name, or add a word below." end
					return "Listening for: " .. table.concat(words, ", ")
				end)
				card.addSectionLabel("OTHER WORDS", "message-circle")
				card.addHint("Nicknames, or anything else people call you. Each one only counts as a word on its own.")
				-- Add a word: a box and a button on one line, like Join Alerts' watch list.
				local addRow = Instance.new("Frame")
				addRow.LayoutOrder = card.nextOrder()
				addRow.Size = UDim2.new(1, 0, 0, 30)
				addRow.BackgroundTransparency = 1
				addRow.Parent = card.content
				local wordBox = Instance.new("TextBox")
				wordBox.Size = UDim2.new(1, -78, 1, 0)
				wordBox.BorderSizePixel = 0
				wordBox.ClearTextOnFocus = false
				wordBox.Font = Enum.Font.Gotham
				wordBox.PlaceholderText = "A word, like a nickname"
				wordBox.Text = ""
				wordBox.TextSize = 12
				wordBox.TextXAlignment = Enum.TextXAlignment.Left
				bindAuxiliaryUiColor(wordBox, "BackgroundColor3", "Inset")
				bindAuxiliaryUiColor(wordBox, "TextColor3", "Text")
				bindAuxiliaryUiColor(wordBox, "PlaceholderColor3", "Muted")
				local wordCorner = Instance.new("UICorner")
				wordCorner.CornerRadius = UDim.new(0, 8)
				wordCorner.Parent = wordBox
				local wordPadding = Instance.new("UIPadding")
				wordPadding.PaddingLeft = UDim.new(0, 10)
				wordPadding.PaddingRight = UDim.new(0, 10)
				wordPadding.Parent = wordBox
				wordBox.Parent = addRow
				local addButton = Instance.new("TextButton")
				addButton.AnchorPoint = Vector2.new(1, 0)
				addButton.Position = UDim2.fromScale(1, 0)
				addButton.Size = UDim2.new(0, 70, 1, 0)
				addButton.AutoButtonColor = false
				addButton.BorderSizePixel = 0
				addButton.Font = Enum.Font.GothamBold
				addButton.Text = "Add"
				addButton.TextSize = 12
				bindAuxiliaryUiColor(addButton, "BackgroundColor3", "Accent")
				bindAuxiliaryUiColor(addButton, "TextColor3", "OnAccent")
				local addCorner = Instance.new("UICorner")
				addCorner.CornerRadius = UDim.new(0, 8)
				addCorner.Parent = addButton
				addButton.Parent = addRow
				-- The words, each with a remove button.
				local wordsFrame = Instance.new("Frame")
				wordsFrame.LayoutOrder = card.nextOrder()
				wordsFrame.Size = UDim2.fromScale(1, 0)
				wordsFrame.AutomaticSize = Enum.AutomaticSize.Y
				wordsFrame.BackgroundTransparency = 1
				wordsFrame.Parent = card.content
				local wordsLayout = Instance.new("UIListLayout")
				wordsLayout.Padding = UDim.new(0, 4)
				wordsLayout.SortOrder = Enum.SortOrder.LayoutOrder
				wordsLayout.Parent = wordsFrame
				local function showWords()
					for _, child in ipairs(wordsFrame:GetChildren()) do
						if child:IsA("GuiObject") then child:Destroy() end
					end
					local list = wordList()
					if #list == 0 then
						local none = Instance.new("TextLabel")
						none.Size = UDim2.new(1, 0, 0, 18)
						none.BackgroundTransparency = 1
						none.Font = Enum.Font.Gotham
						none.Text = "No other words yet."
						none.TextSize = 11
						none.TextXAlignment = Enum.TextXAlignment.Left
						none.TextColor3 = auxiliaryUiTheme.Muted
						none.Parent = wordsFrame
						return
					end
					for index, word in ipairs(list) do
						local row = Instance.new("Frame")
						row.LayoutOrder = index
						row.Size = UDim2.new(1, 0, 0, 28)
						row.BorderSizePixel = 0
						row.BackgroundColor3 = auxiliaryUiTheme.Inset
						local rowCorner = Instance.new("UICorner")
						rowCorner.CornerRadius = UDim.new(0, 7)
						rowCorner.Parent = row
						row.Parent = wordsFrame
						local label = Instance.new("TextLabel")
						label.Position = UDim2.fromOffset(10, 0)
						label.Size = UDim2.new(1, -90, 1, 0)
						label.BackgroundTransparency = 1
						label.Font = Enum.Font.GothamMedium
						label.Text = tostring(word)
						label.TextSize = 12
						label.TextXAlignment = Enum.TextXAlignment.Left
						label.TextTruncate = Enum.TextTruncate.AtEnd
						label.TextColor3 = auxiliaryUiTheme.Text
						label.Parent = row
						local remove = Instance.new("TextButton")
						remove.AnchorPoint = Vector2.new(1, 0.5)
						remove.Position = UDim2.new(1, -4, 0.5, 0)
						remove.Size = UDim2.fromOffset(70, 22)
						remove.AutoButtonColor = false
						remove.BorderSizePixel = 0
						remove.Font = Enum.Font.GothamMedium
						remove.Text = "Remove"
						remove.TextSize = 11
						remove.BackgroundColor3 = auxiliaryUiTheme.Card
						remove.TextColor3 = auxiliaryUiTheme.SubText
						local removeCorner = Instance.new("UICorner")
						removeCorner.CornerRadius = UDim.new(0, 6)
						removeCorner.Parent = remove
						remove.Parent = row
						remove.Activated:Connect(function()
							table.remove(wordList(), index)
							saveFeatureSettings()
							card.refresh()
						end)
					end
				end
				-- Colours here depend on the list, so the list is redrawn with the card.
				table.insert(card.refreshers, showWords)
				local function addTypedWord()
					if addWord(wordBox.Text) then
						wordBox.Text = ""
						card.refresh()
					end
				end
				addButton.Activated:Connect(addTypedWord)
				wordBox.FocusLost:Connect(function(enterPressed)
					if enterPressed then addTypedWord() end
				end)
				card.addSectionLabel("SOUND", "volume-2", "bell")
				card.addSwitchGrid({
					{
						text = "Ping with each alert",
						get = function() return featureSettings.mentionSound == true end,
						set = function(on)
							featureSettings.mentionSound = on
							saveFeatureSettings()
						end,
					},
				}, 1)
				card.refresh()
			end

			menuModules.mentionAlerts = {
				-- For the mentionword and unmentionword commands.
				addWord = function(word)
					local added = addWord(word)
					if added and card then card.refresh() end
					return added
				end,
				removeWord = function(word)
					local removed = removeWord(word)
					if removed and card then card.refresh() end
					return removed
				end,
			}
			if featureSettings.mentionAlerts and entry then
				setQuickToggle(entry, true)
			end
		end)

		------------------------------------------------------------------------------------------
		-- Target HUD: who the aimbot is locked onto, or else who the trigger bot has under the
		-- crosshair: their face, name, a health bar, how far away they are and what they're
		-- holding. With nobody targeted it says so, so it can still be dragged into place (unless
		-- it's set to hide then, in its settings card).
		safeBuild("The Target HUD", function()
			local localPlayer = Players.LocalPlayer
			local hudWindow = menuModules.makeWindow({
				name = "SpreadCheeksTargetHud", title = "Target", icons = { "crosshair", "target" },
				width = 260, height = 118, xKey = "targetHudX", yKey = "targetHudY",
				-- Under the middle of the screen, clear of the crosshair.
				defaultPosition = function(screen, size) return (screen.X - size.X) / 2, screen.Y * 0.62 end,
			})
			local body = hudWindow.body
			-- LOCKED (the aimbot) or IN SIGHT (the trigger bot), in the header.
			local status = Instance.new("TextLabel")
			status.AutomaticSize = Enum.AutomaticSize.X
			status.Size = UDim2.fromOffset(0, 20)
			status.BackgroundTransparency = 1
			status.Font = Enum.Font.GothamBold
			status.Text = ""
			status.TextSize = 10
			status.Parent = hudWindow.headerRight
			local avatar = Instance.new("ImageLabel")
			avatar.Position = UDim2.fromOffset(12, 2)
			avatar.Size = UDim2.fromOffset(52, 52)
			avatar.BorderSizePixel = 0
			bindAuxiliaryUiColor(avatar, "BackgroundColor3", "Inset")
			avatar.Parent = body
			local avatarCorner = Instance.new("UICorner")
			avatarCorner.CornerRadius = UDim.new(0, 10)
			avatarCorner.Parent = avatar
			local nameLabel = Instance.new("TextLabel")
			nameLabel.Position = UDim2.fromOffset(74, 2)
			nameLabel.Size = UDim2.new(1, -86, 0, 18)
			nameLabel.BackgroundTransparency = 1
			nameLabel.Font = Enum.Font.GothamBold
			nameLabel.TextSize = 14
			nameLabel.TextXAlignment = Enum.TextXAlignment.Left
			nameLabel.TextTruncate = Enum.TextTruncate.AtEnd
			bindAuxiliaryUiColor(nameLabel, "TextColor3", "Text")
			nameLabel.Parent = body
			local userLabel = Instance.new("TextLabel")
			userLabel.Position = UDim2.fromOffset(74, 20)
			userLabel.Size = UDim2.new(1, -86, 0, 14)
			userLabel.BackgroundTransparency = 1
			userLabel.Font = Enum.Font.Gotham
			userLabel.TextSize = 11
			userLabel.TextXAlignment = Enum.TextXAlignment.Left
			userLabel.TextTruncate = Enum.TextTruncate.AtEnd
			bindAuxiliaryUiColor(userLabel, "TextColor3", "SubText")
			userLabel.Parent = body
			local healthBack = Instance.new("Frame")
			healthBack.Position = UDim2.fromOffset(74, 42)
			healthBack.Size = UDim2.new(1, -86, 0, 8)
			healthBack.BorderSizePixel = 0
			bindAuxiliaryUiColor(healthBack, "BackgroundColor3", "Inset")
			healthBack.Parent = body
			local healthBackCorner = Instance.new("UICorner")
			healthBackCorner.CornerRadius = UDim.new(1, 0)
			healthBackCorner.Parent = healthBack
			local healthFill = Instance.new("Frame")
			healthFill.Size = UDim2.fromScale(0, 1)
			healthFill.BorderSizePixel = 0
			healthFill.Parent = healthBack
			local healthFillCorner = Instance.new("UICorner")
			healthFillCorner.CornerRadius = UDim.new(1, 0)
			healthFillCorner.Parent = healthFill
			local detailLabel = Instance.new("TextLabel")
			detailLabel.Position = UDim2.fromOffset(12, 62)
			detailLabel.Size = UDim2.new(1, -24, 0, 14)
			detailLabel.BackgroundTransparency = 1
			detailLabel.Font = Enum.Font.GothamMedium
			detailLabel.TextSize = 11
			detailLabel.TextXAlignment = Enum.TextXAlignment.Left
			detailLabel.TextTruncate = Enum.TextTruncate.AtEnd
			bindAuxiliaryUiColor(detailLabel, "TextColor3", "SubText")
			detailLabel.Parent = body

			local enabled, shownTarget, lastUpdate, connection = false, nil, 0, nil
			-- Streamer Mode going on or off draws the name again.
			table.insert(menuModules.nameListeners, function() shownTarget = nil end)
			-- Who to show: the aimbot's lock first, then Silent Aim's target, then whoever the trigger
			-- bot is on.
			local function currentTarget()
				local locked = aimbotState.target
				if locked and locked.Parent then return locked, "LOCKED" end
				local silentTarget = aimbotState.silent.target
				if silentTarget and silentTarget.Parent then return silentTarget, "SILENT AIM" end
				local sighted = triggerBotState.enabled and triggerBotState.target
				if sighted and sighted.Parent then return sighted, "IN SIGHT" end
				return nil, nil
			end
			local function update()
				local target, kind = currentTarget()
				hudWindow.setShown(enabled and (target ~= nil or not featureSettings.targetHudAutoHide))
				if not target then
					shownTarget = nil
					avatar.Image = ""
					nameLabel.Text = "No target"
					if aimbotState.enabled then
						userLabel.Text = "Hold " .. aimbotKeyText() .. " to lock on"
					elseif aimbotState.silent.on then
						userLabel.Text = "Nobody in the circle"
					else
						userLabel.Text = "Turn on the aimbot or trigger bot"
					end
					healthFill.Size = UDim2.fromScale(0, 1)
					detailLabel.Text = ""
					status.Text = ""
					return
				end
				if target ~= shownTarget then
					shownTarget = target
					avatar.Image = "rbxthumb://type=AvatarHeadShot&id=" .. target.UserId .. "&w=150&h=150"
					nameLabel.Text = menuModules.nameOf(target)
					userLabel.Text = featureSettings.streamerMode and "" or ("@" .. target.Name)
				end
				status.Text = kind
				status.TextColor3 = auxiliaryUiTheme.AccentText
				local character = target.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local health = humanoid and math.max(humanoid.Health, 0) or 0
				local maxHealth = humanoid and math.max(humanoid.MaxHealth, 1) or 100
				local fraction = math.clamp(health / maxHealth, 0, 1)
				healthFill.Size = UDim2.fromScale(fraction, 1)
				-- Green when they're healthy, through yellow, to red when they're nearly done.
				healthFill.BackgroundColor3 = Color3.fromHSV(fraction * 0.33, 0.7, 0.95)
				local details = { math.floor(health + 0.5) .. " / " .. math.floor(maxHealth + 0.5) .. " HP" }
				local root = character and getRoot(character)
				local myRoot = localPlayer.Character and getRoot(localPlayer.Character)
				if root and myRoot then
					table.insert(details, math.floor((root.Position - myRoot.Position).Magnitude + 0.5) .. " studs")
				end
				local tool = character and character:FindFirstChildOfClass("Tool")
				table.insert(details, tool and ("Holding " .. tool.Name) or "Empty-handed")
				detailLabel.Text = table.concat(details, "  ·  ")
			end
			-- Ten times a second, and straight away when the target changes.
			local function setEnabled(on)
				enabled = on == true
				if connection then
					connection:Disconnect()
					connection = nil
				end
				if not enabled then return hudWindow.setShown(false) end
				connection = RunService.Heartbeat:Connect(function()
					local now = os.clock()
					if now - lastUpdate < 0.1 and currentTarget() == shownTarget then return end
					lastUpdate = now
					update()
				end)
				table.insert(hudWindow.connections, connection)
				update()
			end

			local entry = quickToggleByName["Target HUD"]
			local card = entry and createSettingsCard(entry)
			if card then
				card.addSectionLabel("SHOW", "eye")
				card.addSwitchGrid({
					{
						text = "Hide when there's no target",
						get = function() return featureSettings.targetHudAutoHide == true end,
						set = function(on)
							featureSettings.targetHudAutoHide = on
							saveFeatureSettings()
							if enabled then update() end
						end,
					},
				}, 1)
				card.addHint("It shows who the aimbot is locked onto while you hold the aim key, or else who the trigger bot has under your crosshair. Turn hiding off to drag it somewhere new.")
				card.refresh()
			end

			menuModules.targetHud = { setEnabled = setEnabled }
			if featureSettings.targetHud and entry then
				setQuickToggle(entry, true)
			end
		end)

		------------------------------------------------------------------------------------------
		-- ESP off-screen arrows: while ESP is on, an arrow round the edge of the screen for each
		-- player who's off it (behind you, say), pointing the way to them, in their ESP colour and
		-- fainter the further away they are. It follows ESP's "Only show enemies". Switched on in
		-- the ESP settings.
		safeBuild("ESP off-screen arrows", function()
			local localPlayer = Players.LocalPlayer
			local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:WaitForChild("PlayerGui")
			local previousGui = playerGui:FindFirstChild("SpreadCheeksEspArrows")
			if previousGui then previousGui:Destroy() end
			local gui = Instance.new("ScreenGui")
			gui.Name = "SpreadCheeksEspArrows"
			gui.ResetOnSpawn = false
			gui.IgnoreGuiInset = true
			-- Under the aimbot's circle and the menu's windows.
			gui.DisplayOrder = 997
			gui.Parent = playerGui
			local arrowImage = menuIcons.get("navigation-2", "chevron-up")
			local arrows = {}
			local function arrowFor(player)
				local arrow = arrows[player]
				if arrow then return arrow end
				arrow = Instance.new("ImageLabel")
				arrow.AnchorPoint = Vector2.new(0.5, 0.5)
				arrow.Size = UDim2.fromOffset(22, 22)
				arrow.BackgroundTransparency = 1
				if arrowImage then menuIcons.apply(arrow, arrowImage) end
				arrow.Parent = gui
				arrows[player] = arrow
				return arrow
			end
			Players.PlayerRemoving:Connect(function(player)
				if arrows[player] then
					arrows[player]:Destroy()
					arrows[player] = nil
				end
			end)
			-- After the camera has moved for the frame, so the arrows point from where it ends up.
			pcall(function() RunService:UnbindFromRenderStep("SpreadCheeksEspArrows") end)
			RunService:BindToRenderStep("SpreadCheeksEspArrows", Enum.RenderPriority.Camera.Value + 3, function()
				local camera = workspace.CurrentCamera
				local shown = {}
				if ESPenabled and espSettings.offscreenArrows and camera then
					local center = camera.ViewportSize / 2
					local myRoot = localPlayer.Character and getRoot(localPlayer.Character)
					for _, player in ipairs(Players:GetPlayers()) do
						local root = player ~= localPlayer and player.Character and getRoot(player.Character)
						if root and not (espSettings.enemiesOnly and espIsTeammate(player)) then
							local _, onScreen = camera:WorldToViewportPoint(root.Position)
							if not onScreen then
								-- Which way they are from the middle of the screen, as the camera sees it;
								-- straight behind you comes out at the bottom.
								local relative = camera.CFrame:PointToObjectSpace(root.Position)
								local direction = Vector2.new(relative.X, -relative.Y)
								direction = direction.Magnitude > 0.001 and direction.Unit or Vector2.new(0, 1)
								local arrow = arrowFor(player)
								arrow.Position = UDim2.fromOffset(center.X + direction.X * (center.X - 48), center.Y + direction.Y * (center.Y - 48))
								arrow.Rotation = math.deg(math.atan2(direction.Y, direction.X)) + 90
								arrow.ImageColor3 = espColorFor(player)
								local distance = myRoot and (root.Position - myRoot.Position).Magnitude or 0
								arrow.ImageTransparency = math.clamp((distance - 50) / 500, 0, 0.6)
								arrow.Visible = true
								shown[player] = true
							end
						end
					end
				end
				for player, arrow in pairs(arrows) do
					if not shown[player] then arrow.Visible = false end
				end
			end)
		end)

		------------------------------------------------------------------------------------------
		------------------------------------------------------------------------------------------
		-- The Big Update (27 October 2026). Each part is built on its own, so a problem in one can't
		-- stop the rest. Their switches are made with the others further up, so they get key boxes;
		-- the ones remembered between sessions come back on at the end (see "Switches that were on").

		------------------------------------------------------------------------------------------
		-- What's New: the first time the script runs after an update, a window shows what the update
		-- added. menuVersion changes with every update, and that update's notes go at the top of
		-- releaseNotes. The What's New button in Interface, and the whatsnew command, open it any time.
		safeBuild("What's New", function()
			-- (2026.10.28.4 added Quick Search, since taken out again, so it has no notes.)
			local menuVersion = "2026.10.29.1"
			local releaseNotes = {
				{
					title = "Spotify", date = "29 October 2026",
					notes = {
						{ "Spotify", "Interface tab. Your Spotify in a window: the song and its cover, play/pause, skip, seek, shuffle, repeat, volume, like, and search to play or queue a song. Needs Premium; the window walks you through connecting it once." },
