			})
			local gotIt = Instance.new("TextButton")
			gotIt.AutomaticSize = Enum.AutomaticSize.X
			gotIt.Size = UDim2.fromOffset(0, 22)
			gotIt.AutoButtonColor = false
			gotIt.BorderSizePixel = 0
			gotIt.Font = Enum.Font.GothamBold
