			hint(emotes, "The first five work on any avatar; the rest need R15, which most games use.")

			-- Moves: your moves (turned to them first) and your own tricks.
			local moves = newTab("Moves", 4)
			sectionLabel(moves, "AT THEM")
			local moveCells = grid(moves, 3)
			for _, move in ipairs(trolling.moves or {}) do
				button(moveCells, move.name, function(player)
					faceThem(player)
					move.run()
				end)
			end
			sectionLabel(moves, "YOU  ·  CLICK AGAIN TO STOP")
			local bodyCells = grid(moves, 3)
			for _, name in ipairs({
				"Emote", "Fake Dead", "Ragdoll", "Fake Lag", "Vibrate", "Spin", "Statue", "Handstand", "Crawl", "Helicopter",
				"Superman", "Marble Ball", "Roomba", "Moonwalk", "Zoomies", "Bunny Hop", "Wall Walk", "Penguin Waddle", "Cartwheel Walk",
			}) do
				if quickToggleByName[name] then selfSwitch(bodyCells, name) end
			end
			settingsSection(moves, {
				{ name = "Fake Lag", items = {
					choiceOf("Style", "trollLagStyle", { "Stutter", "Rubber-band", "Glitch", "Spikes", "Mixed" }),
					sliderOf("Strength", "trollLagStrength", 1, 10, 1),
					switchOf("Only while moving", "trollLagMoving"),
				} },
				{ name = "Fake Dead", items = { choiceOf("Pose", "trollDeadPose", { "On your back", "Face down" }) } },
				{ name = "Spin", items = {
					sliderOf("Speed", "trollSpinSpeed", 1, 100, 1, nil, function(value)
						if trolling.setSpinSpeed then trolling.setSpinSpeed(value) end
					end),
				} },
				{ name = "Crawl", items = { choiceOf("Style", "trollCrawlStyle", { "Worm", "Belly Slide", "Log Roll" }) } },
				{ name = "Helicopter", items = { sliderOf("Hover height", "trollHeliHeight", 3, 30, 1, " studs") } },
				{ name = "Marble Ball", items = {
					sliderOf("Speed", "trollMarbleSpeed", 20, 300, 5),
					sliderOf("Jump", "trollMarbleJump", 0, 250, 5),
					sliderOf("Ball size", "trollMarbleSize", 3, 10, 0.5, " studs", function(value)
						if trolling.setMarbleSize then trolling.setMarbleSize(value) end
					end),
				} },
				{ name = "Roomba", items = { sliderOf("Speed", "trollRoombaSpeed", 4, 30, 1, " studs/s") } },
			})
			hint(moves, "Emote loops the emote picked on the Emotes tab. Switching a trick on shows its settings.")

			-- Tools: getting to them, watching them, and about them.
			local tools = newTab("Tools", 5)
			sectionLabel(tools, "GET TO THEM")
			local goCells = grid(tools, 3)
			button(goCells, "Next to them", function(player) goNear(player, "side") end)
			button(goCells, "In front", function(player) goNear(player, "front") end)
			button(goCells, "Behind", function(player) goNear(player, "behind") end)
			sectionLabel(tools, "WATCHING")
			local watchCells = grid(tools, 2)
			button(watchCells, "Their eyes", function() setEyes(not eyes.on) end, function() return eyes.on end)
			button(watchCells, "Highlight them", function()
				mark.on = not mark.on
				updateMark()
			end, function() return mark.on end)
			button(watchCells, "Previous player", function()
				if menuModules.spectateBar and menuModules.spectateBar.step then menuModules.spectateBar.step(-1) end
			end)
			button(watchCells, "Next player", function()
				if menuModules.spectateBar and menuModules.spectateBar.step then menuModules.spectateBar.step(1) end
			end)
			sectionLabel(tools, "ABOUT THEM")
			local aboutCells = grid(tools, 3)
			button(aboutCells, "Copy name", function(player) menuModules.copy(player.Name, "their username") end)
			button(aboutCells, "Copy ID", function(player) menuModules.copy(player.UserId, "their user ID") end)
			button(aboutCells, "Outfit", function(player)
				if menuModules.openOutfit then menuModules.openOutfit(player) end
			end)
			local noteBox = Instance.new("TextBox")
			noteBox.LayoutOrder = nextIn(tools)
			noteBox.Size = UDim2.new(1, 0, 0, 30)
			noteBox.BorderSizePixel = 0
			noteBox.ClearTextOnFocus = false
			noteBox.Font = Enum.Font.Gotham
			noteBox.PlaceholderText = "A note about them (only you see it)"
			noteBox.Text = ""
			noteBox.TextSize = 12
			noteBox.TextXAlignment = Enum.TextXAlignment.Left
			noteBox.TextTruncate = Enum.TextTruncate.AtEnd
			bindAuxiliaryUiColor(noteBox, "BackgroundColor3", "Inset")
			bindAuxiliaryUiColor(noteBox, "TextColor3", "Text")
			bindAuxiliaryUiColor(noteBox, "PlaceholderColor3", "Muted")
			addCorner(noteBox, UDim.new(0, 8))
			local notePadding = Instance.new("UIPadding")
			notePadding.PaddingLeft = UDim.new(0, 10)
			notePadding.PaddingRight = UDim.new(0, 10)
			notePadding.Parent = noteBox
			noteBox.Parent = tools.frame
			noteBox.FocusLost:Connect(function()
				if shown.player and menuModules.setNote then menuModules.setNote(shown.player, noteBox.Text) end
			end)
			hint(tools, "Their eyes shows what they're looking at. Only you see the highlight. Your note is kept for next time, and shows when they join.")

			-- Four times a second: shown while you spectate someone, and kept up to date about them.
			local function refresh()
				local player = typeof(viewing) == "Instance" and viewing:IsA("Player") and viewing ~= localPlayer and viewing.Parent ~= nil and viewing or nil
				local visible = shown.enabled and player ~= nil
				panel.setShown(visible)
				if not visible then
					if eyes.on then setEyes(false) end
					shown.player = nil
					updateMark()
					return
				end
				if player ~= shown.player then
					shown.player = player
					avatar.Image = "rbxthumb://type=AvatarHeadShot&id=" .. player.UserId .. "&w=150&h=150"
					if not noteBox:IsFocused() then noteBox.Text = menuModules.noteFor and menuModules.noteFor(player) or "" end
				end
				nameLabel.Text = menuModules.nameOf(player)
				local parts = {}
				local character = player.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local root = character and getRoot(character)
				local myRoot = localPlayer.Character and getRoot(localPlayer.Character)
				table.insert(parts, humanoid and (math.floor(math.max(humanoid.Health, 0) + 0.5) .. " health") or "No character")
				if root and myRoot then table.insert(parts, math.floor((root.Position - myRoot.Position).Magnitude + 0.5) .. " studs away") end
				if player.Team then table.insert(parts, player.Team.Name) end
				if isTarget(player) then table.insert(parts, "your target") end
				detailLabel.Text = table.concat(parts, "  ·  ")
				updateMark()
				paint()
			end
			local sinceRefresh = 0
			table.insert(panel.connections, RunService.Heartbeat:Connect(function(deltaTime)
				sinceRefresh += deltaTime
				if sinceRefresh < 0.25 then return end
				sinceRefresh = 0
				refresh()
			end))
			table.insert(menuModules.nameListeners, refresh)
			paint()
			menuModules.trollPanel = {
				setEnabled = function(on)
					shown.enabled = on
					refresh()
				end,
				-- Brings it up straight away (for Shift+click) rather than at the next check.
				refresh = refresh,
			}
		end)

		------------------------------------------------------------------------------------------
		-- Ctrl+Click Select and Shift+click. Hold Ctrl and click a player (or near one) to make them your
		-- target, for the Player Pranks tricks, the Players tab and the commands; while you spectate, it
		-- watches them instead, so the Troll Panel follows. Hold Shift and click someone to spectate them,
		-- which brings up their Troll Panel (while the Troll Panel switch is on). A flash shows who you
		-- picked.
		safeBuild("Ctrl+Click Select", function()
			local localPlayer = Players.LocalPlayer
			-- ctrl: whether the Ctrl+Click Select switch is on.
			local clicking = { ctrl = false }
			local clickParams = RaycastParams.new()
			clickParams.FilterType = Enum.RaycastFilterType.Exclude
			-- The player at a point on the screen: the one whose character is under it, or else whoever's
			-- nearest to it on screen, within 60 pixels.
			local function playerAt(point)
				local camera = workspace.CurrentCamera
				if not camera then return nil end
				local ray = camera:ViewportPointToRay(point.X, point.Y)
				clickParams.FilterDescendantsInstances = { localPlayer.Character }
				local hit = workspace:Raycast(ray.Origin, ray.Direction * 2000, clickParams)
				local model = hit and hit.Instance:FindFirstAncestorWhichIsA("Model")
				while model do
					local player = Players:GetPlayerFromCharacter(model)
					if player then return player end
					model = model:FindFirstAncestorWhichIsA("Model")
				end
				local nearest, nearestGap = nil, 60
				for _, player in ipairs(Players:GetPlayers()) do
					local root = player ~= localPlayer and player.Character and getRoot(player.Character)
					if root then
						local screenPoint, onScreen = camera:WorldToViewportPoint(root.Position)
						local gap = (Vector2.new(screenPoint.X, screenPoint.Y) - point).Magnitude
						if onScreen and gap < nearestGap then nearest, nearestGap = player, gap end
					end
				end
				return nearest
			end
			local function flash(player)
				local character = player.Character
				if not character then return end
				local highlight = Instance.new("Highlight")
				highlight.Name = "SpreadCheeksSelectFlash"
				highlight.Adornee = character
				highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
				highlight.FillColor = auxiliaryUiTheme.AccentText
				highlight.OutlineColor = auxiliaryUiTheme.AccentText
				highlight.FillTransparency = 0.45
				highlight.Parent = COREGUI
				TweenService:Create(highlight, TweenInfo.new(0.9), { FillTransparency = 1, OutlineTransparency = 1 }):Play()
				task.delay(1, function() highlight:Destroy() end)
			end
			local function held(left, right)
				return UserInputService:IsKeyDown(left) or UserInputService:IsKeyDown(right)
			end
			-- One listener for both, kept in the shared environment so running the script again drops the
			-- old one.
			if sharedEnv.SpreadCheeksPlayerClicks then
				pcall(function() sharedEnv.SpreadCheeksPlayerClicks:Disconnect() end)
			end
			sharedEnv.SpreadCheeksPlayerClicks = UserInputService.InputBegan:Connect(function(input, gameProcessed)
				if input.UserInputType ~= Enum.UserInputType.MouseButton1 or gameProcessed then return end
				local ctrl = clicking.ctrl and held(Enum.KeyCode.LeftControl, Enum.KeyCode.RightControl)
				local shift = not ctrl and featureSettings.trollPanel and held(Enum.KeyCode.LeftShift, Enum.KeyCode.RightShift)
				if not ctrl and not shift then return end
				if UserInputService:GetFocusedTextBox() or pointerOverMenu() then return end
				local player = playerAt(UserInputService:GetMouseLocation())
				if not player then return end
				if menuModules.selectPlayer then menuModules.selectPlayer(player.Name, menuModules.labelOf(player, "  ")) end
				flash(player)
				local canWatch = menuModules.spectateBar and menuModules.spectateBar.watch
				if shift then
					-- Watching them is what brings their Troll Panel up.
					if viewing ~= player and canWatch then menuModules.spectateBar.watch(player) end
					if menuModules.trollPanel and menuModules.trollPanel.refresh then menuModules.trollPanel.refresh() end
					return
				end
				local watching = typeof(viewing) == "Instance" and viewing:IsA("Player") and viewing ~= localPlayer
				if watching and viewing ~= player and canWatch then menuModules.spectateBar.watch(player) end
				notify("Target", menuModules.nameOf(player) .. " is your target", 2)
			end)
			menuModules.ctrlClickSelect = {
				setEnabled = function(on) clicking.ctrl = on end,
			}
		end)

		------------------------------------------------------------------------------------------
		------------------------------------------------------------------------------------------
		-- Pranks, Practice and Panic (28 October 2026). Like The Big Update, each part is built on its
		-- own, so a problem in one can't stop the rest; their switches are made with the others further up.

		------------------------------------------------------------------------------------------
		-- Aim Trainer: a practice game in a window of its own. Press Start and targets pop up round the
		-- play area, shrinking as they go; click each one before it's gone. How long a round lasts, how
		-- big the targets are and how fast they go (and so how many are up at once) are in its settings
		-- card, and a round keeps the settings it started with. Quicker hits score more, and clicks that
		-- miss count against your accuracy. The best score for each mix of settings is kept.
		safeBuild("Aim Trainer", function()
			local trainerWindow = menuModules.makeWindow({
				name = "SpreadCheeksAimTrainer", title = "Aim Trainer", icons = { "target", "crosshair" },
				width = 420, height = 400, xKey = "aimTrainerX", yKey = "aimTrainerY",
				defaultPosition = function(screen, size) return (screen.X - size.X) / 2, (screen.Y - size.Y) / 2 end,
			})
			local body = trainerWindow.body
			-- Each size in pixels, and for each speed how long a target lasts (seconds) and how many are up.
			local sizes = { Small = 26, Medium = 38, Large = 52 }
			local speeds = { Easy = { life = 2.2, count = 1 }, Normal = { life = 1.5, count = 2 }, Hard = { life = 1, count = 3 } }
			-- The round being played (or the last one): its settings, the targets up now and how it's going.
			local round = {
				serial = 0, running = false, targets = {}, length = 30, size = "Medium", speed = "Normal",
				score = 0, hits = 0, clicks = 0, missed = 0, reactionTotal = 0, endsAt = 0, lastHitAt = 0,
			}
			local function makeLabel(parent, textSize, font, role)
				local label = Instance.new("TextLabel")
				label.BackgroundTransparency = 1
				label.Font = font
				label.TextSize = textSize
				label.TextWrapped = true
				bindAuxiliaryUiColor(label, "TextColor3", role)
				label.Parent = parent
				return label
			end

			-- The numbers along the top.
			local statsRow = Instance.new("Frame")
			statsRow.Position = UDim2.fromOffset(10, 4)
			statsRow.Size = UDim2.new(1, -20, 0, 34)
			statsRow.BackgroundTransparency = 1
			statsRow.Parent = body
			local statsLayout = Instance.new("UIListLayout")
			statsLayout.FillDirection = Enum.FillDirection.Horizontal
			statsLayout.SortOrder = Enum.SortOrder.LayoutOrder
			statsLayout.Parent = statsRow
			local stats = {}
			for index, name in ipairs({ "Score", "Hits", "Accuracy", "Time" }) do
				local cell = Instance.new("Frame")
				cell.LayoutOrder = index
				cell.Size = UDim2.fromScale(0.25, 1)
				cell.BackgroundTransparency = 1
				cell.Parent = statsRow
				local caption = makeLabel(cell, 10, Enum.Font.GothamBold, "Muted")
				caption.Size = UDim2.new(1, 0, 0, 12)
				caption.Text = name:upper()
				local value = makeLabel(cell, 17, Enum.Font.GothamBold, "Text")
				value.Position = UDim2.fromOffset(0, 13)
				value.Size = UDim2.new(1, 0, 0, 20)
				stats[name] = value
			end

			-- The play area. Clicking it anywhere but on a target is a miss. Modal frees the mouse in
			-- games that hold it in the middle of the screen.
			local area = Instance.new("TextButton")
			area.Position = UDim2.fromOffset(10, 44)
			area.Size = UDim2.new(1, -20, 1, -54)
			area.AutoButtonColor = false
			area.BorderSizePixel = 0
			area.ClipsDescendants = true
			area.Modal = true
			area.Text = ""
			bindAuxiliaryUiColor(area, "BackgroundColor3", "Inset")
			area.Parent = body
			local areaCorner = Instance.new("UICorner")
			areaCorner.CornerRadius = UDim.new(0, 10)
			areaCorner.Parent = area

			-- Between rounds: how to play (or how the last round went), and Start.
			local overlay = Instance.new("Frame")
			overlay.AnchorPoint = Vector2.new(0.5, 0.5)
			overlay.Position = UDim2.fromScale(0.5, 0.5)
			overlay.Size = UDim2.new(1, -40, 0, 160)
			overlay.BackgroundTransparency = 1
			overlay.ZIndex = 5
			overlay.Parent = area
			local heading = makeLabel(overlay, 18, Enum.Font.GothamBold, "Text")
			heading.Size = UDim2.new(1, 0, 0, 24)
			heading.ZIndex = 5
			local summary = makeLabel(overlay, 12, Enum.Font.Gotham, "SubText")
			summary.Position = UDim2.fromOffset(0, 28)
			summary.Size = UDim2.new(1, 0, 0, 78)
			summary.ZIndex = 5
			local startButton = Instance.new("TextButton")
			startButton.AnchorPoint = Vector2.new(0.5, 0)
			startButton.Position = UDim2.new(0.5, 0, 0, 116)
			startButton.Size = UDim2.fromOffset(140, 34)
			startButton.AutoButtonColor = false
			startButton.BorderSizePixel = 0
			startButton.Font = Enum.Font.GothamBold
			startButton.TextSize = 14
			startButton.ZIndex = 5
			bindAuxiliaryUiColor(startButton, "BackgroundColor3", "Accent")
			bindAuxiliaryUiColor(startButton, "TextColor3", "OnAccent")
			startButton.Parent = overlay
			local startCorner = Instance.new("UICorner")
			startCorner.CornerRadius = UDim.new(0, 8)
			startCorner.Parent = startButton
			-- The big 3, 2, 1 before a round starts.
			local countdown = makeLabel(area, 56, Enum.Font.GothamBold, "AccentText")
			countdown.AnchorPoint = Vector2.new(0.5, 0.5)
			countdown.Position = UDim2.fromScale(0.5, 0.5)
			countdown.Size = UDim2.fromOffset(120, 70)
			countdown.ZIndex = 5
			countdown.Visible = false

			local function mixKey(length, size, speed)
				return tostring(length) .. " " .. tostring(size) .. " " .. tostring(speed)
			end
			local function bestFor(key)
				return tonumber(featureSettings.aimTrainerBests[key]) or 0
			end
			local function showStats()
				stats.Score.Text = tostring(round.score)
				stats.Hits.Text = tostring(round.hits)
				stats.Accuracy.Text = round.clicks > 0 and (math.floor(round.hits / round.clicks * 100 + 0.5) .. "%") or "–"
				local left = round.running and math.max(0, round.endsAt - os.clock()) or round.length
				stats.Time.Text = tostring(math.ceil(left))
			end
			local function clearTargets()
				for _, target in ipairs(round.targets) do target.button:Destroy() end
				table.clear(round.targets)
			end
			-- The overlay before any round, with the settings the next one will use.
			local function showIntro()
				local size = sizes[featureSettings.aimTrainerSize] and featureSettings.aimTrainerSize or "Medium"
				local speed = speeds[featureSettings.aimTrainerSpeed] and featureSettings.aimTrainerSpeed or "Normal"
				local best = bestFor(mixKey(featureSettings.aimTrainerLength, size, speed))
				heading.Text = "Aim Trainer"
				summary.Text = "Click the targets before they shrink away. Quicker hits score more; clicks that miss lower your accuracy.\n\n"
					.. featureSettings.aimTrainerLength .. " seconds  ·  " .. size .. "  ·  " .. speed .. (best > 0 and ("  ·  best " .. best) or "")
				startButton.Text = "Start"
				overlay.Visible = true
				countdown.Visible = false
				if not round.running then
					round.length = featureSettings.aimTrainerLength
					showStats()
				end
			end
			-- Ends the round: completed ones get their results and maybe a new best; stopped ones don't.
			local function finish(completed)
				round.serial += 1
				round.running = false
				clearTargets()
				if not completed then return showIntro() end
				local key = mixKey(round.length, round.size, round.speed)
				local best = bestFor(key)
				local newBest = round.score > best
				if newBest then
					featureSettings.aimTrainerBests[key] = round.score
					saveFeatureSettings()
				end
				local accuracy = round.clicks > 0 and math.floor(round.hits / round.clicks * 100 + 0.5) or 0
				local average = round.hits > 0 and math.floor(round.reactionTotal / round.hits * 1000 + 0.5) or nil
				heading.Text = newBest and ("New best: " .. round.score .. "!") or ("Score " .. round.score)
				summary.Text = round.hits .. " hits, " .. round.missed .. " got away  ·  " .. accuracy .. "% accuracy"
					.. (average and ("\n" .. average .. " ms on average to hit one") or "")
					.. "\n\n" .. round.length .. " seconds  ·  " .. round.size .. "  ·  " .. round.speed .. "  ·  best " .. math.max(best, round.score)
				startButton.Text = "Again"
				overlay.Visible = true
				countdown.Visible = false
				showStats()
			end
			-- A new target somewhere in the play area clear of the others. True if there was room.
			local function spawnTarget()
				local size = sizes[round.size]
				local areaSize = area.AbsoluteSize
				local margin = size / 2 + 4
				if areaSize.X < margin * 2 + 10 or areaSize.Y < margin * 2 + 10 then return false end
				local spot = nil
				for _ = 1, 12 do
					spot = Vector2.new(margin + math.random() * (areaSize.X - margin * 2), margin + math.random() * (areaSize.Y - margin * 2))
					local clear = true
					for _, other in ipairs(round.targets) do
						if (spot - other.spot).Magnitude < size * 1.3 then clear = false end
					end
					if clear then break end
				end
				local button = Instance.new("TextButton")
				button.AnchorPoint = Vector2.new(0.5, 0.5)
				button.Position = UDim2.fromOffset(spot.X, spot.Y)
				button.Size = UDim2.fromOffset(size, size)
				button.AutoButtonColor = false
				button.BorderSizePixel = 0
				button.Text = ""
				button.ZIndex = 3
				button.BackgroundColor3 = auxiliaryUiTheme.Accent
				button.Parent = area
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(0.5, 0)
				corner.Parent = button
				local dot = Instance.new("Frame")
				dot.AnchorPoint = Vector2.new(0.5, 0.5)
				dot.Position = UDim2.fromScale(0.5, 0.5)
				dot.Size = UDim2.fromScale(0.4, 0.4)
				dot.BorderSizePixel = 0
				dot.BackgroundColor3 = auxiliaryUiTheme.OnAccent
				dot.ZIndex = 4
				dot.Parent = button
				local dotCorner = Instance.new("UICorner")
				dotCorner.CornerRadius = UDim.new(0.5, 0)
				dotCorner.Parent = dot
				local target = { button = button, born = os.clock(), spot = spot, size = size }
				table.insert(round.targets, target)
				button.MouseButton1Down:Connect(function()
					local index = table.find(round.targets, target)
					if not round.running or not index then return end
					local age = os.clock() - target.born
					table.remove(round.targets, index)
					round.lastHitAt = os.clock()
					round.clicks += 1
					round.hits += 1
					round.score += 50 + math.floor(50 * math.clamp(1 - age / speeds[round.speed].life, 0, 1) + 0.5)
					round.reactionTotal += age
					-- A quick pop as it goes.
					local pop = TweenInfo.new(0.12)
					TweenService:Create(button, pop, { Size = UDim2.fromOffset(button.Size.X.Offset * 1.4, button.Size.Y.Offset * 1.4), BackgroundTransparency = 1 }):Play()
					TweenService:Create(dot, pop, { BackgroundTransparency = 1 }):Play()
					task.delay(0.13, function() button:Destroy() end)
					showStats()
				end)
				return true
			end
			-- A miss, unless the same click hit a target (on some setups a click on a target reaches the
			-- play area under it too).
			area.MouseButton1Down:Connect(function()
				if not round.running then return end
				local clickedAt = os.clock()
				task.defer(function()
					if not round.running or math.abs(round.lastHitAt - clickedAt) < 0.05 then return end
					round.clicks += 1
					showStats()
				end)
			end)
			-- 3, 2, 1, then targets until the time's up.
			local function start()
				round.serial += 1
				local serial = round.serial
				clearTargets()
				round.running = false
				round.length = featureSettings.aimTrainerLength
				round.size = sizes[featureSettings.aimTrainerSize] and featureSettings.aimTrainerSize or "Medium"
				round.speed = speeds[featureSettings.aimTrainerSpeed] and featureSettings.aimTrainerSpeed or "Normal"
				round.score, round.hits, round.clicks, round.missed, round.reactionTotal = 0, 0, 0, 0, 0
				overlay.Visible = false
				showStats()
				task.spawn(function()
					countdown.Visible = true
					for count = 3, 1, -1 do
						countdown.Text = tostring(count)
						task.wait(0.6)
						if round.serial ~= serial then return end
					end
					countdown.Visible = false
					local speed = speeds[round.speed]
					round.endsAt = os.clock() + round.length
					round.running = true
					while round.serial == serial do
						local now = os.clock()
						if now >= round.endsAt then return finish(true) end
						-- Each target shrinks to a quarter of its size, then it's gone.
						for index = #round.targets, 1, -1 do
							local target = round.targets[index]
							local left = 1 - (now - target.born) / speed.life
							if left <= 0 then
								target.button:Destroy()
								table.remove(round.targets, index)
								round.missed += 1
							else
								local size = target.size * (0.25 + 0.75 * left)
								target.button.Size = UDim2.fromOffset(size, size)
							end
						end
						for _ = #round.targets + 1, speed.count do
							if not spawnTarget() then break end
						end
						showStats()
						RunService.Heartbeat:Wait()
					end
				end)
			end
			startButton.MouseButton1Click:Connect(start)

			menuModules.aimTrainer = {
				setShown = function(on)
					trainerWindow.setShown(on)
					-- Closing it stops a round partway through.
					if not on and (round.running or countdown.Visible) then finish(false) end
				end,
			}
			showIntro()

			local entry = quickToggleByName["Aim Trainer"]
			local card = entry and createSettingsCard(entry)
			if not card then return end
			local function changed()
				saveFeatureSettings()
				if not round.running and not countdown.Visible and startButton.Text == "Start" then showIntro() end
			end
			card.addSectionLabel("ROUND", "timer", "clock")
			card.addChoice({ "15 s", "30 s", "60 s" }, function() return featureSettings.aimTrainerLength .. " s" end, function(choice)
				featureSettings.aimTrainerLength = tonumber((choice:gsub(" s", ""))) or 30
				changed()
			end)
			card.addSectionLabel("TARGET SIZE", "target")
			card.addChoice({ "Small", "Medium", "Large" }, function() return featureSettings.aimTrainerSize end, function(size)
				featureSettings.aimTrainerSize = size
				changed()
			end)
			card.addSectionLabel("SPEED", "gauge")
			card.addChoice({ "Easy", "Normal", "Hard" }, function() return featureSettings.aimTrainerSpeed end, function(speed)
				featureSettings.aimTrainerSpeed = speed
				changed()
			end)
			card.addHint(function()
				if featureSettings.aimTrainerSpeed == "Easy" then return "One target at a time, lasting 2.2 seconds." end
				if featureSettings.aimTrainerSpeed == "Hard" then return "Three targets at a time, lasting a second each." end
				return "Two targets at a time, lasting 1.5 seconds each."
			end)
			card.addHint("Your best score is kept for each mix of these. A round in play keeps the settings it started with.")
			card.refresh()
		end)

		------------------------------------------------------------------------------------------
		-- Weather: rain, snow, fog or a thunderstorm, on your screen alone, as heavy as its settings card
		-- says. Rain and snow fall from a sheet that follows your camera, so they fall indoors too. Fog
		-- thickens the game's own haze (or adds some where it has none), and a storm is heavy rain under a
		-- darker sky with lightning flashing now and then. It all goes when it's switched off, and the
		-- game's haze goes back to how it was.
		safeBuild("Weather", function()
			local styles = { "Rain", "Snow", "Fog", "Storm" }
			-- sky: the sheet the rain or snow falls from. fog: the Atmosphere being used, ownFog whether
			-- it's one made here, savedFog the game's settings for it. shade: a storm's darker sky.
			local state = { on = false, loop = nil, sky = nil, emitter = nil, fog = nil, ownFog = false, savedFog = nil, shade = nil, nextFlash = 0, flashes = {} }
			local fogProperties = { "Density", "Offset", "Color", "Decay", "Glare", "Haze" }
			local function styleOf()
				return table.find(styles, featureSettings.weatherStyle) and featureSettings.weatherStyle or "Rain"
			end
			-- The fog at this density and haze, or none with no density.
			local function setFog(density, haze)
				if not density then
					if state.fog and state.ownFog then
						pcall(function() state.fog:Destroy() end)
					elseif state.fog and state.savedFog and state.fog.Parent then
						for property, value in pairs(state.savedFog) do
							pcall(function() state.fog[property] = value end)
						end
					end
					state.fog, state.ownFog, state.savedFog = nil, false, nil
					return
				end
				if not state.fog or not state.fog.Parent then
					local existing = Lighting:FindFirstChildOfClass("Atmosphere")
					if existing then
						state.fog, state.ownFog, state.savedFog = existing, false, {}
						for _, property in ipairs(fogProperties) do state.savedFog[property] = existing[property] end
					else
						local made = Instance.new("Atmosphere")
						made.Name = "SpreadCheeksWeatherFog"
						made.Parent = Lighting
						state.fog, state.ownFog, state.savedFog = made, true, nil
					end
				end
				local fog = state.fog
				fog.Density = density
				fog.Offset = 0
				fog.Haze = haze
				fog.Glare = 0
				fog.Color = Color3.fromRGB(199, 203, 210)
				fog.Decay = Color3.fromRGB(92, 100, 115)
			end
			local function setShade(on)
				if not on then
					if state.shade then pcall(function() state.shade:Destroy() end) end
					state.shade = nil
					return
				end
				if not state.shade or not state.shade.Parent then
					local shade = Instance.new("ColorCorrectionEffect")
					shade.Name = "SpreadCheeksWeatherStorm"
					shade.Parent = Lighting
					state.shade = shade
				end
				state.shade.Brightness = -0.08
				state.shade.Contrast = 0.1
				state.shade.Saturation = -0.35
				state.shade.TintColor = Color3.fromRGB(196, 206, 224)
			end
			-- Rain or snow falling round your camera, or none with no style.
			local function setFall(style)
				if not style then
					if state.sky then pcall(function() state.sky:Destroy() end) end
					state.sky, state.emitter = nil, nil
					return
				end
				if not state.sky or not state.sky.Parent then
					local sky = Instance.new("Part")
					sky.Name = "SpreadCheeksWeather"
					sky.Anchored = true
					sky.CanCollide = false
					sky.CanQuery = false
					sky.CanTouch = false
					sky.CastShadow = false
					sky.Transparency = 1
					sky.Size = Vector3.new(160, 1, 160)
					local emitter = Instance.new("ParticleEmitter")
					emitter.Name = "SpreadCheeksWeatherFall"
					emitter.EmissionDirection = Enum.NormalId.Bottom
					emitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
					emitter.Parent = sky
					sky.Parent = workspace.CurrentCamera or workspace
					state.sky, state.emitter = sky, emitter
				end
				local amount = featureSettings.weatherAmount
				local emitter = state.emitter
				if style == "Snow" then
					-- Little white flakes drifting down, turning as they go.
					emitter.Color = ColorSequence.new(Color3.new(1, 1, 1))
					emitter.LightEmission = 0.3
					emitter.Transparency = NumberSequence.new(0.1)
					emitter.Size = NumberSequence.new(0.3)
					emitter.Squash = NumberSequence.new(0)
					emitter.Orientation = Enum.ParticleOrientation.FacingCamera
					emitter.Speed = NumberRange.new(6, 9)
					emitter.Lifetime = NumberRange.new(7, 9)
					emitter.SpreadAngle = Vector2.new(30, 30)
					emitter.Acceleration = Vector3.new(1.5, -1, 0.8)
					emitter.Rotation = NumberRange.new(0, 360)
					emitter.RotSpeed = NumberRange.new(-60, 60)
					emitter.Rate = 30 * amount
					return
				end
				-- Rain: thin streaks falling fast, heavier and slanting in a storm.
				local storm = style == "Storm"
				emitter.Color = ColorSequence.new(Color3.fromRGB(196, 212, 235))
				emitter.LightEmission = 0.15
				emitter.Transparency = NumberSequence.new(0.45)
				emitter.Size = NumberSequence.new(0.12)
				emitter.Squash = NumberSequence.new(3)
				emitter.Orientation = Enum.ParticleOrientation.VelocityParallel
				emitter.Speed = storm and NumberRange.new(95, 110) or NumberRange.new(75, 90)
				emitter.Lifetime = NumberRange.new(1.1, 1.4)
				emitter.SpreadAngle = storm and Vector2.new(8, 8) or Vector2.new(3, 3)
				emitter.Acceleration = storm and Vector3.new(6, -20, 3) or Vector3.new(0, -20, 0)
				emitter.Rotation = NumberRange.new(0)
				emitter.RotSpeed = NumberRange.new(0)
				emitter.Rate = (storm and 110 or 60) * amount
			end
			local function apply()
				local style = state.on and styleOf() or nil
				local amount = featureSettings.weatherAmount
				setFall(style ~= "Fog" and style or nil)
				if style == "Fog" then
					setFog(0.3 + 0.05 * amount, 1 + 0.2 * amount)
				elseif style == "Storm" then
					setFog(0.3 + 0.02 * amount, 1)
				else
					setFog(nil)
				end
				setShade(style == "Storm")
			end
			-- Every frame: the sheet over your camera (a little ahead of it), and a storm's lightning, a
			-- double flash every few seconds.
			local function step()
				local camera = workspace.CurrentCamera
				if state.sky and camera then
					if state.sky.Parent ~= camera then state.sky.Parent = camera end
					local look = camera.CFrame.LookVector
					local ahead = Vector3.new(look.X, 0, look.Z)
					ahead = ahead.Magnitude > 0.05 and ahead.Unit * 25 or Vector3.zero
					state.sky.CFrame = CFrame.new(camera.CFrame.Position + ahead + Vector3.new(0, 40, 0))
				end
				if state.shade then
					local now = os.clock()
					if now >= state.nextFlash then
						state.nextFlash = now + 4 + math.random() * 8
						state.flashes = { now, now + 0.16 }
					end
					local flashing = false
					for _, at in ipairs(state.flashes) do
						if now >= at and now < at + 0.07 then flashing = true end
					end
					state.shade.Brightness = flashing and 0.45 or -0.08
				end
			end
			local function setEnabled(on)
				state.on = on
				if on and styleOf() ~= "Rain" and styleOf() ~= "Snow" then
					-- Fog and No Fog would undo each other, so No Fog goes off while there's fog.
					local noFog = quickToggleByName["No Fog"]
					if noFog and noFog.state then
						setQuickToggle(noFog, false)
						notify("Weather", "No Fog is off while there's fog.", 3)
					end
				end
				apply()
				if state.loop then
					state.loop:Disconnect()
					state.loop = nil
				end
				if on then
					state.nextFlash = os.clock() + 3
					state.loop = RunService.RenderStepped:Connect(step)
				end
			end
			menuModules.weather = {
				setEnabled = setEnabled,
				-- After the style or amount changes.
				refresh = function()
					if state.on then setEnabled(true) end
				end,
			}

			local entry = quickToggleByName["Weather"]
			local card = entry and createSettingsCard(entry)
			if not card then return end
			card.addSectionLabel("WEATHER", "cloud-rain", "cloud")
			card.addChoice(styles, styleOf, function(style)
				featureSettings.weatherStyle = style
				saveFeatureSettings()
				menuModules.weather.refresh()
			end)
			card.addHint(function()
				local style = styleOf()
				if style == "Snow" then return "Snowflakes drifting down all round you." end
				if style == "Fog" then return "Thick fog, as if a cloud's come down. No Fog goes off while it's on." end
				if style == "Storm" then return "Heavy rain under a dark sky, with lightning every few seconds." end
				return "Rain pouring down all round you."
			end)
			card.addSectionLabel("HOW HEAVY", "gauge")
			card.addSlider({
				text = "Amount",
				icon = { "gauge", "cloud" },
				min = 1, max = 10, step = 1,
				get = function() return featureSettings.weatherAmount end,
				set = function(value)
					featureSettings.weatherAmount = value
					menuModules.weather.refresh()
				end,
				commit = saveFeatureSettings,
				format = function(value) return tostring(math.floor(value + 0.5)) end,
			})
			card.addHint("Only you see it. Rain and snow fall indoors too, as they can't tell where the roofs are.")
			card.refresh()
		end)

		------------------------------------------------------------------------------------------
		-- Graphics Presets: makes the game look better on your screen, with Roblox's own post effects
		-- (bloom, sun rays, colour correction and depth of field) set up in the style picked in its
		-- settings card, as strong as the card says. They go on top of the game's own and are taken away
		-- again when it's switched off; nothing of the game's is changed.
		safeBuild("Graphics Presets", function()
			-- bloom: intensity, size, threshold. rays: intensity, spread. color: brightness, contrast,
			-- saturation and tint. focus: far blur, focus distance, in-focus radius.
			local presets = {
				{ name = "Cinematic", bloom = { 0.5, 24, 1.2 }, rays = { 0.06, 0.6 }, color = { 0.02, 0.18, 0.12, Color3.fromRGB(255, 244, 232) }, focus = { 0.25, 40, 50 },
					hint = "A soft glow, sun rays and richer contrast, with faraway things a touch blurred, like a film." },
				{ name = "Vibrant", bloom = { 0.4, 20, 1.4 }, rays = { 0.05, 0.5 }, color = { 0.03, 0.12, 0.45 },
					hint = "Bright, punchy colours." },
				{ name = "Warm", bloom = { 0.3, 24, 1.3 }, rays = { 0.08, 0.7 }, color = { 0.03, 0.05, 0.1, Color3.fromRGB(255, 226, 196) },
					hint = "A golden, late-afternoon glow." },
				{ name = "Cold", bloom = { 0.25, 20, 1.5 }, color = { 0, 0.08, -0.1, Color3.fromRGB(205, 225, 255) },
					hint = "Cool blue tones, like a winter morning." },
				{ name = "Black & White", color = { 0, 0.2, -1 },
					hint = "No colour at all, with a little extra contrast." },
				{ name = "Vintage", bloom = { 0.3, 30, 1.2 }, color = { 0.02, -0.05, -0.4, Color3.fromRGB(255, 224, 178) },
					hint = "Faded, sepia colours, like an old photo." },
				{ name = "Dreamy", bloom = { 1, 40, 0.9 }, rays = { 0.1, 0.8 }, color = { 0.05, -0.05, 0.15, Color3.fromRGB(255, 236, 250) }, focus = { 0.4, 30, 30 },
					hint = "A strong soft glow, with the distance in a haze." },
				{ name = "Night Vision", bloom = { 0.6, 18, 1 }, color = { 0.15, 0.25, -1, Color3.fromRGB(120, 255, 140) },
					hint = "Bright green, like night-vision goggles." },
			}
			local function presetNamed(name)
				for _, preset in ipairs(presets) do
					if preset.name == name then return preset end
				end
				return presets[1]
			end
			-- A style from a typed name, ignoring case, spaces and punctuation, for the graphics command.
			local aliases = { bw = "Black & White", blackandwhite = "Black & White", greyscale = "Black & White", grayscale = "Black & White", nv = "Night Vision" }
			local function styleNamed(text)
				local wanted = tostring(text or ""):lower():gsub("[%s%p]", "")
				if wanted == "" then return nil end
				if aliases[wanted] then return aliases[wanted] end
				for pass = 1, 2 do
					for _, preset in ipairs(presets) do
						local simple = preset.name:lower():gsub("[%s%p]", "")
						if simple == wanted or (pass == 2 and simple:sub(1, #wanted) == wanted) then return preset.name end
					end
				end
				return nil
			end
			local state = { on = false, effects = {}, serial = 0 }
			-- The effect of this kind made here, made if it isn't there yet (or the game took it away).
			local function effect(kind, className)
				local made = state.effects[kind]
				if made and made.Parent then return made end
				made = Instance.new(className)
				made.Name = "SpreadCheeksGraphics" .. kind
				made.Parent = Lighting
				state.effects[kind] = made
				return made
			end
			local function drop(kind)
				local made = state.effects[kind]
				if made then pcall(function() made:Destroy() end) end
				state.effects[kind] = nil
			end
			local function apply()
				if not state.on then
					for _, kind in ipairs({ "Bloom", "SunRays", "Color", "Focus" }) do drop(kind) end
					return
				end
				local preset = presetNamed(featureSettings.graphicsStyle)
				local strength = featureSettings.graphicsStrength / 100
				if preset.bloom then
					local bloom = effect("Bloom", "BloomEffect")
					bloom.Intensity = preset.bloom[1] * strength
					bloom.Size = preset.bloom[2]
					bloom.Threshold = preset.bloom[3]
				else
					drop("Bloom")
				end
				if preset.rays then
					local rays = effect("SunRays", "SunRaysEffect")
					rays.Intensity = preset.rays[1] * strength
					rays.Spread = preset.rays[2]
				else
					drop("SunRays")
				end
				local color = effect("Color", "ColorCorrectionEffect")
				color.Brightness = preset.color[1] * strength
				color.Contrast = preset.color[2] * strength
				color.Saturation = preset.color[3] * strength
				color.TintColor = Color3.new(1, 1, 1):Lerp(preset.color[4] or Color3.new(1, 1, 1), strength)
				if preset.focus then
					local focus = effect("Focus", "DepthOfFieldEffect")
					focus.FarIntensity = preset.focus[1] * strength
					focus.FocusDistance = preset.focus[2]
					focus.InFocusRadius = preset.focus[3]
					focus.NearIntensity = 0
				else
					drop("Focus")
				end
			end
			local function setEnabled(on)
				state.on = on
				state.serial += 1
				apply()
				if not on then return end
				-- Put back now and then, in case the game clears the lighting's effects.
				local serial = state.serial
				task.spawn(function()
					while state.serial == serial do
						task.wait(2)
						if state.serial ~= serial then return end
						for _, made in pairs(state.effects) do
							if not made.Parent then
								pcall(apply)
								break
							end
						end
					end
				end)
			end
			menuModules.graphicsPresets = {
				setEnabled = setEnabled,
				styleNamed = styleNamed,
				refresh = function() pcall(apply) end,
			}

			local entry = quickToggleByName["Graphics Presets"]
			local card = entry and createSettingsCard(entry)
			if not card then return end
			card.addSectionLabel("STYLE", "palette", "sparkles")
			-- Two rows of four, both for the one setting.
			for row = 1, 2 do
				local options = {}
				for index = row * 4 - 3, row * 4 do table.insert(options, presets[index].name) end
				card.addChoice(options, function() return presetNamed(featureSettings.graphicsStyle).name end, function(name)
					featureSettings.graphicsStyle = name
					saveFeatureSettings()
					apply()
				end)
			end
			card.addHint(function() return presetNamed(featureSettings.graphicsStyle).hint end)
			card.addSectionLabel("STRENGTH", "gauge")
			card.addSlider({
				text = "Strength",
				icon = { "gauge", "sun" },
				min = 10, max = 100, step = 5,
				get = function() return featureSettings.graphicsStrength end,
				set = function(value)
					featureSettings.graphicsStrength = value
					apply()
				end,
				commit = saveFeatureSettings,
				format = function(value) return math.floor(value + 0.5) .. "%" end,
			})
			card.addHint("Only you see it. It goes on top of the game's own look and comes off cleanly.")
			card.refresh()
		end)

		------------------------------------------------------------------------------------------
		-- Panic: switches everything off at once, from its key (End to start with) or its switch: every
		-- switch that changes your character, the world or your screen, and the aimbot. Its settings card
		-- says what else it does: hide the menu, its windows and Infinite Yield's bar; put your walk speed,
		-- jump, gravity and camera back to normal (which stops spectating, flying and emotes too); and
		-- leave the game. Your safety switches, alerts, Streamer Mode and the menu's windows and settings
		-- stay as they are. Switching it off (its key again) brings the menu back and switches back on
		-- everything it switched off.
		safeBuild("Panic", function()
			local localPlayer = Players.LocalPlayer
			-- Left as they are: Panic itself, and the switches that keep you safe, tell you things, or are
			-- the menu's own windows and settings rather than tricks.
			local leaveAlone = {}
			for _, name in ipairs({
				"Panic", "Anti-Fling", "No Fall Damage", "Anti-AFK", "Anti-Void", "Auto Rejoin", "Cheater Detector", "Staff Watch",
				"Join Alerts", "Mention Alerts", "Performance Stats", "Radar", "Logs", "Favourites Bar", "Health & Ping Warnings",
				"Streamer Mode", "Clean Screen", "Ctrl+Click Select", "Troll Panel", "Spectate Bar", "Zoom Key", "Time of Day",
				"FPS Boost", "Mute Game Music", "Mute Player Sounds", "First Person", "Weather", "Graphics Presets", "Emote Wheel",
				"Session Stats", "Aim Warning", "Spotify",
			}) do
				leaveAlone[name] = true
			end
			-- switchedOff: the switches it switched off, to switch back on. hidden: the screens it hid.
			local panic = { switchedOff = {}, aimbot = false, hidden = {}, menuWasShown = false, gravity = workspace.Gravity }
			-- What the game gave each character: its walk speed and jump, noted a moment after it spawns.
			local spawnValues = setmetatable({}, { __mode = "k" })
			local function noteSpawn(character)
				local humanoid = character:WaitForChild("Humanoid", 10)
				if not humanoid then return end
				task.wait(1)
				if spawnValues[humanoid] == nil and humanoid.Parent then
					spawnValues[humanoid] = { WalkSpeed = humanoid.WalkSpeed, JumpPower = humanoid.JumpPower, JumpHeight = humanoid.JumpHeight }
				end
			end
			if localPlayer.Character then task.spawn(noteSpawn, localPlayer.Character) end
			localPlayer.CharacterAdded:Connect(noteSpawn)

			-- Quietly: the switches going off don't each pop up a notification over the game.
			local function quietly(work)
				local speak = notify
				notify = function() end
				local worked, problem = pcall(work)
				notify = speak
				if not worked then warn("[SpreadCheeksGUI] Panic: " .. tostring(problem)) end
			end
			-- The menu, its windows and Infinite Yield's bar, hidden, and noted so they come back.
			local function hideMenu()
				table.clear(panic.hidden)
				local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui")
				local hiddenOk, hiddenGui = false, nil
				if type(gethui) == "function" then hiddenOk, hiddenGui = pcall(gethui) end
				local menuGui = typeof(window.main) == "Instance" and window.main:FindFirstAncestorWhichIsA("LayerCollector") or nil
				for _, container in ipairs({ playerGui, COREGUI, hiddenOk and hiddenGui or nil }) do
					local listOk, children = pcall(function() return container:GetChildren() end)
					for _, gui in ipairs(listOk and children or {}) do
						if gui:IsA("ScreenGui") and gui.Enabled and gui ~= menuGui and gui.Name:sub(1, 12) == "SpreadCheeks" and not table.find(panic.hidden, gui) then
							gui.Enabled = false
							table.insert(panic.hidden, gui)
						end
					end
				end
				if typeof(PARENT) == "Instance" and PARENT:IsA("ScreenGui") and PARENT.Enabled and PARENT.Name ~= "RobloxGui" then
					PARENT.Enabled = false
					table.insert(panic.hidden, PARENT)
				end
				panic.menuWasShown = not window.hidden
				if panic.menuWasShown then pcall(function() window:ToggleHide() end) end
			end
			local function showMenu()
				for _, gui in ipairs(panic.hidden) do
					-- A window that was switched off meanwhile has faded right out, so it stays hidden.
					local panel = gui.Parent and gui:FindFirstChild("Window")
					local faded = panel ~= nil and panel:IsA("GuiObject") and panel.BackgroundTransparency > 0.99
					if gui.Parent and not faded then gui.Enabled = true end
				end
				table.clear(panic.hidden)
				if panic.menuWasShown and window.hidden then pcall(function() window:Show() end) end
				panic.menuWasShown = false
			end
			-- Your walk speed, jump, gravity and camera as the game had them, and nothing still moving you:
			-- no spectating (stopped as Infinite Yield's unview does, without its message), no flying, no
			-- emotes, no sitting or lying where there's no seat.
			local function backToNormal()
				if viewing ~= nil then
					viewing = nil
					if viewDied then pcall(function() viewDied:Disconnect() end) end
					if viewChanged then pcall(function() viewChanged:Disconnect() end) end
				end
				if FLYING and type(NOFLY) == "function" then pcall(NOFLY) end
				if trolling.stopAnimations then pcall(trolling.stopAnimations) end
				workspace.Gravity = panic.gravity
				local character = localPlayer.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				if humanoid then
					for property, value in pairs(spawnValues[humanoid] or {}) do
						pcall(function() humanoid[property] = value end)
					end
					if not humanoid.SeatPart then
						humanoid.Sit = false
						humanoid.PlatformStand = false
					end
				end
				local camera = workspace.CurrentCamera
				if camera then
					camera.CameraType = Enum.CameraType.Custom
					if humanoid then camera.CameraSubject = humanoid end
					camera.FieldOfView = 70
				end
			end
			local function setEnabled(on)
				if on then
					table.clear(panic.switchedOff)
					if featureSettings.panicHide then hideMenu() end
					quietly(function()
						for _, entry in ipairs(quickToggles) do
							if entry.state and not leaveAlone[entry.name] then
								table.insert(panic.switchedOff, entry)
								pcall(setQuickToggle, entry, false)
							end
						end
						panic.aimbot = aimbotState.enabled
						if aimbotState.enabled then
							applyAimbot(false)
							pcall(function() aimbotToggle:Set(false, true) end)
						end
						if featureSettings.panicReset then backToNormal() end
					end)
					if featureSettings.panicLeave then
						-- Auto Rejoin would only bring you straight back, so it stops listening first.
						if menuModules.autoRejoin then pcall(menuModules.autoRejoin.setEnabled, false) end
						task.delay(0.2, function() localPlayer:Kick("You left the game.") end)
						return
					end
					if not featureSettings.panicHide then
						local count = #panic.switchedOff + (panic.aimbot and 1 or 0)
						notify("Panic", count .. (count == 1 and " thing" or " things") .. " switched off. Switch Panic off to put them back.", 3)
					end
					return
				end
				-- Back again: everything it switched off goes back on, then the menu comes back.
				local count = #panic.switchedOff + (panic.aimbot and 1 or 0)
				for _, entry in ipairs(panic.switchedOff) do
					if not entry.state then pcall(setQuickToggle, entry, true) end
				end
				table.clear(panic.switchedOff)
				if panic.aimbot and not aimbotState.enabled then
					applyAimbot(true)
					pcall(function() aimbotToggle:Set(true, true) end)
				end
				panic.aimbot = false
				showMenu()
				notify("Panic", count > 0 and ("Put back " .. count .. (count == 1 and " thing" or " things")) or "Nothing to put back", 2)
			end
			menuModules.panic = { setEnabled = setEnabled }

			-- End the first time, unless something else already has it. Taken off later, it stays off.
			local entry = quickToggleByName["Panic"]
			if entry and not featureSettings.panicKeySet then
				featureSettings.panicKeySet = true
				saveFeatureSettings()
				local taken = isMenuToggleKey(Enum.KeyCode.End)
				for _, other in ipairs(quickToggles) do
					if other.key == Enum.KeyCode.End then taken = true end
				end
				for _, other in ipairs(quickActions) do
					if other.key == Enum.KeyCode.End then taken = true end
				end
				if not taken and not entry.key then
					entry.key = Enum.KeyCode.End
					refreshKeyChip(entry)
					saveQuickKeybinds()
				end
			end

			local card = entry and createSettingsCard(entry)
			if not card then return end
			card.addSectionLabel("WHEN YOU PANIC", "siren", "octagon-alert")
			card.addSwitchGrid({
				{
					text = "Hide the menu",
					get = function() return featureSettings.panicHide == true end,
					set = function(on)
						featureSettings.panicHide = on
						saveFeatureSettings()
					end,
				},
				{
					text = "Back to normal",
					get = function() return featureSettings.panicReset == true end,
					set = function(on)
						featureSettings.panicReset = on
						saveFeatureSettings()
					end,
				},
				{
					text = "Leave the game",
					get = function() return featureSettings.panicLeave == true end,
					set = function(on)
						featureSettings.panicLeave = on
						saveFeatureSettings()
					end,
				},
			}, 1)
			card.addHint("Every switch that changes you, the world or your screen goes off, and the aimbot. Your safety switches, alerts, Streamer Mode and the menu's windows stay as they are. Switch Panic off (its key again) to put it all back.")
			card.addHint("Hide the menu hides it, its windows and Infinite Yield's bar. Back to normal puts your speed, jump, gravity and camera back, and stops spectating, flying and emotes. Leave the game leaves straight after, so nothing is put back.")
			card.refresh()
		end)

		------------------------------------------------------------------------------------------
		-- Waddles, Cartwheels and Colours (28 October 2026). Each part is built on its own; their
		-- switches and buttons are made with the others further up.

		------------------------------------------------------------------------------------------
		-- Auto Go Back: once you respawn after dying, you're taken back to where you died (flown there
		-- with Safe Teleport on), after the wait in its settings card. Not when you died over the void,
		-- where there's no floor to stand on, and not twice running to the same spot, so somewhere that
		-- kills you can't keep you dying.
		safeBuild("Auto Go Back", function()
			local localPlayer = Players.LocalPlayer
			-- diedAt: where you died, waiting for the respawn. lastSpot and lastTime: where it last took
			-- you back to, and when.
			local state = { on = false, diedAt = nil, serial = 0, lastSpot = nil, lastTime = 0 }
			local floorParams = RaycastParams.new()
			floorParams.FilterType = Enum.RaycastFilterType.Exclude
			local function watch(character)
				local humanoid = character:WaitForChild("Humanoid", 10)
				if not humanoid then return end
				humanoid.Died:Connect(function()
					local root = getRoot(character)
					state.diedAt = root and root.Position or nil
				end)
			end
			local function comeBack(character, spot)
				state.serial += 1
				local serial = state.serial
				local root = character:WaitForChild("HumanoidRootPart", 10)
				if not root then return end
				task.wait(featureSettings.autoGoBackWait)
				if state.serial ~= serial or not state.on or localPlayer.Character ~= character or not root.Parent then return end
				-- The floor under where you died, to stand on.
				floorParams.FilterDescendantsInstances = { character }
				local floor = workspace:Raycast(spot + Vector3.new(0, 4, 0), Vector3.new(0, -200, 0), floorParams)
				if not floor then return notify("Auto Go Back", "You died over the void, so you're staying where you respawned.", 3) end
				-- Died again right where it last took you: staying put, so it can't keep killing you.
				if state.lastSpot and (state.lastSpot - floor.Position).Magnitude < 10 and os.clock() - state.lastTime < 30 then
					state.lastSpot = nil
					return notify("Auto Go Back", "You died there again, so you're staying where you respawned this time.", 4)
				end
				state.lastSpot, state.lastTime = floor.Position, os.clock()
				if menuModules.teleportTo then
					menuModules.teleportTo(CFrame.new(floor.Position + Vector3.new(0, 3.5, 0)) * root.CFrame.Rotation, true)
					notify("Auto Go Back", "Back where you died", 2)
				end
			end
			if localPlayer.Character then task.spawn(watch, localPlayer.Character) end
			localPlayer.CharacterAdded:Connect(function(character)
				task.spawn(watch, character)
				local spot = state.diedAt
				state.diedAt = nil
				if state.on and spot then task.spawn(comeBack, character, spot) end
			end)
			menuModules.autoGoBack = {
				setEnabled = function(on) state.on = on end,
			}

			local entry = quickToggleByName["Auto Go Back"]
			local card = entry and createSettingsCard(entry)
			if not card then return end
			card.addSectionLabel("WAIT", "timer")
			card.addSlider({
				text = "Wait after respawning",
				icon = { "timer", "clock" },
				min = 0, max = 5, step = 0.5,
				get = function() return featureSettings.autoGoBackWait end,
				set = function(value) featureSettings.autoGoBackWait = value end,
				commit = saveFeatureSettings,
				format = function(value) return string.format("%.1f s", value) end,
			})
			card.addHint("With Safe Teleport on, it flies you there. It won't take you back over the void, or to the same spot twice running, so somewhere that kills you can't keep you dying.")
			card.refresh()
		end)

		------------------------------------------------------------------------------------------
		-- Custom Theme: a window to pick the Custom theme's two colours, an accent and a background, from
		-- swatches or as hex codes. Picking one switches the menu to the Custom theme and shows it at once;
		-- the rest of its colours are worked out from those two (see "Custom:" with the other themes).
		-- Random picks a pair for you, and Reset goes back to SpreadCheeks' own.
		safeBuild("Custom Theme", function()
			local custom = paletteNamed("Custom")
			if not custom then return end
			local makerWindow = menuModules.makeWindow({
				name = "SpreadCheeksThemeMaker", title = "Custom Theme", icons = { "palette", "paintbrush" },
				width = 330, height = 380, xKey = "themeMakerX", yKey = "themeMakerY",
				defaultPosition = function(screen, size) return screen.X - size.X - 24, (screen.Y - size.Y) / 2 end,
			})
			local accents = {
				"897AEF", "6366F1", "3B82F6", "0EA5E9", "06B6D4", "14B8A6", "22C55E", "84CC16",
				"EAB308", "F59E0B", "F97316", "EF4444", "F43F5E", "EC4899", "D946EF", "A855F7",
			}
			-- Eight dark backgrounds, then four light ones, which make it a light theme.
			local backgrounds = {
				"0E1016", "101012", "0B1220", "0F172A", "111827", "1A1025", "10180F", "1C1410",
				"F3F3F6", "F0F5F9", "FBF2F6", "FFFFFF",
			}
			-- A hex code in capitals without its #, from "#ff4d6d", "FF4D6D" or "f4d"; nil if it isn't one.
			local function cleanHex(text)
				local digits = tostring(text or ""):gsub("[#%s]", ""):upper()
				if digits:match("^%x%x%x%x%x%x$") then return digits end
				if digits:match("^%x%x%x$") then return (digits:gsub("(%x)", "%1%1")) end
				return nil
			end
			local refreshers = {}
			local function refreshAll()
				for _, refresh in ipairs(refreshers) do refresh() end
			end
			-- The menu in the Custom theme, with the colours as they are now.
			local function use()
				custom.refresh()
				saveFeatureSettings()
				applyTheme(custom)
				pcall(function() themeDropdown:Set("Custom", true) end)
				refreshAll()
			end

			local list = Instance.new("Frame")
			list.Size = UDim2.fromScale(1, 1)
			list.BackgroundTransparency = 1
			list.Parent = makerWindow.body
			local listLayout = Instance.new("UIListLayout")
			listLayout.Padding = UDim.new(0, 6)
			listLayout.SortOrder = Enum.SortOrder.LayoutOrder
			listLayout.Parent = list
			local listPadding = Instance.new("UIPadding")
			listPadding.PaddingLeft = UDim.new(0, 12)
			listPadding.PaddingRight = UDim.new(0, 12)
			listPadding.PaddingTop = UDim.new(0, 4)
			listPadding.Parent = list
			local order = 0
			local function nextOrder()
				order += 1
				return order
			end
			local function heading(text)
				local label = Instance.new("TextLabel")
				label.LayoutOrder = nextOrder()
				label.Size = UDim2.new(1, 0, 0, 14)
				label.BackgroundTransparency = 1
				label.Font = Enum.Font.GothamBold
				label.Text = text
				label.TextSize = 10
				label.TextXAlignment = Enum.TextXAlignment.Left
				bindAuxiliaryUiColor(label, "TextColor3", "Muted")
				label.Parent = list
			end
			-- A grid of colours for featureSettings[key]; the one in use has a ring round it.
			local function swatches(colors, columns, key)
				local grid = Instance.new("Frame")
				grid.LayoutOrder = nextOrder()
				grid.Size = UDim2.fromScale(1, 0)
				grid.AutomaticSize = Enum.AutomaticSize.Y
				grid.BackgroundTransparency = 1
				grid.Parent = list
				local gridLayout = Instance.new("UIGridLayout")
				gridLayout.CellSize = UDim2.new(1 / columns, -6 * (columns - 1) / columns, 0, 26)
				gridLayout.CellPadding = UDim2.fromOffset(6, 6)
				gridLayout.SortOrder = Enum.SortOrder.LayoutOrder
				gridLayout.Parent = grid
				local rings = {}
				for index, hex in ipairs(colors) do
					local swatch = Instance.new("TextButton")
					swatch.LayoutOrder = index
					swatch.AutoButtonColor = false
					swatch.BorderSizePixel = 0
					swatch.Text = ""
					swatch.BackgroundColor3 = Color3.fromHex(hex)
					swatch.Parent = grid
					local corner = Instance.new("UICorner")
					corner.CornerRadius = UDim.new(0, 7)
					corner.Parent = swatch
					local ring = Instance.new("UIStroke")
					ring.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
					ring.Thickness = 2
					ring.Parent = swatch
					rings[hex] = ring
					swatch.Activated:Connect(function()
						featureSettings[key] = hex
						use()
					end)
				end
				table.insert(refreshers, function()
					local current = cleanHex(featureSettings[key])
					for hex, ring in pairs(rings) do
						ring.Enabled = hex == current
						ring.Color = auxiliaryUiTheme.Text
					end
				end)
			end
			-- The colour in use and its hex code, which can be typed over.
			local function hexBox(key)
				local row = Instance.new("Frame")
				row.LayoutOrder = nextOrder()
				row.Size = UDim2.new(1, 0, 0, 28)
				row.BackgroundTransparency = 1
				row.Parent = list
				local preview = Instance.new("Frame")
				preview.Size = UDim2.fromOffset(28, 28)
				preview.BorderSizePixel = 0
				preview.Parent = row
				local previewCorner = Instance.new("UICorner")
				previewCorner.CornerRadius = UDim.new(0, 7)
				previewCorner.Parent = preview
				local previewStroke = Instance.new("UIStroke")
				previewStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				bindAuxiliaryUiColor(previewStroke, "Color", "Stroke")
				previewStroke.Parent = preview
				local box = Instance.new("TextBox")
				box.Position = UDim2.fromOffset(36, 0)
				box.Size = UDim2.new(1, -36, 1, 0)
				box.BorderSizePixel = 0
				box.ClearTextOnFocus = false
				box.Font = Enum.Font.GothamMedium
				box.PlaceholderText = "Hex code, like #FF4D6D"
				box.TextSize = 13
				box.TextXAlignment = Enum.TextXAlignment.Left
				bindAuxiliaryUiColor(box, "BackgroundColor3", "Inset")
				bindAuxiliaryUiColor(box, "TextColor3", "Text")
				bindAuxiliaryUiColor(box, "PlaceholderColor3", "Muted")
				box.Parent = row
				local boxCorner = Instance.new("UICorner")
				boxCorner.CornerRadius = UDim.new(0, 7)
				boxCorner.Parent = box
				local boxPadding = Instance.new("UIPadding")
				boxPadding.PaddingLeft = UDim.new(0, 8)
				boxPadding.Parent = box
				box.FocusLost:Connect(function()
					local hex = cleanHex(box.Text)
					if hex then
						featureSettings[key] = hex
						use()
					else
						refreshAll()
					end
				end)
				table.insert(refreshers, function()
					local hex = cleanHex(featureSettings[key]) or "000000"
					if not box:IsFocused() then box.Text = "#" .. hex end
					preview.BackgroundColor3 = Color3.fromHex(hex)
				end)
			end
			local function pairButton(texts, runs)
				local row = Instance.new("Frame")
				row.LayoutOrder = nextOrder()
				row.Size = UDim2.new(1, 0, 0, 28)
				row.BackgroundTransparency = 1
				row.Parent = list
				local rowLayout = Instance.new("UIListLayout")
				rowLayout.FillDirection = Enum.FillDirection.Horizontal
				rowLayout.Padding = UDim.new(0, 6)
				rowLayout.SortOrder = Enum.SortOrder.LayoutOrder
				rowLayout.Parent = row
				for index, text in ipairs(texts) do
					local button = Instance.new("TextButton")
					button.LayoutOrder = index
					button.Size = UDim2.new(1 / #texts, -6 * (#texts - 1) / #texts, 1, 0)
					button.AutoButtonColor = false
					button.BorderSizePixel = 0
					button.Font = Enum.Font.GothamMedium
					button.Text = text
					button.TextSize = 12
					bindAuxiliaryUiColor(button, "BackgroundColor3", "Inset")
					bindAuxiliaryUiColor(button, "TextColor3", "Text")
					button.Parent = row
					local corner = Instance.new("UICorner")
					corner.CornerRadius = UDim.new(0, 8)
					corner.Parent = button
					button.Activated:Connect(runs[index])
				end
			end

			heading("ACCENT")
			swatches(accents, 8, "customAccent")
			hexBox("customAccent")
			heading("BACKGROUND")
			swatches(backgrounds, 6, "customBackground")
			hexBox("customBackground")
			pairButton({ "Random", "Reset" }, {
				function()
					-- A bright accent, on a dark background three times in four and a light one otherwise.
					local accent = Color3.fromHSV(math.random(), 0.55 + math.random() * 0.3, 0.85 + math.random() * 0.15)
					local background = math.random() < 0.25
						and Color3.fromHSV(math.random(), 0.03 + math.random() * 0.05, 0.95 + math.random() * 0.04)
						or Color3.fromHSV(math.random(), 0.25 + math.random() * 0.3, 0.06 + math.random() * 0.06)
					featureSettings.customAccent = accent:ToHex():upper()
					featureSettings.customBackground = background:ToHex():upper()
					use()
				end,
				function()
					featureSettings.customAccent, featureSettings.customBackground = "897AEF", "0E1016"
					use()
				end,
			})
			local hint = Instance.new("TextLabel")
			hint.LayoutOrder = nextOrder()
			hint.Size = UDim2.fromScale(1, 0)
			hint.AutomaticSize = Enum.AutomaticSize.Y
			hint.BackgroundTransparency = 1
			hint.Font = Enum.Font.Gotham
			hint.Text = "Picking a colour switches the menu to the Custom theme. A light background makes it a light theme. The Theme list in the menu's settings switches back any time."
			hint.TextSize = 11
			hint.TextWrapped = true
			hint.TextXAlignment = Enum.TextXAlignment.Left
			bindAuxiliaryUiColor(hint, "TextColor3", "SubText")
			hint.Parent = list

			-- Done, in the header, closes it.
			local done = Instance.new("TextButton")
			done.AutomaticSize = Enum.AutomaticSize.X
			done.Size = UDim2.fromOffset(0, 22)
			done.AutoButtonColor = false
			done.BorderSizePixel = 0
			done.Font = Enum.Font.GothamBold
			done.Text = "Done"
			done.TextSize = 11
			done.ZIndex = 3
			bindAuxiliaryUiColor(done, "BackgroundColor3", "Accent")
			bindAuxiliaryUiColor(done, "TextColor3", "OnAccent")
			local doneCorner = Instance.new("UICorner")
			doneCorner.CornerRadius = UDim.new(0, 7)
			doneCorner.Parent = done
			local donePadding = Instance.new("UIPadding")
			donePadding.PaddingLeft = UDim.new(0, 10)
			donePadding.PaddingRight = UDim.new(0, 10)
			donePadding.Parent = done
			done.Parent = makerWindow.headerRight
			done.Activated:Connect(function() makerWindow.setShown(false) end)

			table.insert(auxiliaryUiThemeListeners, function() pcall(refreshAll) end)
			refreshAll()
			menuModules.themeMaker = {
				open = function()
					refreshAll()
					makerWindow.setShown(true)
				end,
				-- For the themecolours command: the accent, and the background if given. False if either
				-- isn't a hex code.
				setColours = function(accentText, backgroundText)
					local accent = cleanHex(accentText)
					local background = backgroundText ~= nil and cleanHex(backgroundText) or nil
					if not accent or (backgroundText ~= nil and not background) then return false end
					featureSettings.customAccent = accent
					if background then featureSettings.customBackground = background end
					use()
					return true
				end,
			}
		end)

		------------------------------------------------------------------------------------------
		-- Session Stats: how long you've played, how far you've gone, your jumps, deaths and top speed,
		-- and how many other players you've seen, for this session and all time (all but the players).
		-- It counts whether or not its window is shown, and the all-time totals are saved every 20
		-- seconds. A teleport (50 studs in a tenth of a second) doesn't count as distance.
		safeBuild("Session Stats", function()
			local localPlayer = Players.LocalPlayer
			local started = os.clock()
			local session = { distance = 0, jumps = 0, deaths = 0, topSpeed = 0, seen = {}, seenCount = 0 }
			-- The all-time totals from before this session.
			local before = {}
			local saved = type(featureSettings.sessionTotals) == "table" and featureSettings.sessionTotals or {}
			for _, key in ipairs({ "time", "distance", "jumps", "deaths", "topSpeed" }) do
				before[key] = tonumber(saved[key]) or 0
			end
			local function allTime()
				return {
					time = before.time + (os.clock() - started),
					distance = before.distance + session.distance,
					jumps = before.jumps + session.jumps,
					deaths = before.deaths + session.deaths,
					topSpeed = math.max(before.topSpeed, session.topSpeed),
				}
			end
			local function saveTotals()
				local totals = allTime()
				totals.time = math.floor(totals.time)
				totals.distance = math.floor(totals.distance)
				totals.topSpeed = math.floor(totals.topSpeed * 10) / 10
				featureSettings.sessionTotals = totals
				saveFeatureSettings()
			end

			-- Distance and top speed, ten times a second, and the totals saved every 20 seconds.
			local last = { root = nil, position = nil }
			task.spawn(function()
				local sinceSave = 0
				while true do
					local waited = task.wait(0.1)
					local character = localPlayer.Character
					local root = character and getRoot(character)
					if root then
						local position = root.Position
						if root == last.root and last.position then
							local moved = position - last.position
							if moved.Magnitude < 50 then
								session.distance += moved.Magnitude
								local speed = Vector3.new(moved.X, 0, moved.Z).Magnitude / math.max(waited, 0.05)
								if speed > session.topSpeed then session.topSpeed = speed end
							end
						end
						last.root, last.position = root, position
					end
					sinceSave += waited
					if sinceSave >= 20 then
						sinceSave = 0
						pcall(saveTotals)
					end
				end
			end)
			-- Jumps and deaths, on each character.
			local function watch(character)
				local humanoid = character:WaitForChild("Humanoid", 10)
				if not humanoid then return end
				humanoid.StateChanged:Connect(function(_, state)
					if state == Enum.HumanoidStateType.Jumping then session.jumps += 1 end
				end)
				humanoid.Died:Connect(function() session.deaths += 1 end)
			end
			if localPlayer.Character then task.spawn(watch, localPlayer.Character) end
			localPlayer.CharacterAdded:Connect(watch)
			-- Everyone else who's been in the server with you, counted once each.
			local function see(player)
				if player ~= localPlayer and not session.seen[player.UserId] then
					session.seen[player.UserId] = true
					session.seenCount += 1
				end
			end
			for _, player in ipairs(Players:GetPlayers()) do see(player) end
			Players.PlayerAdded:Connect(see)

			local function duration(seconds)
				seconds = math.floor(seconds)
				local hours, minutes = math.floor(seconds / 3600), math.floor(seconds % 3600 / 60)
				if hours > 0 then return string.format("%dh %02dm", hours, minutes) end
				return string.format("%dm %02ds", minutes, seconds % 60)
			end
			-- 1,234, then 12.3k and 1.23M for big numbers.
			local function number(value)
				value = math.floor(value + 0.5)
				if value >= 1000000 then return string.format("%.2fM", value / 1000000) end
				if value >= 10000 then return string.format("%.1fk", value / 1000) end
				local text = tostring(value):reverse():gsub("(%d%d%d)", "%1,"):reverse()
				return (text:gsub("^,", ""))
			end
			local rows = {
				{ name = "Time played", icons = { "timer", "clock" },
					now = function() return duration(os.clock() - started) end, ever = function(all) return duration(all.time) end },
				{ name = "Distance (studs)", icons = { "footprints" },
					now = function() return number(session.distance) end, ever = function(all) return number(all.distance) end },
				{ name = "Jumps", icons = { "chevrons-up" },
					now = function() return number(session.jumps) end, ever = function(all) return number(all.jumps) end },
				{ name = "Deaths", icons = { "skull" },
					now = function() return number(session.deaths) end, ever = function(all) return number(all.deaths) end },
				{ name = "Top speed (studs/s)", icons = { "gauge" },
					now = function() return number(session.topSpeed) end, ever = function(all) return number(all.topSpeed) end },
				{ name = "Players seen", icons = { "users-round" },
					now = function() return number(session.seenCount) end, ever = function() return "–" end },
			}

			local statsWindow = menuModules.makeWindow({
				name = "SpreadCheeksSessionStats", title = "Session Stats", icons = { "bar-chart-3", "activity" },
				width = 310, height = 262, xKey = "sessionStatsX", yKey = "sessionStatsY",
				defaultPosition = function(screen, size) return 24, (screen.Y - size.Y) / 2 end,
			})
			local function text(parent, value, x, width, font, role, alignment)
				local label = Instance.new("TextLabel")
				label.Position = UDim2.new(x, 0, 0, 0)
				label.Size = UDim2.new(width, 0, 1, 0)
				label.BackgroundTransparency = 1
				label.Font = font
				label.Text = value
				label.TextSize = font == Enum.Font.GothamBold and 10 or 12
				label.TextXAlignment = alignment
				label.TextTruncate = Enum.TextTruncate.AtEnd
				bindAuxiliaryUiColor(label, "TextColor3", role)
				label.Parent = parent
				return label
			end
			local holder = Instance.new("Frame")
			holder.Position = UDim2.fromOffset(12, 0)
			holder.Size = UDim2.new(1, -24, 1, -6)
			holder.BackgroundTransparency = 1
			holder.Parent = statsWindow.body
			local holderLayout = Instance.new("UIListLayout")
			holderLayout.Padding = UDim.new(0, 2)
			holderLayout.SortOrder = Enum.SortOrder.LayoutOrder
			holderLayout.Parent = holder
			local captions = Instance.new("Frame")
			captions.LayoutOrder = 0
			captions.Size = UDim2.new(1, 0, 0, 18)
			captions.BackgroundTransparency = 1
			captions.Parent = holder
			text(captions, "THIS SESSION", 0.48, 0.26, Enum.Font.GothamBold, "Muted", Enum.TextXAlignment.Right)
			text(captions, "ALL TIME", 0.74, 0.26, Enum.Font.GothamBold, "Muted", Enum.TextXAlignment.Right)
			for index, row in ipairs(rows) do
				local line = Instance.new("Frame")
				line.LayoutOrder = index
				line.Size = UDim2.new(1, 0, 0, 30)
				line.BorderSizePixel = 0
				bindAuxiliaryUiColor(line, "BackgroundColor3", "Inset")
				line.BackgroundTransparency = index % 2 == 1 and 0 or 1
				line.Parent = holder
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(0, 7)
				corner.Parent = line
				local icon = Instance.new("ImageLabel")
				icon.AnchorPoint = Vector2.new(0, 0.5)
				icon.Position = UDim2.new(0, 8, 0.5, 0)
				icon.Size = UDim2.fromOffset(14, 14)
				icon.BackgroundTransparency = 1
				local image = menuIcons.get(table.unpack(row.icons))
				if image then menuIcons.apply(icon, image) end
				icon.Visible = image ~= nil
				bindAuxiliaryUiColor(icon, "ImageColor3", "AccentText")
				icon.Parent = line
				local name = text(line, row.name, 0, 0.5, Enum.Font.Gotham, "SubText", Enum.TextXAlignment.Left)
				name.Position = UDim2.fromOffset(28, 0)
				name.Size = UDim2.new(0.5, -28, 1, 0)
				row.nowLabel = text(line, "", 0.48, 0.26, Enum.Font.GothamMedium, "Text", Enum.TextXAlignment.Right)
				row.everLabel = text(line, "", 0.74, 0.24, Enum.Font.GothamMedium, "Text", Enum.TextXAlignment.Right)
			end
			local function refresh()
				local all = allTime()
				for _, row in ipairs(rows) do
					row.nowLabel.Text = row.now()
					row.everLabel.Text = row.ever(all)
				end
			end
			statsWindow.onShown = refresh
			task.spawn(function()
				while true do
					task.wait(0.5)
					if statsWindow.isShown() then pcall(refresh) end
				end
			end)

			local function resetTotals()
				for key in pairs(before) do before[key] = 0 end
				pcall(saveTotals)
				pcall(refresh)
				notify("Session Stats", "All-time totals start again from this session", 2.5)
			end
			-- Reset, in the header: a second click within three seconds starts the all-time totals again.
			local reset = Instance.new("TextButton")
			reset.AutomaticSize = Enum.AutomaticSize.X
			reset.Size = UDim2.fromOffset(0, 22)
			reset.AutoButtonColor = false
			reset.BorderSizePixel = 0
			reset.Font = Enum.Font.GothamBold
			reset.Text = "Reset"
			reset.TextSize = 11
			reset.ZIndex = 3
			bindAuxiliaryUiColor(reset, "BackgroundColor3", "Inset")
			bindAuxiliaryUiColor(reset, "TextColor3", "SubText")
			local resetCorner = Instance.new("UICorner")
			resetCorner.CornerRadius = UDim.new(0, 7)
			resetCorner.Parent = reset
			local resetPadding = Instance.new("UIPadding")
			resetPadding.PaddingLeft = UDim.new(0, 10)
			resetPadding.PaddingRight = UDim.new(0, 10)
			resetPadding.Parent = reset
			reset.Parent = statsWindow.headerRight
			local resetState = { armedAt = 0 }
			reset.Activated:Connect(function()
				if os.clock() - resetState.armedAt < 3 then
					resetState.armedAt = 0
					reset.Text = "Reset"
					return resetTotals()
				end
				resetState.armedAt = os.clock()
				reset.Text = "Sure?"
				task.delay(3, function()
					if os.clock() - resetState.armedAt >= 3 then reset.Text = "Reset" end
				end)
			end)

			menuModules.sessionStats = {
				setEnabled = function(on)
					if on then pcall(refresh) end
					statsWindow.setShown(on)
				end,
				resetTotals = resetTotals,
			}
		end)

		------------------------------------------------------------------------------------------
		------------------------------------------------------------------------------------------
		-- Jetpacks and Friends (28 October 2026). Each part is built on its own; their switches and
		-- buttons are made with the others further up.

		------------------------------------------------------------------------------------------
		-- Jetpack: while it's on, holding jump (Space, or the jump button) blasts you upwards, steering
		-- as normal, until the fuel runs out; it fills back up while you're on the ground. How fast it
		-- lifts you, how long a tank lasts and whether it never runs out are in its settings card. The
		-- fuel gauge sits at the bottom of your screen, and flames come out of your back (only you see
		-- those: things a script adds to your character stay on your screen). It waits while Infinite
		-- Yield's fly is on.
		safeBuild("Jetpack", function()
			local localPlayer = Players.LocalPlayer
			local jet = { on = false, fuel = 1, thrusting = false, flames = {}, character = nil }
			local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:WaitForChild("PlayerGui")
			local previous = playerGui:FindFirstChild("SpreadCheeksJetpack")
			if previous then previous:Destroy() end
			-- The fuel gauge, just above the middle of the bottom of the screen.
			local gauge = Instance.new("ScreenGui")
			gauge.Name = "SpreadCheeksJetpack"
			gauge.ResetOnSpawn = false
			gauge.IgnoreGuiInset = true
			gauge.DisplayOrder = 998
			gauge.Enabled = false
			gauge.Parent = playerGui
			local track = Instance.new("Frame")
			track.AnchorPoint = Vector2.new(0.5, 1)
			track.Position = UDim2.new(0.5, 0, 1, -96)
			track.Size = UDim2.fromOffset(180, 8)
			track.BorderSizePixel = 0
			bindAuxiliaryUiColor(track, "BackgroundColor3", "Inset")
			track.Parent = gauge
			local trackCorner = Instance.new("UICorner")
			trackCorner.CornerRadius = UDim.new(1, 0)
			trackCorner.Parent = track
			local trackStroke = Instance.new("UIStroke")
			trackStroke.Transparency = 0.3
			bindAuxiliaryUiColor(trackStroke, "Color", "Stroke")
			trackStroke.Parent = track
			local fill = Instance.new("Frame")
			fill.Size = UDim2.fromScale(1, 1)
			fill.BorderSizePixel = 0
			fill.Parent = track
			local fillCorner = Instance.new("UICorner")
			fillCorner.CornerRadius = UDim.new(1, 0)
			fillCorner.Parent = fill
			local caption = Instance.new("TextLabel")
			caption.AnchorPoint = Vector2.new(0.5, 1)
			caption.Position = UDim2.new(0.5, 0, 0, -3)
			caption.Size = UDim2.fromOffset(180, 12)
			caption.BackgroundTransparency = 1
			caption.Font = Enum.Font.GothamBold
			caption.Text = "JETPACK"
			caption.TextSize = 10
			bindAuxiliaryUiColor(caption, "TextColor3", "SubText")
			caption.Parent = track

			-- Two flames on your back, made on each character the first time they're needed.
			local function makeFlames(character)
				for _, attachment in ipairs(jet.flames) do attachment:Destroy() end
				table.clear(jet.flames)
				jet.character = character
				local torso = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
				if not torso then return end
				for _, side in ipairs({ -0.45, 0.45 }) do
					local attachment = Instance.new("Attachment")
					attachment.Name = "SpreadCheeksJetFlame"
					attachment.Position = Vector3.new(side, -0.6, 0.55)
					local emitter = Instance.new("ParticleEmitter")
					emitter.Name = "SpreadCheeksJetFlame"
					emitter.Texture = "rbxasset://textures/particles/fire_main.dds"
					emitter.EmissionDirection = Enum.NormalId.Bottom
					emitter.Speed = NumberRange.new(12, 16)
					emitter.Lifetime = NumberRange.new(0.25, 0.35)
					emitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.7), NumberSequenceKeypoint.new(1, 0) })
					emitter.Color = ColorSequence.new(Color3.fromRGB(255, 200, 80), Color3.fromRGB(255, 70, 20))
					emitter.LightEmission = 1
					emitter.Rate = 80
					emitter.SpreadAngle = Vector2.new(8, 8)
					emitter.Enabled = false
					emitter.Parent = attachment
					attachment.Parent = torso
					table.insert(jet.flames, attachment)
				end
			end
			local function setFlames(on)
				for _, attachment in ipairs(jet.flames) do
					local emitter = attachment.Parent and attachment:FindFirstChildOfClass("ParticleEmitter")
					if emitter then emitter.Enabled = on end
				end
			end
			-- Every frame, straight after Roblox's controls have read your keys, so humanoid.Jump is
			-- whether you're holding jump right now (keys, pad or touch).
			local function step(deltaTime)
				local character = localPlayer.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local root = character and getRoot(character)
				if not humanoid or not root or humanoid.Health <= 0 then return end
				local tank, infinite = featureSettings.jetpackFuel, featureSettings.jetpackInfinite
				local thrusting = humanoid.Jump and not FLYING and not humanoid.Sit and not humanoid.PlatformStand
					and (infinite or jet.fuel > 0)
				if thrusting then
					local velocity = root.AssemblyLinearVelocity
					local climb = featureSettings.jetpackPower
					-- Against gravity and then some, up to the climb speed (anything faster is left alone).
					if velocity.Y < climb then
						root.AssemblyLinearVelocity = Vector3.new(velocity.X, math.min(velocity.Y + (workspace.Gravity + climb * 2) * deltaTime, climb), velocity.Z)
					end
					if not infinite then jet.fuel = math.max(0, jet.fuel - deltaTime / tank) end
				elseif humanoid.FloorMaterial ~= Enum.Material.Air then
					-- Filling back up on the ground, a little faster than it burns.
					jet.fuel = math.min(1, jet.fuel + deltaTime / (tank * 0.6))
				end
				if thrusting ~= jet.thrusting then
					jet.thrusting = thrusting
					if thrusting and (jet.character ~= character or not jet.flames[1] or not jet.flames[1].Parent) then makeFlames(character) end
					setFlames(thrusting)
				end
				local level = infinite and 1 or jet.fuel
				fill.Size = UDim2.fromScale(level, 1)
				fill.BackgroundColor3 = level < 0.25 and Color3.fromRGB(239, 68, 68) or auxiliaryUiTheme.Accent
			end
			local function setEnabled(on)
				jet.on = on
				pcall(function() RunService:UnbindFromRenderStep("SpreadCheeksJetpack") end)
				jet.thrusting = false
				setFlames(false)
				gauge.Enabled = on
				if not on then return end
				if menuModules.claimMovement then menuModules.claimMovement("Jetpack") end
				-- Infinite Yield's fly would fight it, so that goes off.
				local fly = quickToggleByName["Fly"]
				if fly and fly.state then setQuickToggle(fly, false) end
				RunService:BindToRenderStep("SpreadCheeksJetpack", Enum.RenderPriority.Input.Value + 1, step)
			end
			menuModules.jetpack = { setEnabled = setEnabled }

			local entry = quickToggleByName["Jetpack"]
			local card = entry and createSettingsCard(entry)
			if not card then return end
			card.addSectionLabel("THRUST", "rocket", "flame")
			card.addSlider({
				text = "Power",
				icon = { "rocket", "chevrons-up" },
				min = 20, max = 100, step = 5,
				get = function() return featureSettings.jetpackPower end,
				set = function(value) featureSettings.jetpackPower = value end,
				commit = saveFeatureSettings,
				format = function(value) return math.floor(value + 0.5) .. " studs/s" end,
			})
			card.addSectionLabel("FUEL", "fuel", "gauge")
			card.addSlider({
				text = "A full tank lasts",
				icon = { "fuel", "timer" },
				min = 1, max = 10, step = 0.5,
				get = function() return featureSettings.jetpackFuel end,
				set = function(value) featureSettings.jetpackFuel = value end,
				commit = saveFeatureSettings,
				format = function(value) return string.format("%.1f s", value) end,
			})
			card.addSwitchGrid({
				{
					text = "Never runs out",
					get = function() return featureSettings.jetpackInfinite == true end,
					set = function(on)
						featureSettings.jetpackInfinite = on
						saveFeatureSettings()
					end,
				},
			}, 1)
			card.addHint("Hold jump to fly up and steer as you normally would. It fills back up while you're on the ground. Some games hurt you for long falls, so No Fall Damage helps.")
			card.refresh()
		end)

		------------------------------------------------------------------------------------------
		-- Friends Online: a window listing your friends who are online now, playing first, with what
		-- they're playing and a Join button when Roblox says which server they're in (their privacy
		-- settings decide that). Here means they're in this server with you. It refreshes every 30
		-- seconds while it's open, and with Refresh. Streamer Mode hides their names and pictures. Roblox
		-- only tells games about friends playing something else if they let everyone see they're online,
		-- so a note under the count says why someone may be missing.
		safeBuild("Friends Online", function()
			local localPlayer = Players.LocalPlayer
			local friendsWindow = menuModules.makeWindow({
				name = "SpreadCheeksFriends", title = "Friends Online", icons = { "users-round", "user-plus" },
				width = 330, height = 400, xKey = "friendsX", yKey = "friendsY",
				defaultPosition = function(screen, size) return (screen.X - size.X) / 2, (screen.Y - size.Y) / 2 end,
			})
			local state = { loading = false, lastLoad = 0 }
			-- Game names by place ID, once looked up.
			local placeNames = {}
			-- What Roblox says each friend is doing, by its LocationType.
			local doing = {
				[0] = "On the Roblox website", [1] = "In a game", [2] = "On the Roblox website", [3] = "In Roblox Studio",
				[4] = "In a game", [5] = "In a game", [6] = "In Roblox Studio",
			}

			local status = Instance.new("TextLabel")
			status.Position = UDim2.fromOffset(14, 2)
			status.Size = UDim2.new(1, -28, 0, 18)
			status.BackgroundTransparency = 1
			status.Font = Enum.Font.Gotham
			status.TextSize = 12
			status.TextXAlignment = Enum.TextXAlignment.Left
			status.TextTruncate = Enum.TextTruncate.AtEnd
			bindAuxiliaryUiColor(status, "TextColor3", "SubText")
			status.Parent = friendsWindow.body
			local note = Instance.new("TextLabel")
			note.Position = UDim2.fromOffset(14, 21)
			note.Size = UDim2.new(1, -28, 0, 40)
			note.BackgroundTransparency = 1
			note.Font = Enum.Font.Gotham
			note.Text = "Friends playing a different game only show here if they let everyone see when they're online. Roblox hides the rest until they're in this game."
			note.TextSize = 11
			note.TextWrapped = true
			note.TextXAlignment = Enum.TextXAlignment.Left
			note.TextYAlignment = Enum.TextYAlignment.Top
			bindAuxiliaryUiColor(note, "TextColor3", "Muted")
			note.Parent = friendsWindow.body
			local list = Instance.new("ScrollingFrame")
			list.Position = UDim2.fromOffset(6, 64)
			list.Size = UDim2.new(1, -12, 1, -70)
			list.BackgroundTransparency = 1
			list.BorderSizePixel = 0
			list.ScrollBarThickness = 3
			list.ScrollingDirection = Enum.ScrollingDirection.Y
			list.AutomaticCanvasSize = Enum.AutomaticSize.Y
			list.CanvasSize = UDim2.new()
			bindAuxiliaryUiColor(list, "ScrollBarImageColor3", "Muted")
			list.Parent = friendsWindow.body
			local listLayout = Instance.new("UIListLayout")
			listLayout.Padding = UDim.new(0, 6)
			listLayout.SortOrder = Enum.SortOrder.LayoutOrder
			listLayout.Parent = list
			local listPadding = Instance.new("UIPadding")
			listPadding.PaddingLeft = UDim.new(0, 8)
			listPadding.PaddingRight = UDim.new(0, 10)
			listPadding.PaddingBottom = UDim.new(0, 8)
			listPadding.Parent = list

			local function headerButton(text, order, role, textRole)
				local button = Instance.new("TextButton")
				button.LayoutOrder = order
				button.AutomaticSize = Enum.AutomaticSize.X
				button.Size = UDim2.fromOffset(0, 22)
				button.AutoButtonColor = false
				button.BorderSizePixel = 0
				button.Font = Enum.Font.GothamBold
				button.Text = text
				button.TextSize = 11
				button.ZIndex = 3
				bindAuxiliaryUiColor(button, "BackgroundColor3", role)
				bindAuxiliaryUiColor(button, "TextColor3", textRole)
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(0, 7)
				corner.Parent = button
				local padding = Instance.new("UIPadding")
				padding.PaddingLeft = UDim.new(0, 10)
				padding.PaddingRight = UDim.new(0, 10)
				padding.Parent = button
				button.Parent = friendsWindow.headerRight
				return button
			end
			local refreshButton = headerButton("Refresh", 1, "Inset", "SubText")
			local doneButton = headerButton("Done", 2, "Accent", "OnAccent")

			local function join(friend, name)
				local joined, problem = pcall(function()
					TeleportService:TeleportToPlaceInstance(friend.PlaceId, friend.GameId, localPlayer)
				end)
				if joined then
					notify("Friends Online", "Joining " .. name .. "...", 3)
				else
					notify("Friends Online", "Couldn't join " .. name .. ": " .. tostring(problem), 4)
				end
			end
			local function row(friend, index, hidden)
				local name = hidden and ("Friend " .. index) or tostring(friend.DisplayName or friend.UserName or "Friend")
				local card = Instance.new("Frame")
				card.LayoutOrder = index
				card.Size = UDim2.new(1, 0, 0, 52)
				card.BorderSizePixel = 0
				card.BackgroundColor3 = auxiliaryUiTheme.Card
				card.Parent = list
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(0, 10)
				corner.Parent = card
				local avatar = Instance.new("ImageLabel")
				avatar.Position = UDim2.fromOffset(8, 6)
				avatar.Size = UDim2.fromOffset(40, 40)
				avatar.BorderSizePixel = 0
				avatar.BackgroundColor3 = auxiliaryUiTheme.Inset
				avatar.Image = hidden and "" or ("rbxthumb://type=AvatarHeadShot&id=" .. tostring(friend.VisitorId) .. "&w=150&h=150")
				avatar.Parent = card
				local avatarCorner = Instance.new("UICorner")
				avatarCorner.CornerRadius = UDim.new(1, 0)
				avatarCorner.Parent = avatar
				local nameLabel = Instance.new("TextLabel")
				nameLabel.Position = UDim2.fromOffset(56, 8)
				nameLabel.Size = UDim2.new(1, -124, 0, 18)
				nameLabel.BackgroundTransparency = 1
				nameLabel.Font = Enum.Font.GothamBold
				nameLabel.Text = name .. ((hidden or not friend.UserName) and "" or ("  @" .. friend.UserName))
				nameLabel.TextSize = 13
				nameLabel.TextXAlignment = Enum.TextXAlignment.Left
				nameLabel.TextTruncate = Enum.TextTruncate.AtEnd
				nameLabel.TextColor3 = auxiliaryUiTheme.Text
				nameLabel.Parent = card
				local doingLabel = Instance.new("TextLabel")
				doingLabel.Position = UDim2.fromOffset(56, 27)
				doingLabel.Size = UDim2.new(1, -124, 0, 16)
				doingLabel.BackgroundTransparency = 1
				doingLabel.Font = Enum.Font.Gotham
				doingLabel.Text = doing[friend.LocationType] or "Online"
				doingLabel.TextSize = 11
				doingLabel.TextXAlignment = Enum.TextXAlignment.Left
				doingLabel.TextTruncate = Enum.TextTruncate.AtEnd
				doingLabel.TextColor3 = auxiliaryUiTheme.SubText
				doingLabel.Parent = card
				-- The game's name, looked up once per game.
				local placeId = tonumber(friend.PlaceId)
				if placeId and placeId > 0 then
					local function showPlace(placeName)
						if doingLabel.Parent then doingLabel.Text = "Playing " .. placeName end
					end
					if placeNames[placeId] then
						showPlace(placeNames[placeId])
					else
						task.spawn(function()
							local found, info = pcall(function() return MarketplaceService:GetProductInfo(placeId) end)
							placeNames[placeId] = found and type(info) == "table" and tostring(info.Name or "a game") or "a game"
							showPlace(placeNames[placeId])
						end)
					end
				end
				-- Join when Roblox says which server they're in; Here when it's this one.
				local jobId = type(friend.GameId) == "string" and friend.GameId ~= "" and friend.GameId or nil
				if placeId and placeId > 0 and jobId then
					local here = jobId == game.JobId
					local button = Instance.new("TextButton")
					button.AnchorPoint = Vector2.new(1, 0.5)
					button.Position = UDim2.new(1, -10, 0.5, 0)
					button.Size = UDim2.fromOffset(56, 26)
					button.AutoButtonColor = false
					button.BorderSizePixel = 0
					button.Font = Enum.Font.GothamBold
					button.Text = here and "Here" or "Join"
					button.TextSize = 12
					button.BackgroundColor3 = here and auxiliaryUiTheme.Inset or auxiliaryUiTheme.Accent
					button.TextColor3 = here and auxiliaryUiTheme.SubText or auxiliaryUiTheme.OnAccent
					button.Parent = card
					local buttonCorner = Instance.new("UICorner")
					buttonCorner.CornerRadius = UDim.new(0, 8)
					buttonCorner.Parent = button
					if not here then
						button.Activated:Connect(function() join(friend, name) end)
					end
				end
			end
			-- In a game you can join first, then other games, then everyone else; by name within those.
			local function rank(friend)
				if tonumber(friend.PlaceId) and type(friend.GameId) == "string" and friend.GameId ~= "" then return 0 end
				local location = friend.LocationType
				if location == 1 or location == 4 or location == 5 then return 1 end
				return 2
			end
			local function render(friends)
				for _, child in ipairs(list:GetChildren()) do
					if child:IsA("GuiObject") then child:Destroy() end
				end
				table.sort(friends, function(left, right)
					local leftRank, rightRank = rank(left), rank(right)
					if leftRank ~= rightRank then return leftRank < rightRank end
					return tostring(left.DisplayName or ""):lower() < tostring(right.DisplayName or ""):lower()
				end)
				local hidden = featureSettings.streamerMode == true
				for index, friend in ipairs(friends) do
					row(friend, index, hidden)
				end
				local count = #friends
				status.Text = count == 0 and "No friends to show right now."
					or (count .. (count == 1 and " friend" or " friends") .. " online")
			end
			local function load()
				if state.loading then return end
				state.loading = true
				status.Text = "Loading your friends..."
				task.spawn(function()
					local found, friends = pcall(function() return localPlayer:GetFriendsOnline(200) end)
					state.loading = false
					state.lastLoad = os.clock()
					if not found or type(friends) ~= "table" then
						status.Text = "Couldn't get your friends right now. Try Refresh in a moment."
						return
					end
					render(friends)
				end)
			end
			refreshButton.Activated:Connect(load)
			doneButton.Activated:Connect(function() friendsWindow.setShown(false) end)
			-- Every 30 seconds while it's open.
			task.spawn(function()
				while true do
					task.wait(5)
					if friendsWindow.isShown() and os.clock() - state.lastLoad > 30 then load() end
				end
			end)
			menuModules.friendsOnline = {
				open = function()
					friendsWindow.setShown(true)
					load()
				end,
			}
		end)

		------------------------------------------------------------------------------------------
		-- Switches follow commands: the switches that run Infinite Yield's commands (Noclip, Fly, ESP
		-- and the rest) move to match when those commands are run some other way: the ; bar, chat, the
		-- Command Bar tab or IY's own keybinds. Each command is wrapped so that running it first moves
		-- its switch, without running anything twice; the keybind list and Home go by the switches, so
		-- they follow too. Only your own commands count.
		safeBuild("Switches follow commands", function()
			local localPlayer = Players.LocalPlayer
			-- A switch on or off without running what it does (the command's already doing that).
			local function mark(name, on)
				local entry = quickToggleByName[name]
				if not entry or entry.state == on then return end
				entry.state = on
				pcall(function() entry.object:Set(on, true) end)
			end
			local function follow(commandName, marks)
				local command = findCmd(commandName)
				if type(command) ~= "table" or type(command.FUNC) ~= "function" then return end
				local original = command.FUNC
				command.FUNC = function(args, speaker, ...)
					if speaker == nil or speaker == localPlayer then pcall(marks) end
					return original(args, speaker, ...)
				end
			end
			-- The menu's command switches note their on and off commands (addCommandToggle).
			for _, entry in ipairs(quickToggles) do
				if entry.commands then
					local name = entry.name
					follow(entry.commands[1], function() mark(name, true) end)
					follow(entry.commands[2], function() mark(name, false) end)
				end
			end
			-- Fly and Vehicle Fly share one flight, so starting either replaces the other and stopping
			-- either stops both. The toggles go by whether you're flying now.
			follow("fly", function()
				mark("Fly", true)
				mark("Vehicle Fly", false)
			end)
			follow("vfly", function()
				mark("Vehicle Fly", true)
				mark("Fly", false)
			end)
			for _, commandName in ipairs({ "unfly", "unvfly" }) do
				follow(commandName, function()
					mark("Fly", false)
					mark("Vehicle Fly", false)
				end)
			end
			follow("togglefly", function()
				mark("Fly", not FLYING)
				mark("Vehicle Fly", false)
			end)
			follow("togglevfly", function()
				mark("Vehicle Fly", not FLYING)
				mark("Fly", false)
			end)
			-- Walk fling stops any walk fling first (which would show it off), so it's shown on again once
			-- it's going.
			follow("walkfling", function()
				mark("Walk Fling", true)
				task.spawn(function()
					for _ = 1, 10 do
						task.wait(0.1)
						if walkflinging then return mark("Walk Fling", true) end
					end
				end)
			end)
			follow("unwalkfling", function() mark("Walk Fling", false) end)
			follow("swim", function() mark("Swim in Air", true) end)
			follow("unswim", function() mark("Swim in Air", false) end)
			follow("antifling", function() mark("Anti-Fling", true) end)
			follow("unantifling", function() mark("Anti-Fling", false) end)
			follow("togglexray", function() mark("X-ray", not xrayEnabled) end)
		end)

		------------------------------------------------------------------------------------------
		------------------------------------------------------------------------------------------
		-- Aim Warning, Hit Markers and Custom Crosshair (28 October 2026), for the Combat tab. Each part is
		-- built on its own; their switches are made with the others further up.

		------------------------------------------------------------------------------------------
		-- Aim Warning: a red arrow round the middle of your screen, pointing at anyone who's been looking
		-- straight at you for a moment, with their name, and a ping as it appears. "Looking at you" goes by
		-- which way their character faces (as Weeping Angel does), within the angle and range in its
		-- settings card, with nothing solid in between; teammates can be left out.
		safeBuild("Aim Warning", function()
			local localPlayer = Players.LocalPlayer
			local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:WaitForChild("PlayerGui")
			local previous = playerGui:FindFirstChild("SpreadCheeksAimWarning")
			if previous then previous:Destroy() end
			local gui = Instance.new("ScreenGui")
			gui.Name = "SpreadCheeksAimWarning"
			gui.ResetOnSpawn = false
			gui.IgnoreGuiInset = true
			gui.DisplayOrder = 996
			gui.Enabled = false
			gui.Parent = playerGui
			-- How far off looking straight at you still counts (degrees), by the card's choice.
			local angles = { Strict = 5, Normal = 9, Loose = 16 }
			local red = Color3.fromRGB(239, 68, 68)
			local params = RaycastParams.new()
			params.FilterType = Enum.RaycastFilterType.Exclude
			-- arrows: each watcher's arrow. since: when each started looking. pinged: their last ping.
			local state = { loop = nil, arrows = {}, since = {}, pinged = {} }
			local function arrowFor(player)
				local arrow = state.arrows[player]
				if arrow then return arrow end
				local holder = Instance.new("Frame")
				holder.AnchorPoint = Vector2.new(0.5, 0.5)
				holder.Size = UDim2.fromOffset(30, 30)
				holder.BackgroundTransparency = 1
				holder.Visible = false
				holder.Parent = gui
				local icon = Instance.new("ImageLabel")
				icon.Size = UDim2.fromScale(1, 1)
				icon.BackgroundTransparency = 1
				icon.ImageColor3 = red
				local image = menuIcons.get("navigation-2", "arrow-big-up")
				if image then menuIcons.apply(icon, image) end
				icon.Parent = holder
				local label = Instance.new("TextLabel")
				label.AnchorPoint = Vector2.new(0.5, 0)
				label.Position = UDim2.new(0.5, 0, 1, 2)
				label.Size = UDim2.fromOffset(140, 14)
				label.BackgroundTransparency = 1
				label.Font = Enum.Font.GothamBold
				label.TextSize = 11
				label.TextColor3 = Color3.new(1, 1, 1)
				label.TextStrokeTransparency = 0.4
				label.Parent = holder
				arrow = { holder = holder, icon = icon, label = label }
				state.arrows[player] = arrow
				return arrow
			end
			local function hideAll()
				for _, arrow in pairs(state.arrows) do arrow.holder.Visible = false end
				table.clear(state.since)
			end
			Players.PlayerRemoving:Connect(function(player)
				local arrow = state.arrows[player]
				if arrow then arrow.holder:Destroy() end
				state.arrows[player], state.since[player], state.pinged[player] = nil, nil, nil
			end)
			local function ping()
				local sound = Instance.new("Sound")
				sound.SoundId = "rbxasset://sounds/electronicpingshort.wav"
				sound.PlaybackSpeed = 0.8
				sound.Volume = 0.5
				sound.Parent = SoundService
				sound:Play()
				task.delay(3, function() sound:Destroy() end)
			end
			local function step()
				local camera = workspace.CurrentCamera
				local character = localPlayer.Character
				local myHead = character and (character:FindFirstChild("Head") or getRoot(character))
				if not camera or not myHead then return hideAll() end
				local limit = math.cos(math.rad(angles[featureSettings.aimWarningAngle] or 9))
				local now = os.clock()
				local viewport = camera.ViewportSize
				for _, player in ipairs(Players:GetPlayers()) do
					if player ~= localPlayer then
						local theirCharacter = player.Character
						local theirHead = theirCharacter and theirCharacter:FindFirstChild("Head")
						local looking = false
						local teammate = featureSettings.aimWarningTeam and player.Team ~= nil and player.Team == localPlayer.Team
						if theirHead and theirHead:IsA("BasePart") and not teammate then
							local toMe = myHead.Position - theirHead.Position
							local distance = toMe.Magnitude
							-- Which way they face, level, against which way you are from them, level.
							local facing = Vector3.new(theirHead.CFrame.LookVector.X, 0, theirHead.CFrame.LookVector.Z)
							local across = Vector3.new(toMe.X, 0, toMe.Z)
							if distance > 3 and distance <= featureSettings.aimWarningRange and facing.Magnitude > 0.1 and across.Magnitude > 0.1
								and facing.Unit:Dot(across.Unit) >= limit then
								params.FilterDescendantsInstances = { character, theirCharacter }
								local hit = workspace:Raycast(theirHead.Position, toMe, params)
								looking = hit == nil or hit.Instance.Transparency >= 0.8
							end
						end
						-- A moment of looking first, so people just turning past you don't set it off.
						if looking then
							state.since[player] = state.since[player] or now
						else
							state.since[player] = nil
						end
						local warned = state.since[player] ~= nil and now - state.since[player] >= 0.35
						local arrow = (warned or state.arrows[player]) and arrowFor(player)
						if arrow then
							if warned and not arrow.holder.Visible and featureSettings.aimWarningSound
								and now - (state.pinged[player] or 0) > 3 then
								state.pinged[player] = now
								ping()
							end
							arrow.holder.Visible = warned
							if warned then
								-- Round the middle of the screen, pointing the way they are from your camera.
								local relative = camera.CFrame:VectorToObjectSpace(theirHead.Position - camera.CFrame.Position)
								local turn = math.atan2(relative.X, -relative.Z)
								arrow.holder.Position = UDim2.fromOffset(viewport.X / 2 + math.sin(turn) * 110, viewport.Y / 2 - math.cos(turn) * 110)
								arrow.icon.Rotation = math.deg(turn)
								arrow.icon.ImageTransparency = 0.15 + 0.25 * (0.5 + 0.5 * math.sin(now * 8))
								arrow.label.Text = menuModules.nameOf(player)
							end
						end
					end
				end
			end
			local function setEnabled(on)
				if state.loop then
					state.loop:Disconnect()
					state.loop = nil
				end
				hideAll()
				gui.Enabled = on
				if on then state.loop = RunService.RenderStepped:Connect(step) end
			end
			menuModules.aimWarning = { setEnabled = setEnabled }

			local entry = quickToggleByName["Aim Warning"]
			local card = entry and createSettingsCard(entry)
			if not card then return end
			card.addSectionLabel("HOW STRAIGHT AT YOU", "crosshair", "target")
			card.addChoice({ "Strict", "Normal", "Loose" }, function() return featureSettings.aimWarningAngle end, function(choice)
				featureSettings.aimWarningAngle = choice
				saveFeatureSettings()
			end)
			card.addSectionLabel("RANGE", "ruler")
			card.addSlider({
				text = "Up to",
				icon = { "ruler", "scan-eye" },
				min = 50, max = 1000, step = 25,
				get = function() return featureSettings.aimWarningRange end,
				set = function(value) featureSettings.aimWarningRange = value end,
				commit = saveFeatureSettings,
				format = function(value) return math.floor(value + 0.5) .. " studs" end,
			})
			card.addSwitchGrid({
				{
					text = "Ping sound",
					get = function() return featureSettings.aimWarningSound == true end,
					set = function(on)
						featureSettings.aimWarningSound = on
						saveFeatureSettings()
					end,
				},
				{
					text = "Leave out teammates",
					get = function() return featureSettings.aimWarningTeam == true end,
					set = function(on)
						featureSettings.aimWarningTeam = on
						saveFeatureSettings()
					end,
				},
			})
			card.addHint("It goes by which way their character faces, so it's surest with players in first person or shift lock, as in most shooters. Walls block it.")
			card.refresh()
		end)

		------------------------------------------------------------------------------------------
		-- Hit Markers: when a player near you loses health, the damage pops off them as a number (KO for
		-- the last of it), an X flashes on your crosshair and a tick plays. Only you see and hear it. With
		-- "Only after you attack" (on to start with), it only counts within a moment of you clicking or
		-- using a tool, which is near enough to "you hit them".
		safeBuild("Hit Markers", function()
			local localPlayer = Players.LocalPlayer
			local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:WaitForChild("PlayerGui")
			local previous = playerGui:FindFirstChild("SpreadCheeksHitMarkers")
			if previous then previous:Destroy() end
			local gui = Instance.new("ScreenGui")
			gui.Name = "SpreadCheeksHitMarkers"
			gui.ResetOnSpawn = false
			gui.IgnoreGuiInset = true
			gui.DisplayOrder = 997
			gui.Enabled = false
			gui.Parent = playerGui
			local state = { on = false, lastAttack = 0, flashSerial = 0 }
			-- The X: four short strokes round the middle of the screen (or the pointer, with Custom Crosshair
			-- following the mouse).
			local cross = Instance.new("Frame")
			cross.AnchorPoint = Vector2.new(0.5, 0.5)
			cross.Position = UDim2.fromScale(0.5, 0.5)
			cross.Size = UDim2.fromOffset(0, 0)
			cross.BackgroundTransparency = 1
			cross.Visible = false
			cross.Parent = gui
			local strokes = {}
			for _, corner in ipairs({ { -1, -1 }, { 1, -1 }, { -1, 1 }, { 1, 1 } }) do
				local stroke = Instance.new("Frame")
				stroke.AnchorPoint = Vector2.new(0.5, 0.5)
				stroke.Position = UDim2.fromOffset(corner[1] * 9, corner[2] * 9)
				stroke.Size = UDim2.fromOffset(9, 2)
				stroke.Rotation = corner[1] * corner[2] * 45
				stroke.BorderSizePixel = 0
				stroke.Parent = cross
				table.insert(strokes, stroke)
			end
			local function flash(killed)
				state.flashSerial += 1
				local serial = state.flashSerial
				if featureSettings.crosshairPlace == "Mouse" then
					local mouse = UserInputService:GetMouseLocation()
					cross.Position = UDim2.fromOffset(mouse.X, mouse.Y)
				else
					cross.Position = UDim2.fromScale(0.5, 0.5)
				end
				for _, stroke in ipairs(strokes) do
					stroke.BackgroundColor3 = killed and Color3.fromRGB(239, 68, 68) or Color3.new(1, 1, 1)
				end
				cross.Visible = true
				task.delay(killed and 0.4 or 0.2, function()
					if state.flashSerial == serial then cross.Visible = false end
				end)
			end
			local function tick(killed)
				local sound = Instance.new("Sound")
				sound.SoundId = "rbxasset://sounds/electronicpingshort.wav"
				sound.PlaybackSpeed = killed and 1.3 or 2.4
				sound.Volume = 0.45
				sound.Parent = SoundService
				sound:Play()
				task.delay(2, function() sound:Destroy() end)
			end
			-- The damage, floating up off their head and fading.
			local function popNumber(head, lost, killed)
				local board = Instance.new("BillboardGui")
				board.Name = "SpreadCheeksHitNumber"
				board.Adornee = head
				board.AlwaysOnTop = true
				board.Size = UDim2.fromOffset(90, 28)
				board.StudsOffset = Vector3.new((math.random() - 0.5) * 2, 2.5, 0)
				-- Straight in PlayerGui: a billboard inside a ScreenGui isn't drawn.
				board.Parent = playerGui
				local label = Instance.new("TextLabel")
				label.Size = UDim2.fromScale(1, 1)
				label.BackgroundTransparency = 1
				label.Font = Enum.Font.GothamBold
				label.TextSize = killed and 22 or 18
				label.Text = killed and "KO" or tostring(math.floor(lost + 0.5))
				label.TextColor3 = killed and Color3.fromRGB(239, 68, 68) or Color3.fromRGB(255, 214, 64)
				label.TextStrokeTransparency = 0.3
				label.Parent = board
				local float = TweenInfo.new(0.8, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				TweenService:Create(board, float, { StudsOffset = board.StudsOffset + Vector3.new(0, 2, 0) }):Play()
				TweenService:Create(label, float, { TextTransparency = 1, TextStrokeTransparency = 1 }):Play()
				task.delay(0.85, function() board:Destroy() end)
			end
			-- Your attacks: clicks and taps that aren't on this menu, and tools being used.
			UserInputService.InputBegan:Connect(function(input)
				local kind = input.UserInputType
				if (kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch or input.KeyCode == Enum.KeyCode.ButtonR2)
					and not pointerOverMenu() then
					state.lastAttack = os.clock()
				end
			end)
			local function hookTools(character)
				character.ChildAdded:Connect(function(child)
					if child:IsA("Tool") then
						child.Activated:Connect(function() state.lastAttack = os.clock() end)
					end
				end)
			end
			if localPlayer.Character then hookTools(localPlayer.Character) end
			localPlayer.CharacterAdded:Connect(hookTools)
			-- Everyone else's health, on each of their characters.
			local function watch(player)
				if player == localPlayer then return end
				local function hook(character)
					local humanoid = character:WaitForChild("Humanoid", 10)
					if not humanoid then return end
					local last = humanoid.Health
					humanoid.HealthChanged:Connect(function(health)
						local lost = last - health
						last = health
						if not state.on or lost < 0.5 then return end
						if featureSettings.hitOnlyYours and os.clock() - state.lastAttack > 1.5 then return end
						local myRoot = localPlayer.Character and getRoot(localPlayer.Character)
						local theirRoot = getRoot(character)
						if not myRoot or not theirRoot or (theirRoot.Position - myRoot.Position).Magnitude > featureSettings.hitRange then return end
						local killed = health <= 0
						local head = character:FindFirstChild("Head") or theirRoot
						if featureSettings.hitNumbers then popNumber(head, lost, killed) end
						flash(killed)
						if featureSettings.hitSound then tick(killed) end
					end)
				end
				if player.Character then task.spawn(hook, player.Character) end
				player.CharacterAdded:Connect(hook)
			end
			for _, player in ipairs(Players:GetPlayers()) do watch(player) end
			Players.PlayerAdded:Connect(watch)
			menuModules.hitMarkers = {
				setEnabled = function(on)
					state.on = on
					gui.Enabled = on
				end,
			}

			local entry = quickToggleByName["Hit Markers"]
			local card = entry and createSettingsCard(entry)
			if not card then return end
			card.addSectionLabel("SHOW", "crosshair", "hash")
			card.addSwitchGrid({
				{
					text = "Damage numbers",
					get = function() return featureSettings.hitNumbers == true end,
					set = function(on)
						featureSettings.hitNumbers = on
						saveFeatureSettings()
					end,
				},
				{
					text = "Hit sound",
					get = function() return featureSettings.hitSound == true end,
					set = function(on)
						featureSettings.hitSound = on
						saveFeatureSettings()
					end,
				},
				{
					text = "Only after you attack",
					get = function() return featureSettings.hitOnlyYours == true end,
					set = function(on)
						featureSettings.hitOnlyYours = on
						saveFeatureSettings()
					end,
				},
			})
			card.addSectionLabel("RANGE", "ruler")
			card.addSlider({
				text = "Players within",
				icon = { "ruler", "users-round" },
				min = 25, max = 500, step = 25,
				get = function() return featureSettings.hitRange end,
				set = function(value) featureSettings.hitRange = value end,
				commit = saveFeatureSettings,
				format = function(value) return math.floor(value + 0.5) .. " studs" end,
			})
			card.addHint("Roblox doesn't say who did the damage, so Only after you attack counts damage within a moment of you clicking or using a tool. Off, it shows everyone's damage nearby.")
			card.refresh()
		end)

		------------------------------------------------------------------------------------------
		-- Custom Crosshair: a crosshair of your own in the middle of the screen (or on your pointer): a dot,
		-- a cross, a cross with a dot, or a circle, in any of a few colours, as big, thick and open as its
		-- settings card says, with a dark outline so it shows on anything.
		safeBuild("Custom Crosshair", function()
			local localPlayer = Players.LocalPlayer
			local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:WaitForChild("PlayerGui")
			local previous = playerGui:FindFirstChild("SpreadCheeksCrosshair")
			if previous then previous:Destroy() end
			local gui = Instance.new("ScreenGui")
			gui.Name = "SpreadCheeksCrosshair"
			gui.ResetOnSpawn = false
			gui.IgnoreGuiInset = true
			gui.DisplayOrder = 995
			gui.Enabled = false
			gui.Parent = playerGui
			local holder = Instance.new("Frame")
			holder.AnchorPoint = Vector2.new(0.5, 0.5)
			holder.Position = UDim2.fromScale(0.5, 0.5)
			holder.Size = UDim2.fromOffset(0, 0)
			holder.BackgroundTransparency = 1
			holder.Parent = gui
			local function outlined(frame)
				local outline = Instance.new("UIStroke")
				outline.Color = Color3.new(0, 0, 0)
				outline.Transparency = 0.35
				outline.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				outline.Parent = frame
				return outline
			end
			-- The four arms of the cross: right, left, down, up.
			local arms = {}
			for _, way in ipairs({ { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }) do
				local arm = Instance.new("Frame")
				arm.AnchorPoint = Vector2.new(0.5, 0.5)
				arm.BorderSizePixel = 0
				arm.Parent = holder
				table.insert(arms, { frame = arm, outline = outlined(arm), x = way[1], y = way[2] })
			end
			local dot = Instance.new("Frame")
			dot.AnchorPoint = Vector2.new(0.5, 0.5)
			dot.BorderSizePixel = 0
			dot.Parent = holder
			local dotCorner = Instance.new("UICorner")
			dotCorner.CornerRadius = UDim.new(1, 0)
			dotCorner.Parent = dot
			local dotOutline = outlined(dot)
			local ring = Instance.new("Frame")
			ring.AnchorPoint = Vector2.new(0.5, 0.5)
			ring.BackgroundTransparency = 1
			ring.Parent = holder
			local ringCorner = Instance.new("UICorner")
			ringCorner.CornerRadius = UDim.new(1, 0)
			ringCorner.Parent = ring
			local ringLine = Instance.new("UIStroke")
			ringLine.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			ringLine.Parent = ring
			local colours = {
				White = Color3.new(1, 1, 1), Red = Color3.fromRGB(239, 68, 68), Green = Color3.fromRGB(74, 222, 128),
				Cyan = Color3.fromRGB(34, 211, 238), Yellow = Color3.fromRGB(250, 204, 21), Pink = Color3.fromRGB(244, 114, 182),
			}
			local function layout()
				local style = featureSettings.crosshairStyle
				local size, thick, gap = featureSettings.crosshairSize, featureSettings.crosshairThickness, featureSettings.crosshairGap
				local colour = colours[featureSettings.crosshairColor] or auxiliaryUiTheme.Accent
				local outline = featureSettings.crosshairOutline == true
				local cross = style == "Cross" or style == "Cross + Dot"
				for _, arm in ipairs(arms) do
					arm.frame.Visible = cross
					arm.frame.BackgroundColor3 = colour
					arm.outline.Enabled = outline
					if arm.x ~= 0 then
						arm.frame.Size = UDim2.fromOffset(size, thick)
						arm.frame.Position = UDim2.fromOffset(arm.x * (gap + size / 2), 0)
					else
						arm.frame.Size = UDim2.fromOffset(thick, size)
						arm.frame.Position = UDim2.fromOffset(0, arm.y * (gap + size / 2))
					end
				end
				dot.Visible = style == "Dot" or style == "Cross + Dot"
				local dotSize = style == "Dot" and math.max(4, math.floor(size / 3)) or math.max(3, thick + 2)
				dot.Size = UDim2.fromOffset(dotSize, dotSize)
				dot.BackgroundColor3 = colour
				dotOutline.Enabled = outline
				ring.Visible = style == "Circle"
				ring.Size = UDim2.fromOffset(size * 2, size * 2)
				ringLine.Thickness = thick
				ringLine.Color = colour
			end
			local state = { loop = nil }
			local function setEnabled(on)
				if state.loop then
					state.loop:Disconnect()
					state.loop = nil
				end
				gui.Enabled = on
				if not on then return end
				layout()
				-- On your pointer, it follows it every frame.
				state.loop = RunService.RenderStepped:Connect(function()
					if featureSettings.crosshairPlace == "Mouse" then
						local mouse = UserInputService:GetMouseLocation()
						holder.Position = UDim2.fromOffset(mouse.X, mouse.Y)
					else
						holder.Position = UDim2.fromScale(0.5, 0.5)
					end
				end)
			end
			menuModules.crosshair = { setEnabled = setEnabled, refresh = function() pcall(layout) end }
			table.insert(auxiliaryUiThemeListeners, function() pcall(layout) end)

			local entry = quickToggleByName["Custom Crosshair"]
			local card = entry and createSettingsCard(entry)
			if not card then return end
			local function setting(key)
				return function(value)
					featureSettings[key] = value
					saveFeatureSettings()
					pcall(layout)
				end
			end
			card.addSectionLabel("STYLE", "crosshair")
			card.addChoice({ "Dot", "Cross", "Cross + Dot", "Circle" }, function() return featureSettings.crosshairStyle end, setting("crosshairStyle"))
			card.addSectionLabel("COLOUR", "palette")
			card.addChoice({ "Theme", "White", "Red", "Green" }, function() return featureSettings.crosshairColor end, setting("crosshairColor"))
			card.addChoice({ "Cyan", "Yellow", "Pink" }, function() return featureSettings.crosshairColor end, setting("crosshairColor"))
			card.addSectionLabel("SHAPE", "ruler")
			for _, slider in ipairs({
				{ "Size", "crosshairSize", 4, 40, { "maximize-2" } },
				{ "Thickness", "crosshairThickness", 1, 5, { "minus" } },
				{ "Gap in the middle", "crosshairGap", 0, 16, { "move-horizontal" } },
			}) do
				local key = slider[2]
				card.addSlider({
					text = slider[1],
					icon = slider[5],
					min = slider[3], max = slider[4], step = 1,
					get = function() return featureSettings[key] end,
					set = function(value)
						featureSettings[key] = value
						pcall(layout)
					end,
					commit = saveFeatureSettings,
					format = function(value) return math.floor(value + 0.5) .. " px" end,
				})
			end
			card.addSwitchGrid({
				{
					text = "Dark outline",
					get = function() return featureSettings.crosshairOutline == true end,
					set = function(on)
						featureSettings.crosshairOutline = on
						saveFeatureSettings()
						pcall(layout)
					end,
				},
			}, 1)
			card.addSectionLabel("WHERE", "move")
			card.addChoice({ "Centre", "Mouse" }, function() return featureSettings.crosshairPlace end, setting("crosshairPlace"))
			card.addHint("Centre is for first person and shift lock, where you aim with the middle of the screen. Mouse puts it on your pointer, for games you aim with the mouse.")
			card.refresh()
		end)

		------------------------------------------------------------------------------------------
		-- Silent Aim (28 October 2026): while it's on, the game's shots go to whoever's nearest your cursor
		-- inside the aimbot's circle, while your view and cursor stay where they are. Who it picks comes
		-- from the aimbot (aimbotState.pick): its circle, part, aim prediction, and team, wall and friend
		-- checks. It works by changing the answers to the game's own questions about where you're aiming:
		-- the mouse's Hit and Target, raycasts that start near you and head roughly where you're aiming (so
		-- the game's camera and ground checks are left alone), and, if chosen, the camera's rays through
		-- the cursor. The menu's own questions are never changed. It needs an executor that can hook
		-- metamethods; the hooks go in the first time it's switched on, are tested straight away, and stay
		-- in for the rest of the game, doing nothing while it's off. Its settings card shows what the game
		-- has asked and what was sent at the target, to see why it isn't working in a game. Auto shoot, in
		-- its settings, has the Trigger Bot's clicker fire for you while it has a target.
		safeBuild("Silent Aim", function()
			local localPlayer = Players.LocalPlayer
			local silent = aimbotState.silent
			-- What the hooks read. It's kept in the shared environment, so running the script again uses the
			-- hooks already in rather than adding more. on: switched on. active: on, with a target, and this
			-- frame's roll of the hit chance came up. busy: Silent Aim's own work is running, so the calls
			-- are its own. counts: what the game has asked since it was switched on, what was sent at the
			-- target, and why the rest weren't.
			local shared = sharedEnv.SpreadCheeksSilentAim or {}
			sharedEnv.SpreadCheeksSilentAim = shared
			if shared.loop then pcall(function() shared.loop:Disconnect() end) end
			shared.loop = nil
			shared.on = false
			shared.active = false
			shared.busy = false
			shared.testing = nil
			local function newCounts()
				return { raycast = 0, oldRays = 0, cameraRays = 0, mouse = 0, sent = 0, mouseSent = 0, far = 0, away = 0, short = 0 }
			end
			shared.counts = newCounts()
			shared.mouse = localPlayer:GetMouse()

			local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:WaitForChild("PlayerGui")
			local previous = playerGui:FindFirstChild("SpreadCheeksSilentAim")
			if previous then previous:Destroy() end
			local gui = Instance.new("ScreenGui")
			gui.Name = "SpreadCheeksSilentAim"
			gui.ResetOnSpawn = false
			gui.IgnoreGuiInset = true
			gui.DisplayOrder = 998
			gui.Parent = playerGui
			-- The mark: a small ring on whoever it's on.
			local mark = Instance.new("Frame")
			mark.AnchorPoint = Vector2.new(0.5, 0.5)
			mark.Size = UDim2.fromOffset(14, 14)
			mark.BackgroundTransparency = 1
			mark.Visible = false
			mark.Parent = gui
			local markCorner = Instance.new("UICorner")
			markCorner.CornerRadius = UDim.new(1, 0)
			markCorner.Parent = mark
			local markStroke = Instance.new("UIStroke")
			markStroke.Thickness = 2
			bindAuxiliaryUiColor(markStroke, "Color", "AccentText")
			markStroke.Parent = mark

			-- The game's calls it looks at, by method, and the switch each comes under. And the mouse's
			-- properties it answers, with what it answers them from.
			local watched = {
				Raycast = "raycast", Spherecast = "raycast", Blockcast = "raycast",
				FindPartOnRay = "oldRays", findPartOnRay = "oldRays", FindPartOnRayWithIgnoreList = "oldRays", FindPartOnRayWithWhitelist = "oldRays",
				ScreenPointToRay = "cameraRays", ViewportPointToRay = "cameraRays",
			}
			local mouseKeys = { Hit = "hit", hit = "hit", Target = "part", target = "part", UnitRay = "unitRay" }

			-- Where a ray the game is about to cast should go instead: at the target, if it starts near you
			-- (your camera or your character) and heads within about 50 degrees of where you're aiming. nil
			-- leaves it alone. Nothing in the hooks calls a method with a colon, which would change the method
			-- the game's call goes on to.
			local function redirect(origin, direction)
				if typeof(origin) ~= "Vector3" or typeof(direction) ~= "Vector3" then return nil end
				local counts = shared.counts
				local length = direction.Magnitude
				if length < 4 then
					counts.short += 1
					return nil
				end
				local root = shared.root
				if (origin - shared.from).Magnitude > 30 and (not root or (origin - root).Magnitude > 30) then
					counts.far += 1
					return nil
				end
				local look = shared.look
				if (direction.X * look.X + direction.Y * look.Y + direction.Z * look.Z) / length < 0.64 then
					counts.away += 1
					return nil
				end
				local toTarget = shared.point - origin
				local distance = toTarget.Magnitude
				if distance < 0.01 then return nil end
				counts.sent += 1
				-- At least as long as it was, and long enough to reach them.
				return toTarget.Unit * math.max(length, distance + 5)
			end

			-- Puts the hooks in, once a game, and checks they really run. Returns whether any work. They go on
			-- a new folder rather than game, which some executors hand scripts a stand-in for; every instance
			-- shares one metatable, so that hooks them all.
			local function installHooks()
				if shared.hookState == "working" or shared.hookState == "partial" then return true end
				if shared.hookState == "fake" or shared.hookState == "failed" then return false end
				if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then
					shared.hookState = "missing"
					return false
				end
				-- newcclosure hides the hooks from the game. Infinite Yield puts in a stand-in when the executor
				-- has none, which runs the function instead of wrapping it, so only a real one is used.
				local wrap = function(callback) return callback end
				if type(newcclosure) == "function" then
					local wrapOk, wrapped = pcall(newcclosure, function() return true end)
					if wrapOk and type(wrapped) == "function" then wrap = newcclosure end
				end
				local isCaller = type(checkcaller) == "function" and checkcaller or function() return false end
				-- Whether the executor can tell its own calls from the game's (the menu's calls outside
				-- Silent Aim's own work can't be told apart otherwise).
				shared.checkcallerWorks = isCaller() == true
				local probe = Instance.new("Folder")
				local meta = nil
				if type(getrawmetatable) == "function" then pcall(function() meta = getrawmetatable(probe) end) end

				local namecallOk, namecallProblem = pcall(function()
					local original = meta and rawget(meta, "__namecall")
					local oldNamecall
					oldNamecall = hookmetamethod(probe, "__namecall", wrap(function(self, ...)
						local method = getnamecallmethod()
						if shared.testing == "namecall" then shared.tested = true end
						if not shared.on or shared.busy or isCaller() then return oldNamecall(self, ...) end
						local kind = watched[method]
						if kind then
							local counts = shared.counts
							counts[kind] += 1
							if shared.active and shared[kind] then
								if kind == "raycast" then
									-- Raycast(origin, direction, params); Spherecast(position, radius, direction,
									-- params); Blockcast(cframe, size, direction, params).
									local args = table.pack(...)
									local slot = method == "Raycast" and 2 or 3
									local origin = args[1]
									if typeof(origin) == "CFrame" then origin = origin.Position end
									local aimed = redirect(origin, args[slot])
									if aimed then
										args[slot] = aimed
										return oldNamecall(self, table.unpack(args, 1, args.n))
									end
								elseif kind == "oldRays" then
									local ray = ...
									if typeof(ray) == "Ray" then
										local aimed = redirect(ray.Origin, ray.Direction)
										if aimed then
											local args = table.pack(...)
											args[1] = Ray.new(ray.Origin, aimed)
											return oldNamecall(self, table.unpack(args, 1, args.n))
										end
									end
								else
									-- Camera rays, only through the cursor (or very near it), which is how games turn
									-- a click into a shot. ScreenPointToRay counts from under Roblox's top bar.
									local x, y = ...
									if type(x) == "number" and type(y) == "number" then
										if method == "ScreenPointToRay" then y += shared.insetY end
										local cursor = shared.cursor
										local dx, dy = x - cursor.X, y - cursor.Y
										if dx * dx + dy * dy <= 3600 then
											local ray = oldNamecall(self, ...)
											if typeof(ray) == "Ray" then
												local toTarget = shared.point - ray.Origin
												if toTarget.Magnitude > 0.01 then
													counts.sent += 1
													return Ray.new(ray.Origin, toTarget.Unit)
												end
											end
											return ray
										end
										counts.away += 1
									end
								end
							end
						end
						return oldNamecall(self, ...)
					end)) or original
				end)
				local namecallWorks = false
				if namecallOk then
					-- A call on the folder has to go through the hook.
					shared.tested = false
					shared.testing = "namecall"
					pcall(function() probe:GetChildren() end)
					shared.testing = nil
					namecallWorks = shared.tested
				end

				local indexOk, indexProblem = pcall(function()
					local original = meta and rawget(meta, "__index")
					local oldIndex
					-- The mouse the game asks about: the one from GetMouse, or any other with the mouse's class.
					local function isMouse(object)
						if rawequal(object, shared.mouse) then return true end
						local class = oldIndex(object, "ClassName")
						return class == "PlayerMouse" or class == "Mouse"
					end
					oldIndex = hookmetamethod(probe, "__index", wrap(function(self, key)
						if shared.testing == "index" then shared.tested = true end
						local which = shared.on and mouseKeys[key]
						if which and not shared.busy and not isCaller() and isMouse(self) then
							local counts = shared.counts
							counts.mouse += 1
							if shared.active and shared.mouseHit then
								counts.mouseSent += 1
								return shared[which]
							end
						end
						return oldIndex(self, key)
					end)) or original
				end)
				local indexWorks = false
				if indexOk then
					-- So does reading one of its properties.
					shared.tested = false
					shared.testing = "index"
					pcall(function()
						local _ = probe.Name
					end)
					shared.testing = nil
					indexWorks = shared.tested
				end
				probe:Destroy()

				shared.raycastHooks, shared.mouseHooks = namecallWorks, indexWorks
				if not namecallOk or not indexOk then
					shared.hookProblem = tostring(not namecallOk and namecallProblem or indexProblem)
				end
				if namecallWorks and indexWorks then
					shared.hookState = "working"
				elseif namecallWorks or indexWorks then
					shared.hookState = "partial"
				elseif namecallOk or indexOk then
					shared.hookState = "fake"
				else
					shared.hookState = "failed"
				end
				return namecallWorks or indexWorks
			end

			-- Each frame: who it's on, and everything the hooks need, worked out once so they do as little
			-- as possible.
			local randomPick = { target = nil, part = nil, nextPickAt = 0 }
			local rng = Random.new()
			local function clear()
				shared.active = false
				silent.target = nil
				mark.Visible = false
			end
			local function holdingTool()
				local character = localPlayer.Character
				return character ~= nil and character:FindFirstChildOfClass("Tool") ~= nil
			end
			local function step()
				local pick = aimbotState.pick
				local camera = workspace.CurrentCamera
				if not pick or not camera or (featureSettings.silentAimToolOnly and not holdingTool()) then return clear() end
				local cursor = UserInputService:GetMouseLocation()
				-- Whoever the aimbot is locked on, or else whoever's nearest the cursor inside the circle.
				local target, part = aimbotState.target, nil
				if target and target.Parent then
					part = pick.targetPart(target)
					if part and not pick.canAimAt(part, target.Character) then part = nil end
				end
				if not part then
					target = pick.findTarget(cursor)
					part = target and pick.targetPart(target)
				end
				if not part then return clear() end
				local aimAt = featureSettings.aimbotRandomPart and pick.randomPartFor(target, part, randomPick) or part
				local point = pick.leadPoint(aimAt)
				local from = camera.CFrame.Position
				local toward = (point - from).Unit
				local root = localPlayer.Character and getRoot(localPlayer.Character)
				silent.target = target
				shared.point, shared.part, shared.from, shared.cursor = point, aimAt, from, cursor
				shared.root = root and root.Position or nil
				shared.look = camera:ViewportPointToRay(cursor.X, cursor.Y).Direction
				shared.insetY = GuiService:GetGuiInset().Y
				shared.hit = CFrame.lookAt(point, point + toward)
				shared.unitRay = Ray.new(from, toward)
				shared.mouseHit = featureSettings.silentAimMouse
				shared.raycast = featureSettings.silentAimRaycast
				shared.oldRays = featureSettings.silentAimOldRays
				shared.cameraRays = featureSettings.silentAimCameraRays
				-- The hit chance is rolled once a frame, so everything one shot asks gets the same answer.
				shared.active = featureSettings.silentAimChance >= 100 or rng:NextNumber() * 100 < featureSettings.silentAimChance
				local screen, onScreen = camera:WorldToViewportPoint(point)
				mark.Visible = featureSettings.silentAimMark and onScreen
				if mark.Visible then mark.Position = UDim2.fromOffset(screen.X, screen.Y) end
			end

			local function executorName()
				local name = nil
				pcall(function()
					if type(identifyexecutor) == "function" then name = identifyexecutor() end
				end)
				return (type(name) == "string" and name ~= "") and name or "your executor"
			end
			local function capitalised(text)
				return text:sub(1, 1):upper() .. text:sub(2)
			end
			-- What's going on, for its settings card and the silentaimstatus command.
			local function statusText()
				local executor = executorName()
				local state = shared.hookState
				local lines = {}
				if state == nil then
					return "Switch it on, then shoot at someone, and this shows what the game does."
				elseif state == "missing" then
					table.insert(lines, capitalised(executor) .. " doesn't have hookmetamethod, which Silent Aim needs, so it can't work there.")
				elseif state == "fake" then
					table.insert(lines, capitalised(executor) .. " has hookmetamethod, but it doesn't actually hook anything, so Silent Aim can't work there.")
				elseif state == "failed" then
					table.insert(lines, capitalised(executor) .. " wouldn't let Silent Aim hook the game: " .. tostring(shared.hookProblem))
				elseif state == "partial" then
					table.insert(lines, "Only some hooks work in " .. executor .. ": raycasts " .. (shared.raycastHooks and "yes" or "no")
						.. ", mouse " .. (shared.mouseHooks and "yes" or "no") .. ".")
				else
					table.insert(lines, "Hooks working in " .. executor .. ".")
				end
				if state == "working" and not shared.checkcallerWorks then
					table.insert(lines, "It can't tell the menu's own calls from the game's, so the numbers include some of the menu's.")
				end
				if not silent.on then
					if state == "working" or state == "partial" then table.insert(lines, "Switched off.") end
					return table.concat(lines, "\n")
				end
				local target = silent.target
				if target then
					table.insert(lines, "Aiming at " .. menuModules.nameOf(target) .. ".")
				else
					local others, bodies = 0, 0
					for _, player in ipairs(Players:GetPlayers()) do
						if player ~= localPlayer then
							others += 1
							local character = player.Character
							if character and character:FindFirstChildOfClass("Humanoid") then bodies += 1 end
						end
					end
					table.insert(lines, "Nobody in the circle right now (" .. bodies .. " of the " .. others
						.. " others here have a normal body it can aim at). If someone's in it, try Wall check off.")
				end
				local counts = shared.counts
				table.insert(lines, string.format("Since you switched it on, the game asked for %d raycasts, %d old raycasts, %d camera rays and %d mouse hits.",
					counts.raycast, counts.oldRays, counts.cameraRays, counts.mouse))
				table.insert(lines, string.format("Sent at your target: %d rays and %d mouse hits. Left alone: %d too far from you, %d pointing away, %d too short.",
					counts.sent, counts.mouseSent, counts.far, counts.away, counts.short))
				return table.concat(lines, "\n")
			end

			local entry = quickToggleByName["Silent Aim"]
			local function stop()
				if shared.loop then
					shared.loop:Disconnect()
					shared.loop = nil
				end
				shared.on = false
				silent.on = false
				clear()
			end
			-- Why it won't switch on, after the executor's name.
			local cantReasons = {
				missing = " doesn't have hookmetamethod, which Silent Aim needs. The Aimbot's Free aim works instead",
				fake = "'s hookmetamethod doesn't actually hook anything, so Silent Aim can't work. The Aimbot's Free aim works instead",
				failed = " wouldn't let Silent Aim hook the game. The Aimbot's Free aim works instead",
			}
			local function setEnabled(on)
				stop()
				if not on then return end
				if not aimbotState.pick then
					notify("Silent Aim", "It goes by the Aimbot's settings, and the Aimbot didn't load", 4)
					return false
				end
				local hooked = false
				local installOk, problem = pcall(function() hooked = installHooks() end)
				if not installOk then
					shared.hookState, shared.hookProblem = "failed", tostring(problem)
				end
				if not hooked then
					notify("Silent Aim", capitalised(executorName()) .. (cantReasons[shared.hookState] or cantReasons.failed), 6)
					return false
				end
				shared.counts = newCounts()
				shared.on = true
				silent.on = true
				shared.loop = RunService.RenderStepped:Connect(function()
					shared.busy = true
					local stepOk, stepProblem = pcall(step)
					shared.busy = false
					if not stepOk then
						stop()
						warn("[SpreadCheeksGUI] Silent Aim stopped: " .. tostring(stepProblem))
						if entry then task.defer(setQuickToggle, entry, false) end
					end
				end)
				notify("Silent Aim", "Your shots go to whoever's nearest your cursor inside the circle", 3)
			end
			menuModules.silentAim = { setEnabled = setEnabled, status = statusText }

			local card = entry and createSettingsCard(entry)
			if not card then return end
			local function setting(text, key)
				return {
					text = text,
					get = function() return featureSettings[key] == true end,
					set = function(on)
						featureSettings[key] = on
						saveFeatureSettings()
					end,
				}
			end
			-- Who it goes for: the Aimbot's settings, here too so they're to hand.
			card.addSectionLabel("TARGET", "target", "crosshair")
			card.addChoice({ "Head", "Torso", "Random" }, function()
				return featureSettings.aimbotRandomPart and "Random" or featureSettings.aimbotPart
			end, function(option)
				if option == "Random" then
					featureSettings.aimbotRandomPart = true
				else
					featureSettings.aimbotPart = option
					featureSettings.aimbotRandomPart = false
				end
				saveFeatureSettings()
			end)
			card.addSwitchGrid({ setting("Team check", "aimbotTeamCheck"), setting("Wall check", "aimbotWallCheck"), setting("Friend check", "aimbotFriendCheck") })
			card.addSectionLabel("FOV", "circle-dashed", "circle")
			card.addSlider({
				text = "Circle size",
				icon = { "circle-dashed", "circle" },
				min = 20, max = 600, step = 10,
				get = function() return featureSettings.aimbotFov end,
				set = function(value) featureSettings.aimbotFov = value end,
				commit = saveFeatureSettings,
				format = function(value) return math.floor(value + 0.5) .. " px" end,
			})
			card.addSwitchGrid({ setting("Show FOV circle", "aimbotShowFov"), setting("Mark who it's on", "silentAimMark") })
			card.addHint("The target, checks and circle are the Aimbot's too, so changing them here changes them there. Aim prediction is in the Aimbot's settings.")

			card.addSectionLabel("HIT CHANCE", "percent", "target")
			card.addSlider({
				text = "Hit chance",
				icon = { "percent", "dices" },
				min = 5, max = 100, step = 5,
				get = function() return featureSettings.silentAimChance end,
				set = function(value) featureSettings.silentAimChance = value end,
				commit = saveFeatureSettings,
				format = function(value) return math.floor(value + 0.5) .. "%" end,
			})
			card.addHint("Below 100%, some shots go where you're really aiming, so it looks less perfect.")

			card.addSectionLabel("WHAT IT TAKES OVER", "mouse-pointer-2", "mouse-pointer")
			card.addSwitchGrid({
				setting("Mouse hit", "silentAimMouse"),
				setting("Raycasts", "silentAimRaycast"),
				setting("Old raycasts", "silentAimOldRays"),
				setting("Camera rays", "silentAimCameraRays"),
			})
			card.addHint("Games aim their shots in different ways, and these are the ones it can take over. If your shots still go where you aim, switch on Camera rays. If something else in the game acts oddly while it's on, switch off what that game doesn't need.")
			card.addSwitchGrid({ setting("Only with a tool out", "silentAimToolOnly") }, 1)
			card.addHint("Leaves everything alone unless you're holding a tool, for games where you click on things. Games with their own guns that aren't tools need this off.")

			-- Auto shoot: fires for you the moment someone's in the circle. The clicking is the Trigger Bot's
			-- (built further up), which goes by these settings while it's firing at Silent Aim's target.
			card.addSectionLabel("AUTO SHOOT", "mouse-pointer-click", "zap")
			card.addSwitchGrid({ setting("Auto shoot", "silentAimAutoShoot") }, 1)
			card.addChoice({ "Tap", "Hold" }, function() return featureSettings.silentAimShootMode end, function(mode)
				featureSettings.silentAimShootMode = mode
				saveFeatureSettings()
			end)
			card.addHint(function()
				if featureSettings.silentAimShootMode == "Hold" then
					return "Holds the mouse button down while someone's in the circle and lets go when nobody is, for automatic guns."
				end
				return "Clicks the moment someone's in the circle, then again every shot delay while they're in it, for guns that fire once per click."
			end)
			card.addSlider({
				text = "Reaction time",
				icon = { "timer", "clock" },
				min = 0, max = 500, step = 10,
				get = function() return featureSettings.silentAimShootDelay end,
				set = function(value) featureSettings.silentAimShootDelay = value end,
				commit = saveFeatureSettings,
				format = function(value) return value <= 0 and "Instant" or (math.floor(value + 0.5) .. " ms") end,
			})
			card.addSlider({
				text = "Shot delay",
				icon = { "repeat", "rotate-cw" },
				min = 50, max = 1000, step = 10,
				get = function() return featureSettings.silentAimShootInterval end,
				set = function(value) featureSettings.silentAimShootInterval = value end,
				commit = saveFeatureSettings,
				format = function(value) return math.floor(value + 0.5) .. " ms" end,
			})
			card.addHint("It won't click while you're typing, in a menu, dead, or with your cursor on one of the game's buttons. In games where guns are tools, switch on Only with a tool out so it only fires while you're holding one.")

			-- What's happening, kept up to date twice a second while the card is open.
			card.addSectionLabel("WHAT'S HAPPENING", "activity", "info")
			card.addHint(statusText)
			card.refresh()
			task.spawn(function()
				while gui.Parent do
					task.wait(0.5)
					if card.expanded then pcall(card.refresh) end
				end
			end)
		end)

		------------------------------------------------------------------------------------------
		-- Spotify (28 October 2026): your own Spotify in a window, through Spotify's Web API: what's
		-- playing with its cover, play/pause, skip, seek, shuffle, repeat, volume, like, and search to play
		-- a song now or add it to the queue. It plays where Spotify always does (your PC or phone); nobody
		-- in the game hears it. Spotify only allows this with Premium: an app's owner needs it (since
		-- February 2026), and so does controlling playback. Setup is once: you make an app on Spotify's
		-- developer dashboard, paste its Client ID here, approve a login link in your browser and paste
		-- back the address it ends on. The login is Spotify's PKCE kind, so no secret is ever needed. What
		-- Spotify gives back is kept in its own file (spotifyFile), apart from the settings and configs so
		-- sharing a config never shares it, and it renews itself.
		safeBuild("Spotify", function()
			local spotifyFile = "SpreadCheeksGUI_Spotify.json"
			local coverFolder = "SpreadCheeksGUI_SpotifyCovers"
			local redirectUri = "http://127.0.0.1:8888/callback"
			local dashboardUrl = "https://developer.spotify.com/dashboard"
			local scopes = "user-read-playback-state user-modify-playback-state user-read-currently-playing user-library-modify"

			-- saved: what's kept in spotifyFile: the app's Client ID, the login, and the secret behind a
			-- login link that hasn't been approved yet. token: the access token in use and when it runs out.
			-- player: what Spotify last said was playing and when, when it was last asked, and when it may
			-- be asked again.
			local saved = { clientId = "", refreshToken = "", verifier = "", state = "" }
			local token = { value = nil, expiresAt = 0, refreshing = false }
			local player = { playback = nil, fetchedAt = 0, askedAt = 0, polling = false, quietUntil = 0, connecting = false, dragging = nil }
			if readfile then
				local readOk, contents = readfile(spotifyFile, true)
				if readOk and type(contents) == "string" and contents ~= "" then
					local decodeOk, data = pcall(function() return HttpService:JSONDecode(contents) end)
					if decodeOk and type(data) == "table" then
						for key in pairs(saved) do
							if type(data[key]) == "string" then saved[key] = data[key] end
						end
					end
				end
			end
			local function save()
				if writefile then writefile(spotifyFile, HttpService:JSONEncode(saved), true) end
			end

			-- SHA-256 and base64url, for the login: the link carries a hash of a secret kept here, and the
			-- secret itself goes to Spotify afterwards, which proves the approval was for this window.
			local sha256Constants = {
				0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
				0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
				0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
				0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
				0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
				0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
				0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
				0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
			}
			local function sha256(message)
				local hash = { 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19 }
				-- A 1 bit, zeros, and the length in bits as 8 bytes, to a whole number of 64-byte blocks.
				local length = #message
				local lengthBytes = {}
				for shift = 7, 0, -1 do
					table.insert(lengthBytes, string.char(math.floor(length * 8 / 2 ^ (shift * 8)) % 256))
				end
				message = message .. "\128" .. string.rep("\0", (55 - length) % 64) .. table.concat(lengthBytes)
				local words = {}
				for blockStart = 1, #message, 64 do
					for index = 0, 15 do
						local byte1, byte2, byte3, byte4 = string.byte(message, blockStart + index * 4, blockStart + index * 4 + 3)
						words[index] = ((byte1 * 256 + byte2) * 256 + byte3) * 256 + byte4
					end
					for index = 16, 63 do
						local early, late = words[index - 15], words[index - 2]
						local sigma0 = bit32.bxor(bit32.rrotate(early, 7), bit32.rrotate(early, 18), bit32.rshift(early, 3))
						local sigma1 = bit32.bxor(bit32.rrotate(late, 17), bit32.rrotate(late, 19), bit32.rshift(late, 10))
						words[index] = (words[index - 16] + sigma0 + words[index - 7] + sigma1) % 4294967296
					end
					local a, b, c, d, e, f, g, h = table.unpack(hash)
					for index = 0, 63 do
						local sum1 = bit32.bxor(bit32.rrotate(e, 6), bit32.rrotate(e, 11), bit32.rrotate(e, 25))
						local choose = bit32.bxor(bit32.band(e, f), bit32.band(bit32.bnot(e), g))
						local first = (h + sum1 + choose + sha256Constants[index + 1] + words[index]) % 4294967296
						local sum0 = bit32.bxor(bit32.rrotate(a, 2), bit32.rrotate(a, 13), bit32.rrotate(a, 22))
						local majority = bit32.bxor(bit32.band(a, b), bit32.band(a, c), bit32.band(b, c))
						local second = (sum0 + majority) % 4294967296
						h, g, f, e, d, c, b, a = g, f, e, (d + first) % 4294967296, c, b, a, (first + second) % 4294967296
					end
					for index, value in ipairs({ a, b, c, d, e, f, g, h }) do
						hash[index] = (hash[index] + value) % 4294967296
					end
				end
				local digest = {}
				for _, value in ipairs(hash) do
					table.insert(digest, string.char(math.floor(value / 16777216) % 256, math.floor(value / 65536) % 256, math.floor(value / 256) % 256, value % 256))
				end
				return table.concat(digest)
			end
			local base64Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
			local function base64Url(bytes)
				local out = {}
				for start = 1, #bytes, 3 do
					local byte1, byte2, byte3 = string.byte(bytes, start, start + 2)
					local group = byte1 * 65536 + (byte2 or 0) * 256 + (byte3 or 0)
					local count = byte3 and 4 or (byte2 and 3 or 2)
					for place = 1, count do
						local index = math.floor(group / 2 ^ (6 * (4 - place))) % 64
						table.insert(out, string.sub(base64Alphabet, index + 1, index + 1))
					end
				end
				return table.concat(out)
			end
			local function challengeFor(verifier)
				return base64Url(sha256(verifier))
			end
			-- Checked against the worked example in the PKCE standard (RFC 7636) before it's used.
			local checkOk, checked = pcall(challengeFor, "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk")
			local loginWorks = checkOk and checked == "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM"

			local rng = Random.new()
			local function randomText(length)
				local characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
				local out = {}
				for _ = 1, length do
					local index = rng:NextInteger(1, #characters)
					table.insert(out, string.sub(characters, index, index))
				end
				return table.concat(out)
			end
			local function urlEncode(text)
				return (string.gsub(tostring(text), "[^%w%-%._~]", function(character)
					return string.format("%%%02X", string.byte(character))
				end))
			end
			-- 3:07 for milliseconds.
			local function clock(milliseconds)
				local seconds = math.max(0, math.floor((tonumber(milliseconds) or 0) / 1000))
				return string.format("%d:%02d", math.floor(seconds / 60), seconds % 60)
			end
			local function artistsOf(item)
				if type(item) ~= "table" then return "" end
				if type(item.artists) == "table" then
					local names = {}
					for _, artist in ipairs(item.artists) do
						if type(artist) == "table" and artist.name then table.insert(names, tostring(artist.name)) end
					end
					return table.concat(names, ", ")
				end
				-- A podcast episode has its show instead.
				if type(item.show) == "table" and item.show.name then return tostring(item.show.name) end
				return ""
			end
			-- The cover nearest 300 pixels across: sharp enough for the window and quick to download.
			local function coverUrlOf(item)
				if type(item) ~= "table" then return nil end
				local images = (type(item.album) == "table" and item.album.images) or item.images
				if type(images) ~= "table" then return nil end
				local best, bestGap = nil, math.huge
				for _, image in ipairs(images) do
					local gap = math.abs((tonumber(type(image) == "table" and image.width) or 300) - 300)
					if type(image) == "table" and type(image.url) == "string" and gap < bestGap then
						best, bestGap = image.url, gap
					end
				end
				return best
			end

			---------------------------------------------------------------------------------------
			-- The window: the setup steps until you're connected, then the player.
			local spotifyWindow = menuModules.makeWindow({
				name = "SpreadCheeksSpotify", title = "Spotify", icons = { "music", "disc-3", "headphones" },
				width = 340, height = 380, xKey = "spotifyX", yKey = "spotifyY",
				defaultPosition = function(screen, size) return screen.X - size.X - 24, screen.Y - size.Y - 140 end,
			})
			local ui = {}
			local function text(parent, content, font, textSize, role, position, size)
				local made = Instance.new("TextLabel")
				made.Position = position
				made.Size = size
				made.BackgroundTransparency = 1
				made.Font = font
				made.Text = content
				made.TextSize = textSize
				made.TextXAlignment = Enum.TextXAlignment.Left
				made.TextTruncate = Enum.TextTruncate.AtEnd
				bindAuxiliaryUiColor(made, "TextColor3", role)
				made.Parent = parent
				return made
			end
			-- Small print that wraps, in a list that stacks itself.
			local function note(parent, content, role, order)
				local made = text(parent, content, Enum.Font.Gotham, 11, role, UDim2.new(), UDim2.fromScale(1, 0))
				made.LayoutOrder = order
				made.AutomaticSize = Enum.AutomaticSize.Y
				made.TextWrapped = true
				made.TextTruncate = Enum.TextTruncate.None
				made.TextYAlignment = Enum.TextYAlignment.Top
				return made
			end
			local function pill(parent, content, role, textRole, position, size)
				local button = Instance.new("TextButton")
				button.Position = position
				button.Size = size
				button.AutoButtonColor = false
				button.BorderSizePixel = 0
				button.Font = Enum.Font.GothamBold
				button.Text = content
				button.TextSize = 12
				bindAuxiliaryUiColor(button, "BackgroundColor3", role)
				bindAuxiliaryUiColor(button, "TextColor3", textRole)
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(0, 8)
				corner.Parent = button
				button.Parent = parent
				return button
			end
			local function inputBox(parent, placeholder, position, size)
				local box = Instance.new("TextBox")
				box.Position = position
				box.Size = size
				box.BorderSizePixel = 0
				box.ClearTextOnFocus = false
				box.ClipsDescendants = true
				box.Font = Enum.Font.Gotham
				box.PlaceholderText = placeholder
				box.Text = ""
				box.TextSize = 12
				box.TextXAlignment = Enum.TextXAlignment.Left
				bindAuxiliaryUiColor(box, "BackgroundColor3", "Inset")
				bindAuxiliaryUiColor(box, "TextColor3", "Text")
				bindAuxiliaryUiColor(box, "PlaceholderColor3", "Muted")
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(0, 8)
				corner.Parent = box
				local padding = Instance.new("UIPadding")
				padding.PaddingLeft = UDim.new(0, 8)
				padding.PaddingRight = UDim.new(0, 8)
				padding.Parent = box
				box.Parent = parent
				return box
			end
			-- A round button with an icon, or a word when the icon sheet didn't load.
			local function iconButton(parent, iconName, fallback, position, buttonSize, iconSize, role)
				local button = Instance.new("TextButton")
				button.AnchorPoint = Vector2.new(0.5, 0.5)
				button.Position = position
				button.Size = UDim2.fromOffset(buttonSize, buttonSize)
				button.AutoButtonColor = false
				button.BorderSizePixel = 0
				button.Font = Enum.Font.GothamBold
				button.Text = ""
				button.TextSize = 10
				bindAuxiliaryUiColor(button, "BackgroundColor3", role)
				bindAuxiliaryUiColor(button, "TextColor3", role == "Accent" and "OnAccent" or "Text")
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(1, 0)
				corner.Parent = button
				local image = Instance.new("ImageLabel")
				image.AnchorPoint = Vector2.new(0.5, 0.5)
				image.Position = UDim2.fromScale(0.5, 0.5)
				image.Size = UDim2.fromOffset(iconSize, iconSize)
				image.BackgroundTransparency = 1
				image.Parent = button
				button.Parent = parent
				local icon = menuIcons.get(iconName)
				if icon then
					menuIcons.apply(image, icon)
				else
					image.Visible = false
					button.Text = fallback
				end
				return button, image
			end
			local function setIcon(button, image, iconName, fallback)
				local icon = menuIcons.get(iconName)
				if icon and image.Visible then
					menuIcons.apply(image, icon)
				elseif not image.Visible then
					button.Text = fallback
				end
			end

			-- Setup: the steps, stacked by a list layout so wrapped lines push the rest down.
			ui.setup = Instance.new("Frame")
			ui.setup.Size = UDim2.fromScale(1, 1)
			ui.setup.BackgroundTransparency = 1
			ui.setup.Parent = spotifyWindow.body
			ui.setupLayout = Instance.new("UIListLayout")
			ui.setupLayout.Padding = UDim.new(0, 6)
			ui.setupLayout.SortOrder = Enum.SortOrder.LayoutOrder
			ui.setupLayout.Parent = ui.setup
			local setupPadding = Instance.new("UIPadding")
			setupPadding.PaddingTop = UDim.new(0, 4)
			setupPadding.PaddingLeft = UDim.new(0, 14)
			setupPadding.PaddingRight = UDim.new(0, 14)
			setupPadding.Parent = ui.setup
			local heading = text(ui.setup, "Connect your Spotify", Enum.Font.GothamBold, 13, "Text", UDim2.new(), UDim2.new(1, 0, 0, 18))
			heading.LayoutOrder = 1
			note(ui.setup, "Spotify only allows this with Premium: the app's owner needs it, and so do the play and skip buttons. Nobody in the game hears your music.", "Muted", 2)
			note(ui.setup, "1. Make an app on Spotify's developer dashboard. Give it the Redirect URI " .. redirectUri .. ", tick Web API, and save.", "SubText", 3)
			local copyRow = Instance.new("Frame")
			copyRow.LayoutOrder = 4
			copyRow.Size = UDim2.new(1, 0, 0, 26)
			copyRow.BackgroundTransparency = 1
			copyRow.Parent = ui.setup
			ui.copyDashboard = pill(copyRow, "Copy dashboard link", "Inset", "Text", UDim2.new(), UDim2.new(0.5, -3, 1, 0))
			ui.copyRedirect = pill(copyRow, "Copy Redirect URI", "Inset", "Text", UDim2.new(0.5, 3, 0, 0), UDim2.new(0.5, -3, 1, 0))
			note(ui.setup, "2. Paste the app's Client ID here (it's on the app's page):", "SubText", 5)
			ui.clientId = inputBox(ui.setup, "Client ID", UDim2.new(), UDim2.new(1, 0, 0, 28))
			ui.clientId.LayoutOrder = 6
			ui.clientId.Text = saved.clientId
			note(ui.setup, "3. Copy the login link, open it in your browser and press Agree:", "SubText", 7)
			ui.copyLogin = pill(ui.setup, "Copy login link", "Accent", "OnAccent", UDim2.new(), UDim2.new(1, 0, 0, 28))
			ui.copyLogin.LayoutOrder = 8
			note(ui.setup, "4. The page it ends on won't load. That's fine: copy its whole address from the address bar and paste it here.", "SubText", 9)
			local pasteRow = Instance.new("Frame")
			pasteRow.LayoutOrder = 10
			pasteRow.Size = UDim2.new(1, 0, 0, 28)
			pasteRow.BackgroundTransparency = 1
			pasteRow.Parent = ui.setup
			ui.code = inputBox(pasteRow, redirectUri .. "?code=...", UDim2.new(), UDim2.new(1, -88, 1, 0))
			ui.connect = pill(pasteRow, "Connect", "Accent", "OnAccent", UDim2.new(1, -80, 0, 0), UDim2.new(0, 80, 1, 0))
			ui.setupMessage = note(ui.setup, "", "AccentText", 11)

			-- The player.
			ui.player = Instance.new("Frame")
			ui.player.Size = UDim2.fromScale(1, 1)
			ui.player.BackgroundTransparency = 1
			ui.player.Visible = false
			ui.player.Parent = spotifyWindow.body
			ui.cover = Instance.new("ImageLabel")
			ui.cover.Position = UDim2.fromOffset(14, 6)
			ui.cover.Size = UDim2.fromOffset(76, 76)
			ui.cover.BorderSizePixel = 0
			ui.cover.ScaleType = Enum.ScaleType.Crop
			bindAuxiliaryUiColor(ui.cover, "BackgroundColor3", "Inset")
			ui.cover.Parent = ui.player
			local coverCorner = Instance.new("UICorner")
			coverCorner.CornerRadius = UDim.new(0, 8)
			coverCorner.Parent = ui.cover
			-- A note on the cover while there's no picture.
			ui.coverIcon = Instance.new("ImageLabel")
			ui.coverIcon.AnchorPoint = Vector2.new(0.5, 0.5)
			ui.coverIcon.Position = UDim2.fromScale(0.5, 0.5)
			ui.coverIcon.Size = UDim2.fromOffset(26, 26)
			ui.coverIcon.BackgroundTransparency = 1
			bindAuxiliaryUiColor(ui.coverIcon, "ImageColor3", "Muted")
			local musicIcon = menuIcons.get("music", "disc-3")
			if musicIcon then menuIcons.apply(ui.coverIcon, musicIcon) end
			ui.coverIcon.Parent = ui.cover
			ui.title = text(ui.player, "Nothing playing", Enum.Font.GothamBold, 14, "Text", UDim2.fromOffset(100, 8), UDim2.new(1, -144, 0, 18))
			ui.artist = text(ui.player, "", Enum.Font.Gotham, 12, "SubText", UDim2.fromOffset(100, 28), UDim2.new(1, -114, 0, 16))
			ui.detail = text(ui.player, "", Enum.Font.Gotham, 11, "Muted", UDim2.fromOffset(100, 46), UDim2.new(1, -114, 0, 14))
			ui.like, ui.likeImage = iconButton(ui.player, "heart", "Like", UDim2.new(1, -27, 0, 17), 26, 14, "Inset")
			-- How far through: the times either side of a bar, with a taller strip over it to click or drag.
			ui.elapsed = text(ui.player, "0:00", Enum.Font.GothamMedium, 10, "Muted", UDim2.fromOffset(14, 90), UDim2.fromOffset(38, 14))
			ui.elapsed.TextXAlignment = Enum.TextXAlignment.Right
			ui.total = text(ui.player, "0:00", Enum.Font.GothamMedium, 10, "Muted", UDim2.new(1, -52, 0, 90), UDim2.fromOffset(38, 14))
			local function bar(position, size)
				local back = Instance.new("Frame")
