				return back, fill, area
			end
			ui.progress, ui.progressFill, ui.seekArea = bar(UDim2.fromOffset(58, 95), UDim2.new(1, -116, 0, 4))
			local controlsY = 128
			ui.shuffle, ui.shuffleImage = iconButton(ui.player, "shuffle", "Mix", UDim2.new(0.5, -92, 0, controlsY), 30, 15, "Inset")
			ui.previous, ui.previousImage = iconButton(ui.player, "skip-back", "Back", UDim2.new(0.5, -46, 0, controlsY), 32, 16, "Inset")
			ui.play, ui.playImage = iconButton(ui.player, "play", "Play", UDim2.new(0.5, 0, 0, controlsY), 40, 18, "Accent")
			ui.next, ui.nextImage = iconButton(ui.player, "skip-forward", "Next", UDim2.new(0.5, 46, 0, controlsY), 32, 16, "Inset")
			ui.repeatButton, ui.repeatImage = iconButton(ui.player, "repeat", "Loop", UDim2.new(0.5, 92, 0, controlsY), 30, 15, "Inset")
			ui.volumeIcon = Instance.new("ImageLabel")
			ui.volumeIcon.Position = UDim2.fromOffset(14, 155)
			ui.volumeIcon.Size = UDim2.fromOffset(14, 14)
			ui.volumeIcon.BackgroundTransparency = 1
			bindAuxiliaryUiColor(ui.volumeIcon, "ImageColor3", "Muted")
			local volumeImage = menuIcons.get("volume-2", "volume-1", "volume")
			if volumeImage then menuIcons.apply(ui.volumeIcon, volumeImage) end
			ui.volumeIcon.Parent = ui.player
			ui.volume, ui.volumeFill, ui.volumeArea = bar(UDim2.fromOffset(36, 160), UDim2.new(1, -90, 0, 4))
			ui.volumeLabel = text(ui.player, "", Enum.Font.GothamMedium, 10, "Muted", UDim2.new(1, -46, 0, 155), UDim2.fromOffset(32, 14))
			ui.volumeLabel.TextXAlignment = Enum.TextXAlignment.Right
			ui.message = text(ui.player, "", Enum.Font.Gotham, 11, "AccentText", UDim2.fromOffset(14, 175), UDim2.new(1, -28, 0, 14))
			ui.search = inputBox(ui.player, "Search for a song, then press Enter", UDim2.fromOffset(14, 194), UDim2.new(1, -28, 0, 28))
			ui.results = Instance.new("Frame")
			ui.results.Position = UDim2.fromOffset(14, 228)
			ui.results.Size = UDim2.new(1, -28, 0, 0)
			ui.results.AutomaticSize = Enum.AutomaticSize.Y
			ui.results.BackgroundTransparency = 1
			ui.results.Parent = ui.player
			ui.resultsLayout = Instance.new("UIListLayout")
			ui.resultsLayout.Padding = UDim.new(0, 4)
			ui.resultsLayout.SortOrder = Enum.SortOrder.LayoutOrder
			ui.resultsLayout.Parent = ui.results

			-- Log out, in the header: a second click within three seconds does it.
			ui.logOut = Instance.new("TextButton")
			ui.logOut.AutomaticSize = Enum.AutomaticSize.X
			ui.logOut.Size = UDim2.fromOffset(0, 22)
			ui.logOut.AutoButtonColor = false
			ui.logOut.BorderSizePixel = 0
			ui.logOut.Font = Enum.Font.GothamBold
			ui.logOut.Text = "Log out"
			ui.logOut.TextSize = 11
			ui.logOut.ZIndex = 3
			bindAuxiliaryUiColor(ui.logOut, "BackgroundColor3", "Inset")
			bindAuxiliaryUiColor(ui.logOut, "TextColor3", "SubText")
			local logOutCorner = Instance.new("UICorner")
			logOutCorner.CornerRadius = UDim.new(0, 7)
			logOutCorner.Parent = ui.logOut
			local logOutPadding = Instance.new("UIPadding")
			logOutPadding.PaddingLeft = UDim.new(0, 10)
			logOutPadding.PaddingRight = UDim.new(0, 10)
			logOutPadding.Parent = ui.logOut
			ui.logOut.Parent = spotifyWindow.headerRight

			local function setMessage(content)
				ui.message.Text = content or ""
				ui.setupMessage.Text = content or ""
			end
			-- The window's height follows what's in it: the setup steps, or the player and any results.
			local function fit()
				local height
				if ui.setup.Visible then
					height = ui.setupLayout.AbsoluteContentSize.Y + 14
				else
					local listHeight = ui.resultsLayout.AbsoluteContentSize.Y
					height = 228 + (listHeight > 0 and listHeight + 6 or 0) + 4
				end
				spotifyWindow.resize(340, 36 + math.ceil(height))
			end
			ui.setupLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fit)
			ui.resultsLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fit)
			-- Colours that depend on what's on, read from the theme each time.
			local function paint()
				local theme = auxiliaryUiTheme
				local playback = player.playback
				local shuffleOn = playback ~= nil and playback.shuffle_state == true
				local repeatOn = playback ~= nil and playback.repeat_state ~= nil and playback.repeat_state ~= "off"
				ui.shuffleImage.ImageColor3 = shuffleOn and theme.AccentText or theme.SubText
				ui.repeatImage.ImageColor3 = repeatOn and theme.AccentText or theme.SubText
				ui.previousImage.ImageColor3 = theme.Text
				ui.nextImage.ImageColor3 = theme.Text
				ui.likeImage.ImageColor3 = theme.Text
				ui.playImage.ImageColor3 = theme.OnAccent
			end
			table.insert(auxiliaryUiThemeListeners, paint)

			-- Where the song is now: from where Spotify last said, plus the time since while it's playing.
			local function currentProgress()
				local playback = player.playback
				if not playback then return 0 end
				local progress = tonumber(playback.progress_ms) or 0
				if playback.is_playing then progress += (os.clock() - player.fetchedAt) * 1000 end
				local duration = type(playback.item) == "table" and tonumber(playback.item.duration_ms) or 0
				return duration > 0 and math.min(progress, duration) or progress
			end

			---------------------------------------------------------------------------------------
			-- Talking to Spotify, through the executor's web requests.
			local function send(options)
				if type(httprequest) ~= "function" then return nil end
				local sent, response = pcall(httprequest, options)
				if sent and type(response) == "table" then return response end
				return nil
			end
			local function decode(body)
				if type(body) ~= "string" or body == "" then return nil end
				local decoded, data = pcall(function() return HttpService:JSONDecode(body) end)
				return decoded and type(data) == "table" and data or nil
			end
			local function header(response, name)
				local headers = response and response.Headers
				if type(headers) ~= "table" then return nil end
				for key, value in pairs(headers) do
					if type(key) == "string" and key:lower() == name then return value end
				end
				return nil
			end

			-- Cover pictures: downloaded once each and shown from a file through getcustomasset, each under
			-- its own name so Roblox never shows an old one from its cache. The one before is deleted.
			local coverState = { url = nil, path = nil }
			local function loadCover(url)
				if url == coverState.url then return end
				coverState.url = url
				if not url then
					ui.cover.Image = ""
					ui.coverIcon.Visible = true
					return
				end
				if type(waxgetcustomasset) ~= "function" or not writefile then return end
				task.spawn(function()
					local response = send({ Url = url, Method = "GET" })
					if coverState.url ~= url or not response or response.StatusCode ~= 200 or type(response.Body) ~= "string" then return end
					local folder = ""
					if makefolder and isfolder then
						local made = pcall(function()
							if not isfolder(coverFolder) then makefolder(coverFolder) end
						end)
						if made then folder = coverFolder .. "/" end
					end
					local path = folder .. "cover_" .. (url:match("(%w+)$") or tostring(math.floor(os.clock() * 1000))) .. ".jpg"
					writefile(path, response.Body, true)
					local loaded, asset = pcall(waxgetcustomasset, path)
					if coverState.url ~= url or not loaded or type(asset) ~= "string" then return end
					ui.cover.Image = asset
					ui.coverIcon.Visible = false
					if coverState.path and coverState.path ~= path and type(delfile) == "function" then pcall(delfile, coverState.path) end
					coverState.path = path
				end)
			end

			local function render()
				local connected = saved.refreshToken ~= ""
				ui.setup.Visible = not connected
				ui.player.Visible = connected
				ui.logOut.Visible = connected
				if connected then
					local playback = player.playback
					local item = playback and playback.item
					if type(item) == "table" then
						ui.title.Text = tostring(item.name or "")
						ui.artist.Text = artistsOf(item)
						local parts = {}
						if type(item.album) == "table" and item.album.name then table.insert(parts, tostring(item.album.name)) end
						-- Your device's name can have your name in it, so Streamer Mode leaves it out.
						local device = type(playback.device) == "table" and playback.device.name
						if device and not featureSettings.streamerMode then table.insert(parts, "on " .. tostring(device)) end
						ui.detail.Text = table.concat(parts, "  ·  ")
						ui.total.Text = clock(item.duration_ms)
						loadCover(coverUrlOf(item))
					else
						ui.title.Text = playback and (playback.currently_playing_type == "ad" and "An ad" or "Playing") or "Nothing playing"
						ui.artist.Text = playback and "" or "Start something in Spotify, on your PC or phone."
						ui.detail.Text = ""
						ui.total.Text = "0:00"
						loadCover(nil)
					end
					local playing = playback ~= nil and playback.is_playing == true
					setIcon(ui.play, ui.playImage, playing and "pause" or "play", playing and "Pause" or "Play")
					setIcon(ui.repeatButton, ui.repeatImage, (playback and playback.repeat_state == "track") and "repeat-1" or "repeat", "Loop")
					local device = playback and playback.device
					local volume = type(device) == "table" and tonumber(device.volume_percent) or nil
					if player.dragging ~= "volume" then
						ui.volumeFill.Size = UDim2.fromScale((volume or 0) / 100, 1)
						ui.volumeLabel.Text = volume and (math.floor(volume + 0.5) .. "%") or ""
					end
					paint()
				end
				fit()
			end

			-- The login's tokens: the access token lasts an hour, and the saved login gets a new one.
			local function tokenRequest(fields)
				local parts = {}
				for key, value in pairs(fields) do
					table.insert(parts, key .. "=" .. urlEncode(value))
				end
				local response = send({
					Url = "https://accounts.spotify.com/api/token",
					Method = "POST",
					Headers = { ["Content-Type"] = "application/x-www-form-urlencoded" },
					Body = table.concat(parts, "&"),
				})
				return response, response and decode(response.Body)
			end
			local function takeTokens(data)
				token.value = data.access_token
				token.expiresAt = os.clock() + (tonumber(data.expires_in) or 3600) - 60
				-- Spotify sometimes sends a new login with it; the old one carries on otherwise.
				if type(data.refresh_token) == "string" and data.refresh_token ~= "" then saved.refreshToken = data.refresh_token end
				save()
			end
			-- Gets a new access token from the saved login. false when it can't.
			local function refreshToken()
				if saved.refreshToken == "" or saved.clientId == "" then return false end
				while token.refreshing do task.wait(0.1) end
				if token.value and os.clock() < token.expiresAt then return true end
				token.refreshing = true
				local response, data = tokenRequest({ grant_type = "refresh_token", refresh_token = saved.refreshToken, client_id = saved.clientId })
				token.refreshing = false
				if response and response.StatusCode == 200 and data and data.access_token then
					takeTokens(data)
					return true
				end
				if response and response.StatusCode == 400 then
					-- The login was cancelled or ran out, so it has to be done again.
					saved.refreshToken = ""
					token.value = nil
					player.playback = nil
					save()
					render()
					setMessage("Spotify logged you out, so connect again: copy a new login link (step 3).")
				end
				return false
			end
			-- One call to the Web API. A token Spotify turns down is renewed once and the call made again.
			local function call(method, path, query, body)
				if not token.value or os.clock() >= token.expiresAt then
					if not refreshToken() then return nil end
				end
				local function attempt()
					local options = {
						Url = "https://api.spotify.com/v1" .. path .. (query and ("?" .. query) or ""),
						Method = method,
						Headers = { Authorization = "Bearer " .. tostring(token.value) },
					}
					if body ~= nil then
						options.Headers["Content-Type"] = "application/json"
						options.Body = HttpService:JSONEncode(body)
					elseif method ~= "GET" then
						options.Body = ""
					end
					return send(options)
				end
				local response = attempt()
				if response and response.StatusCode == 401 then
					token.expiresAt = 0
					if refreshToken() then response = attempt() end
				end
				return response
			end
			-- What went wrong, in words, for a call that didn't work.
			local function explain(response)
				if not response then return "Couldn't reach Spotify. Check your internet." end
				local code = response.StatusCode
				local data = decode(response.Body)
				local problem = data and type(data.error) == "table" and data.error or {}
				local reason, message = tostring(problem.reason or ""), tostring(problem.message or "")
				if code == 429 then
					local wait = tonumber(header(response, "retry-after")) or 15
					player.quietUntil = os.clock() + wait
					return "Spotify asked for a break, so it waits " .. math.ceil(wait) .. " s."
				elseif reason == "PREMIUM_REQUIRED" then
					return "That needs Spotify Premium."
				elseif reason == "NO_ACTIVE_DEVICE" or code == 404 then
					return "Start playing something in Spotify first, on your PC or phone."
				elseif code == 403 and message:lower():find("regist") then
					return "Your account isn't on the app's user list: add your Spotify email under User Management in the dashboard."
				end
				return "Spotify said: " .. (message ~= "" and message or ("error " .. tostring(code)))
			end

			-- What's playing, asked every few seconds while the window's open, and after each button.
			local function poll()
				if player.polling or saved.refreshToken == "" then return end
				player.polling = true
				player.askedAt = os.clock()
				local response = call("GET", "/me/player", "additional_types=episode")
				player.polling = false
				if saved.refreshToken == "" then return end
				if response and response.StatusCode == 204 then
					player.playback = nil
					setMessage("")
				elseif response and response.StatusCode == 200 then
					local data = decode(response.Body)
					if data then
						player.playback = data
						player.fetchedAt = os.clock()
						setMessage("")
					end
				else
					setMessage(explain(response))
				end
				render()
			end
			-- A button's call, then a fresh look at what's playing. done runs when it worked.
			local function act(method, path, query, body, done)
				task.spawn(function()
					local response = call(method, path, query, body)
					if response and response.StatusCode >= 200 and response.StatusCode < 300 then
						setMessage("")
						if done then done() end
					elseif saved.refreshToken ~= "" then
						setMessage(explain(response))
					end
					task.wait(0.5)
					poll()
				end)
			end
			local function connected()
				if saved.refreshToken ~= "" then return true end
				notify("Spotify", "Connect your Spotify first: switch on Spotify in the Interface tab", 4)
				return false
			end
			-- Runs then, after checking what's playing if the last look is old (for keys and commands).
			local function withFreshState(thenRun)
				task.spawn(function()
					if os.clock() - player.fetchedAt > 5 then poll() end
					thenRun()
				end)
			end
			local function togglePlay()
				if not connected() then return end
				withFreshState(function()
					local playback = player.playback
					if playback and playback.is_playing then
						playback.progress_ms = currentProgress()
						playback.is_playing = false
						player.fetchedAt = os.clock()
						act("PUT", "/me/player/pause")
					else
						if playback then
							playback.is_playing = true
							player.fetchedAt = os.clock()
						end
						act("PUT", "/me/player/play")
					end
					render()
				end)
			end
			local function skip(forward)
				if not connected() then return end
				act("POST", forward and "/me/player/next" or "/me/player/previous")
			end
			local function seekTo(fraction)
				local playback = player.playback
				local duration = playback and type(playback.item) == "table" and tonumber(playback.item.duration_ms) or 0
				if duration <= 0 then return end
				local position = math.floor(math.clamp(fraction, 0, 1) * duration)
				playback.progress_ms = position
				player.fetchedAt = os.clock()
				act("PUT", "/me/player/seek", "position_ms=" .. position)
			end
			local function setVolume(percent)
				if not connected() then return end
				percent = math.clamp(math.floor(percent + 0.5), 0, 100)
				local playback = player.playback
				if playback and type(playback.device) == "table" then playback.device.volume_percent = percent end
				render()
				act("PUT", "/me/player/volume", "volume_percent=" .. percent)
			end
			local function toggleShuffle()
				local playback = player.playback
				local on = not (playback and playback.shuffle_state == true)
				if playback then playback.shuffle_state = on end
				paint()
				act("PUT", "/me/player/shuffle", "state=" .. tostring(on))
			end
			local repeatAfter = { off = "context", context = "track", track = "off" }
			local function cycleRepeat()
				local playback = player.playback
				local mode = repeatAfter[playback and playback.repeat_state or "off"] or "off"
				if playback then playback.repeat_state = mode end
				render()
				act("PUT", "/me/player/repeat", "state=" .. mode)
			end
			local function like()
				if not connected() then return end
				withFreshState(function()
					local item = player.playback and player.playback.item
					if type(item) ~= "table" or type(item.uri) ~= "string" then
						return notify("Spotify", "Nothing's playing to like", 3)
					end
					local name = tostring(item.name or "it")
					act("PUT", "/me/library", "uris=" .. urlEncode(item.uri), nil, function()
						notify("Spotify", "Saved " .. name .. " to your library", 3)
					end)
				end)
			end
			local function playTrack(track)
				act("PUT", "/me/player/play", nil, { uris = { track.uri } })
			end
			local function queueTrack(track)
				local name = tostring(track.name or "It")
				act("POST", "/me/player/queue", "uri=" .. urlEncode(track.uri), nil, function()
					notify("Spotify", name .. " is up next in your queue", 3)
				end)
			end
			-- Up to five songs for a search, handed to found.
			local function findTracks(query, found)
				task.spawn(function()
					local response = call("GET", "/search", "q=" .. urlEncode(query) .. "&type=track&limit=5")
					if not response or response.StatusCode ~= 200 then
						local problem = explain(response)
						setMessage(problem)
						return notify("Spotify", problem, 4)
					end
					local data = decode(response.Body)
					local items = data and type(data.tracks) == "table" and data.tracks.items
					if type(items) ~= "table" or type(items[1]) ~= "table" then
						return notify("Spotify", "Nothing found for " .. query, 3)
					end
					found(items)
				end)
			end
			local function clearResults()
				for _, child in ipairs(ui.results:GetChildren()) do
					if child:IsA("GuiObject") then child:Destroy() end
				end
			end
			local function showResults(items)
				clearResults()
				local theme = auxiliaryUiTheme
				for index, track in ipairs(items) do
					if index > 5 or type(track) ~= "table" or type(track.uri) ~= "string" then break end
					local row = Instance.new("Frame")
					row.LayoutOrder = index
					row.Size = UDim2.new(1, 0, 0, 30)
					row.BorderSizePixel = 0
					row.BackgroundColor3 = theme.Card
					row.Parent = ui.results
					local rowCorner = Instance.new("UICorner")
					rowCorner.CornerRadius = UDim.new(0, 8)
					rowCorner.Parent = row
					local by = artistsOf(track)
					local label = Instance.new("TextLabel")
					label.Position = UDim2.fromOffset(10, 0)
					label.Size = UDim2.new(1, -124, 1, 0)
					label.BackgroundTransparency = 1
					label.Font = Enum.Font.GothamMedium
					label.Text = tostring(track.name or "") .. (by ~= "" and ("  ·  " .. by) or "")
					label.TextColor3 = theme.Text
					label.TextSize = 12
					label.TextTruncate = Enum.TextTruncate.AtEnd
					label.TextXAlignment = Enum.TextXAlignment.Left
					label.Parent = row
					local function rowButton(content, x, role, textRole)
						local button = Instance.new("TextButton")
						button.AnchorPoint = Vector2.new(0, 0.5)
						button.Position = UDim2.new(1, x, 0.5, 0)
						button.Size = UDim2.fromOffset(52, 22)
						button.AutoButtonColor = false
						button.BorderSizePixel = 0
						button.Font = Enum.Font.GothamBold
						button.Text = content
						button.TextSize = 11
						button.BackgroundColor3 = theme[role]
						button.TextColor3 = theme[textRole]
						button.Parent = row
						local buttonCorner = Instance.new("UICorner")
						buttonCorner.CornerRadius = UDim.new(0, 7)
						buttonCorner.Parent = button
						return button
					end
					rowButton("Play", -112, "Accent", "OnAccent").Activated:Connect(function()
						playTrack(track)
						clearResults()
						ui.search.Text = ""
					end)
					rowButton("Queue", -56, "Inset", "SubText").Activated:Connect(function()
						queueTrack(track)
					end)
				end
			end
			local function describeNow()
				local playback = player.playback
				local item = playback and playback.item
				if type(item) ~= "table" then return "Nothing's playing" end
				local by = artistsOf(item)
				return tostring(item.name or "") .. (by ~= "" and (" by " .. by) or "") .. (playback.is_playing and "" or " (paused)")
			end

			---------------------------------------------------------------------------------------
			-- The buttons.
			local function copy(textToCopy, what)
				if type(everyClipboard) == "function" and pcall(everyClipboard, textToCopy) then
					setMessage(what .. " copied.")
					return true
				end
				return false
			end
			ui.copyDashboard.Activated:Connect(function()
				if not copy(dashboardUrl, "Dashboard link") then setMessage("Go to " .. dashboardUrl) end
			end)
			ui.copyRedirect.Activated:Connect(function()
				if not copy(redirectUri, "Redirect URI") then setMessage("The Redirect URI is " .. redirectUri) end
			end)
			ui.clientId.FocusLost:Connect(function()
				local typed = (ui.clientId.Text:gsub("%s", ""))
				ui.clientId.Text = typed
				if typed ~= saved.clientId then
					saved.clientId = typed
					save()
				end
			end)
			ui.copyLogin.Activated:Connect(function()
				local clientId = (ui.clientId.Text:gsub("%s", ""))
				if #clientId ~= 32 or not clientId:match("^%x+$") then
					return setMessage("Paste your app's Client ID first (step 2). It's 32 letters and numbers.")
				end
				if not loginWorks then
					return setMessage("This executor works out the login's check differently, so the login can't start here.")
				end
				saved.clientId = clientId
				saved.verifier = randomText(64)
				saved.state = randomText(16)
				save()
				local link = "https://accounts.spotify.com/authorize?" .. table.concat({
					"client_id=" .. urlEncode(clientId),
					"response_type=code",
					"redirect_uri=" .. urlEncode(redirectUri),
					"code_challenge_method=S256",
					"code_challenge=" .. challengeFor(saved.verifier),
					"scope=" .. urlEncode(scopes),
					"state=" .. saved.state,
				}, "&")
				if copy(link, "Login link") then
					setMessage("Login link copied. Paste it into your browser's address bar, log in if it asks, and press Agree.")
				else
					-- Nothing to copy with, so it goes in the box to select and copy by hand.
					ui.code.Text = link
					setMessage("Your executor can't copy, so the login link is in the box below: select it all, copy it and open it in your browser.")
				end
			end)
			local function connect()
				if player.connecting then return end
				local pasted = (ui.code.Text:gsub("%s", ""))
				local denied = pasted:match("[?&#]error=([^&#]+)")
				if denied then
					return setMessage(denied == "access_denied" and "You pressed Cancel instead of Agree. Copy the login link again." or ("Spotify said: " .. denied))
				end
				local code = pasted:match("[?&#]code=([^&#]+)")
				local returnedState = pasted:match("[?&#]state=([^&#]+)")
				-- Just the code on its own works too.
				if not code and #pasted > 40 and pasted:match("^[%w%-_]+$") then code = pasted end
				if not code then
					return setMessage("Paste the whole address your browser ended on. It starts with " .. redirectUri .. "?code=")
				end
				if saved.verifier == "" then
					return setMessage("Copy the login link first (step 3), then try again.")
				end
				if returnedState and returnedState ~= saved.state then
					return setMessage("That address is from an older login link. Copy the login link again and use the new one.")
				end
				player.connecting = true
				setMessage("Connecting...")
				task.spawn(function()
					local response, data = tokenRequest({
						grant_type = "authorization_code", code = code, redirect_uri = redirectUri,
						client_id = saved.clientId, code_verifier = saved.verifier,
					})
					player.connecting = false
					if response and response.StatusCode == 200 and data and data.access_token and data.refresh_token then
						saved.verifier, saved.state = "", ""
						takeTokens(data)
						ui.code.Text = ""
						setMessage("")
						render()
						notify("Spotify", "Connected", 3)
						poll()
					elseif response then
						local problem = data and (data.error_description or data.error)
						setMessage("Spotify said: " .. tostring(problem or ("error " .. tostring(response.StatusCode))) .. ". Copy the login link again and retry.")
					else
						setMessage(explain(nil))
					end
				end)
			end
			ui.connect.Activated:Connect(connect)
			ui.code.FocusLost:Connect(function(enterPressed)
				if enterPressed then connect() end
			end)
			local logOutArmedAt = 0
			ui.logOut.Activated:Connect(function()
				if os.clock() - logOutArmedAt > 3 then
					logOutArmedAt = os.clock()
					ui.logOut.Text = "Sure?"
					task.delay(3, function()
						if os.clock() - logOutArmedAt >= 3 then ui.logOut.Text = "Log out" end
					end)
					return
				end
				logOutArmedAt = 0
				ui.logOut.Text = "Log out"
				saved.refreshToken, saved.verifier, saved.state = "", "", ""
				token.value, token.expiresAt = nil, 0
				player.playback = nil
				save()
				clearResults()
				render()
				setMessage("Logged out. To cut the app off completely, remove it under Manage apps in your Spotify account.")
			end)
			ui.play.Activated:Connect(togglePlay)
			ui.previous.Activated:Connect(function() skip(false) end)
			ui.next.Activated:Connect(function() skip(true) end)
			ui.shuffle.Activated:Connect(toggleShuffle)
			ui.repeatButton.Activated:Connect(cycleRepeat)
			ui.like.Activated:Connect(like)
			ui.search.FocusLost:Connect(function(enterPressed)
				local query = (ui.search.Text:gsub("^%s+", ""):gsub("%s+$", ""))
				if query == "" then return clearResults() end
				if enterPressed then findTracks(query, showResults) end
			end)
			-- Dragging along the progress bar seeks, and along the volume bar sets the volume, on letting go.
			local function fractionAlong(back)
				local x = UserInputService:GetMouseLocation().X
				return math.clamp((x - back.AbsolutePosition.X) / math.max(back.AbsoluteSize.X, 1), 0, 1)
			end
			local function startDrag(which)
				return function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						player.dragging = which
					end
				end
			end
			ui.seekArea.InputBegan:Connect(startDrag("seek"))
			ui.volumeArea.InputBegan:Connect(startDrag("volume"))
			table.insert(spotifyWindow.connections, UserInputService.InputChanged:Connect(function(input)
				if not player.dragging then return end
				if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
				if player.dragging == "seek" then
					local fraction = fractionAlong(ui.progress)
					local playback = player.playback
					local duration = playback and type(playback.item) == "table" and tonumber(playback.item.duration_ms) or 0
					ui.progressFill.Size = UDim2.fromScale(fraction, 1)
					ui.elapsed.Text = clock(fraction * duration)
				else
					local fraction = fractionAlong(ui.volume)
					ui.volumeFill.Size = UDim2.fromScale(fraction, 1)
					ui.volumeLabel.Text = math.floor(fraction * 100 + 0.5) .. "%"
				end
			end))
			table.insert(spotifyWindow.connections, UserInputService.InputEnded:Connect(function(input)
				if not player.dragging then return end
				if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
				local which = player.dragging
				player.dragging = nil
				if which == "seek" then
					seekTo(fractionAlong(ui.progress))
				else
					setVolume(fractionAlong(ui.volume) * 100)
				end
			end))
			-- The progress bar moves along between looks, and a song that should have ended gets a look
			-- straight away, so the next one shows up quickly.
			table.insert(spotifyWindow.connections, RunService.Heartbeat:Connect(function()
				if not spotifyWindow.isShown() or not ui.player.Visible or player.dragging == "seek" then return end
				local playback = player.playback
				local duration = playback and type(playback.item) == "table" and tonumber(playback.item.duration_ms) or 0
				local progress = currentProgress()
				ui.progressFill.Size = UDim2.fromScale(duration > 0 and math.clamp(progress / duration, 0, 1) or 0, 1)
				ui.elapsed.Text = clock(progress)
				-- Never more than once every 2 seconds, even if Spotify keeps answering with a problem.
				if playback and playback.is_playing and duration > 0 and progress >= duration and not player.polling
					and os.clock() - player.askedAt > 2 and os.clock() >= player.quietUntil then
					task.spawn(poll)
				end
			end))

			spotifyWindow.onShown = function()
				render()
				if saved.refreshToken ~= "" then task.spawn(poll) end
			end
			-- Every 3 seconds while a song plays and the window's open, every 6 while paused.
			task.spawn(function()
				while spotifyWindow.gui.Parent do
					task.wait((player.playback and player.playback.is_playing) and 3 or 6)
					if spotifyWindow.isShown() and saved.refreshToken ~= "" and os.clock() >= player.quietUntil then
						pcall(poll)
					end
				end
			end)
			render()

			menuModules.spotify = {
				setEnabled = function(on)
					spotifyWindow.setShown(on)
				end,
				togglePlay = togglePlay,
				next = function() skip(true) end,
				previous = function() skip(false) end,
				resume = function()
					if connected() then act("PUT", "/me/player/play") end
				end,
				playSearch = function(query)
					if connected() then
						findTracks(query, function(items)
							playTrack(items[1])
							notify("Spotify", "Playing " .. tostring(items[1].name or query), 3)
						end)
					end
				end,
				queueSearch = function(query)
					if connected() then findTracks(query, function(items) queueTrack(items[1]) end) end
				end,
				setVolume = setVolume,
				like = like,
				nowPlaying = function()
					if not connected() then return end
					withFreshState(function() notify("Spotify", describeNow(), 4) end)
				end,
			}
		end)

		-- Switches that were on: the switches remembered between sessions (addRememberedToggle) come back
		-- on now that what they switch has been built.
		safeBuild("Switches that were on", function()
			for _, remembered in ipairs(menuModules.remembered) do
				local entry = quickToggleByName[remembered.name]
				if entry and featureSettings[remembered.key] and not entry.state then setQuickToggle(entry, true) end
			end
		end)

		-- Player info: a card under the Player name box in the Players tab with everything about the
		-- selected player (account age, team, health, distance, what they're holding, membership,
		-- whether they're your friend and who they're friends with here), and quick actions.
		safeBuild("The player info panel", function()
			local anchor = menuModules.playerNameInput and menuModules.playerNameInput.main
			if typeof(anchor) ~= "Instance" or not anchor.Parent then
				warn("[SpreadCheeksGUI] Couldn't add the player info panel; Rayfield's input layout may have changed.")
				return
			end
			local localPlayer = Players.LocalPlayer
			local page = anchor.Parent

			local function addCorner(object, radius)
				local corner = Instance.new("UICorner")
				corner.CornerRadius = radius or UDim.new(0, 8)
				corner.Parent = object
			end
			local function makeLabel(parent, text, font, size, role, position, frameSize)
				local label = Instance.new("TextLabel")
				label.BackgroundTransparency = 1
				label.Font = font
				label.Text = text
				label.TextSize = size
				label.TextXAlignment = Enum.TextXAlignment.Left
				label.TextTruncate = Enum.TextTruncate.AtEnd
				label.Position = position
				label.Size = frameSize
				bindAuxiliaryUiColor(label, "TextColor3", role)
				label.Parent = parent
				return label
			end

			-- As wide as the rows, right under the Player name box (wherever Rayfield numbers it).
			local width = anchor.Size.X
			if width.Scale == 0 and width.Offset <= 0 then width = UDim.new(1, -20) end
			local card = Instance.new("Frame")
			card.Name = "PlayerInfo"
			card.Size = UDim2.new(width, UDim.new(0, 0))
			card.AutomaticSize = Enum.AutomaticSize.Y
			card.BorderSizePixel = 0
			card.LayoutOrder = anchor.LayoutOrder + 5
			anchor:GetPropertyChangedSignal("LayoutOrder"):Connect(function()
				card.LayoutOrder = anchor.LayoutOrder + 5
			end)
			bindAuxiliaryUiColor(card, "BackgroundColor3", "Card")
			addCorner(card, UDim.new(0, 10))
			local cardStroke = Instance.new("UIStroke")
			cardStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			cardStroke.Transparency = 0.35
			bindAuxiliaryUiColor(cardStroke, "Color", "Stroke")
			cardStroke.Parent = card
			local cardPadding = Instance.new("UIPadding")
			cardPadding.PaddingTop = UDim.new(0, 12)
			cardPadding.PaddingBottom = UDim.new(0, 12)
			cardPadding.PaddingLeft = UDim.new(0, 12)
			cardPadding.PaddingRight = UDim.new(0, 12)
			cardPadding.Parent = card
			local cardLayout = Instance.new("UIListLayout")
			cardLayout.Padding = UDim.new(0, 8)
			cardLayout.SortOrder = Enum.SortOrder.LayoutOrder
			cardLayout.Parent = card
			card.Parent = page

			-- Who: their picture, names and whether they're here.
			local top = Instance.new("Frame")
			top.LayoutOrder = 1
			top.Size = UDim2.new(1, 0, 0, 48)
			top.BackgroundTransparency = 1
			top.Parent = card
			local avatar = Instance.new("ImageLabel")
			avatar.Size = UDim2.fromOffset(48, 48)
			avatar.BorderSizePixel = 0
			bindAuxiliaryUiColor(avatar, "BackgroundColor3", "Inset")
			addCorner(avatar, UDim.new(1, 0))
			avatar.Parent = top
			local nameLabel = makeLabel(top, "", Enum.Font.GothamBold, 14, "Text", UDim2.fromOffset(58, 6), UDim2.new(1, -170, 0, 18))
			local userLabel = makeLabel(top, "", Enum.Font.Gotham, 11, "SubText", UDim2.fromOffset(58, 26), UDim2.new(1, -170, 0, 14))
			local status = Instance.new("TextLabel")
			status.AnchorPoint = Vector2.new(1, 0)
			status.Position = UDim2.new(1, 0, 0, 4)
			status.AutomaticSize = Enum.AutomaticSize.X
			status.Size = UDim2.fromOffset(0, 22)
			status.BorderSizePixel = 0
			status.Font = Enum.Font.GothamBold
			status.TextSize = 10
			bindAuxiliaryUiColor(status, "BackgroundColor3", "Inset")
			addCorner(status, UDim.new(0, 7))
			local statusPadding = Instance.new("UIPadding")
			statusPadding.PaddingLeft = UDim.new(0, 9)
			statusPadding.PaddingRight = UDim.new(0, 9)
			statusPadding.Parent = status
			status.Parent = top

			-- The facts, two to a line.
			local grid = Instance.new("Frame")
			grid.LayoutOrder = 2
			grid.Size = UDim2.fromScale(1, 0)
			grid.AutomaticSize = Enum.AutomaticSize.Y
			grid.BackgroundTransparency = 1
			grid.Parent = card
			local gridLayout = Instance.new("UIGridLayout")
			gridLayout.CellSize = UDim2.new(0.5, -4, 0, 36)
			gridLayout.CellPadding = UDim2.fromOffset(8, 6)
			gridLayout.SortOrder = Enum.SortOrder.LayoutOrder
			gridLayout.Parent = grid
			local facts = {}
			for index, caption in ipairs({ "Account age", "Team", "Health", "Distance", "Holding", "Membership", "Your friend", "Joined Roblox" }) do
				local cell = Instance.new("Frame")
				cell.LayoutOrder = index
				cell.BorderSizePixel = 0
				bindAuxiliaryUiColor(cell, "BackgroundColor3", "Inset")
				addCorner(cell, UDim.new(0, 8))
				cell.Parent = grid
				makeLabel(cell, caption:upper(), Enum.Font.GothamBold, 9, "Muted", UDim2.fromOffset(10, 5), UDim2.new(1, -16, 0, 11))
				facts[caption] = makeLabel(cell, "--", Enum.Font.GothamMedium, 12, "Text", UDim2.fromOffset(10, 17), UDim2.new(1, -16, 0, 15))
			end
			-- Who they're friends with here can be a long list, so it gets a full line.
			local friendsLine = Instance.new("Frame")
			friendsLine.LayoutOrder = 3
			friendsLine.Size = UDim2.fromScale(1, 0)
			friendsLine.AutomaticSize = Enum.AutomaticSize.Y
			friendsLine.BorderSizePixel = 0
			bindAuxiliaryUiColor(friendsLine, "BackgroundColor3", "Inset")
			addCorner(friendsLine, UDim.new(0, 8))
			friendsLine.Parent = card
			local friendsPadding = Instance.new("UIPadding")
			friendsPadding.PaddingTop = UDim.new(0, 5)
			friendsPadding.PaddingBottom = UDim.new(0, 7)
			friendsPadding.PaddingLeft = UDim.new(0, 10)
			friendsPadding.PaddingRight = UDim.new(0, 10)
			friendsPadding.Parent = friendsLine
			local friendsLayout = Instance.new("UIListLayout")
			friendsLayout.Padding = UDim.new(0, 2)
			friendsLayout.SortOrder = Enum.SortOrder.LayoutOrder
			friendsLayout.Parent = friendsLine
			local friendsCaption = makeLabel(friendsLine, "FRIENDS IN THIS SERVER", Enum.Font.GothamBold, 9, "Muted", UDim2.new(), UDim2.new(1, 0, 0, 11))
			friendsCaption.LayoutOrder = 1
			local friendsValue = makeLabel(friendsLine, "--", Enum.Font.GothamMedium, 12, "Text", UDim2.new(), UDim2.fromScale(1, 0))
			friendsValue.LayoutOrder = 2
			friendsValue.AutomaticSize = Enum.AutomaticSize.Y
			friendsValue.TextWrapped = true
			friendsValue.TextTruncate = Enum.TextTruncate.None

			-- Your own note on them (Player Notes), kept between sessions. It saves when you click away.
			local noteBox = Instance.new("TextBox")
			noteBox.LayoutOrder = 4
			noteBox.Size = UDim2.new(1, 0, 0, 30)
			noteBox.BorderSizePixel = 0
			noteBox.ClearTextOnFocus = false
			noteBox.Font = Enum.Font.Gotham
			noteBox.PlaceholderText = "Add a note about them (only you see it)"
			noteBox.Text = ""
			noteBox.TextSize = 12
			noteBox.TextXAlignment = Enum.TextXAlignment.Left
			noteBox.TextTruncate = Enum.TextTruncate.AtEnd
			bindAuxiliaryUiColor(noteBox, "BackgroundColor3", "Inset")
			bindAuxiliaryUiColor(noteBox, "TextColor3", "Text")
			bindAuxiliaryUiColor(noteBox, "PlaceholderColor3", "Muted")
			addCorner(noteBox, UDim.new(0, 8))
			local notePadding = Instance.new("UIPadding")
			notePadding.PaddingLeft = UDim.new(0, 10)
			notePadding.PaddingRight = UDim.new(0, 10)
			notePadding.Parent = noteBox
			noteBox.Visible = false
			noteBox.Parent = card

			-- Quick actions, wrapping onto a second line when the menu is narrow.
			local actions = Instance.new("Frame")
			actions.LayoutOrder = 5
			actions.Size = UDim2.fromScale(1, 0)
			actions.AutomaticSize = Enum.AutomaticSize.Y
			actions.BackgroundTransparency = 1
			actions.Parent = card
			local actionsLayout = Instance.new("UIListLayout")
			actionsLayout.FillDirection = Enum.FillDirection.Horizontal
			actionsLayout.Padding = UDim.new(0, 6)
			actionsLayout.SortOrder = Enum.SortOrder.LayoutOrder
			actionsLayout.Wraps = true
			actionsLayout.Parent = actions
			local function makeAction(text, order, primary)
				local button = Instance.new("TextButton")
				button.LayoutOrder = order
				button.AutomaticSize = Enum.AutomaticSize.X
				button.Size = UDim2.fromOffset(0, 28)
				button.AutoButtonColor = false
				button.BorderSizePixel = 0
				button.Font = Enum.Font.GothamMedium
				button.Text = text
				button.TextSize = 12
				bindAuxiliaryUiColor(button, "BackgroundColor3", primary and "Accent" or "Inset")
				bindAuxiliaryUiColor(button, "TextColor3", primary and "OnAccent" or "Text")
				addCorner(button, UDim.new(0, 8))
				local padding = Instance.new("UIPadding")
				padding.PaddingLeft = UDim.new(0, 12)
				padding.PaddingRight = UDim.new(0, 12)
				padding.Parent = button
				button.Parent = actions
				return button
			end
			local gotoButton = makeAction("Go to", 1, true)
			local spectateButton = makeAction("Spectate", 2)
			local copyNameButton = makeAction("Copy name", 3)
			local copyIdButton = makeAction("Copy ID", 4)
			local outfitButton = makeAction("Outfit", 5)

			local function formatAge(days)
				days = tonumber(days) or 0
				if days < 1 then return "New today" end
				if days < 31 then return days .. (days == 1 and " day" or " days") end
				if days < 365 then return math.floor(days / 30) .. " months" end
				return string.format("%.1f years", days / 365)
			end
			-- The selected player, if they're in the server (by username or display name).
			local function selectedPlayer()
				local name = tostring(selectedPlayerName or ""):lower()
				for _, player in ipairs(Players:GetPlayers()) do
					if player.Name:lower() == name or player.DisplayName:lower() == name then return player end
				end
				return nil
			end

			-- Friendships take web requests, so they're looked up in the background and remembered
			-- for a minute.
			local friendsCache = {}
			local refresh
			local function lookUpFriends(player)
				local cached = friendsCache[player.UserId]
				if cached and os.clock() - cached.at < 60 then return end
				local entry = { at = os.clock() }
				friendsCache[player.UserId] = entry
				task.spawn(function()
					if player ~= localPlayer then
						local checked, isFriend = pcall(function() return localPlayer:IsFriendsWith(player.UserId) end)
						entry.you = checked and (isFriend and "Yes" or "No") or "Can't check"
					else
						entry.you = "That's you"
					end
					-- The players themselves are kept, so their names show the Streamer Mode way when drawn.
					local here, failed = {}, false
					for _, other in ipairs(Players:GetPlayers()) do
						if other ~= player then
							local checked, friends = pcall(function() return player:IsFriendsWith(other.UserId) end)
							if not checked then
								failed = true
								break
							end
							if friends then table.insert(here, other) end
						end
					end
					entry.failed = failed
					entry.here = here
					if refresh then pcall(refresh) end
				end)
			end

			local spectating = false
			refresh = function()
				local player = selectedPlayer()
				local theme = auxiliaryUiTheme
				if not player then
					local typed = tostring(selectedPlayerName or "")
					avatar.Image = ""
					nameLabel.Text = typed ~= "" and typed or "No one selected"
					userLabel.Text = "Pick a player above to see their info"
					status.Text = "NOT HERE"
					status.TextColor3 = theme.Muted
					for _, label in pairs(facts) do label.Text = "--" end
					friendsValue.Text = "--"
					noteBox.Visible = false
					return
				end
				avatar.Image = "rbxthumb://type=AvatarHeadShot&id=" .. player.UserId .. "&w=150&h=150"
				nameLabel.Text = menuModules.nameOf(player)
				userLabel.Text = featureSettings.streamerMode and "Names hidden by Streamer Mode" or ("@" .. player.Name .. "  ·  ID " .. player.UserId)
				noteBox.Visible = player ~= localPlayer and menuModules.noteFor ~= nil
				if noteBox.Visible and not noteBox:IsFocused() then noteBox.Text = menuModules.noteFor(player) or "" end
				status.Text = player == localPlayer and "YOU" or "IN THIS SERVER"
				status.TextColor3 = player == localPlayer and theme.AccentText or theme.Good
				facts["Account age"].Text = formatAge(player.AccountAge)
				local joined = os.date("*t", os.time() - (tonumber(player.AccountAge) or 0) * 86400)
				local months = { "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" }
				facts["Joined Roblox"].Text = (months[joined.month] or "?") .. " " .. joined.year
				facts["Team"].Text = player.Team and player.Team.Name or "No team"
				facts["Membership"].Text = player.MembershipType == Enum.MembershipType.Premium and "Premium" or "Standard"
				local character = player.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				facts["Health"].Text = humanoid and (math.floor(humanoid.Health + 0.5) .. " / " .. math.floor(humanoid.MaxHealth + 0.5)) or "No character"
				local root = character and getRoot(character)
				local myRoot = localPlayer.Character and getRoot(localPlayer.Character)
				facts["Distance"].Text = (root and myRoot and player ~= localPlayer) and (math.floor((root.Position - myRoot.Position).Magnitude) .. " studs") or "--"
				local tool = character and character:FindFirstChildOfClass("Tool")
				facts["Holding"].Text = tool and tool.Name or "Nothing"
				lookUpFriends(player)
				local cached = friendsCache[player.UserId]
				facts["Your friend"].Text = cached and cached.you or "Checking..."
				local friendsText = "Checking..."
				if cached and cached.failed then
					friendsText = "Can't check from here"
				elseif cached and cached.here then
					local names = {}
					for _, other in ipairs(cached.here) do table.insert(names, menuModules.nameOf(other)) end
					friendsText = #names > 0 and table.concat(names, ", ") or "No one"
				end
				friendsValue.Text = friendsText
			end
			table.insert(menuModules.nameListeners, function() pcall(refresh) end)
			noteBox.FocusLost:Connect(function()
				local player = selectedPlayer()
				if player and menuModules.setNote then menuModules.setNote(player, noteBox.Text) end
			end)
			outfitButton.Activated:Connect(function()
				local player = selectedPlayer()
				if not player then return notify("Outfit", "Pick someone who's in this server first.") end
				if menuModules.openOutfit then menuModules.openOutfit(player) end
			end)

			gotoButton.Activated:Connect(function() runForSelectedPlayer("goto") end)
			spectateButton.Activated:Connect(function()
				spectating = not spectating
				if spectating then
					runForSelectedPlayer("view")
				else
					execCmd("unview", Players.LocalPlayer, true)
				end
				spectateButton.Text = spectating and "Stop spectating" or "Spectate"
			end)
			copyNameButton.Activated:Connect(function()
				local player = selectedPlayer()
				toClipboard(player and player.Name or tostring(selectedPlayerName or ""))
			end)
			copyIdButton.Activated:Connect(function()
				local player = selectedPlayer()
				if player then
					toClipboard(tostring(player.UserId))
				else
					notify("Player info", "They're not in this server, so their ID isn't known here.")
				end
			end)

			menuModules.onPlayerSelected = function()
				if spectating then
					spectating = false
					spectateButton.Text = "Spectate"
				end
				refresh()
			end
			-- Status colours depend on the player, so they're set again after a theme change.
			table.insert(auxiliaryUiThemeListeners, function() pcall(refresh) end)
			pcall(refresh)
			-- Health and distance change all the time, so the card keeps up while the tab is open.
			task.spawn(function()
				while card.Parent do
					task.wait(0.5)
					if page.Visible then pcall(refresh) end
				end
			end)
		end)

		-- Commands for everything this menu adds, so it all works from the ; bar, the Command Bar
		-- tab, chat and IY keybinds like any other command. Each also gets a line in IY's command
		-- list (CMDs), which is where the usage and description shown while typing come from.
		local function registerMenuCommands()
			local function describe(name, description)
				CMDs[#CMDs + 1] = { NAME = name, DESC = description }
			end
			-- Turns a Quick Controls switch on or off (or over, with on left out), moving the switch.
			local function setSwitch(name, on)
				local entry = quickToggleByName[name]
				if not entry then
					warn("[SpreadCheeksGUI] There's no switch called " .. tostring(name))
					return
				end
				if on == nil then on = not entry.state end
				setQuickToggle(entry, on)
			end
			-- switchName is the switch's name as it shows in the menu; label is how the toggle
			-- command's description names it, when that reads better ("the radar").
			local function addSwitchCommands(switchName, names, onDescription, offDescription, label)
				local on, off, toggle = names[1], names[2], names[3]
				describe(on[1] .. (on[2] and (" / " .. on[2]) or ""), onDescription)
				describe(off[1] .. (off[2] and (" / " .. off[2]) or ""), offDescription)
				describe(toggle, "Turns " .. (label or switchName) .. " on or off")
				addcmd(on[1], { on[2] }, function() setSwitch(switchName, true) end)
				addcmd(off[1], { off[2] }, function() setSwitch(switchName, false) end)
				addcmd(toggle, {}, function() setSwitch(switchName, nil) end)
			end
			-- Opens the menu on one of its tabs.
			local function openTab(tab)
				pcall(function() window:Show() end)
				pcall(function() window:Navigate(tab) end)
			end
			local function firstArgument(args)
				return tostring(args[1] or ""):lower()
			end

			-- Aimbot.
			local function setAimbot(on)
				applyAimbot(on)
				pcall(function() aimbotToggle:Set(aimbotState.enabled, true) end)
			end
			describe("aimbot / aim", "Turns the aimbot on. Hold the aim key (right mouse by default) to aim")
			describe("unaimbot / unaim", "Turns the aimbot off")
			describe("toggleaimbot", "Turns the aimbot on or off")
			addcmd("aimbot", { "aim" }, function() setAimbot(true) end)
			addcmd("unaimbot", { "unaim" }, function() setAimbot(false) end)
			addcmd("toggleaimbot", {}, function() setAimbot(not aimbotState.enabled) end)
			describe("aimbotfov [size]", "Sets the size of the aimbot's circle, 20 to 600 (150 to start with)")
			addcmd("aimbotfov", {}, function(args)
				local size = tonumber(args[1])
				if not size then return notify("Aimbot", "Give a size, like aimbotfov 200") end
				featureSettings.aimbotFov = math.clamp(math.floor(size + 0.5), 20, 600)
				saveFeatureSettings()
				notify("Aimbot", "Circle size " .. featureSettings.aimbotFov, 2)
			end)
			describe("aimbotsmooth / aimbotsmoothness [1-10]", "How gently the aimbot turns: 1 snaps straight on, 10 is slowest")
			addcmd("aimbotsmooth", { "aimbotsmoothness" }, function(args)
				local value = tonumber(args[1])
				if not value then return notify("Aimbot", "Give a number from 1 to 10, like aimbotsmooth 3") end
				featureSettings.aimbotSmoothness = math.clamp(math.floor(value * 2 + 0.5) / 2, 1, 10)
				saveFeatureSettings()
				notify("Aimbot", "Smoothness " .. featureSettings.aimbotSmoothness, 2)
			end)
			describe("aimbotpart [head/torso/random]", "What the aimbot aims at")
			addcmd("aimbotpart", {}, function(args)
				local choice = firstArgument(args)
				if choice == "random" then
					featureSettings.aimbotRandomPart = true
				elseif choice == "head" or choice == "torso" then
					featureSettings.aimbotPart = choice == "head" and "Head" or "Torso"
					featureSettings.aimbotRandomPart = false
				else
					return notify("Aimbot", "Choose head, torso or random, like aimbotpart head")
				end
				saveFeatureSettings()
				notify("Aimbot", "Aiming at " .. (featureSettings.aimbotRandomPart and "random body parts" or ("the " .. choice)), 2)
			end)
			describe("aimbotmethod [camera/mouse/freeaim]", "How the aimbot aims: turning the camera, moving the cursor, or Free aim for games with their own camera")
			addcmd("aimbotmethod", {}, function(args)
				local methods = { camera = "Camera", mouse = "Mouse", freeaim = "Free aim", free = "Free aim" }
				local method = methods[firstArgument(args)]
				if not method then return notify("Aimbot", "Choose camera, mouse or freeaim, like aimbotmethod freeaim") end
				featureSettings.aimbotMethod = method
				saveFeatureSettings()
				notify("Aimbot", "Aiming with " .. method, 2)
			end)
			describe("aimbotkey [key]", "The key to hold to aim: a key like e or leftshift, or rmb / lmb for the mouse buttons")
			addcmd("aimbotkey", {}, function(args)
				local typed = firstArgument(args)
				local key = nil
				if typed == "rmb" or typed == "rightclick" or typed == "mouse2" then
					key = "RightClick"
				elseif typed == "lmb" or typed == "leftclick" or typed == "mouse1" then
					key = "LeftClick"
				else
					for _, keyCode in ipairs(Enum.KeyCode:GetEnumItems()) do
						if keyCode.Name:lower() == typed and not reservedKeys[keyCode] and not isMenuToggleKey(keyCode) then
							key = keyCode.Name
							break
						end
					end
				end
				if not key then return notify("Aimbot", "Give a key, like aimbotkey e, or rmb / lmb for the mouse buttons") end
				featureSettings.aimbotKey = key
				saveFeatureSettings()
				if aimbotState.refreshKey then aimbotState.refreshKey() end
				notify("Aimbot", "Hold " .. aimbotKeyText() .. " to aim", 2.5)
			end)
			describe("friendcheck [on/off]", "Whether the aimbot and trigger bot leave your Roblox friends alone (on to start with)")
			addcmd("friendcheck", {}, function(args)
				local choice = firstArgument(args)
				if choice ~= "on" and choice ~= "off" then return notify("Friend Check", "Choose on or off, like friendcheck on") end
				featureSettings.aimbotFriendCheck = choice == "on"
				featureSettings.triggerFriendCheck = choice == "on"
				saveFeatureSettings()
				notify("Friend Check", choice == "on" and "The aimbot and trigger bot leave your friends alone" or "Friends can be aimed at too", 3)
			end)
			addSwitchCommands("Target HUD", { { "targethud" }, { "untargethud" }, "toggletargethud" },
				"Shows the Target HUD: who you're aiming at, their health, distance and what they're holding", "Hides the Target HUD", "the Target HUD")

			-- Trigger bot.
			addSwitchCommands("Trigger Bot", { { "triggerbot", "tbot" }, { "untriggerbot", "untbot" }, "toggletriggerbot" },
				"Turns the trigger bot on: it fires while your crosshair is on a player", "Turns the trigger bot off", "the trigger bot")
			describe("triggermode [tap/hold]", "Tap clicks once per shot delay; Hold keeps the button down, for automatic guns")
			addcmd("triggermode", {}, function(args)
				local choice = firstArgument(args)
				if choice ~= "tap" and choice ~= "hold" then return notify("Trigger Bot", "Choose tap or hold, like triggermode hold") end
				featureSettings.triggerMode = choice == "tap" and "Tap" or "Hold"
				saveFeatureSettings()
				notify("Trigger Bot", featureSettings.triggerMode .. " mode", 2)
			end)
			describe("triggerdelay [ms]", "How long the crosshair stays on someone before the first shot, 0 to 500 ms")
			addcmd("triggerdelay", {}, function(args)
				local delayMs = tonumber(args[1])
				if not delayMs then return notify("Trigger Bot", "Give a time in milliseconds, like triggerdelay 80") end
				featureSettings.triggerDelay = math.clamp(math.floor(delayMs / 10 + 0.5) * 10, 0, 500)
				saveFeatureSettings()
				notify("Trigger Bot", "Reaction time " .. featureSettings.triggerDelay .. " ms", 2)
			end)

			-- Silent aim.
			addSwitchCommands("Silent Aim", { { "silentaim" }, { "unsilentaim" }, "togglesilentaim" },
				"Turns on silent aim: your shots go to whoever's nearest your cursor inside the aimbot's circle", "Turns silent aim off", "silent aim")
			describe("silentaimchance / hitchance [5-100]", "How often silent aim sends a shot to your target, in percent (100 to start with)")
			addcmd("silentaimchance", { "hitchance" }, function(args)
				local chance = tonumber(args[1])
				if not chance then return notify("Silent Aim", "Give a percent, like silentaimchance 80") end
				featureSettings.silentAimChance = math.clamp(math.floor(chance / 5 + 0.5) * 5, 5, 100)
				saveFeatureSettings()
				notify("Silent Aim", "Hit chance " .. featureSettings.silentAimChance .. "%", 2)
			end)
			describe("autoshoot [on/off]", "Whether silent aim shoots for you the moment someone's in the circle (switches it over if you leave out on or off)")
			addcmd("autoshoot", { "silentaimautoshoot" }, function(args)
				local choice = firstArgument(args)
				if choice == "on" then
					featureSettings.silentAimAutoShoot = true
				elseif choice == "off" then
					featureSettings.silentAimAutoShoot = false
				else
					featureSettings.silentAimAutoShoot = not featureSettings.silentAimAutoShoot
				end
				saveFeatureSettings()
				notify("Silent Aim", featureSettings.silentAimAutoShoot and ("Auto shoot on" .. (aimbotState.silent.on and "" or ". Switch on Silent Aim too")) or "Auto shoot off", 3)
			end)
			describe("silentaimstatus", "Shows whether silent aim can hook the game, who it's on, and what the game has asked (also printed in the F9 console)")
			addcmd("silentaimstatus", {}, function()
				if not menuModules.silentAim then return notify("Silent Aim", "Silent Aim didn't load") end
				local text = menuModules.silentAim.status()
				print("[SpreadCheeksGUI] Silent Aim status:\n" .. text)
				notify("Silent Aim", text, 12)
			end)

			-- Cheater detector.
			addSwitchCommands("Cheater Detector", { { "cheatdetector", "detectcheaters" }, { "uncheatdetector", "undetectcheaters" }, "togglecheatdetector" },
				"Warns you when someone moves like a cheater: flying, speed, teleporting, noclip or flinging", "Turns the cheater detector off", "the cheater detector")
			describe("cheatsensitivity [relaxed/normal/strict]", "How sure the cheater detector has to be before it warns you")
			addcmd("cheatsensitivity", {}, function(args)
				local levels = { relaxed = "Relaxed", normal = "Normal", strict = "Strict" }
				local level = levels[firstArgument(args)]
				if not level then return notify("Cheater Detector", "Choose relaxed, normal or strict") end
				featureSettings.cheatSensitivity = level
				saveFeatureSettings()
				notify("Cheater Detector", level .. " sensitivity", 2)
			end)

			-- Windows on screen.
			addSwitchCommands("Performance Stats", { { "perfstats", "performancestats" }, { "unperfstats", "unperformancestats" }, "toggleperfstats" },
				"Shows the Performance Stats window: FPS, ping, memory and more", "Hides the Performance Stats window")
			local function setKeybindList(on)
				showKeybindList(on)
				pcall(function() keybindListToggle:Set(featureSettings.keybindList, true) end)
			end
			describe("keybindlist / showkeybinds", "Shows the on-screen list of your keybinds")
			describe("unkeybindlist / hidekeybinds", "Hides the keybind list")
			describe("togglekeybindlist", "Shows or hides the keybind list")
			addcmd("keybindlist", { "showkeybinds" }, function() setKeybindList(true) end)
			addcmd("unkeybindlist", { "hidekeybinds" }, function() setKeybindList(false) end)
			addcmd("togglekeybindlist", {}, function() setKeybindList(not featureSettings.keybindList) end)

			-- Protection and ESP.
			describe("nofalldamage / nofall", "Prevents fall damage in Natural Disaster Survival")
			describe("unnofalldamage / unnofall", "Turns No Fall Damage off")
			addcmd("nofalldamage", { "nofall" }, function() setSwitch("No Fall Damage", true) end)
			addcmd("unnofalldamage", { "unnofall" }, function() setSwitch("No Fall Damage", false) end)
			describe("espenemies", "ESP only shows players on the other team")
			describe("unespenemies", "ESP shows everyone again")
			addcmd("espenemies", {}, function()
				espSettings.enemiesOnly = true
				saveEspSettings()
				notify("ESP", "Only showing enemies", 2)
			end)
			addcmd("unespenemies", {}, function()
				espSettings.enemiesOnly = false
				saveEspSettings()
				notify("ESP", "Showing everyone", 2)
			end)
			describe("esparrows", "ESP shows arrows round the edge of your screen pointing at players who are off it")
			describe("unesparrows", "Takes the ESP's off-screen arrows away")
			addcmd("esparrows", {}, function()
				espSettings.offscreenArrows = true
				saveEspSettings()
				notify("ESP", "Off-screen arrows on" .. (ESPenabled and "" or ". Turn ESP on to see them"), 3)
			end)
			addcmd("unesparrows", {}, function()
				espSettings.offscreenArrows = false
				saveEspSettings()
				notify("ESP", "Off-screen arrows off", 2)
			end)

			-- The menu: its theme, its tabs, and joining servers.
			describe("theme [name]", "Changes the menu's theme: " .. table.concat(themeNames, ", "))
			addcmd("theme", {}, function(args)
				local palette = nil
				for _, each in ipairs(themePalettes) do
					if each.name:lower() == firstArgument(args) then palette = each end
				end
				if not palette then return notify("Theme", "Pick one of: " .. table.concat(themeNames, ", "), 6) end
				applyTheme(palette)
				pcall(function() themeDropdown:Set(palette.name, true) end)
				notify("Theme", palette.name, 2)
			end)
			describe("menu / togglemenu", "Shows or hides this menu")
			addcmd("menu", { "togglemenu" }, function()
				pcall(function() window:ToggleHide() end)
			end)
			describe("home / dashboard", "Opens the menu on the Home tab")
			addcmd("home", { "dashboard" }, function() openTab(homeTab) end)
			describe("commandbar", "Opens the menu on the Command Bar tab")
			addcmd("commandbar", {}, function() openTab(runTab) end)
			describe("servers / serverbrowser", "Opens the menu on the Servers tab, to browse and join this game's servers")
			addcmd("servers", { "serverbrowser" }, function() openTab(serversTab) end)
			describe("iysettings", "Opens the menu on IY Settings: keybinds, prefix, aliases, waypoints and plugins")
			addcmd("iysettings", {}, function() openTab(iySettingsTab) end)
			-- Windows and alerts added with the radar and logs.
			addSwitchCommands("Radar", { { "radar", "minimap" }, { "unradar", "unminimap" }, "toggleradar" },
				"Shows the radar: a minimap of the players around you", "Hides the radar", "the radar")
			addSwitchCommands("Logs", { { "logswindow" }, { "unlogswindow" }, "togglelogswindow" },
				"Shows the Logs window: chat, joins and recent notifications", "Hides the Logs window", "the Logs window")
			addSwitchCommands("Join Alerts", { { "joinalerts" }, { "unjoinalerts" }, "togglejoinalerts" },
				"Tells you when friends or watched players join or leave", "Turns Join Alerts off")
			describe("watch [username]", "Adds a player to your watch list, so Join Alerts tells you when they come and go")
			addcmd("watch", {}, function(args)
				local name = getstring(1, args)
				if not menuModules.joinAlerts or not menuModules.joinAlerts.watch(name) then
					return notify("Join Alerts", "Give a username, like watch builderman")
				end
				notify("Join Alerts", "Watching " .. name .. (featureSettings.joinAlerts and "" or ". Turn on Join Alerts to be told when they come and go"), 4)
			end)
			describe("unwatch [username]", "Takes a player off your watch list")
			addcmd("unwatch", {}, function(args)
				local name = getstring(1, args)
				if menuModules.joinAlerts and menuModules.joinAlerts.unwatch(name) then
					notify("Join Alerts", "Stopped watching " .. name, 3)
				else
					notify("Join Alerts", name .. " isn't on your watch list")
				end
			end)
			addSwitchCommands("Mention Alerts", { { "mentionalerts", "mentions" }, { "unmentionalerts", "unmentions" }, "togglementionalerts" },
				"Tells you when someone says your name in chat", "Turns Mention Alerts off")
			describe("mentionword [word]", "Adds a word that counts as your name for Mention Alerts, like a nickname")
			addcmd("mentionword", {}, function(args)
				local word = getstring(1, args)
				if not menuModules.mentionAlerts or not menuModules.mentionAlerts.addWord(word) then
					return notify("Mention Alerts", "Give a word of up to 30 letters, like mentionword captain")
				end
				notify("Mention Alerts", "Listening for " .. word .. (featureSettings.mentionAlerts and "" or ". Turn on Mention Alerts to be told when someone says it"), 4)
			end)
			describe("unmentionword [word]", "Takes a word off Mention Alerts' list")
			addcmd("unmentionword", {}, function(args)
				local word = getstring(1, args)
				if menuModules.mentionAlerts and menuModules.mentionAlerts.removeWord(word) then
					notify("Mention Alerts", "Stopped listening for " .. word, 3)
				else
					notify("Mention Alerts", word .. " isn't on the list")
				end
			end)

			-- The Favourites bar.
			addSwitchCommands("Favourites Bar", { { "favbar", "favouritesbar" }, { "unfavbar", "unfavouritesbar" }, "togglefavbar" },
				"Shows the Favourites bar: your starred switches and moves", "Hides the Favourites bar", "the Favourites bar")
			-- A switch or move from a typed name, ignoring case, spaces and punctuation: the one that
			-- matches, or else the first that starts with it. Gives its favourites key and its name.
			local function favouriteNamed(typed)
				local wanted = tostring(typed or ""):lower():gsub("[%s%p]", "")
				if wanted == "" then return nil end
				local choices = {}
				for _, entry in ipairs(quickToggles) do
					if not entry.noFavourite then table.insert(choices, { "switch:" .. entry.name, entry.name }) end
				end
				for _, move in ipairs(trolling.moves or {}) do
					table.insert(choices, { "move:" .. move.name, move.name })
				end
				for pass = 1, 2 do
					for _, choice in ipairs(choices) do
						local simple = choice[2]:lower():gsub("[%s%p]", "")
						if simple == wanted or (pass == 2 and simple:sub(1, #wanted) == wanted) then
							return choice[1], choice[2]
						end
					end
				end
				return nil
			end
			describe("fav / favourite [switch or move]", "Puts a switch or move on the Favourites bar, by its name in the menu, like fav fly or fav front flip")
			addcmd("fav", { "favourite", "favorite" }, function(args)
				local key, name = favouriteNamed(getstring(1, args))
				if not key then return notify("Favourites", "Give the name of a switch or move, like fav fly") end
				favourites.set(key, true)
				notify("Favourites", name .. " is on your Favourites bar", 2)
			end)
			describe("unfav / unfavourite [switch or move]", "Takes a switch or move off the Favourites bar")
			addcmd("unfav", { "unfavourite", "unfavorite" }, function(args)
				local key, name = favouriteNamed(getstring(1, args))
				if not key or not favourites.has(key) then return notify("Favourites", "That isn't on your Favourites bar") end
				favourites.set(key, false)
				notify("Favourites", name .. " is off your Favourites bar", 2)
			end)

			-- Trolling. (Spin, Headsit, Orbit, Swim, Trip and Fakeout already have Infinite Yield commands of
			-- those names.)
			describe("trolling", "Opens the menu on the trolling tabs, starting with Emotes")
			addcmd("trolling", {}, function() openTab(trollTab) end)
			describe("pranks", "Opens the menu on Player Pranks, where you pick who the tricks are played on")
			addcmd("pranks", {}, function() openTab(trollTabs.players) end)
			-- Picks the Player Pranks target from a typed name, for the commands that take one.
			local function chooseTarget(args, speaker, feature)
				if not args[1] then return true end
				local names = getPlayer(args[1], speaker)
				local target = names and names[1] and Players:FindFirstChild(names[1])
				if not target or target == Players.LocalPlayer then
					notify(feature, "Couldn't find that player")
					return false
				end
				if menuModules.selectPlayer then
					menuModules.selectPlayer(target.Name, menuModules.labelOf(target, "  "))
				end
				return true
			end

