			addcmd("unweather", {}, function() setSwitch("Weather", false) end)
			describe("graphics / shaders [style]", "Makes the game look better: cinematic, vibrant, warm, cold, bw, vintage, dreamy or nightvision (with no style, turns Graphics Presets on)")
			addcmd("graphics", { "shaders" }, function(args)
				local wanted = tostring(getstring(1, args) or ""):lower():gsub("[%s%p]", "")
				if wanted ~= "" then
					local style = menuModules.graphicsPresets and menuModules.graphicsPresets.styleNamed(wanted)
					if not style then return notify("Graphics Presets", "Choose cinematic, vibrant, warm, cold, bw, vintage, dreamy or nightvision") end
					featureSettings.graphicsStyle = style
					saveFeatureSettings()
					menuModules.graphicsPresets.refresh()
				end
				setSwitch("Graphics Presets", true)
			end)
			describe("ungraphics / unshaders", "Puts the game's own look back")
			addcmd("ungraphics", { "unshaders" }, function() setSwitch("Graphics Presets", false) end)
			describe("panic", "Switches everything off at once and hides the menu, like the Panic key (End to start with)")
			addcmd("panic", {}, function() setSwitch("Panic", true) end)
			describe("unpanic", "Puts back everything Panic switched off")
			addcmd("unpanic", {}, function() setSwitch("Panic", false) end)

			-- Waddles, Cartwheels and Colours.
			addSwitchCommands("Auto Go Back", { { "autogoback" }, { "unautogoback" }, "toggleautogoback" },
				"After you die, takes you back to where you died once you respawn", "Stays where you respawn")
			addSwitchCommands("Session Stats", { { "sessionstats" }, { "unsessionstats" }, "togglesessionstats" },
				"Shows your session stats: time played, distance, jumps, deaths and more", "Hides your session stats")
			describe("resetstats", "Starts Session Stats' all-time totals again from this session")
			addcmd("resetstats", {}, function()
				if menuModules.sessionStats then menuModules.sessionStats.resetTotals() end
			end)
			describe("customtheme", "Opens Custom Theme, to pick your own colours for the menu")
			addcmd("customtheme", {}, function()
				if menuModules.themeMaker then menuModules.themeMaker.open() end
			end)
			describe("themecolours / themecolors [accent] [background]", "Sets the Custom theme's colours as hex codes and switches to it, like themecolours ff4d6d 101012")
			addcmd("themecolours", { "themecolors" }, function(args)
				if not menuModules.themeMaker then return end
				if not menuModules.themeMaker.setColours(args[1], args[2]) then
					notify("Custom Theme", "Give one or two hex codes, the accent then the background, like themecolours ff4d6d 101012")
				end
			end)

			-- Jetpacks and Friends.
			addSwitchCommands("Jetpack", { { "jetpack" }, { "unjetpack" }, "togglejetpack" },
				"Puts the Jetpack on: hold Space to blast upwards", "Takes the Jetpack off")
			describe("friendsonline / friendslist", "Shows which of your friends are online and what they're playing, to join them")
			addcmd("friendsonline", { "friendslist" }, function()
				if menuModules.friendsOnline then menuModules.friendsOnline.open() end
			end)

			-- Combat Tools (Fake Leave's commands are with the other trolling ones).
			addSwitchCommands("Aim Warning", { { "aimwarning" }, { "unaimwarning" }, "toggleaimwarning" },
				"Shows a red arrow pointing at anyone looking straight at you", "Stops the aim warnings")
			addSwitchCommands("Hit Markers", { { "hitmarkers" }, { "unhitmarkers" }, "togglehitmarkers" },
				"Shows damage numbers and an X on your crosshair when you hit someone", "Stops the hit markers")
			addSwitchCommands("Custom Crosshair", { { "crosshair" }, { "uncrosshair" }, "togglecrosshair" },
				"Shows a crosshair of your own in the middle of the screen", "Hides your crosshair")

			-- Spotify.
			addSwitchCommands("Spotify", { { "spotify" }, { "unspotify" }, "togglespotify" },
				"Shows your Spotify player (needs Premium)", "Hides the Spotify player", "the Spotify player")
			local function spotifyRun(action, ...)
				if not menuModules.spotify then return notify("Spotify", "Spotify didn't load") end
				menuModules.spotify[action](...)
			end
			describe("sppause / spplaypause", "Plays or pauses your Spotify")
			addcmd("sppause", { "spplaypause" }, function() spotifyRun("togglePlay") end)
			describe("spnext / spskip", "Skips to the next song on Spotify")
			addcmd("spnext", { "spskip" }, function() spotifyRun("next") end)
			describe("spprev / spback", "Goes back a song on Spotify")
			addcmd("spprev", { "spback" }, function() spotifyRun("previous") end)
			describe("spplay [song]", "Plays a song on Spotify by name, or carries on playing if you leave the name out")
			addcmd("spplay", {}, function(args)
				local query = table.concat(args, " ")
				if query == "" then spotifyRun("resume") else spotifyRun("playSearch", query) end
			end)
			describe("spqueue [song]", "Adds a song to your Spotify queue by name")
			addcmd("spqueue", {}, function(args)
				local query = table.concat(args, " ")
				if query == "" then return notify("Spotify", "Give a song, like spqueue blinding lights") end
				spotifyRun("queueSearch", query)
			end)
